INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vjr2005/Challenge/project-structure', 'community', 'vjr2005', 'Challenge', 'vjr2005/Challenge', 'project-structure', 0, 0, 51, '2026-03-07T01:49:01.719Z', '2026-03-07T02:46:52.102Z', 'fea979d9ac32d41702dc3e9216c43836e931f4838d324d9417bd9a9b67c8fdc7', '{"id":"vjr2005/Challenge/project-structure","name":"project-structure","description":{"en":"The project-structure skill provides a guide for organizing files and directories in a project. It helps developers understand the codebase layout and create a new feature module.","zh":"项目结构是代码库的骨架，良好的结构可以提高开发效率和代码维护性","ja":"プロジェクト構造はコードベースの骨格であり、良好な構造は開発効率とコードメンテナンス性を向上させる","ko":"프로젝트 구조는 코드베이스의 뼈대이며, 좋은 구조는 개발 효율과 코드 유지보수성을 향상시킵니다","es":"Nuestra guía de estructura de proyecto te ayuda a organizar tus archivos y carpetas de manera eficiente. Aprende a crear un proyecto escalable","fr":"Notre guide de structure de projet vous aide à organiser vos fichiers et dossiers de manière efficace. Apprenez à créer un projet scalable pour les développeurs d''AI Agents","de":"Unsere Projektstruktur-Setup-Anleitung hilft Ihnen, Ihre Dateien und Ordner effizient zu organisieren. Erfahren Sie, wie Sie ein skalierbares Projekt für Entwickler mit AI-Tools erstellen","pt":"Nossa guia de estrutura de projeto fornece orientação sobre como organizar arquivos e pastas de forma eficiente. Aprenda a criar uma estrutura de projeto escalável.","ru":"Наше руководство по структуре проекта предоставляет рекомендации о том, как организовать файлы и папки эффективно. Узнайте, как создать масштабируемую структуру проекта.","ar":"دليلنا للهيكل المشروع يوفر إرشادات حول كيفية تنظيم الملفات والمجلدات بفعالية. تعلم كيفية إنشاء هيكل مشروع قابل للتوسيع."},"seo":{"title":{"en":"Project-Structure: Directory Setup Guide for AI Agents","zh":"项目结构设置指南 - 了解代码库布局","ja":"プロジェクト構造設定ガイド - コードベースレイアウトを理解する","ko":"프로젝트 구조 설정 가이드 - 코드베이스 레이아웃 이해","es":"Guía de estructura de proyecto para desarrolladores","fr":"Guide de structure de projet pour les développeurs d''AI A...","de":"Projektstruktur-Setup für Entwickler mit AI-Tools","pt":"Guia de Estrutura de Projeto: Melhores Práticas para Dese...","ru":"ИИ Агенты: Руководство по Структуре Проекта для Разработч...","ar":"هيكل المشروع: دليل لإعداد وتخطيط المشاريع البرمجية"},"description":{"en":"Discover how to organize your codebase with project-structure. Learn directory layout best practices and get started with our setup guide today!","zh":"了解项目结构的重要性和最佳实践，优化代码库布局和文件组织","ja":"プロジェクト構造の重要性とベストプラクティスを理解し、コードベースのレイアウトとファイルの組織化を最適化する","ko":"프로젝트 구조의 중요성과最佳實踐을 이해하고 코드베이스 레이아웃과 파일 조직을 최적화합니다","es":"Aprende a organizar tu proyecto con nuestra guía de estructura de proyecto. Mejora la eficiencia y la escalabilidad de tu código","fr":"Découvrez comment organiser votre projet avec notre guide de structure de projet pour les développeurs d''AI Agents. Améliorez l''efficacité et la scalabilité ...","de":"Erfahren Sie, wie Sie Ihr Projekt mit unserer Projektstruktur-Setup-Anleitung für Entwickler mit AI-Tools organisieren. Verbessern Sie die Effizienz und Skal...","pt":"Aprenda a organizar seu projeto com eficiência usando nossa guia de estrutura de projeto. Descubra as melhores práticas para desenvolvedores.","ru":"Узнайте, как правильно организовать свой проект с помощью нашего руководства по структуре проекта. Откройте для себя лучшие практики для разработчиков.","ar":"تعلم كيفية تنظيم مشروعك بفعالية باستخدام دليلنا للهيكل المشروع. اكتشف أفضل الممارسات للمطورين."},"definition":{"en":"project-structure is a skill that provides guidance on organizing project directories and files, including App and Tests folders, and Assets.xcassets management","zh":"项目结构指的是代码库的组织和目录结构","ja":"プロジェクト構造とはコードベースの組織化とディレクトリ構造を指す","ko":"프로젝트 구조는 코드베이스의 조직과 디렉토리 구조를指します","es":"La estructura de proyecto es la organización de los archivos y carpetas de un proyecto de software","fr":"La structure de projet est l''organisation des fichiers et dossiers d''un projet de logiciel pour les développeurs d''AI Agents","de":"Die Projektstruktur ist die Organisation der Dateien und Ordner eines Software-Projekts für Entwickler mit AI-Tools","pt":"Estrutura de projeto é a organização lógica de arquivos e pastas em um projeto de software.","ru":"Структура проекта - это логическая организация файлов и папок в проекте программного обеспечения.","ar":"هيكل المشروع هو التنظيم المنطقي للملفات والمجلدات في مشروع البرمجيات."},"features":{"en":["Creates a minimal entry point with AppKit imports in AppNameApp.swift","Organizes files into Sources, Resources, and Tests directories","Manages UI tests in the Tests/UI folder","Supports extensions to existing types","Provides a directory structure for App and Tests folders"],"zh":["创建新特性模块","组织文件正确","了解代码库布局","添加扩展到现有类型","使用AppKit和Assets.xcassets"],"ja":["新しい機能モジュールを作成する","ファイルを正しく組織する","コードベースのレイアウトを理解する","既存のタイプに拡張を追加する","AppKitとAssets.xcassetsを使用する"],"ko":["새로운 기능 모듈 생성","파일을 올바르게 조직화","코드베이스 레이아웃 이해","기존 유형에 확장 추가","AppKit과 Assets.xcassets 사용"],"es":["Organización de archivos y carpetas","Creación de un proyecto escalable","Estructura de directorios para AppName","Uso de Sources y Tests para una mejor organización","Incorporación de Assets.xcassets para recursos visuales"],"fr":["Organisation des fichiers et dossiers","Création d''un projet scalable pour les développeurs d''AI Agents","Structure de répertoires pour AppName","Utilisation de Sources et Tests pour une meilleure organisation","Intégration d''Assets.xcassets pour les ressources visuelles"],"de":["Organisation von Dateien und Ordnern","Erstellung eines skalierbaren Projekts für Entwickler mit AI-Tools","Verzeichnisstruktur für AppName","Verwendung von Sources und Tests für eine bessere Organisation","Einbindung von Assets.xcassets für visuelle Ressourcen"],"pt":["Organização de arquivos e pastas","Criação de uma estrutura de projeto escalável","Uso de pastas Sources e Tests","Integração com AppKit","Suporte a Assets.xcassets"],"ru":["Организация файлов и папок","Создание масштабируемой структуры проекта","Использование папок Sources и Tests","Интеграция с AppKit","Поддержка Assets.xcassets"],"ar":["تنظيم الملفات والمجلدات","إنشاء هيكل مشروع قابل للتوسيع","استخدام مجلدات Sources و Tests","التكامل مع AppKit","دعم Assets.xcassets"]},"keywords":{"en":["how to use project-structure","project-structure setup guide","project-structure vs file system","what is project-structure","project-structure directory layout","project-structure install for AI agents","project-structure best practices for developers","project-structure alternative for code organization","project-structure and AppKit integration"],"zh":["项目结构","代码库布局","文件组织","AppKit","Assets.xcassets","代码维护性","开发效率"],"ja":["プロジェクト構造","コードベースレイアウト","ファイル組織","AppKit","Assets.xcassets","コードメンテナンス性","開発効率"],"ko":["프로젝트 구조","코드베이스 레이아웃","파일 조직","AppKit","Assets.xcassets","코드 유지보수성","개발 효율"],"es":["estructura de proyecto","organización de archivos","desarrollo de software","proyecto escalable","appName","sources","tests","assets.xcassets"],"fr":["structure de projet","organisation de fichiers","développement de logiciel","projet scalable","appName","sources","tests","assets.xcassets","AI Agents"],"de":["projektstruktur","organisation von dateien","software-entwicklung","skalierbares projekt","appName","sources","tests","assets.xcassets","AI-Tools"],"pt":["estrutura de projeto","organização de arquivos","pastas sources","pastas tests","AppKit","Assets.xcassets","desenvolvimento de software","guias de projeto"],"ru":["структура проекта","организация файлов","папки sources","папки tests","AppKit","Assets.xcassets","разработка программного обеспечения","руководства по проекту"],"ar":["هيكل المشروع","تنظيم الملفات","مجلدات sources","مجلدات tests","AppKit","Assets.xcassets","تطوير البرمجيات","دلائل المشروع"]}},"owner":"vjr2005","repo":"Challenge","repoPath":"vjr2005/Challenge","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.719Z","topics":[],"category":"community","skillMd":{"name":"project-structure","description":"Project organization and directory structure. Use when creating features, organizing files, or understanding the codebase layout.","bodyPreview":"# Skill: Project Structure\n\nGuide for project organization and directory structure.\n\n## When to use this skill\n\n- Create a new feature module\n- Organize files correctly\n- Understand the codebase layout\n- Add extensions to existing types\n\n---\n\n## Project Overview\n\n```\n{AppName}/\n├── App/\n│   ├── Sources/\n│   │   ├── {AppName}App.swift        # Minimal entry point (imports AppKit)\n│   │   └── Resources/\n│   │       └── Assets.xcassets/\n│   └── Tests/\n│       └── UI/                       # UI test","body":"# Skill: Project Structure\n\nGuide for project organization and directory structure.\n\n## When to use this skill\n\n- Create a new feature module\n- Organize files correctly\n- Understand the codebase layout\n- Add extensions to existing types\n\n---\n\n## Project Overview\n\n```\n{AppName}/\n├── App/\n│   ├── Sources/\n│   │   ├── {AppName}App.swift        # Minimal entry point (imports AppKit)\n│   │   └── Resources/\n│   │       └── Assets.xcassets/\n│   └── Tests/\n│       └── UI/                       # UI tests only\n├── AppKit/                           # Testable app code (SPM local package)\n│   ├── Package.swift\n│   ├── Sources/\n│   │   ├── AppContainer.swift        # Composition Root (centralized DI)\n│   │   ├── Data/\n│   │   │   └── AppEnvironment+API.swift\n│   │   └── Presentation/\n│   │       ├── Navigation/\n│   │       │   └── AppNavigationRedirect.swift\n│   │       └── Views/\n│   │           └── RootContainerView.swift\n│   └── Tests/\n│       ├── Unit/                     # Unit tests\n│       ├── Snapshots/                # Snapshot tests\n│       └── Shared/                   # Shared resources\n├── Features/                         # Each feature is an SPM local package\n│   ├── {Feature}/\n│   │   ├── Package.swift\n│   │   └── ...\n│   └── Home/\n│       ├── Package.swift\n│       └── ...\n├── Libraries/                        # Each library is an SPM local package\n│   ├── Core/\n│   │   ├── Package.swift\n│   │   └── ...\n│   ├── Networking/\n│   ├── DesignSystem/\n│   └── SnapshotTestKit/\n├── Shared/\n│   └── Resources/\n│       ├── Package.swift\n│       └── ...\n├── Derived/                          # Generated by Tuist (gitignored)\n│   └── InfoPlists/\n├── Tuist/\n│   ├── ProjectDescriptionHelpers/\n│   └── Package.swift               # External SPM dependencies + target settings\n├── Project.swift                    # Root project (app + UI tests + module packages)\n├── Workspace.swift                  # Workspace configuration (code coverage)\n├── {AppName}.xctestplan            # Test plan aggregating all module test targets (SPM strategy only)\n├── Tuist.swift\n└── CLAUDE.md\n```\n\n**Key Architecture:**\n- **App**: Minimal entry point that imports `ChallengeAppKit`\n- **AppKit**: Framework containing testable app code (AppContainer, RootContainerView, AppNavigationRedirect). Tests run without TEST_HOST.\n\n---\n\n## Feature Naming\n\nFeature directory names must **not** contain the word \"Feature\". Use simple, descriptive names:\n\n```\n// RIGHT\nFeatures/User/\nFeatures/Character/\nFeatures/Home/\n\n// WRONG\nFeatures/UserFeature/\nFeatures/CharacterFeature/\n```\n\n---\n\n## Feature Module Structure\n\nEach feature module follows this internal structure:\n\n```\nFeatureName/\n├── Package.swift                            # SPM local package definition\n├── Sources/\n│   ├── {Feature}Feature.swift              # Public entry point (navigation + deep links)\n│   ├── {Feature}Container.swift            # Dependency composition (factories)\n│   ├── Domain/\n│   │   ├── Models/\n│   │   │   └── {Name}.swift                # Domain models\n│   │   ├── UseCases/\n│   │   │   └── Get{Name}UseCase.swift      # Business logic\n│   │   └── Repositories/\n│   │       └── {Name}RepositoryContract.swift  # Repository contracts\n│   ├── Data/\n│   │   ├── DataSources/\n│   │   │   ├── Remote/\n│   │   │   │   ├── {Name}RemoteDataSourceContract.swift\n│   │   │   │   └── {Name}RESTDataSource.swift\n│   │   │   └── Local/\n│   │   │       ├── {Name}LocalDataSourceContract.swift\n│   │   │       └── {Name}MemoryDataSource.swift\n│   │   ├── DTOs/\n│   │   │   └── {Name}DTO.swift\n│   │   ├── Mappers/\n│   │   │   └── {Name}Mapper.swift\n│   │   └── Repositories/\n│   │       └── {Name}Repository.swift\n│   └── Presentation/\n│       ├── Navigation/                             # Feature-level navigation (inside Presentation)\n│       │   ├── {Feature}IncomingNavigation.swift   # Navigation destinations\n│       │   ├── {Feature}OutgoingNavigation.swift   # Cross-feature navigation (optional)\n│       │   └── {Feature}DeepLinkHandler.swift      # Deep link handler\n│       ├── {Name}List/\n│       │   ├── Navigator/\n│       │   │   ├── {Name}ListNavigatorContract.swift\n│       │   │   └── {Name}ListNavigator.swift\n│       │   ├── Tracker/\n│       │   │   ├── {Name}ListTrackerContract.swift\n│       │   │   ├── {Name}ListTracker.swift\n│       │   │   └── {Name}ListEvent.swift\n│       │   ├── Views/\n│       │   │   └── {Name}ListView.swift\n│       │   └── ViewModels/\n│       │       ├── {Name}ListViewModel.swift\n│       │       └── {Name}ListViewState.swift\n│       └── {Name}Detail/\n│           ├── Navigator/\n│           │   ├── {Name}DetailNavigatorContract.swift\n│           │   └── {Name}DetailNavigator.swift\n│           ├── Tracker/\n│           │   ├── {Name}DetailTrackerContract.swift\n│           │   ├── {Name}DetailTracker.swift\n│           │   └── {Name}DetailEvent.swift\n│           ├── Views/\n│           │   └── {Name}DetailView.swift\n│           └── ViewModels/\n│               ├── {Name}DetailViewModel.swift\n│               └── {Name}DetailViewState.swift\n├── Tests/\n│   ├── Unit/                                # Unit tests (Swift Testing)\n│   │   ├── Domain/\n│   │   │   └── UseCases/\n│   │   │       └── Get{Name}UseCaseTests.swift\n│   │   ├── Data/\n│   │   │   ├── Repositories/\n│   │   │   │   └── {Name}RepositoryTests.swift\n│   │   ├── Presentation/\n│   │   │   ├── Navigation/\n│   │   │   │   └── {Feature}DeepLinkHandlerTests.swift\n│   │   │   └── {Name}List/\n│   │   │       └── ViewModels/\n│   │   │           └── {Name}ListViewModelTests.swift\n│   │   └── Feature/\n│   │       └── {Feature}FeatureTests.swift\n│   ├── Snapshots/                           # Snapshot tests (ChallengeSnapshotTestKit)\n│   │   └── Presentation/\n│   │       └── {Name}List/\n│   │           ├── {Name}ListViewSnapshotTests.swift\n│   │           └── __Snapshots__/\n│   └── Shared/                              # Shared resources\n│       ├── Stubs/\n│       │   └── {Name}+Stub.swift\n│       ├── Mocks/\n│       │   ├── Get{Name}UseCaseMock.swift\n│       │   └── {Name}RepositoryMock.swift\n│       ├── Fixtures/\n│       │   └── {name}.json\n│       ├── Extensions/\n│       │   └── {Name}ViewState+Equatable.swift\n│       └── Resources/\n│           └── test-avatar.jpg\n└── Mocks/                                   # Public mocks (if needed)\n    └── {Name}RepositoryMock.swift\n```\n\n---\n\n## Presentation Layer Organization\n\nThe Presentation layer groups related Views and ViewModels by feature name:\n\n```\nPresentation/\n├── CharacterDetail/            # Feature: Character detail screen\n│   ├── Navigator/\n│   │   ├── CharacterDetailNavigatorContract.swift\n│   │   └── CharacterDetailNavigator.swift\n│   ├── Tracker/\n│   │   ├── CharacterDetailTrackerContract.swift\n│   │   ├── CharacterDetailTracker.swift\n│   │   └── CharacterDetailEvent.swift\n│   ├── Views/\n│   │   └── CharacterDetailView.swift\n│   └── ViewModels/\n│       ├── CharacterDetailViewModel.swift\n│       └── CharacterDetailViewState.swift\n├── CharacterList/              # Feature: Character list screen\n│   ├── Navigator/\n│   │   ├── CharacterListNavigatorContract.swift\n│   │   └── CharacterListNavigator.swift\n│   ├── Tracker/\n│   │   ├── CharacterListTrackerContract.swift\n│   │   ├── CharacterListTracker.swift\n│   │   └── CharacterListEvent.swift\n│   ├── Views/\n│   │   └── CharacterListView.swift\n│   └── ViewModels/\n│       ├── CharacterListViewModel.swift\n│       └── CharacterListViewState.swift\n└── ...\n```\n\n**Naming conventions:**\n- Folder name matches the feature (e.g., `CharacterDetail`)\n- Navigator: `{Feature}Navigator.swift` and `{Feature}NavigatorContract.swift`\n- Tracker: `{Feature}Tracker.swift`, `{Feature}TrackerContract.swift`, and `{Feature}Event.swift`\n- View: `{Feature}View.swift`\n- ViewModel: `{Feature}ViewModel.swift`\n- ViewState: `{Feature}ViewState.swift`\n\n---\n\n## Extensions\n\nExtensions of external framework types (Foundation, UIKit, SwiftUI, etc.) must be placed in an `Extensions/` folder.\n\n### Location\n\n```\nSources/\n├── Extensions/\n│   ├── URL+QueryItems.swift\n│   ├── Date+Formatting.swift\n│   └── String+Validation.swift\n└── ...\n\nTests/\n├── Extensions/\n│   ├── URLSession+Mock.swift\n│   ├── HTTPURLResponse+Mock.swift\n│   └── URLRequest+BodyData.swift\n└── ...\n```\n\n### Naming Convention\n\n**Pattern:** `TypeName+Purpose.swift`\n\n```swift\n// URL+QueryItems.swift\nextension URL {\n    func appendingQueryItems(_ items: [URLQueryItem]) -> URL { ... }\n}\n\n// URLSession+Mock.swift (in Tests)\nextension URLSession {\n    static func mockSession() -> URLSession { ... }\n}\n\n// Date+Formatting.swift\nextension Date {\n    func formatted(style: DateFormatter.Style) -> String { ... }\n}\n```\n\n---\n\n## Tests Directory Structure\n\n```\nTests/\n├── Unit/                         # Unit tests (Swift Testing)\n│   ├── Domain/\n│   │   └── UseCases/\n│   │       └── Get{Name}UseCaseTests.swift\n│   ├── Data/\n│   │   ├── Repositories/\n│   │   │   └── {Name}RepositoryTests.swift\n│   │   └── DataSources/\n│   │       ├── Remote/\n│   │       │   └── {Name}RemoteDataSourceTests.swift\n│   │       └── Local/\n│   │           └── {Name}MemoryDataSourceTests.swift\n│   ├── Presentation/\n│   │   └── {ScreenName}/\n│   │       └── ViewModels/\n│   │           └── {ScreenName}ViewModelTests.swift\n│   └── Feature/\n│       └── {Feature}FeatureTests.swift\n├── Snapshots/                    # Snapshot tests (ChallengeSnapshotTestKit)\n│   └── Presentation/\n│       └── {ScreenName}/\n│           ├── {ScreenName}ViewSnapshotTests.swift\n│           └── __Snapshots__/\n├── UI/                           # UI tests (XCTest, App only)\n└── Shared/                       # Shared resources (used by Unit, Snapshots, and UI)\n    ├── Stubs/                    # Domain model test data\n    │   ├── Character+Stub.swift\n    │   └── Location+Stub.swift\n    ├── Mocks/                    # Internal test mocks\n    │   ├── Get{Name}UseCaseMock.swift\n    │   └── {Name}RepositoryMock.swift\n    ├── Fixtures/                 # JSON fixtures for DTOs\n    │   ├── character.json\n    │   └── character_list.json\n    ├── Extensions/               # Test helpers (Equatable, etc.)\n    │   └── {Name}ViewState+Equatable.swift\n    ├── Scenarios/                # Reusable SwiftMockServer configurations (UI tests)\n    │   └── UITestCase+Scenarios.swift\n    └── Resources/                # Test images\n        └── test-avatar.jpg\n```\n\n---\n\n## Mocks Location\n\n| Location | Visibility | Usage |\n|----------|------------|-------|\n| `Mocks/` (framework) | Public | Mocks used by other modules |\n| `Tests/Shared/Mocks/` | Internal | Mocks shared between Unit and Snapshot tests |\n\n```\nFeatureName/\n├── Mocks/                    # Public mocks ({AppName}FeatureNameMocks framework)\n│   └── {Name}RepositoryMock.swift\n└── Tests/\n    └── Shared/\n        └── Mocks/            # Internal test-only mocks\n            └── {Name}DataSourceMock.swift\n```\n\n---\n\n## Core Module\n\n```\nLibraries/Core/\n├── Sources/\n│   ├── AppEnvironment/\n│   │   └── AppEnvironment.swift      # Base environment enum\n│   ├── Feature/\n│   │   └── FeatureContract.swift      # Feature protocol\n│   ├── Navigation/\n│   │   ├── NavigationCoordinator.swift   # @Observable path manager\n│   │   ├── NavigatorContract.swift       # Navigation protocol\n│   │   ├── NavigationRedirectContract.swift\n│   │   ├── Navigation.swift              # Base navigation protocol\n│   │   ├── AnyNavigation.swift           # Type-erased wrapper\n│   │   └── DeepLinkHandler.swift\n│   ├── ImageLoader/\n│   │   ├── ImageLoaderContract.swift\n│   │   ├── CachedImageLoader.swift\n│   │   ├── ImageLoaderEnvironment.swift\n│   │   ├── DiskCache/\n│   │   │   ├── ImageDiskCacheContract.swift\n│   │   │   ├── ImageDiskCache.swift\n│   │   │   ├── DiskCacheConfiguration.swift\n│   │   │   ├── FileSystemContract.swift\n│   │   │   └── FileSystem.swift\n│   │   └── MemoryCache/\n│   │       ├── ImageMemoryCacheContract.swift\n│   │       └── ImageMemoryCache.swift\n│   ├── Tracking/\n│   │   ├── TrackerContract.swift\n│   │   ├── Tracker.swift\n│   │   ├── TrackingEventContract.swift\n│   │   └── Providers/\n│   │       ├── TrackingProviderContract.swift\n│   │       └── ConsoleTrackingProvider.swift\n│   └── Extensions/\n│       └── ...\n├── Tests/\n│   └── Unit/\n│       ├── AppEnvironment/\n│       │   └── AppEnvironmentTests.swift\n│       ├── Navigation/\n│       │   └── NavigationCoordinatorTests.swift\n│       └── Tracking/\n│           ├── TrackerTests.swift\n│           └── ConsoleTrackingProviderTests.swift\n└── Mocks/\n    ├── NavigatorMock.swift\n    ├── TrackerMock.swift\n    ├── ImageLoaderMock.swift\n    └── Bundle+JSON.swift\n```\n\n---\n\n## Networking Module\n\n```\nLibraries/Networking/\n├── Sources/\n│   ├── HTTP/\n│   │   ├── HTTPClient.swift\n│   │   ├── HTTPClientContract.swift\n│   │   ├── Endpoint.swift\n│   │   ├── HTTPMethod.swift\n│   │   └── HTTPError.swift\n├── Tests/\n│   └── Unit/\n└── Mocks/\n    └── HTTPClientMock.swift\n```\n\n---\n\n## Shared Directory\n\nThe `Shared/` directory contains app-specific modules (not reusable across apps).\n\n### Resources Module\n\n```\nShared/Resources/\n├── Package.swift\n├── Sources/\n│   ├── Extensions/\n│   │   └── String+Localized.swift    # localized() extension\n│   └── Resources/\n│       └── Localizable.xcstrings\n└── Tests/\n```\n\nThe Resources module provides:\n- **Localization**: Centralized `Localizable.xcstrings` and `String.localized()` extension\n- **Bundle.module**: Auto-generated by SPM for targets with resources\n\n---\n\n## Derived Directory\n\nTuist generates files in `Derived/` (gitignored):\n\n```\nDerived/\n└── InfoPlists/\n    ├── {AppName}-Info.plist\n    └── {AppName}UITests-Info.plist\n```\n\n**Contents:** Only `Info.plist` files for the app and UI tests targets. Module Info.plists are managed by SPM.\n\n**No generated Swift code:** `disableBundleAccessors` and `disableSynthesizedResourceAccessors` are enabled in `Project.swift`.\n\n---\n\n## App and AppKit Directories\n\nThe app code is split into two modules:\n- **App**: Minimal entry point with UI tests only\n- **AppKit**: Testable app code (unit and snapshot tests run here without TEST_HOST)\n\n```\nApp/\n├── Sources/\n│   ├── {AppName}App.swift        # Minimal entry point (imports AppKit)\n│   └── Resources/\n│       └── Assets.xcassets/\n│           ├── AppIcon.appiconset/        # Production icon\n│           ├── AppIconDev.appiconset/     # Development icon\n│           └── AppIconStaging.appiconset/ # Staging icon\n└── Tests/\n    ├── Shared/\n    │   ├── Robots/               # Robot pattern for UI interactions\n    │   ├── Scenarios/            # Reusable SwiftMockServer configurations\n    │   ├── Stubs/                # Test data helpers\n    │   ├── Fixtures/             # JSON fixtures\n    │   └── Resources/            # Test images\n    └── UI/                       # UI tests only (XCTest)\n\nAppKit/\n├── Sources/\n│   ├── AppContainer.swift        # Composition Root (centralized DI)\n│   ├── Data/\n│   │   └── AppEnvironment+API.swift  # API configuration extension\n│   └── Presentation/\n│       ├── Navigation/\n│       │   └── AppNavigationRedirect.swift\n│       └── Views/\n│           └── RootContainerView.swift    # Root view with navigation\n└── Tests/\n    ├── Unit/                     # Unit tests (Swift Testing)\n    │   ├── Data/\n    │   │   └── AppEnvironment+APITests.swift\n    │   └── Presentation/\n    │       └── Navigation/\n    │           ├── AppContainerNavigationTests.swift\n    │           └── AppNavigationRedirectTests.swift\n    ├── Snapshots/                # Snapshot tests\n    │   └── Presentation/\n    └── Shared/                   # Shared resources\n        └── Stubs/\n```\n\n**Why AppKit?** Unit and snapshot tests for app-level code can run without launching the app (no TEST_HOST required).\n\n---\n\n## File Naming Summary\n\n| Component | Naming Pattern | Example |\n|-----------|----------------|---------|\n| Feature folder | `{Name}/` | `Character/` |\n| Public entry | `{Feature}Feature.swift` | `CharacterFeature.swift` |\n| Container | `{Feature}Container.swift` | `CharacterContainer.swift` |\n| Navigation | `Presentation/Navigation/{Feature}IncomingNavigation.swift` | `Presentation/Navigation/CharacterIncomingNavigation.swift` |\n| Domain model | `{Name}.swift` | `Character.swift` |\n| DTO | `{Name}DTO.swift` | `CharacterDTO.swift` |\n| UseCase | `{Action}{Name}UseCase.swift` | `GetCharacterUseCase.swift` |\n| Repository | `{Name}Repository.swift` | `CharacterRepository.swift` |\n| Mapper | `{Name}Mapper.swift` | `CharacterMapper.swift` |\n| Contract | `{Name}Contract.swift` | `CharacterRepositoryContract.swift` |\n| DataSource Contract | `{Name}{Type}DataSourceContract.swift` | `CharacterRemoteDataSourceContract.swift` |\n| DataSource Implementation | `{Name}{Impl}DataSource.swift` | `CharacterRESTDataSource.swift`, `CharacterMemoryDataSource.swift` |\n| Navigator | `{ScreenName}Navigator.swift` | `CharacterDetailNavigator.swift` |\n| NavigatorContract | `{ScreenName}NavigatorContract.swift` | `CharacterDetailNavigatorContract.swift` |\n| Tracker | `{ScreenName}Tracker.swift` | `CharacterDetailTracker.swift` |\n| TrackerContract | `{ScreenName}TrackerContract.swift` | `CharacterDetailTrackerContract.swift` |\n| Event | `{ScreenName}Event.swift` | `CharacterDetailEvent.swift` |\n| View | `{ScreenName}View.swift` | `CharacterDetailView.swift` |\n| ViewModel | `{ScreenName}ViewModel.swift` | `CharacterDetailViewModel.swift` |\n| ViewState | `{ScreenName}ViewState.swift` | `CharacterDetailViewState.swift` |\n| Test | `{Component}Tests.swift` | `CharacterRepositoryTests.swift` |\n| Feature Test | `{Feature}FeatureTests.swift` | `CharacterFeatureTests.swift` |\n| Stub | `{Name}+Stub.swift` | `Character+Stub.swift` |\n| Mock | `{Name}Mock.swift` | `CharacterRepositoryMock.swift` |\n| Extension | `{Type}+{Purpose}.swift` | `URL+QueryItems.swift` |\n| Package definition | `Package.swift` | `Package.swift` |\n| JSON fixture | `{name}.json` | `character.json` |\n\n---\n\n## Checklist\n\n- [ ] App contains only `{AppName}App.swift` and UI tests (with Robots, Scenarios, Stubs, Fixtures)\n- [ ] AppKit contains testable code: `AppContainer.swift`, `RootContainerView.swift`, `AppNavigationRedirect.swift`\n- [ ] Feature folder does not contain \"Feature\" suffix\n- [ ] {Feature}Container.swift for dependency composition\n- [ ] {Feature}Feature.swift as public entry point with `makeMainView()` and `resolve()`\n- [ ] Sources organized by layer: Domain, Data, Presentation\n- [ ] Navigation folder inside `Presentation/Navigation/`\n- [ ] Presentation organized by screen: {ScreenName}/Navigator/, {ScreenName}/Tracker/, {ScreenName}/Views/, {ScreenName}/ViewModels/\n- [ ] Unit tests in `Tests/Unit/` mirroring Sources structure\n- [ ] Snapshot tests in `Tests/Snapshots/`\n- [ ] Feature tests in `Tests/Unit/Feature/`\n- [ ] Extensions in dedicated `Extensions/` folder\n- [ ] Extension files named `{Type}+{Purpose}.swift`\n- [ ] Public mocks in `Mocks/`, internal mocks in `Tests/Shared/Mocks/`\n- [ ] Stubs in `Tests/Shared/Stubs/`\n- [ ] JSON fixtures in `Tests/Shared/Fixtures/`\n- [ ] Test resources in `Tests/Shared/Resources/`\n- [ ] Module has its own `Package.swift` with source, mocks, and test targets\n- [ ] Module''s test target is included in the Dev scheme (Framework: via `testableTargets`, SPM: via `Challenge.xctestplan`)\n- [ ] Module''s target settings are configured in `Tuist/Package.swift`\n"},"lastSynced":"2026-03-07T02:46:52.102Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing comprehensive project organization and directory structure guidance.","zh":"非常适合需要全面项目组织和目录结构指导的代码分析代理。","ja":"コード分析エージェントが包括的なプロジェクトの組織化とディレクトリ構造のガイダンスを必要とする場合に最適です。","ko":"포괄적인 프로젝트 조직 및 디렉토리 구조 가이드가 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de Análisis de Código que necesitan una organización y orientación de estructura de proyecto y directorio integral.","fr":"Parfait pour les agents d''Analyse de Code ayant besoin d''une organisation et d''une orientation de structure de projet et de répertoire complet.","de":"Perfekt für Code-Analyse-Agents, die eine umfassende Projektorganisation und eine Verzeichnisstruktur-Anleitung benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de organização de projeto e orientação de estrutura de diretório abrangente.","ru":"Идеально подходит для агентов анализа кода, которым требуется всесторонняя организация проекта и руководство по структуре каталогов.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى تنظيم مشروع شامل وتوجيه هيكل الدليل."},"recommendation":{"en":"Empowers agents to create modular and scalable codebases using standardized directory layouts, facilitating the addition of new feature modules and extensions to existing types, while ensuring correct file organization and codebase layout understanding through AppKit and Assets.xcassets.","zh":"使代理能够创建模块化和可扩展的代码库，使用标准化的目录布局，方便添加新的功能模块和现有类型的扩展，同时通过AppKit和Assets.xcassets确保正确的文件组织和代码库布局理解。","ja":"エージェントがモジュール化され、スケーラブルなコードベースを作成できるようにし、標準化されたディレクトリレイアウトを使用して、新しい機能モジュールと既存のタイプの拡張を追加し、AppKitとAssets.xcassetsを通じて正しいファイルの組織化とコードベースレイアウトの理解を保証します。","ko":"에이전트가 모듈화되고 확장 가능한 코드베이스를 생성할 수 있도록 하여 표준화된 디렉토리 레이아웃을 사용하여 새로운 기능 모듈과 기존 유형의 확장 추가를 쉽게 하며, AppKit 및 Assets.xcassets를 통해 올바른 파일 조직 및 코드베이스 레이아웃 이해를 보장합니다.","es":"Habilita a los agentes a crear bases de código modulares y escalables utilizando diseños de directorio estandarizados, lo que facilita la adición de nuevos módulos de características y extensiones a los tipos existentes, mientras garantiza la organización correcta de archivos y la comprensión del diseño de la base de código a través de AppKit y Assets.xcassets.","fr":"Permet aux agents de créer des bases de code modulaires et évolutives en utilisant des dispositions de répertoire standardisées, ce qui facilite l''ajout de nouveaux modules de fonctionnalités et d''extensions aux types existants, tout en garantissant une organisation correcte des fichiers et une compréhension du layout de la base de code via AppKit et Assets.xcassets.","de":"Ermöglicht es den Agents, modulare und skalierbare Codebasen unter Verwendung standardisierter Verzeichnislayouts zu erstellen, wodurch die Hinzufügung neuer Feature-Module und Erweiterungen zu bestehenden Typen erleichtert wird, während die korrekte Dateiorganisation und das Verständnis des Codebase-Layouts durch AppKit und Assets.xcassets gewährleistet werden.","pt":"Habilita os agentes a criar repositórios de código modulares e escaláveis usando layouts de diretório padronizados, facilitando a adição de novos módulos de recursos e extensões a tipos existentes, garantindo a organização correta de arquivos e compreensão do layout do repositório de código por meio do AppKit e Assets.xcassets.","ru":"Наделяет агентов возможностью создавать модульные и масштабируемые базы кода с использованием стандартизированных макетов каталогов, облегчая добавление новых модулей функций и расширений к существующим типам, обеспечивая при этом правильную организацию файлов и понимание структуры базы кода через AppKit и Assets.xcassets.","ar":"يمنح الوكيل khảية إنشاء قواعد شفرة قابلة للتوسيع ومدروسة باستخدام تخطيطات دليل معيارية، وتسهيل إضافة وحدات ميزات جديدة وتوسيعات إلى أنواع موجودة، مع ضمان تنظيم الملفات بشكل صحيح وفهم تخطيط قاعدة الشفرة من خلال AppKit و Assets.xcassets."},"useCases":{"en":["Organizing files and directories for a new feature module","Creating a modular and scalable codebase structure","Understanding and navigating existing codebase layouts"],"zh":["为新的功能模块组织文件和目录","创建模块化和可扩展的代码库结构","了解和导航现有的代码库布局"],"ja":["新しい機能モジュールのファイルとディレクトリを整理する","モジュール化され、スケーラブルなコードベース構造を作成する","既存のコードベースレイアウトを理解し、ナビゲートする"],"ko":["새로운 기능 모듈의 파일과 디렉토리를 조직화하는 것","모듈화되고 확장 가능한 코드베이스 구조를 생성하는 것","기존의 코드베이스 레이아웃을 이해하고 탐색하는 것"],"es":["Organizar archivos y directorios para un nuevo módulo de características","Crear una estructura de base de código modular y escalable","Comprender y navegar por diseños de base de código existentes"],"fr":["Organiser des fichiers et des répertoires pour un nouveau module de fonctionnalités","Créer une structure de base de code modulaire et évutive","Comprendre et naviguer dans les dispositions de base de code existantes"],"de":["Dateien und Verzeichnisse für ein neues Feature-Modul organisieren","Eine modulare und skalierbare Codebasis-Struktur erstellen","Existierende Codebasis-Layouts verstehen und navigieren"],"pt":["Organizar arquivos e diretórios para um novo módulo de recurso","Criar uma estrutura de repositório de código modular e escalável","Compreender e navegar por layouts de repositório de código existentes"],"ru":["Организация файлов и каталогов для нового модуля функций","Создание модульной и масштабируемой структуры базы кода","Понимание и навигация по существующим макетам базы кода"],"ar":["تنظيم الملفات والدلائل لموديل ميزة جديد","إنشاء هيكل قاعدة شفرة قابلة للتوسيع ومدروس","فهم وتحريك تخطيطات قاعدة الشفرة الموجودة"]},"limitations":{"en":["Requires knowledge of AppKit and Assets.xcassets","Specific to Swift-based projects"],"zh":["需要了解AppKit和Assets.xcassets","特定于Swift 기반项目"],"ja":["AppKitとAssets.xcassetsの知識が必要","Swiftベースのプロジェクトに特有"],"ko":["AppKit 및 Assets.xcassets에 대한 지식이 필요","Swift 기반 프로젝트에 특정"],"es":["Requiere conocimiento de AppKit y Assets.xcassets","Específico para proyectos basados en Swift"],"fr":["Nécessite des connaissances en AppKit et Assets.xcassets","Spécifique aux projets basés sur Swift"],"de":["Benötigt Kenntnisse von AppKit und Assets.xcassets","Spezifisch für Swift-basierte Projekte"],"pt":["Exige conhecimento de AppKit e Assets.xcassets","Específico para projetos baseados em Swift"],"ru":["Требует знания AppKit и Assets.xcassets","Специфичен для проектов на основе Swift"],"ar":["يتطلب معرفة AppKit و Assets.xcassets","محدد لمشاريع مبنية على Swift"]},"version":4},"contentHash":"fea979d9ac32d41702dc3e9216c43836e931f4838d324d9417bd9a9b67c8fdc7","qualityScore":51}');
