INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('guidodinello/claude-dotfiles/writing-react-effects', 'writing-react-effects', 'guidodinello', 'claude-dotfiles', 'community', 'writing-react-effects guidodinello claude-dotfiles community The writing-react-effects skill guides developers in writing efficient React components that avoid unnecessary useEffect calls, ideal for AI agents and external system integrations. Writing React Effects帮助开发者编写高效的React组件，避免不必要的useEffect调用 Writing React Effectsは、ReactコンポーネントのuseEffect呼び出しを最適化するためのベストプラクティスを提供する Writing React Effects는 개발자가 효율적인 React 컴포넌트를 작성하도록 도와주며 불필요한 useEffect 호출을 피할 수 있다 La habilidad de escritura de efectos de React ayuda a evitar llamadas innecesarias a useEffect. Aprende a sincronizar con sistemas externos de manera efectiva La compétence d''écriture d''effets React aide à éviter les appels inutiles à useEffect. Apprenez à synchroniser avec des systèmes externes de manière efficace Die Fähigkeit zum Schreiben von React-Effekten hilft, unnötige useEffect-Aufrufe zu vermeiden. Erfahren Sie, wie Sie mit externen Systemen effektiv synchronisieren O skill writing-react-effects ajuda a escrever componentes React que evitam chamadas desnecessárias ao useEffect, melhorando o desempenho da aplicação Навык writing-react-effects помогает писать компоненты React, которые избегают ненужных вызовов useEffect, улучшая производительность приложения для ИИ Агентов تمكّن مهارة writing-react-effects من كتابة مكونات React التي تتجنب الدعوات غير الضرورية إلى useEffect، مما يحسن أداء التطبيق how to use writing-react-effects writing-react-effects setup guide writing-react-effects vs react-hooks what is writing-react-effects writing-react-effects install writing-react-effects alternative react effects optimization useEffect best practices writing-react-effects tutorial Writing React Effects React组件优化 useEffect调用优化 外部系统同步 AIエージェント React开发最佳实践 Provides decision flowcharts for determining when to use useEffect Guides synchronization with external systems like WebSockets and browser APIs Helps avoid unnecessary useEffect calls for better performance Supports optimization of React components for AI agents Offers best practices for using useEffect with third-party widgets Includes examples for WebSocket and browser API subscription writing-react-effects is a skill that helps developers write React components with optimized useEffect calls for synchronizing with external systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('akrk1986/youtube-download/python-type-safety', 'community', 'akrk1986', 'youtube-download', 'akrk1986/youtube-download', 'python-type-safety', 0, 0, 51, '2026-03-05T10:24:12Z', '2026-03-07T13:11:42.812Z', '35dee544eeda5a8cc9844d60615a51a7d0c4870004039ea5064e1618b2f53e56', '{"id":"akrk1986/youtube-download/python-type-safety","name":"python-type-safety","description":{"en":"Python-type-safety helps developers catch errors at static analysis time by leveraging Python''s type system. It benefits developers working on large-scale projects or building type-safe APIs and libraries.","zh":"Python类型安全是通过类型注释和静态分析来捕获错误的方法。它可以帮助开发者创建更可靠和可维护的代码","ja":"Python Type Safetyは、タイプヒントと静的分析を使用してエラーを捕捉する方法です。より信頼性の高いコードを作成するのに役立ちます","ko":"파이썬 타입 안전성은 타입 주석과 정적 분석을 통해 오류를 捕获하는 방법입니다. 더 신뢰할 수 있는 코드를 생성하는 데 도움이 됩니다","es":"La seguridad de tipos de Python te permite detectar errores en tiempo de análisis estático. Utiliza anotaciones de tipos para crear código más seguro y mantenible","fr":"La sécurité de types Python vous permet de détecter les erreurs au moment de l''analyse statique. Utilisez des annotations de types pour créer un code plus sûr et plus maintenable","de":"Die Typsicherheit von Python ermöglicht es Ihnen, Fehler in der statischen Analyse zu erkennen. Verwenden Sie Typannotierungen, um sichereren und wartbaren Code zu erstellen","pt":"A segurança de tipo Python é uma técnica para detectar erros em tempo de análise estática, melhorando a qualidade do código. Aprenda a usá-la com type hints e mypy","ru":"Безопасность типов Python - это техника для обнаружения ошибок на этапе статического анализа, улучшающая качество кода. Узнайте, как использовать ее с помощью type hints и mypy","ar":"أمان النوع بايثون هو تقنية لتحديد الأخطاء في وقت التحليل الساكن، مما ي cảiر جودة الكود. تعلم كيفية استخدامها مع type hints و mypy"},"seo":{"title":{"en":"python-type-safety: Type Hinting Setup Guide | AI Agent S...","zh":"Python类型安全设置指南","ja":"Python Type Safety のベストプラクティス","ko":"파이썬 타입 안전성 구현 가이드","es":"Guía de configuración de seguridad de tipos Python","fr":"Guide de mise en place de la sécurité de types Python","de":"Leitfaden für Python-Typensicherheit-Setup","pt":"Guia de Configuração de Segurança de Tipo Python","ru":"ИИ Агенты: Руководство по Безопасности Типов Python","ar":"دليل الإعداد لأمان النوع بايثون"},"description":{"en":"Discover how to leverage Python''s type system with python-type-safety. Learn to catch errors at static analysis time and improve your code quality - get star...","zh":"了解Python类型安全的核心概念，包括类型注释、泛型类和协议，并学习如何配置mypy或pyright进行严格检查","ja":"Python Type Safetyの基本概念、タイプヒント、ジェネリッククラス、プロトコルについて学び、mypyまたはpyrightを使用した厳格なチェックの設定方法をマスターしましょう","ko":"파이썬 타입 안전성의 핵심 개념을 이해하고, 타입 주석, 제네릭 클래스, 프로토콜을 학습하며, mypy 또는 pyright를 사용한 엄격한 검사 설정 방법을 익히세요","es":"Aprende a utilizar la seguridad de tipos de Python para detectar errores en tiempo de análisis estático y mejora la calidad de tu código","fr":"Découvrez comment utiliser la sécurité de types Python pour détecter les erreurs au moment de l''analyse statique et améliorer la qualité de votre code","de":"Erfahren Sie, wie Sie die Typsicherheit von Python nutzen können, um Fehler in der statischen Analyse zu erkennen und die Code-Qualität zu verbessern","pt":"Aprenda a usar a segurança de tipo Python para detectar erros em tempo de análise estática e melhorar a qualidade do seu código","ru":"Используйте безопасность типов Python, чтобы обнаруживать ошибки на этапе статического анализа и улучшать качество вашего кода с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام أمان النوع بايثون لتحديد الأخطاء في وقت التحليل الساكن وتحسين جودة كودك"},"definition":{"en":"python-type-safety is a skill that enables developers to utilize Python''s type annotations for enforced documentation and automatic validation by tooling like mypy or pyright.","zh":"Python类型安全是一种通过类型注释和静态分析来确保代码正确性和可靠性的方法","ja":"Python Type Safetyは、タイプヒントと静的分析を使用してコードの正しさと信頼性を保証する方法です","ko":"파이썬 타입 안전성은 타입 주석과 정적 분석을 사용하여 코드의 정확성과 신뢰성을 보장하는 방법입니다","es":"La seguridad de tipos de Python es una característica que permite detectar errores en tiempo de análisis estático mediante anotaciones de tipos","fr":"La sécurité de types Python est une fonctionnalité qui permet de détecter les erreurs au moment de l''analyse statique grâce aux annotations de types","de":"Die Typsicherheit von Python ist eine Funktion, die es ermöglicht, Fehler in der statischen Analyse zu erkennen, indem Typannotierungen verwendet werden","pt":"Segurança de tipo Python é uma técnica de programação que usa anotações de tipo para detectar erros em tempo de análise estática","ru":"Безопасность типов Python - это техника программирования, использующая аннотации типов для обнаружения ошибок на этапе статического анализа","ar":"أمان النوع بايثون هو تقنية برمجة تستخدم التعليقات النوعية لتحديد الأخطاء في وقت التحليل الساكن"},"features":{"en":["Adding type hints to existing code for better maintainability","Creating generic, reusable classes with protocols","Defining structural interfaces with protocols for strict checking","Configuring mypy or pyright for strict type checking","Understanding type narrowing and guards for improved code quality","Building type-safe APIs and libraries with Python''s type system"],"zh":["类型注释","泛型类","协议","mypy或pyright配置","类型缩小和守卫","类型安全API和库"],"ja":["タイプヒント","ジェネリッククラス","プロトコル","mypyまたはpyrightの設定","タイプナロウイングとガード","タイプセーフAPIとライブラリ"],"ko":["타입 주석","제네릭 클래스","프로토콜","mypy 또는 pyright 설정","타입 좁히기와 가드","타입 안전 API와 라이브러리"],"es":["Anotaciones de tipos para código más seguro","Comprobación estricta con mypy o pyright","Creación de clases genéricas y reutilizables","Definición de interfaces estructurales con protocolos","Comprensión de la reducción de tipos y guarda","Construcción de API y bibliotecas seguras"],"fr":["Annotations de types pour un code plus sûr","Vérification stricte avec mypy ou pyright","Création de classes génériques et réutilisables","Définition d''interfaces structurelles avec des protocoles","Compréhension de la réduction de types et de la garde","Conception d''API et de bibliothèques sécurisées"],"de":["Typannotierungen für sichereren Code","Strenger Check mit mypy oder pyright","Erstellung von generischen und wiederverwendbaren Klassen","Definition von strukturellen Schnittstellen mit Protokollen","Verständnis von Typverengung und Wächter","Erstellung von sicheren APIs und Bibliotheken"],"pt":["Adicionar type hints ao código existente","Criar classes genéricas e reutilizáveis","Definir interfaces estruturais com protocols","Configurar mypy ou pyright para verificação estrita","Entender type narrowing e guards","Construir APIs e bibliotecas seguras com tipos"],"ru":["Добавление type hints к существующему коду","Создание.generic и многоразовых классов","Определение структурных интерфейсов с помощью protocols","Настройка mypy или pyright для строгой проверки","Понимание type narrowing и guards","Создание безопасных API и библиотек с помощью типов"],"ar":["إضافة type hints إلى الكود الحالي","إنشاء فئات عامة ويمكن إعادة استخدامها","تحديد واجهات بنية باستخدام بروتوكولات","تهيئة mypy أو pyright للتحقق الصارم","فهم type narrowing و guards","بناء واجهات برمجة تطبيقات وأدوات seguro مع أنواع"]},"keywords":{"en":["how to use python-type-safety","python-type-safety setup guide","what is python-type-safety","python-type-safety vs mypy","python-type-safety alternative to pyright","python-type-safety install","python type hinting best practices","python type safety tutorial","python type checking tools"],"zh":["Python类型安全","类型注释","泛型类","协议","mypy","pyright","类型安全","代码质量","静态分析"],"ja":["Python Type Safety","タイプヒント","ジェネリッククラス","プロトコル","mypy","pyright","タイプセーフ","コード品質","静的分析"],"ko":["파이썬 타입 안전성","타입 주석","제네릭 클래스","프로토콜","mypy","pyright","타입 안전","코드 품질","정적 분석"],"es":["seguridad de tipos python","anotaciones de tipos","mypy","pyright","clases genéricas","protocolos","reducción de tipos","guarda","api seguras","bibliotecas seguras"],"fr":["sécurité de types python","annotations de types","mypy","pyright","classes génériques","protocoles","réduction de types","garde","api sécurisées","bibliothèques sécurisées"],"de":["typsicherheit python","typannotierungen","mypy","pyright","generische klassen","protokolle","typverengung","wächter","sichere api","sichere bibliotheken"],"pt":["segurança de tipo python","type hints","mypy","pyright","análise estática","qualidade de código","programação python","desenvolvimento de software"],"ru":["безопасность типов python","type hints","mypy","pyright","статический анализ","качество кода","программирование на python","разработка программного обеспечения"],"ar":["أمان النوع بايثون","type hints","mypy","pyright","التحليل الساكن","جودة الكود","برمجة بايثون","تطوير البرمجيات"]}},"owner":"akrk1986","repo":"youtube-download","repoPath":"akrk1986/youtube-download","stars":0,"forks":0,"updatedAt":"2026-03-05T10:24:12Z","topics":[],"category":"community","skillMd":{"name":"python-type-safety","description":"Python type safety with type hints, generics, protocols, and strict type checking. Use when adding type annotations, implementing generic classes, defining structural interfaces, or configuring mypy/pyright.","bodyPreview":"# Python Type Safety\n\nLeverage Python''s type system to catch errors at static analysis time. Type annotations serve as enforced documentation that tooling validates automatically.\n\n## When to Use This Skill\n\n- Adding type hints to existing code\n- Creating generic, reusable classes\n- Defining structural interfaces with protocols\n- Configuring mypy or pyright for strict checking\n- Understanding type narrowing and guards\n- Building type-safe APIs and libraries\n\n## Core Concepts\n\n### 1. Type Annotat","body":"# Python Type Safety\n\nLeverage Python''s type system to catch errors at static analysis time. Type annotations serve as enforced documentation that tooling validates automatically.\n\n## When to Use This Skill\n\n- Adding type hints to existing code\n- Creating generic, reusable classes\n- Defining structural interfaces with protocols\n- Configuring mypy or pyright for strict checking\n- Understanding type narrowing and guards\n- Building type-safe APIs and libraries\n\n## Core Concepts\n\n### 1. Type Annotations\n\nDeclare expected types for function parameters, return values, and variables.\n\n### 2. Generics\n\nWrite reusable code that preserves type information across different types.\n\n### 3. Protocols\n\nDefine structural interfaces without inheritance (duck typing with type safety).\n\n### 4. Type Narrowing\n\nUse guards and conditionals to narrow types within code blocks.\n\n## Quick Start\n\n```python\ndef get_user(user_id: str) -> User | None:\n    \"\"\"Return type makes ''might not exist'' explicit.\"\"\"\n    ...\n\n# Type checker enforces handling None case\nuser = get_user(\"123\")\nif user is None:\n    raise UserNotFoundError(\"123\")\nprint(user.name)  # Type checker knows user is User here\n```\n\n## Fundamental Patterns\n\n### Pattern 1: Annotate All Public Signatures\n\nEvery public function, method, and class should have type annotations.\n\n```python\ndef get_user(user_id: str) -> User:\n    \"\"\"Retrieve user by ID.\"\"\"\n    ...\n\ndef process_batch(\n    items: list[Item],\n    max_workers: int = 4,\n) -> BatchResult[ProcessedItem]:\n    \"\"\"Process items concurrently.\"\"\"\n    ...\n\nclass UserRepository:\n    def __init__(self, db: Database) -> None:\n        self._db = db\n\n    async def find_by_id(self, user_id: str) -> User | None:\n        \"\"\"Return User if found, None otherwise.\"\"\"\n        ...\n\n    async def find_by_email(self, email: str) -> User | None:\n        ...\n\n    async def save(self, user: User) -> User:\n        \"\"\"Save and return user with generated ID.\"\"\"\n        ...\n```\n\nUse `mypy --strict` or `pyright` in CI to catch type errors early. For existing projects, enable strict mode incrementally using per-module overrides.\n\n### Pattern 2: Use Modern Union Syntax\n\nPython 3.10+ provides cleaner union syntax.\n\n```python\n# Preferred (3.10+)\ndef find_user(user_id: str) -> User | None:\n    ...\n\ndef parse_value(v: str) -> int | float | str:\n    ...\n\n# Older style (still valid, needed for 3.9)\nfrom typing import Optional, Union\n\ndef find_user(user_id: str) -> Optional[User]:\n    ...\n```\n\n### Pattern 3: Type Narrowing with Guards\n\nUse conditionals to narrow types for the type checker.\n\n```python\ndef process_user(user_id: str) -> UserData:\n    user = find_user(user_id)\n\n    if user is None:\n        raise UserNotFoundError(f\"User {user_id} not found\")\n\n    # Type checker knows user is User here, not User | None\n    return UserData(\n        name=user.name,\n        email=user.email,\n    )\n\ndef process_items(items: list[Item | None]) -> list[ProcessedItem]:\n    # Filter and narrow types\n    valid_items = [item for item in items if item is not None]\n    # valid_items is now list[Item]\n    return [process(item) for item in valid_items]\n```\n\n### Pattern 4: Generic Classes\n\nCreate type-safe reusable containers.\n\n```python\nfrom typing import TypeVar, Generic\n\nT = TypeVar(\"T\")\nE = TypeVar(\"E\", bound=Exception)\n\nclass Result(Generic[T, E]):\n    \"\"\"Represents either a success value or an error.\"\"\"\n\n    def __init__(\n        self,\n        value: T | None = None,\n        error: E | None = None,\n    ) -> None:\n        if (value is None) == (error is None):\n            raise ValueError(\"Exactly one of value or error must be set\")\n        self._value = value\n        self._error = error\n\n    @property\n    def is_success(self) -> bool:\n        return self._error is None\n\n    @property\n    def is_failure(self) -> bool:\n        return self._error is not None\n\n    def unwrap(self) -> T:\n        \"\"\"Get value or raise the error.\"\"\"\n        if self._error is not None:\n            raise self._error\n        return self._value  # type: ignore[return-value]\n\n    def unwrap_or(self, default: T) -> T:\n        \"\"\"Get value or return default.\"\"\"\n        if self._error is not None:\n            return default\n        return self._value  # type: ignore[return-value]\n\n# Usage preserves types\ndef parse_config(path: str) -> Result[Config, ConfigError]:\n    try:\n        return Result(value=Config.from_file(path))\n    except ConfigError as e:\n        return Result(error=e)\n\nresult = parse_config(\"config.yaml\")\nif result.is_success:\n    config = result.unwrap()  # Type: Config\n```\n\n## Advanced Patterns\n\n### Pattern 5: Generic Repository\n\nCreate type-safe data access patterns.\n\n```python\nfrom typing import TypeVar, Generic\nfrom abc import ABC, abstractmethod\n\nT = TypeVar(\"T\")\nID = TypeVar(\"ID\")\n\nclass Repository(ABC, Generic[T, ID]):\n    \"\"\"Generic repository interface.\"\"\"\n\n    @abstractmethod\n    async def get(self, id: ID) -> T | None:\n        \"\"\"Get entity by ID.\"\"\"\n        ...\n\n    @abstractmethod\n    async def save(self, entity: T) -> T:\n        \"\"\"Save and return entity.\"\"\"\n        ...\n\n    @abstractmethod\n    async def delete(self, id: ID) -> bool:\n        \"\"\"Delete entity, return True if existed.\"\"\"\n        ...\n\nclass UserRepository(Repository[User, str]):\n    \"\"\"Concrete repository for Users with string IDs.\"\"\"\n\n    async def get(self, id: str) -> User | None:\n        row = await self._db.fetchrow(\n            \"SELECT * FROM users WHERE id = $1\", id\n        )\n        return User(**row) if row else None\n\n    async def save(self, entity: User) -> User:\n        ...\n\n    async def delete(self, id: str) -> bool:\n        ...\n```\n\n### Pattern 6: TypeVar with Bounds\n\nRestrict generic parameters to specific types.\n\n```python\nfrom typing import TypeVar\nfrom pydantic import BaseModel\n\nModelT = TypeVar(\"ModelT\", bound=BaseModel)\n\ndef validate_and_create(model_cls: type[ModelT], data: dict) -> ModelT:\n    \"\"\"Create a validated Pydantic model from dict.\"\"\"\n    return model_cls.model_validate(data)\n\n# Works with any BaseModel subclass\nclass User(BaseModel):\n    name: str\n    email: str\n\nuser = validate_and_create(User, {\"name\": \"Alice\", \"email\": \"a@b.com\"})\n# user is typed as User\n\n# Type error: str is not a BaseModel subclass\nresult = validate_and_create(str, {\"name\": \"Alice\"})  # Error!\n```\n\n### Pattern 7: Protocols for Structural Typing\n\nDefine interfaces without requiring inheritance.\n\n```python\nfrom typing import Protocol, runtime_checkable\n\n@runtime_checkable\nclass Serializable(Protocol):\n    \"\"\"Any class that can be serialized to/from dict.\"\"\"\n\n    def to_dict(self) -> dict:\n        ...\n\n    @classmethod\n    def from_dict(cls, data: dict) -> \"Serializable\":\n        ...\n\n# User satisfies Serializable without inheriting from it\nclass User:\n    def __init__(self, id: str, name: str) -> None:\n        self.id = id\n        self.name = name\n\n    def to_dict(self) -> dict:\n        return {\"id\": self.id, \"name\": self.name}\n\n    @classmethod\n    def from_dict(cls, data: dict) -> \"User\":\n        return cls(id=data[\"id\"], name=data[\"name\"])\n\ndef serialize(obj: Serializable) -> str:\n    \"\"\"Works with any Serializable object.\"\"\"\n    return json.dumps(obj.to_dict())\n\n# Works - User matches the protocol\nserialize(User(\"1\", \"Alice\"))\n\n# Runtime checking with @runtime_checkable\nisinstance(User(\"1\", \"Alice\"), Serializable)  # True\n```\n\n### Pattern 8: Common Protocol Patterns\n\nDefine reusable structural interfaces.\n\n```python\nfrom typing import Protocol\n\nclass Closeable(Protocol):\n    \"\"\"Resource that can be closed.\"\"\"\n    def close(self) -> None: ...\n\nclass AsyncCloseable(Protocol):\n    \"\"\"Async resource that can be closed.\"\"\"\n    async def close(self) -> None: ...\n\nclass Readable(Protocol):\n    \"\"\"Object that can be read from.\"\"\"\n    def read(self, n: int = -1) -> bytes: ...\n\nclass HasId(Protocol):\n    \"\"\"Object with an ID property.\"\"\"\n    @property\n    def id(self) -> str: ...\n\nclass Comparable(Protocol):\n    \"\"\"Object that supports comparison.\"\"\"\n    def __lt__(self, other: \"Comparable\") -> bool: ...\n    def __le__(self, other: \"Comparable\") -> bool: ...\n```\n\n### Pattern 9: Type Aliases\n\nCreate meaningful type names.\n\n**Note:** The `type` statement was introduced in Python 3.10 for simple aliases. Generic type statements require Python 3.12+.\n\n```python\n# Python 3.10+ type statement for simple aliases\ntype UserId = str\ntype UserDict = dict[str, Any]\n\n# Python 3.12+ type statement with generics\ntype Handler[T] = Callable[[Request], T]\ntype AsyncHandler[T] = Callable[[Request], Awaitable[T]]\n\n# Python 3.9-3.11 style (needed for broader compatibility)\nfrom typing import TypeAlias\nfrom collections.abc import Callable, Awaitable\n\nUserId: TypeAlias = str\nHandler: TypeAlias = Callable[[Request], Response]\n\n# Usage\ndef register_handler(path: str, handler: Handler[Response]) -> None:\n    ...\n```\n\n### Pattern 10: Callable Types\n\nType function parameters and callbacks.\n\n```python\nfrom collections.abc import Callable, Awaitable\n\n# Sync callback\nProgressCallback = Callable[[int, int], None]  # (current, total)\n\n# Async callback\nAsyncHandler = Callable[[Request], Awaitable[Response]]\n\n# With named parameters (using Protocol)\nclass OnProgress(Protocol):\n    def __call__(\n        self,\n        current: int,\n        total: int,\n        *,\n        message: str = \"\",\n    ) -> None: ...\n\ndef process_items(\n    items: list[Item],\n    on_progress: ProgressCallback | None = None,\n) -> list[Result]:\n    for i, item in enumerate(items):\n        if on_progress:\n            on_progress(i, len(items))\n        ...\n```\n\n## Configuration\n\n### Strict Mode Checklist\n\nFor `mypy --strict` compliance:\n\n```toml\n# pyproject.toml\n[tool.mypy]\npython_version = \"3.12\"\nstrict = true\nwarn_return_any = true\nwarn_unused_ignores = true\ndisallow_untyped_defs = true\ndisallow_incomplete_defs = true\nno_implicit_optional = true\n```\n\nIncremental adoption goals:\n- All function parameters annotated\n- All return types annotated\n- Class attributes annotated\n- Minimize `Any` usage (acceptable for truly dynamic data)\n- Generic collections use type parameters (`list[str]` not `list`)\n\nFor existing codebases, enable strict mode per-module using `# mypy: strict` or configure per-module overrides in `pyproject.toml`.\n\n## Best Practices Summary\n\n1. **Annotate all public APIs** - Functions, methods, class attributes\n2. **Use `T | None`** - Modern union syntax over `Optional[T]`\n3. **Run strict type checking** - `mypy --strict` in CI\n4. **Use generics** - Preserve type info in reusable code\n5. **Define protocols** - Structural typing for interfaces\n6. **Narrow types** - Use guards to help the type checker\n7. **Bound type vars** - Restrict generics to meaningful types\n8. **Create type aliases** - Meaningful names for complex types\n9. **Minimize `Any`** - Use specific types or generics. `Any` is acceptable for truly dynamic data or when interfacing with untyped third-party code\n10. **Document with types** - Types are enforceable documentation"},"lastSynced":"2026-03-07T13:11:42.812Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing robust type checking and code validation.","zh":"非常适合需要强大的类型检查和代码验证的Python开发代理。","ja":"Python開発エージェントが堅牢な型チェックとコード検証を必要とする場合に最適です。","ko":"강력한 타입 검사 및 코드 검증이 필요한 Python 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de Python que necesitan una comprobación de tipo robusta y validación de código.","fr":"Parfait pour les agents de développement Python ayant besoin d''une vérification de type robuste et de validation de code.","de":"Perfekt für Python-Entwicklungsagenten, die eine robuste Typüberprüfung und Codevalidierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que precisam de verificação de tipo robusta e validação de código.","ru":"Идеально для агентов разработки Python, которым необходима надежная проверка типов и валидация кода.","ar":"مثالي لعميل تطوير بايثون الذي يحتاج إلى التحقق من النوع القوي وvalidation الكود."},"recommendation":{"en":"Empowers agents to leverage Python''s type system for static analysis, utilizing tools like mypy or pyright for strict type checking and ensuring the creation of type-safe APIs and libraries with protocols and generic classes.","zh":"赋予代理使用Python的类型系统进行静态分析，利用mypy或pyright等工具进行严格的类型检查，确保使用协议和泛型类创建类型安全的API和库。","ja":"エージェントがPythonの型システムを使用して静的分析を実行できるようにし、mypyまたはpyrightなどのツールを使用して厳格な型チェックを行い、プロトコルとジェネリッククラスを使用して型安全なAPIとライブラリを作成することを保証します。","ko":"에이전트가 Python의 유형 시스템을 사용하여 정적 분석을 수행할 수 있도록 하며, mypy 또는 pyright와 같은 도구를 사용하여 엄격한 유형 검사를 수행하고, 프로토콜 및 제네릭 클래스를 사용하여 유형 안전한 API 및 라이브러리를 생성하는 것을 보장합니다.","es":"Habilita a los agentes a aprovechar el sistema de tipos de Python para análisis estático, utilizando herramientas como mypy o pyright para una comprobación de tipo estricta y garantizando la creación de APIs y bibliotecas seguras con protocolos y clases genéricas.","fr":"Permet aux agents d''exploiter le système de types Python pour l''analyse statique, en utilisant des outils comme mypy ou pyright pour une vérification de type stricte et en garantissant la création d''API et de bibliothèques sécurisées avec des protocoles et des classes génériques.","de":"Ermöglicht es Agenten, Pythons Typsystem für statische Analyse zu nutzen, indem Tools wie mypy oder pyright für eine strenge Typüberprüfung verwendet werden und die Erstellung von typsicheren APIs und Bibliotheken mit Protokollen und generischen Klassen gewährleistet.","pt":"Habilita os agentes a aproveitar o sistema de tipos do Python para análise estática, utilizando ferramentas como mypy ou pyright para verificação de tipo estrita e garantindo a criação de APIs e bibliotecas seguras com protocolos e classes genéricas.","ru":"Позволяет агентам использовать систему типов Python для статического анализа, используя инструменты seperti mypy или pyright для строгой проверки типов и обеспечивая создание безопасных API и библиотек с протоколами и.generic классами.","ar":"يمكن للعميل الاستفادة من نظام أنواع بايثون للتحليل الساكن، باستخدام أدوات مثل mypy أو pyright للتحقق من النوع الصارم وتأمين إنشاء واجهات برمجة التطبيقات ومكتبات آمنة مع بروتوكولات و فئات عامة."},"useCases":{"en":["Adding type hints to existing codebases for improved maintainability","Creating generic, reusable classes with defined structural interfaces","Configuring mypy or pyright for strict type checking and validation"],"zh":["向现有代码库添加类型提示以提高可维护性","创建具有定义的结构接口的泛型、可重用类","配置mypy或pyright以进行严格的类型检查和验证"],"ja":["既存のコードベースに型ヒントを追加して保守性を向上させる","定義された構造インターフェイスを持つ汎用的かつ再利用可能なクラスを作成する","mypyまたはpyrightを設定して厳格な型チェックと検証を実行する"],"ko":["기존 코드베이스에 유형 힌트를 추가하여 유지 보수성 향상","정의된 구조적 인터페이스를 갖춘 범용 및 재사용 가능한 클래스 생성","mypy 또는 pyright를 구성하여 엄격한 유형 검사 및 검증 수행"],"es":["Agregar sugerencias de tipo a bases de código existentes para mejorar la mantenibilidad","Crear clases genéricas y reutilizables con interfaces estructurales definidas","Configurar mypy o pyright para una comprobación de tipo estricta y validación"],"fr":["Ajouter des indices de type à des bases de code existantes pour améliorer la maintenabilité","Créer des classes génériques et réutilisables avec des interfaces structurales définies","Configurer mypy ou pyright pour une vérification de type stricte et une validation"],"de":["Hinzufügen von Typ-Hinweisen zu bestehenden Codebasen für verbesserte Wartbarkeit","Erstellen von generischen, wiederverwendbaren Klassen mit definierten strukturellen Schnittstellen","Konfigurieren von mypy oder pyright für eine strenge Typüberprüfung und Validierung"],"pt":["Adicionar dicas de tipo a bases de código existentes para melhorar a manutenção","Criar classes genéricas e reutilizáveis com interfaces estruturais definidas","Configurar mypy ou pyright para verificação de tipo estrita e validação"],"ru":["Добавление типов к существующим базам кода для улучшения обслуживания","Создание общих, многоразовых классов с определенными структурными интерфейсами","Настройка mypy или pyright для строгой проверки типов и валидации"],"ar":["إضافة تلميحات النوع إلى قواعد الكود الحالية لتحسين الصيانة","إنشاء فئات عامة قابلة لإعادة الاستخدام مع واجهات بنية محددة","تهيئة mypy أو pyright للتحقق من النوع الصارم والتحقق"]},"limitations":{"en":["Requires Python 3.5+ for type hinting support","Limited to static type checking, not runtime type checking"],"zh":["需要Python 3.5+以支持类型提示","仅限静态类型检查，不支持运行时类型检查"],"ja":["型ヒントをサポートするためにPython 3.5+が必要","静的型チェックのみ、実行時型チェックはサポートされない"],"ko":["타입 힌트를 지원하기 위해 Python 3.5+가 필요","정적 타입 검사만 해당, 런타임 타입 검사는 지원되지 않음"],"es":["Requiere Python 3.5+ para admitir sugerencias de tipo","Limitado a la comprobación de tipo estática, no a la comprobación de tipo en tiempo de ejecución"],"fr":["Nécessite Python 3.5+ pour prendre en charge les indices de type","Limité à la vérification de type statique, et non à la vérification de type à l''exécution"],"de":["Benötigt Python 3.5+ für Typ-Hinweis-Unterstützung","Begrenzt auf statische Typüberprüfung, nicht auf Laufzeit-Typüberprüfung"],"pt":["Requer Python 3.5+ para suporte a dicas de tipo","Limitado à verificação de tipo estática, não verificação de tipo em tempo de execução"],"ru":["Требуется Python 3.5+ для поддержки типов","Ограничен только статической проверкой типов, а не проверкой типов во время выполнения"],"ar":["يتطلب بايثون 3.5+ لدعم تلميحات النوع","محدود بالتحقق من النوع الساكن، وليس التحقق من النوع في وقت التشغيل"]},"version":4},"contentHash":"35dee544eeda5a8cc9844d60615a51a7d0c4870004039ea5064e1618b2f53e56","qualityScore":51}');
