INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ricardocidale/LB_Hospitality/Auto Refresh', 'Auto Refresh', 'ricardocidale', 'LB_Hospitality', 'community', 'Auto Refresh ricardocidale LB_Hospitality community Auto Refresh automatically updates stale market research data on user login, providing an engaging experience with 3D animations. This skill benefits developers and users alike by ensuring data freshness. Auto Refresh 是一种自动刷新市场研究数据的功能，使用 sessionStorage 项防止重复触发 Auto Refresh は、ログイン後に市場調査データを自動更新する機能で、sessionStorage を使用して再トリガーを防ぎます Auto Refresh는 로그인 후 시장 조사 데이터를 자동으로 갱신하는 기능으로, sessionStorage를 사용하여 재トリ거를 방지합니다 Auto Refresh actualiza automáticamente los datos de investigación de mercado al iniciar sesión, con una animación 3D de progreso L''Auto Refresh met à jour automatiquement les données de recherche de marché lors de la connexion, avec une animation 3D de progression Auto Refresh aktualisiert Marktforschungsdaten automatisch beim Einloggen, mit einer 3D-Fortschrittsanimation O Auto Refresh atualiza dados de mercado estagnados quando um usuário faz login, com uma overlay de progresso animada em 3D Авто-Обновление обновляет устаревшие рыночные данные при входе пользователя, с помощью 3D-анимированной полосы прогресса الت刷新 التلقائي يحدث بيانات السوق القديمة عند تسجيل الدخول للمستخدم، مع شريط تقدم متحرك ثلاثي الأبعاد how to use Auto Refresh what is Auto Refresh Auto Refresh alternative Auto Refresh vs other skills Auto Refresh install guide Auto Refresh setup for AI Agents sessionStorage usage in Auto Refresh 3D animated progress overlay implementation market research data refresh techniques Auto Refresh 自动刷新市场研究数据 sessionStorage 3D 动画进度条 AI 工具 市场研究数据更新 Triggers once per browser session after successful login Uses sessionStorage.setItem to prevent re-triggering on navigation Clears on browser tab close due to session storage behavior Displays an engaging 3D animated progress overlay during data updates Prevents re-triggering with ''research_refresh_done'' flag in sessionStorage Fires automatically after a user logs in, ensuring data freshness Auto Refresh is a skill that automatically refreshes market research data when a user logs in, utilizing sessionStorage to prevent re-triggering.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('incursa/workbench/workbench-sync', 'community', 'incursa', 'workbench', 'incursa/workbench', 'workbench-sync', 0, 0, 51, '2026-02-20T06:38:09Z', '2026-03-07T13:12:21.298Z', '8a00d8ece947dbd6e317ed99de0e5f00e6530d6e565c54336ac98fa119c5acce', '{"id":"incursa/workbench/workbench-sync","name":"workbench-sync","description":{"en":"workbench-sync is a CLI tool that manages work items and docs, syncing them with GitHub issues, branches, and PRs. It benefits developers and teams using GitHub for project management.","zh":"Workbench-sync是一种CLI工具，用于管理工作项和文档，并将其与GitHub问题、分支和PR同步","ja":"Workbench-syncは、CLIツールを使用して作業項目とドキュメントを管理し、GitHubの問題、ブランチ、PRと同期する","ko":"Workbench-sync는 CLI 도구를 사용하여 작업 항목과 문서를 관리하고 GitHub 문제, 브랜치, PR과 동기화하는 도구입니다","es":"Workbench-sync es una herramienta de línea de comandos que gestiona elementos de trabajo y documentos, y los sincroniza con GitHub. Permite la importación de problemas de GitHub y la creación de ramas para elementos de trabajo activos","fr":"Workbench-sync est un outil en ligne de commande qui gère les éléments de travail et les documents, et les synchronise avec GitHub. Il permet l''importation de problèmes GitHub et la création de branches pour les éléments de travail actifs","de":"Workbench-sync ist ein Kommandozeilen-Tool, das Arbeitsartikel und Dokumente verwaltet und mit GitHub synchronisiert. Es ermöglicht die Importierung von GitHub-Problemen und die Erstellung von Branches für aktive Arbeitsartikel","pt":"O workbench-sync é uma ferramenta de linha de comando que sincroniza itens de trabalho e documentos com o GitHub, incluindo specs e ADRs.","ru":"Workbench-sync — это инструмент командной строки, который синхронизирует задачи и документы с GitHub, включая спецификации и ADR.","ar":"workbench-sync هو أداة سطر أوامر لمزامنة عناصر العمل والوثائق مع GitHub، بما في ذلك المواصفات وADR."},"seo":{"title":{"en":"workbench-sync: GitHub Sync Setup Guide | AI Agent Skill","zh":"Workbench-sync Setup Guide: GitHub同步和工作项管理","ja":"Workbench-sync ベストプラクティス: GitHubイシューとドキュメントの同期","ko":"Workbench-sync 사용자 가이드: GitHub 이슈 및 작업 항목 관리","es":"Guía de configuración de workbench-sync para GitHub","fr":"Configurer workbench-sync pour GitHub : Guide étape par é...","de":"Workbench-sync Einrichtung für GitHub: Schritt-für-Schrit...","pt":"Guia de Configuração do workbench-sync: Ferramenta de Sin...","ru":"Настройка workbench-sync: Инструмент для синхронизации за...","ar":"دليل إعداد workbench-sync: أداة تحكم في عناصر العمل ومزام..."},"description":{"en":"Streamline your workflow with workbench-sync! Learn how to sync GitHub issues, branches, and PRs with local work items and docs. Get started now!","zh":"使用Workbench-sync CLI工具来管理工作项、文档和GitHub问题，提高开发效率","ja":"Workbench-syncを使用してGitHubイシューとドキュメントを同期し、開発プロセスを最適化する","ko":"Workbench-sync를 사용하여 GitHub 이슈와 문서를 동기화하고 개발 프로세스를 최적화하는 방법","es":"Aprende a sincronizar trabajo y documentos con GitHub utilizando workbench-sync, una herramienta de línea de comandos para gestionar elementos de trabajo y d...","fr":"Découvrez comment synchroniser votre travail et vos documents avec GitHub à l''aide de workbench-sync, un outil en ligne de commande pour gérer les éléments d...","de":"Erfahren Sie, wie Sie Arbeit und Dokumente mit GitHub synchronisieren können, indem Sie workbench-sync verwenden, ein Kommandozeilen-Tool zum Verwalten von A...","pt":"Aprenda a configurar o workbench-sync para sincronizar itens de trabalho e documentos com o GitHub, melhore sua produtividade com essa ferramenta de linha de...","ru":"Узнайте, как настроить workbench-sync для синхронизации задач и документов с GitHub, повысьте свою производительность с помощью этой командной строки","ar":"تعرف على كيفية إعداد workbench-sync لمزامنة عناصر العمل والوثائق مع GitHub، وزيادة إنتاجيتك مع هذه أداة سطر الأوامر"},"definition":{"en":"workbench-sync is a command-line interface (CLI) tool that synchronizes local work items and documentation with GitHub issues, branches, and pull requests.","zh":"Workbench-sync是一种用于管理工作项、文档和GitHub问题的CLI工具","ja":"Workbench-syncは、作業項目、ドキュメント、GitHubの問題を管理するためのCLIツール","ko":"Workbench-sync는 작업 항목, 문서, GitHub 문제를 관리하는 CLI 도구입니다","es":"Workbench-sync es una herramienta de línea de comandos para sincronizar trabajo y documentos con GitHub","fr":"Workbench-sync est un outil en ligne de commande pour synchroniser le travail et les documents avec GitHub","de":"Workbench-sync ist ein Kommandozeilen-Tool zum Synchronisieren von Arbeit und Dokumenten mit GitHub","pt":"O workbench-sync é uma ferramenta de sincronização de itens de trabalho e documentos que integra GitHub.","ru":"Workbench-sync — это инструмент синхронизации задач и документов, интегрирующий GitHub.","ar":"workbench-sync هو أداة مزامنة عناصر العمل والوثائق التي تدمج GitHub."},"features":{"en":["Imports missing GitHub issues into local work items using the `.workbench/config.json` file","Creates missing GitHub issues for active work items and branches","Syncs doc backlinks and front matter using the `workbench.ps1 sync` command","Supports dry-run sync using the `--dry-run` flag","Requires `gh auth login` for authentication before syncing issues","Configures core workflows using settings like `github.owner` and `git.defaultBaseBranch`"],"zh":["支持GitHub问题和分支的同步","支持文档和工作项的管理","提供Dry-run模式用于测试同步","支持多种配置选项，例如github.owner和github.repository","支持创建缺失的GitHub问题和分支","支持同步文档的反向链接和前置内容"],"ja":["GitHubの問題とブランチの同期をサポート","ドキュメントと作業項目の管理をサポート","Dry-runモードを提供して同期をテスト","複数の設定オプションをサポート、例えばgithub.ownerとgithub.repository","欠けているGitHubの問題とブランチを作成することをサポート","ドキュメントのバックリンクとフロントマターの同期をサポート"],"ko":["GitHub 문제와 브랜치의 동기화를 지원","문서와 작업 항목의 관리를 지원","Dry-run 모드를 제공하여 동기화를 테스트","여러 가지 설정 옵션을 지원, 예를 들어 github.owner와 github.repository","결과의 GitHub 문제와 브랜치를 생성하는 것을 지원","문서의 역링크와 전위 내용의 동기화를 지원"],"es":["Importación de problemas de GitHub","Creación de ramas para elementos de trabajo activos","Sincronización de enlaces de documentos y metadatos","Compatibilidad con GitHub issues y pull requests","Configuración personalizable a través de `.workbench/config.json`","Soporte para autenticación de GitHub mediante `gh auth login`"],"fr":["Importation de problèmes GitHub","Création de branches pour les éléments de travail actifs","Synchronisation de liens de documents et de métadonnées","Compatibilité avec les problèmes GitHub et les demandes de tirage","Configuration personnalisable via `.workbench/config.json`","Prise en charge de l''authentification GitHub via `gh auth login`"],"de":["Importierung von GitHub-Problemen","Erstellung von Branches für aktive Arbeitsartikel","Synchronisation von Dokumentenlinks und Metadaten","Kompatibilität mit GitHub-Problemen und Pull-Requests","Anpassbare Konfiguration über `.workbench/config.json`","Unterstützung für GitHub-Authentifizierung über `gh auth login`"],"pt":["Sincronização de itens de trabalho com issues do GitHub","Criação de branches para itens de trabalho ativos","Sincronização de documentos e specs com o GitHub","Suporte à autenticação do GitHub via gh auth login","Opção de dry-run para testar a sincronização"],"ru":["Синхронизация задач с проблемами GitHub","Создание веток для активных задач","Синхронизация документов и спецификаций с GitHub","Поддержка аутентификации GitHub через gh auth login","Вариант dry-run для тестирования синхронизации"],"ar":["مزامنة عناصر العمل مع قضايا GitHub","إنشاء فروع لعناصر العمل النشطة","مزامنة الوثائق والمواصفات مع GitHub","دعم مصادقة GitHub عبر gh auth login","خيار dry-run لاختبار المزامنة"]},"keywords":{"en":["how to use workbench-sync","workbench-sync setup guide","workbench-sync vs git","workbench-sync install","github issue sync","workbench-sync alternative","workbench-sync documentation","what is workbench-sync","workbench-sync tutorial"],"zh":["Workbench-sync","GitHub同步","工作项管理","文档管理","CLI工具","Dotnet工具","GitHub问题管理","任务跟踪","工作流管理"],"ja":["Workbench-sync","GitHub同期","作業項目管理","ドキュメント管理","CLIツール","Dotnetツール","GitHub問題管理","タスク追跡","ワークフローマネジメント"],"ko":["Workbench-sync","GitHub 동기화","작업 항목 관리","문서 관리","CLI 도구","Dotnet 도구","GitHub 문제 관리","태스크 추적","워크플로우 관리"],"es":["workbench-sync","GitHub","CLI","herramienta de línea de comandos","gestión de trabajo","sincronización de documentos","problemas de GitHub","ramas de GitHub","autenticación de GitHub"],"fr":["workbench-sync","GitHub","CLI","outil en ligne de commande","gestion de travail","synchronisation de documents","problèmes GitHub","branches GitHub","authentification GitHub"],"de":["workbench-sync","GitHub","CLI","Kommandozeilen-Tool","Arbeitsverwaltung","Dokumentensynchronisation","GitHub-Probleme","GitHub-Branches","GitHub-Authentifizierung"],"pt":["workbench-sync","sincronização de itens de trabalho","GitHub issues","CLI","ferramenta de linha de comando","ADR","specs","documentação","autenticação do GitHub"],"ru":["workbench-sync","синхронизация задач","GitHub issues","CLI","инструмент командной строки","ADR","спецификации","документация","аутентификация GitHub"],"ar":["workbench-sync","مزامنة عناصر العمل","قضايا GitHub","CLI","أداة سطر الأوامر","ADR","المواصفات","الوثائق","مصادقة GitHub"]}},"owner":"incursa","repo":"workbench","repoPath":"incursa/workbench","stars":0,"forks":0,"updatedAt":"2026-02-20T06:38:09Z","topics":["adr","automation","cli","docs","dotnet-tool","github","task-tracking","workflow"],"category":"community","skillMd":{"name":"workbench-sync","description":"Sync workflows for Workbench CLI. Use when aligning local work items with GitHub issues, creating branches, or reconciling doc backlinks.","bodyPreview":"## Key settings\n\n- `.workbench/config.json`: github.owner, github.repository, github.host, git.defaultBaseBranch.\n- Ensure `gh auth login` is complete before syncing issues.\n\n## Core workflows\n\n1. Import missing GitHub issues into local work items.\n2. Create missing GitHub issues for active work items.\n3. Create branches for active items.\n4. Sync doc backlinks and front matter.\n\n## Commands\n\nDry-run sync:\n```bash\nworkbench.ps1 sync --dry-run\n```\n\nSync a specific item and prefer GitHub content:\n`","body":"## Key settings\n\n- `.workbench/config.json`: github.owner, github.repository, github.host, git.defaultBaseBranch.\n- Ensure `gh auth login` is complete before syncing issues.\n\n## Core workflows\n\n1. Import missing GitHub issues into local work items.\n2. Create missing GitHub issues for active work items.\n3. Create branches for active items.\n4. Sync doc backlinks and front matter.\n\n## Commands\n\nDry-run sync:\n```bash\nworkbench.ps1 sync --dry-run\n```\n\nSync a specific item and prefer GitHub content:\n```bash\nworkbench.ps1 item sync --id TASK-0001 --prefer github\n```\n\nBulk sync (local wins on conflicts):\n```bash\nworkbench.ps1 sync --items\n```\n\nImport unlinked GitHub issues (slower):\n```bash\nworkbench.ps1 sync --items --import-issues\n```\n\nSync doc backlinks (include done items when needed):\n```bash\nworkbench.ps1 doc sync --all\nworkbench.ps1 doc sync --all --include-done\n```\n\n## Output\n\n- New work items from GitHub issues.\n- New GitHub issues and branches for active work items.\n- Updated doc backlinks and front matter.\n\n## Guardrails\n\n- Use `--dry-run` before creating issues or branches.\n- `workbench.ps1 sync` defaults to linked work items only; use `--import-issues` to pull unlinked GitHub issues.\n- Terminal items (done/dropped) do not create issues or branches by default.\n- Sync is not a replacement for specs/ADRs; create or update them during planning.\n"},"lastSynced":"2026-03-07T13:12:21.298Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents utilizing GitHub for project management and requiring seamless issue and documentation synchronization.","zh":"适用于使用 GitHub 进行项目管理，并需要无缝同步问题和文档的开发代理。","ja":"GitHub をプロジェクト管理に使用し、問題やドキュメントのシームレスな同期を必要とする開発エージェントに適しています。","ko":"GitHub를 프로젝트 관리에 사용하며 문제와 문서의 무손실 동기화를 필요로 하는 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que utilizan GitHub para la gestión de proyectos y requieren una sincronización perfecta de problemas y documentación.","fr":"Idéal pour les agents de développement qui utilisent GitHub pour la gestion de projets et nécessitent une synchronisation parfaite des problèmes et de la documentation.","de":"Ideal für Entwicklungsmittel, die GitHub für das Projektmanagement verwenden und eine nahtlose Synchronisierung von Problemen und Dokumentation erfordern.","pt":"Ideal para Agentes de Desenvolvimento que utilizam o GitHub para gerenciamento de projetos e requerem sincronização perfeita de problemas e documentação.","ru":"Идеально подходит для агентов разработки, использующих GitHub для управления проектами и требующих бесшовной синхронизации проблем и документации.","ar":"مثالي للوكلاء النشطين الذين يستخدمون GitHub لإدارة المشاريع ويتطلبون تناسقًا مثاليًا لقضايا الوثائق"},"recommendation":{"en":"Empowers agents to synchronize local work items with GitHub issues, branches, and PRs, leveraging CLI tools and configuring settings like github.owner and git.defaultBaseBranch, while ensuring authenticated access via gh auth login.","zh":"赋予代理人使用 CLI 工具同步本地工作项与 GitHub 问题、分支和 PR 的能力，并配置诸如 github.owner 和 git.defaultBaseBranch 的设置，同时通过 gh auth login 确保认证访问。","ja":"CLI ツールを使用してローカルの作業項目を GitHub の問題、ブランチ、PR と同期する能力をエージェントに与え、github.owner や git.defaultBaseBranch などの設定を構成し、gh auth login を使用した認証アクセスを確保します。","ko":"CLI 도구를 사용하여 로컬 작업 항목을 GitHub 문제, 브랜치 및 PR와 동기화하는 능력을 에이전트에게 부여하고 github.owner 및 git.defaultBaseBranch와 같은 설정을 구성하며 gh auth login을 통해 인증된 액세스를 보장합니다.","es":"Permite a los agentes sincronizar elementos de trabajo locales con problemas de GitHub, ramas y solicitudes de extracción, utilizando herramientas de CLI y configurando ajustes como github.owner y git.defaultBaseBranch, garantizando al mismo tiempo el acceso autenticado a través de gh auth login.","fr":"Permet aux agents de synchroniser les éléments de travail locaux avec les problèmes GitHub, les branches et les demandes d''extraction, en utilisant des outils CLI et en configurant des paramètres comme github.owner et git.defaultBaseBranch, tout en assurant un accès authentifié via gh auth login.","de":"Ermöglicht es Agenten, lokale Arbeitsartikel mit GitHub-Problemen, -Zweigen und -Pull-Requests zu synchronisieren, indem es CLI-Tools verwendet und Einstellungen wie github.owner und git.defaultBaseBranch konfiguriert, während es gleichzeitig den authentifizierten Zugriff über gh auth login sicherstellt.","pt":"Habilita os agentes a sincronizar itens de trabalho locais com problemas do GitHub, branches e PRs, utilizando ferramentas CLI e configurando configurações como github.owner e git.defaultBaseBranch, garantindo acesso autenticado via gh auth login.","ru":"Наделяет агентов возможностью синхронизировать локальные рабочие элементы с проблемами GitHub, ветками и PR, используя инструменты CLI и настраивая параметры, такие как github.owner и git.defaultBaseBranch, обеспечивая аутентифицированный доступ через gh auth login.","ar":"يمكّن الوكلاء من مزامنة عناصر العمل المحلية مع قضايا GitHub والفروع و PRs، باستخدام أدوات CLI وضبط الإعدادات مثل github.owner و git.defaultBaseBranch، مع ضمان الوصول المُصادق عبر gh auth login."},"useCases":{"en":["Importing missing GitHub issues into local work items for unified project tracking","Creating missing GitHub issues for active work items to maintain consistency","Syncing doc backlinks and front matter for accurate documentation","Automating branch creation for active items to streamline development workflows"],"zh":["将缺失的 GitHub 问题导入本地工作项以实现统一的项目跟踪","为活动工作项创建缺失的 GitHub 问题以保持一致性","同步文档反向链接和前置内容以实现准确的文档","自动化分支创建以简化开发工作流"],"ja":["プロジェクトの統一された追跡のために、不足している GitHub の問題をローカルの作業項目にインポートします","一貫性を維持するために、アクティブな作業項目の不足している GitHub の問題を作成します","正確なドキュメントのために、ドキュメントのバックリンクとフロントマターを同期します","開発ワークフローの効率化のために、ブランチの作成を自動化します"],"ko":["统一 프로젝트 추적을 위해 누락된 GitHub 문제를 로컬 작업 항목으로 가져옵니다","일관성을 유지하기 위해 활성 작업 항목의 누락된 GitHub 문제를 생성합니다","정확한 문서화를 위해 문서 역링크 및 전면 물질을 동기화합니다","개발 워크플로를 간소화하기 위해 분기 생성을 자동화합니다"],"es":["Importar problemas de GitHub que faltan en elementos de trabajo locales para un seguimiento de proyectos unificado","Crear problemas de GitHub que faltan para elementos de trabajo activos para mantener la coherencia","Sincronizar enlaces de documentación y metadatos para una documentación precisa","Automatizar la creación de ramas para elementos activos para agilizar los flujos de trabajo de desarrollo"],"fr":["Importer des problèmes GitHub manquants dans des éléments de travail locaux pour un suivi de projet unifié","Créer des problèmes GitHub manquants pour des éléments de travail actifs pour maintenir la cohérence","Synchroniser les liens de documentation et les métadonnées pour une documentation précise","Automatiser la création de branches pour des éléments actifs pour rationaliser les flux de travail de développement"],"de":["Fehlende GitHub-Probleme in lokale Arbeitsartikel importieren, um ein einheitliches Projekttracking zu ermöglichen","Fehlende GitHub-Probleme für aktive Arbeitsartikel erstellen, um die Konsistenz zu gewährleisten","Dokumentations-Backlinks und Metadaten synchronisieren, um eine genaue Dokumentation zu gewährleisten","Automatisieren der Erstellung von Zweigen für aktive Artikel, um die Entwicklungsworkflows zu rationalisieren"],"pt":["Importação de problemas do GitHub ausentes para itens de trabalho locais para rastreamento de projeto unificado","Criação de problemas do GitHub ausentes para itens de trabalho ativos para manter a consistência","Sincronização de links de documentação e matéria frontal para documentação precisa","Criação automática de branches para itens ativos para otimizar fluxos de trabalho de desenvolvimento"],"ru":["Импорт отсутствующих проблем GitHub в локальные рабочие элементы для унифицированного отслеживания проекта","Создание отсутствующих проблем GitHub для активных рабочих элементов для поддержания согласованности","Синхронизация обратных ссылок документации и основного содержания для точной документации","Автоматическое создание веток для активных элементов для оптимизации рабочих процессов разработки"],"ar":["استيراد قضايا GitHub الناقصة إلى عناصر العمل المحلية لتتبع مشروع موحد","إنشاء قضايا GitHub الناقصة لعناصر العمل النشطة للحفاظ على الاتساق","مزامنة روابط الوثائق والمادة الأمامية لتدوين دقيق","إنشاء فرع تلقائي لعناصر العمل النشطة لتحسين سير عمل التطوير"]},"limitations":{"en":["Requires GitHub authentication via gh auth login","Needs configuration of .workbench/config.json settings","Limited to GitHub as the project management platform"],"zh":["需要通过 gh auth login 进行 GitHub 认证","需要配置 .workbench/config.json 设置","仅限于 GitHub 作为项目管理平台"],"ja":["GitHub の認証が gh auth login を使用して必要です",".workbench/config.json の設定の構成が必要です","プロジェクト管理プラットフォームとして GitHub だけに限定されています"],"ko":["gh auth login을 통해 GitHub 인증이 필요합니다",".workbench/config.json 설정의 구성이 필요합니다","프로젝트 관리 플랫폼으로 GitHub만 사용할 수 있습니다"],"es":["Requiere autenticación de GitHub a través de gh auth login","Necesita la configuración de la configuración .workbench/config.json","Limitado a GitHub como plataforma de gestión de proyectos"],"fr":["Nécessite une authentification GitHub via gh auth login","Nécessite la configuration des paramètres .workbench/config.json","Limité à GitHub en tant que plateforme de gestion de projets"],"de":["Benötigt eine GitHub-Authentifizierung über gh auth login","Benötigt die Konfiguration der Einstellungen .workbench/config.json","Begrenzt auf GitHub als Projektmanagementplattform"],"pt":["Exige autenticação do GitHub via gh auth login","Necessita de configuração de configurações .workbench/config.json","Limitado ao GitHub como plataforma de gerenciamento de projetos"],"ru":["Требует аутентификации GitHub через gh auth login","Требует настройки параметров .workbench/config.json","Ограничен GitHub в качестве платформы управления проектами"],"ar":["يحتاج إلى مصادقة GitHub عبر gh auth login","يحتاج إلى تكوين إعدادات .workbench/config.json","محدود بـ GitHub كمنصة لإدارة المشاريع"]},"version":4},"contentHash":"8a00d8ece947dbd6e317ed99de0e5f00e6530d6e565c54336ac98fa119c5acce","qualityScore":51}');
