INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Devdha/wm/wm-git-worktree-manager', 'wm-git-worktree-manager', 'Devdha', 'wm', 'community', 'wm-git-worktree-manager Devdha wm community The wm-git-worktree-manager skill provides a CLI tool for easy git worktree management, benefiting developers who need to manage multiple worktrees efficiently. wm-git-worktree-manager是一个CLI工具，用于轻松管理git工作树 wm-git-worktree-managerは、gitワークツリーを簡単に管理するためのCLIツールです wm-git-worktree-manager는 git 작업 트리를 쉽게 관리할 수 있는 CLI 툴입니다 wm-git-worktree-manager es una herramienta de línea de comandos para la gestión de git worktree. Permite inicializar proyectos y gestionar configuraciones de manera sencilla. wm-git-worktree-manager est un outil de ligne de commande pour la gestion de git worktree. Il permet d''initialiser des projets et de gérer des configurations de manière simple. wm-git-worktree-manager ist ein Kommandozeilen-Tool für die Verwaltung von git worktree. Es ermöglicht die Initialisierung von Projekten und die Verwaltung von Konfigurationen auf einfache Weise. O wm-git-worktree-manager é uma ferramenta CLI para gerenciar worktrees Git de forma fácil wm-git-worktree-manager - это инструмент CLI для легкого управления worktrees Git - ИИ Агенты wm-git-worktree-manager هو أداة CLI لدارة worktrees Git بسهولة - أدوات ذكاء اصطناعي how to use wm-git-worktree-manager wm-git-worktree-manager setup guide git worktree management best practices wm-git-worktree-manager alternative wm-git-worktree-manager vs git worktree wm-git-worktree-manager install wm-git-worktree-manager CLI commands git worktree manager tool wm-git-worktree-manager automated environments wm-git-worktree-manager git工作树管理 CLI工具 AI工具 项目配置 工作树添加 工作树删除 非交互模式 Initialize project config using the `wm init` command Add worktrees using the `wm add` command with explicit arguments Remove worktrees using the `wm remove` command with explicit arguments Supports non-interactive mode for automated environments Configures projects using the .wm.yaml file format wm-git-worktree-manager is a command-line interface tool designed for managing git worktrees, allowing developers to initialize and manage worktrees using explicit arguments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sailscastshq/boring-stack/inertia', 'community', 'sailscastshq', 'boring-stack', 'sailscastshq/boring-stack', 'inertia', 0, 0, 51, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:35.711Z', '487c3d503fcd8ef112a8e7e7b670ef66cde279b5faaa1f4c415fcf8441881132', '{"id":"sailscastshq/boring-stack/inertia","name":"inertia","description":{"en":"Inertia.js enables building modern single-page apps using classic server-side routing and controllers. It bridges Sails.js and frontend frameworks like React, Vue, or Svelte.","zh":"Inertia.js 是连接 Sails.js 和前端框架（React、Vue 或 Svelte）的桥梁，实现快速开发","ja":"Inertia.js は Sails.js とフロントエンドフレームワーク（React、Vue、または Svelte）を接続するブリッジです","ko":"Inertia.js는 Sails.js와 프론트엔드 프레임워크（React、Vue 또는 Svelte）를 연결하는 브릿지로 빠른 개발을 가능하게 합니다","es":"Inertia.js es un puente entre Sails.js y frameworks de frontend como React, Vue o Svelte, permitiendo crear aplicaciones de página única modernas","fr":"Inertia.js est un pont entre Sails.js et les frameworks de frontend tels que React, Vue ou Svelte, permettant de créer des applications de page unique modernes","de":"Inertia.js ist eine Brücke zwischen Sails.js und Frontend-Frameworks wie React, Vue oder Svelte, um moderne Single-Page-Anwendungen zu erstellen","pt":"Inertia.js é uma ponte entre Sails.js e frameworks frontend, permitindo a criação de aplicações modernas com roteamento e controladores de servidor.","ru":"Inertia.js является мостом между Sails.js и фронтенд-фреймворками, позволяя создавать современные приложения с серверным маршрутизацией и контроллерами.","ar":"Inertia.js هو جسر بين Sails.js وإطارات عمل الواجهة الأمامية، مما يسمح بإنشاء تطبيقات حديثة مع التوجيه والمراقبين على الخادم."},"seo":{"title":{"en":"Inertia: Setup Guide for The Boring JavaScript Stack | AI...","zh":"Inertia.js 快速开发指南","ja":"Inertia.js のセットアップガイド - AIエージェント","ko":"Inertia.js 빠른 개