INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sailscastshq/boring-stack/inertia', 'inertia', 'sailscastshq', 'boring-stack', 'community', 'inertia sailscastshq boring-stack community Inertia.js enables building modern single-page apps using classic server-side routing and controllers. It bridges Sails.js and frontend frameworks like React, Vue, or Svelte. Inertia.js 是连接 Sails.js 和前端框架（React、Vue 或 Svelte）的桥梁，实现快速开发 Inertia.js は Sails.js とフロントエンドフレームワーク（React、Vue、または Svelte）を接続するブリッジです Inertia.js는 Sails.js와 프론트엔드 프레임워크（React、Vue 또는 Svelte）를 연결하는 브릿지로 빠른 개발을 가능하게 합니다 Inertia.js es un puente entre Sails.js y frameworks de frontend como React, Vue o Svelte, permitiendo crear aplicaciones de página única modernas Inertia.js est un pont entre Sails.js et les frameworks de frontend tels que React, Vue ou Svelte, permettant de créer des applications de page unique modernes Inertia.js ist eine Brücke zwischen Sails.js und Frontend-Frameworks wie React, Vue oder Svelte, um moderne Single-Page-Anwendungen zu erstellen Inertia.js é uma ponte entre Sails.js e frameworks frontend, permitindo a criação de aplicações modernas com roteamento e controladores de servidor. Inertia.js является мостом между Sails.js и фронтенд-фреймворками, позволяя создавать современные приложения с серверным маршрутизацией и контроллерами. Inertia.js هو جسر بين Sails.js وإطارات عمل الواجهة الأمامية، مما يسمح بإنشاء تطبيقات حديثة مع التوجيه والمراقبين على الخادم. how to use inertia inertia setup guide inertia vs react inertia install what is inertia inertia alternative inertia and sails.js inertia.js tutorial inertia and vue.js inertia single-page apps Inertia.js Sails.js React Vue Svelte 单页应用 快速开发 JavaScript 库 AIエージェント Implements the full Inertia.js v2 protocol as a Sails hook via `inertia-sails` package Supports rendering pages with Inertia using `responseType: ''inertia''` Enables setting page-specific meta tags Works with frontend frameworks like React, Vue, or Svelte Allows building modern single-page apps without requiring an API Inertia is a bridge between Sails.js and frontend frameworks, enabling modern single-page apps with classic server-side routing and controllers');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('serejaris/ris-claude-code/cc-analytics', 'community', 'serejaris', 'ris-claude-code', 'serejaris/ris-claude-code', 'cc-analytics', 0, 0, 51, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:40.933Z', '8005260291525360d794124b3c9e02282d60b7476516c23e7c4ad1189e0e37e9', '{"id":"serejaris/ris-claude-code/cc-analytics","name":"cc-analytics","description":{"en":"cc-analytics generates HTML reports of Claude Code usage from ~/.claude/history.jsonl, benefiting developers with project insights. It utilizes Git data for enhanced analytics.","zh":"CC-Analytics 是一个生成 HTML 报告的工具，用于分析 Claude Code 用法。它支持从历史记录中读取数据，并生成包含项目统计、Git 数据和 ASCII 图表的报告","ja":"CC-Analytics は、Claude Code の使用状況を分析する HTML レポートを生成するツールです。歴史レコードからデータを読み取り、プロジェクト統計、Git データ、ASCII グラフなどを含むレポートを生成します","ko":"CC-Analytics는 Claude Code 사용량을 분석하는 HTML 보고서를 생성하는 도구입니다. 기록에서 데이터를 읽어와 프로젝트 통계, Git 데이터, ASCII 차트 등이 포함된 보고서를 생성합니다","es":"cc-analytics es una herramienta que genera informes HTML de uso de Claude Code. Proporciona estadísticas y gráficos de uso.","fr":"cc-analytics est un outil qui génère des rapports HTML d''utilisation de Claude Code. Il fournit des statistiques et des graphiques d''utilisation.","de":"cc-analytics ist ein Tool, das HTML-Berichte zur Nutzung von Claude Code generiert. Es bietet Statistiken und Grafiken zur Nutzung.","pt":"O cc-analytics é uma ferramenta que gera relatórios de uso de Claude Code, incluindo estatísticas e gráficos de projeto. Ele utiliza dados de histórico e Git para fornecer uma visão geral do uso","ru":"cc-analytics - это инструмент, который генерирует отчеты об использовании Claude Code, включая статистику и графики проектов. Он использует данные истории и Git для предоставления обзора использования для ИИ Агентов","ar":"cc-analytics هو أداة لتوليد تقارير استخدام Claude Code، بما في ذلك الإحصاءات ورسوم بيانية المشروع. يستخدم بيانات التاريخ و Git لتوفير نظرة عامة على الاستخدام لآلات الإي الأجنبي"},"seo":{"title":{"en":"cc-analytics: HTML Report Generation for AI Agents | AI A...","zh":"CC-Analytics 报告生成指南","ja":"CC-Analytics レポート生成ガイド","ko":"CC-Analytics 리포트 생성 가이드","es":"Guía de configuración de cc-analytics: Informes de uso de...","fr":"Guide de configuration de cc-analytics: Rapports d''utilis...","de":"Konfigurationsleitfaden für cc-analytics: Berichte zur Nu...","pt":"Guia de Configuração do cc-analytics: Relatórios de Uso d...","ru":"Настройка cc-analytics: Отчеты об использовании Claude Co...","ar":"دليل الإعداد لcc-analytics: تقارير استخدام Claude Code لآ..."},"description":{"en":"Discover how to generate insightful HTML reports with cc-analytics. Learn to leverage ~/.claude/history.jsonl and Git data for AI agent analytics","zh":"使用 CC-Analytics 生成 HTML 报告，分析 Claude Code 用法，包括项目统计、Git 数据和 ASCII 图表","ja":"CC-Analytics を使用して HTML レポートを生成し、Claude Code の使用状況を分析します。プロジェクト統計、Git データ、ASCII グラフなどが含まれます","ko":"CC-Analytics를 사용하여 HTML 보고서를 생성하고 Claude Code 사용량을 분석합니다. 프로젝트 통계, Git 데이터, ASCII 차트 등이 포함됩니다","es":"Genera informes HTML de uso de Claude Code con cc-analytics. Obtén estadísticas y gráficos de uso con este script de Python","fr":"Générez des rapports HTML d''utilisation de Claude Code avec cc-analytics. Obtenez des statistiques et des graphiques d''utilisation avec ce script Python","de":"Erstellen Sie HTML-Berichte zur Nutzung von Claude Code mit cc-analytics. Erhalten Sie Statistiken und Grafiken zur Nutzung mit diesem Python-Script","pt":"Aprenda a configurar o cc-analytics para gerar relatórios de uso de Claude Code, incluindo estatísticas e gráficos de projeto","ru":"Узнайте, как настроить cc-analytics для генерации отчетов об использовании Claude Code, включая статистику и графики проектов для ИИ Агентов","ar":"تعلم كيفية ضبط cc-analytics لإنشاء تقارير استخدام Claude Code، بما في ذلك الإحصاءات ورسوم بيانية المشروع لآلات الإي الأجنبي"},"definition":{"en":"cc-analytics is a skill that generates HTML reports of Claude Code usage, providing summary stats and project tables with remote links","zh":"CC-Analytics 是一个生成 HTML 报告的工具，用于分析 Claude Code 用法","ja":"CC-Analytics は、Claude Code の使用状況を分析する HTML レポートを生成するツールです","ko":"CC-Analytics는 Claude Code 사용량을 분석하는 HTML 보고서를 생성하는 도구입니다","es":"cc-analytics es una herramienta de análisis de código que genera informes de uso de Claude Code","fr":"cc-analytics est un outil d''analyse de code qui génère des rapports d''utilisation de Claude Code","de":"cc-analytics ist ein Code-Analyse-Tool, das Berichte zur Nutzung von Claude Code generiert","pt":"O cc-analytics é uma ferramenta de relatórios de uso de Claude Code que gera um arquivo HTML com estatísticas e gráficos de projeto","ru":"cc-analytics - это инструмент для генерации отчетов об использовании Claude Code, который создает файл HTML со статистикой и графиками проектов для ИИ Агентов","ar":"cc-analytics هو أداة لتوليد تقارير استخدام Claude Code التي ت生成 ملف HTML مع الإحصاءات ورسوم بيانية المشروع لآلات الإي الأجنبي"},"features":{"en":["Generates single HTML file with terminal aesthetic","Utilizes ~/.claude/history.jsonl for prompt and project data","Leverages Git data for remote URLs and commit counts","Creates ASCII art header and bar chart for visualization","Runs via Python script for report generation"],"zh":["生成 HTML 报告","分析 Claude Code 用法","支持从历史记录中读取数据","包含项目统计、Git 数据和 ASCII 图表","使用 Python 脚本生成报告","支持 Git 远程 URL 和提交计数"],"ja":["HTML レポートを生成","Claude Code の使用状況を分析","歴史レコードからデータを読み取り","プロジェクト統計、Git データ、ASCII グラフなどを含む","Python スクリプトを使用してレポートを生成","Git リモート URL とコミット数をサポート"],"ko":["HTML 보고서 생성","Claude Code 사용량 분석","기록에서 데이터 읽기","프로젝트 통계, Git 데이터, ASCII 차트 등 포함","Python 스크립트를 사용하여 보고서 생성","Git 원격 URL 및 커밋 수 지원"],"es":["Generación de informes HTML de uso de Claude Code","Estadísticas de uso, incluyendo proyectos, prompts y commits","Gráficos de barras ASCII para visualizar el uso","Enlace a proyectos remotos en la tabla de proyectos","Script de Python para generar el informe"],"fr":["Génération de rapports HTML d''utilisation de Claude Code","Statistiques d''utilisation, y compris les projets, les prompts et les commits","Graphiques à barres ASCII pour visualiser l''utilisation","Lien vers les projets distants dans le tableau des projets","Script Python pour générer le rapport"],"de":["Erstellung von HTML-Berichten zur Nutzung von Claude Code","Nutzungsstatistiken, einschließlich Projekte, Prompts und Commits","ASCII-Balken-Diagramme zur Visualisierung der Nutzung","Link zu Remote-Projekten in der Projekt-Tabelle","Python-Script zum Erstellen des Berichts"],"pt":["Geração de relatórios de uso de Claude Code","Inclusão de estatísticas de projeto, como número de prompts e commits","Gráficos de projeto em ASCII","Uso de dados de histórico e Git para fornecer uma visão geral do uso","Saída em formato HTML com estética de terminal"],"ru":["Генерация отчетов об использовании Claude Code","Включение статистики проектов, таких как количество запросов и коммитов","Графики проектов в ASCII","Использование данных истории и Git для предоставления обзора использования для ИИ Агентов","Выходные данные в формате HTML с терминальной эстетикой"],"ar":["توليد تقارير استخدام Claude Code","تشمل الإحصاءات الخاصة بالمشروع، مثل عدد الطلبات والالتزامات","رسوم بيانية للمشروع في ASCII","استخدام بيانات التاريخ و Git لتوفير نظرة عامة على الاستخدام لآلات الإي الأجنبي","إخراج في تنسيق HTML مع جمالية الطرفية"]},"keywords":{"en":["how to use cc-analytics","cc-analytics setup guide","cc-analytics alternative","cc-analytics vs claude code","what is cc-analytics","cc-analytics install","cc-analytics report generation","claude code analytics","git data analytics"],"zh":["CC-Analytics","Claude Code","HTML 报告","Python 脚本","Git 数据","ASCII 图表","项目统计","AI 工具","代码分析"],"ja":["CC-Analytics","Claude Code","HTML レポート","Python スクリプト","Git データ","ASCII グラフ","プロジェクト統計","AI エージェント","コード分析"],"ko":["CC-Analytics","Claude Code","HTML 보고서","Python 스크립트","Git 데이터","ASCII 차트","프로젝트 통계","AI 도구","코드 분석"],"es":["cc-analytics","informes de uso de Claude Code","análisis de código","herramientas de desarrollo","script de Python","generación de informes","estadísticas de uso","gráficos de uso"],"fr":["cc-analytics","rapports d''utilisation de Claude Code","analyse de code","outils de développement","script Python","génération de rapports","statistiques d''utilisation","graphiques d''utilisation"],"de":["cc-analytics","Berichte zur Nutzung von Claude Code","Code-Analyse","Entwicklungstools","Python-Script","Berichterstellung","Nutzungsstatistiken","Nutzungsgrafiken"],"pt":["cc-analytics","relatórios de uso de Claude Code","estatísticas de projeto","gráficos de projeto em ASCII","dados de histórico e Git","saída em formato HTML","ferramentas de desenvolvimento","otimização de código"],"ru":["cc-analytics","отчеты об использовании Claude Code","статистика проектов","графики проектов в ASCII","данные истории и Git","выходные данные в формате HTML","инструменты разработки","оптимизация кода для ИИ Агентов"],"ar":["cc-analytics","تقارير استخدام Claude Code","إحصاءات المشروع","رسوم بيانية للمشروع في ASCII","بيانات التاريخ و Git","إخراج في تنسيق HTML","أدوات التطوير","تحسين الكود لآلات الإي الأجنبي"]}},"owner":"serejaris","repo":"ris-claude-code","repoPath":"serejaris/ris-claude-code","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.276Z","topics":[],"category":"community","skillMd":{"name":"cc-analytics","description":"Use when user asks for Claude Code usage stats, weekly analytics, project activity summary, or wants to see what projects were worked on. Triggers on аналитика, статистика claude, cc stats, weekly report, что делал","bodyPreview":"# Claude Code Analytics\n\nGenerate HTML report of Claude Code usage from `~/.claude/history.jsonl`.\n\n## Data Sources\n\n- **History:** `~/.claude/history.jsonl` — prompts with timestamps and project paths\n- **Git:** Remote URLs and commit counts per project\n\n## Output\n\nSingle HTML file with terminal aesthetic:\n- ASCII art header\n- Summary stats (projects, prompts, commits, days)\n- Project table with remote links\n- ASCII bar chart\n\n## Generation Script\n\nRun this Python script to generate the report:","body":"# Claude Code Analytics\n\nGenerate HTML report of Claude Code usage from `~/.claude/history.jsonl`.\n\n## Data Sources\n\n- **History:** `~/.claude/history.jsonl` — prompts with timestamps and project paths\n- **Git:** Remote URLs and commit counts per project\n\n## Output\n\nSingle HTML file with terminal aesthetic:\n- ASCII art header\n- Summary stats (projects, prompts, commits, days)\n- Project table with remote links\n- ASCII bar chart\n\n## Generation Script\n\nRun this Python script to generate the report:\n\n```python\nimport json\nimport os\nimport subprocess\nfrom datetime import datetime, timedelta\nfrom collections import defaultdict\n\ndef get_git_info(path):\n    if not os.path.isdir(path) or not os.path.exists(os.path.join(path, ''.git'')):\n        return None, 0\n    try:\n        result = subprocess.run([''git'', ''-C'', path, ''remote'', ''get-url'', ''origin''],\n                                capture_output=True, text=True, timeout=5)\n        remote = result.stdout.strip() if result.returncode == 0 else None\n        if remote:\n            remote = remote.replace(''git@github.com:'', ''github.com/'').replace(''.git'', '''').replace(''https://'', '''')\n\n        week_ago = (datetime.now() - timedelta(days=7)).strftime(''%Y-%m-%d'')\n        result = subprocess.run([''git'', ''-C'', path, ''rev-list'', ''--count'', f''--since={week_ago}'', ''HEAD''],\n                                capture_output=True, text=True, timeout=5)\n        commits = int(result.stdout.strip()) if result.returncode == 0 else 0\n        return remote, commits\n    except:\n        return None, 0\n\n# Parse history\nhistory = []\nwith open(os.path.expanduser(''~/.claude/history.jsonl''), ''r'') as f:\n    for line in f:\n        try:\n            history.append(json.loads(line))\n        except:\n            pass\n\n# Filter last N days (default 7)\ndays = 7\nnow = datetime.now()\ncutoff = (now - timedelta(days=days)).timestamp() * 1000\n\nprojects = defaultdict(lambda: {''prompts'': [], ''sessions'': set()})\nfor entry in history:\n    ts = entry.get(''timestamp'', 0)\n    if ts >= cutoff:\n        project = entry.get(''project'', ''unknown'')\n        projects[project][''prompts''].append(entry)\n        projects[project][''sessions''].add(datetime.fromtimestamp(ts/1000).strftime(''%Y-%m-%d''))\n\n# Collect data\nresults = []\ntotal_commits = 0\nfor project, data in projects.items():\n    remote, commits = get_git_info(project)\n    total_commits += commits\n    results.append({\n        ''name'': os.path.basename(project) or project.replace(''/Users/ris/'', ''~/''),\n        ''folder'': project.replace(''/Users/ris/'', ''~/''),\n        ''remote'': remote,\n        ''prompts'': len(data[''prompts'']),\n        ''sessions'': len(data[''sessions'']),\n        ''commits'': commits\n    })\n\nresults.sort(key=lambda x: -x[''prompts''])\nmax_prompts = results[0][''prompts''] if results else 1\n```\n\n## HTML Template\n\nUse terminal aesthetic with:\n- Monospace system fonts: `''SF Mono'', ''Monaco'', ''Inconsolata'', monospace`\n- Dark background: `#0d0d0d`\n- Muted colors: `#b0b0b0` (text), `#555` (dim), `#4ec9b0` (cyan), `#ce9178` (orange)\n- ASCII box-drawing for header\n- `$ command --flags` style section headers\n- ASCII bar chart using `█` characters\n\n```html\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>claude-analytics</title>\n  <style>\n    body {\n      font-family: ''SF Mono'', ''Monaco'', ''Inconsolata'', monospace;\n      background: #0d0d0d;\n      color: #b0b0b0;\n      font-size: 14px;\n      line-height: 1.6;\n      padding: 24px;\n    }\n    .container { max-width: 900px; margin: 0 auto; }\n    .header { color: #6a9955; margin-bottom: 24px; }\n    .dim { color: #555; }\n    .bright { color: #e0e0e0; }\n    .cyan { color: #4ec9b0; }\n    .orange { color: #ce9178; }\n    .row {\n      display: grid;\n      grid-template-columns: 24px 200px 1fr 80px 80px 60px;\n      gap: 8px;\n      padding: 6px 0;\n      border-bottom: 1px solid #1a1a1a;\n    }\n    .row:hover { background: #141414; }\n    a { color: #555; text-decoration: none; }\n    a:hover { color: #888; }\n    .stat-box { display: inline-block; margin-right: 32px; }\n    .stat-value { font-size: 28px; color: #e0e0e0; }\n    .stat-label { color: #555; font-size: 12px; }\n  </style>\n</head>\n<body>\n  <div class=\"container\">\n    <pre class=\"header\">\n┌─────────────────────────────────────────────────────────────────┐\n│   ██████╗██╗      █████╗ ██╗   ██╗██████╗ ███████╗              │\n│  ██╔════╝██║     ██╔══██╗██║   ██║██╔══██╗██╔════╝              │\n│  ██║     ██║     ███████║██║   ██║██║  ██║█████╗                │\n│  ██║     ██║     ██╔══██║██║   ██║██║  ██║██╔══╝                │\n│  ╚██████╗███████╗██║  ██║╚██████╔╝██████╔╝███████╗              │\n│   ╚═════╝╚══════╝╚═╝  ╚═╝ ╚═════╝ ╚═════╝ ╚══════╝              │\n│   Weekly Analytics Report                                       │\n│   {start_date} .. {end_date}                                    │\n└─────────────────────────────────────────────────────────────────┘\n</pre>\n    <!-- Stats, table, chart sections -->\n  </div>\n</body>\n</html>\n```\n\n## Bar Chart Generation\n\n```python\ndef make_bar(value, max_val, width=40):\n    filled = int((value / max_val) * width)\n    return ''█'' * filled\n\n# Example output:\n# cohorts          ████████████████████████████████████████ 194\n# ai-whisper       █████████████████████████████████████▋ 183\n```\n\n## Usage\n\n1. User asks for analytics: \"покажи статистику cc\", \"weekly report\", \"что делал за неделю\"\n2. Run Python script to collect data\n3. Generate HTML with template\n4. Save to `~/claude-analytics.html`\n5. Open in browser: `open ~/claude-analytics.html`\n\n## Customization\n\n- **Period:** Change `days = 7` to desired range\n- **Output path:** Change save location\n- **Colors:** Adjust CSS variables\n- **Columns:** Add/remove metrics in grid\n"},"lastSynced":"2026-03-08T02:00:40.933Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Analysis Agents needing advanced Claude Code usage analytics and HTML report generation capabilities.","zh":"非常适合需要高级Claude Code使用分析和HTML报告生成功能的Python分析Agent。","ja":"高度なClaude Code使用状況分析とHTMLレポート生成機能を必要とするPython分析エージェントに最適です。","ko":"고급 Claude Code 사용 분석 및 HTML 보고서 생성 기능이 필요한 Python 분석 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Análisis de Python que necesitan análisis avanzados de uso de Claude Code y capacidades de generación de informes HTML.","fr":"Parfait pour les Agents d''Analyse Python nécessitant des analyses avancées de l''utilisation de Claude Code et des capacités de génération de rapports HTML.","de":"Perfekt für Python-Analyse-Agents, die erweiterte Nutzungsanalysen von Claude Code und Funktionen zur HTML-Berichterstellung benötigen.","pt":"Perfeito para Agentes de Análise Python que necessitam de análises avançadas de uso do Claude Code e capacidades de geração de relatórios HTML.","ru":"Идеально подходит для Агентов анализа Python, которым необходимы расширенная аналитика использования Claude Code и возможности генерации HTML-отчетов.","ar":"مثالي لعوامل تحليل Python التي تحتاج إلى تحليلات متقدمة لاستخدام Claude Code وإمكانيات إنشاء تقارير HTML."},"recommendation":{"en":"Empowers agents to generate comprehensive HTML reports of Claude Code usage from ~/.claude/history.jsonl, utilizing Git data for enhanced analytics and providing insights through ASCII art headers, summary stats, and project tables with remote links.","zh":"使Agent能够利用Git数据生成来自~/.claude/history.jsonl的全面Claude Code使用情况HTML报告，通过ASCII艺术标题、摘要统计和带有远程链接的项目表格提供深入分析。","ja":"~/.claude/history.jsonlからのClaude Code使用状況に関する包括的なHTMLレポートを生成し、Gitデータを活用した高度な分析と、ASCIIアートヘッダー、サマリー統計、リモートリンク付きプロジェクトテーブルによるインサイト提供を可能にします。","ko":"~/.claude/history.jsonl에서 Claude Code 사용에 대한 포괄적인 HTML 보고서를 생성하며, 향상된 분석을 위해 Git 데이터를 활용하고 ASCII 아트 헤더, 요약 통계 및 원격 링크가 포함된 프로젝트 테이블을 통해 인사이트를 제공합니다.","es":"Permite a los agentes generar informes HTML completos del uso de Claude Code a partir de ~/.claude/history.jsonl, utilizando datos de Git para análisis mejorados y proporcionando información a través de encabezados de arte ASCII, estadísticas de resumen y tablas de proyectos con enlaces remotos.","fr":"Permet aux agents de générer des rapports HTML complets sur l''utilisation de Claude Code à partir de ~/.claude/history.jsonl, en utilisant les données Git pour des analyses améliorées et en fournissant des insights via des en-têtes en art ASCII, des statistiques récapitulatives et des tableaux de projets avec des liens distants.","de":"Ermöglicht es Agents, umfassende HTML-Berichte über die Claude Code-Nutzung aus ~/.claude/history.jsonl zu generieren, nutzt Git-Daten für erweiterte Analysen und liefert Einblicke durch ASCII-Art-Header, Zusammenfassungsstatistiken und Projekt-Tabellen mit Remote-Links.","pt":"Capacita os agentes a gerarem relatórios HTML abrangentes do uso do Claude Code a partir de ~/.claude/history.jsonl, utilizando dados do Git para análises aprimoradas e fornecendo insights através de cabeçalhos de arte ASCII, estatísticas de resumo e tabelas de projetos com links remotos.","ru":"Позволяет агентам генерировать комплексные HTML-отчеты об использовании Claude Code из ~/.claude/history.jsonl, используя данные Git для расширенной аналитики и предоставляя аналитику через заголовки с ASCII-артом, сводную статистику и таблицы проектов со ссылками на удаленные репозитории.","ar":"يمكن العوامل من إنشاء تقارير HTML شاملة لاستخدام Claude Code من ~/.claude/history.jsonl، باستخدام بيانات Git لتحليلات معززة وتقديم رؤى من خلال رؤوس برسوم ASCII، وإحصائيات ملخصة، وجداول المشاريع مع روابط بعيدة."},"useCases":{"en":["Generating HTML reports of Claude Code usage","Analyzing project insights with Git data integration","Visualizing ASCII bar charts for commit counts"],"zh":["生成Claude Code使用情况的HTML报告","通过Git数据集成分析项目洞察","使用ASCII条形图可视化提交计数"],"ja":["Claude Code使用状況のHTMLレポート生成","Gitデータ連携によるプロジェクトインサイトの分析","コミット数のASCII棒グラフによる可視化"],"ko":["Claude Code 사용 현황에 대한 HTML 보고서 생성","Git 데이터 통합을 통한 프로젝트 인사이트 분석","커밋 횟수를 위한 ASCII 막대 그래프 시각화"],"es":["Generación de informes HTML del uso de Claude Code","Análisis de información del proyecto con integración de datos de Git","Visualización de gráficos de barras ASCII para recuentos de commits"],"fr":["Génération de rapports HTML sur l''utilisation de Claude Code","Analyse des insights du projet avec intégration des données Git","Visualisation de diagrammes en barres ASCII pour les décomptes de commits"],"de":["Generieren von HTML-Berichten über die Claude Code-Nutzung","Analyse von Projekteinblicken mit Git-Datenintegration","Visualisierung von ASCII-Balkendiagrammen für Commit-Zählungen"],"pt":["Geração de relatórios HTML do uso do Claude Code","Análise de insights do projeto com integração de dados do Git","Visualização de gráficos de barras ASCII para contagens de commit"],"ru":["Генерация HTML-отчетов об использовании Claude Code","Анализ аналитики проекта с интеграцией данных Git","Визуализация ASCII-гистограмм для подсчета коммитов"],"ar":["إنشاء تقارير HTML لاستخدام Claude Code","تحليل رؤى المشروع مع تكامل بيانات Git","تصوير مخططات بار ASCII لأعداد الـ commit"]},"limitations":{"en":["Requires access to ~/.claude/history.jsonl","Python script execution needed","Git data availability required for enhanced analytics"],"zh":["需要访问~/.claude/history.jsonl","需要执行Python脚本","增强分析需要Git数据可用性"],"ja":["~/.claude/history.jsonlへのアクセスが必要","Pythonスクリプトの実行が必要","高度な分析にはGitデータの可用性が必要"],"ko":["~/.claude/history.jsonl에 대한 액세스 필요","Python 스크립트 실행 필요","향상된 분석을 위해 Git 데이터 가용성 필요"],"es":["Requiere acceso a ~/.claude/history.jsonl","Se necesita la ejecución de un script de Python","Se requiere la disponibilidad de datos de Git para análisis mejorados"],"fr":["Nécessite un accès à ~/.claude/history.jsonl","Exécution d''un script Python nécessaire","Disponibilité des données Git requise pour des analyses améliorées"],"de":["Erfordert Zugriff auf ~/.claude/history.jsonl","Ausführung eines Python-Skripts erforderlich","Git-Datenverfügbarkeit für erweiterte Analysen erforderlich"],"pt":["Requer acesso a ~/.claude/history.jsonl","Necessita da execução de script Python","Disponibilidade de dados Git necessária para análises aprimoradas"],"ru":["Требуется доступ к ~/.claude/history.jsonl","Требуется выполнение Python-скрипта","Для расширенной аналитики необходима доступность данных Git"],"ar":["يتطلب الوصول إلى ~/.claude/history.jsonl","يتطلب تنفيذ سكربت Python","يتوفر بيانات Git مطلوبة للتحليلات المعززة"]},"version":4},"contentHash":"8005260291525360d794124b3c9e02282d60b7476516c23e7c4ad1189e0e37e9","qualityScore":51}');
