INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('am-will/codex-skills/parallel-task', 'parallel-task', 'am-will', 'codex-skills', 'community', 'parallel-task am-will codex-skills community The parallel-task skill enables AI agents to orchestrate subagents, parsing plan files and delegating tasks in a loop until completion. This skill benefits developers seeking efficient task management. parallel-task是一种并行任务执行器，能够解析计划文件、委托任务给子代理，并确保任务正确完成和日志更新 parallel-taskは並列タスク実行器で、プランファイルを解析し、タスクをサブエージェントに委託し、タスクの完了とログ更新を確実に行います parallel-task는 병렬 작업 실행기로, 계획 파일을解析하고 작업을 하위 에이전트에 위임하며, 작업 완료와 로그 업데이트 를 보장합니다 El ejecutor de tareas paralelas es un orchestrador para subagentes que delega tareas en paralelo utilizando dependencias de tareas. Asegúrate de que los subagentes se lancen en el orden correcto y completen sus tareas correctamente. L''exécuteur de tâches parallèles est un orchestrateur pour des sous-agents qui délègue des tâches en parallèle en utilisant des dépendances de tâches. Assurez-vous que les sous-agents soient lancés dans le bon ordre et terminent leurs tâches correctement. Der parallele Aufgabenausführer ist ein Orchestrierer für Subagenten, der Aufgaben parallel mithilfe von Aufgabenabhängigkeiten delegiert. Stellen Sie sicher, dass die Subagenten in der richtigen Reihenfolge gestartet werden und ihre Aufgaben korrekt abschließen. O parallel-task é um executor de tarefas paralelas que delega tarefas a subagentes, garantindo a ordem correta de execução e atualizações de logs Параллельное выполнение задач - это исполнитель параллельных задач, который делегирует задачи субагентам, обеспечивая правильный порядок выполнения и обновления журналов parallel-task هو منفذ مهام متوازية يفوض المهام إلى وكلاء فرعيين، مما يضمن التنفيذ بالترتيب الصحيح وتحديثات السجلات how to use parallel-task parallel-task setup guide what is parallel-task parallel-task alternative parallel-task vs workflow management parallel-task install parallel-task orchestration mode parallel-task AIエージェント 并行任务执行 计划文件解析 任务依赖关系 子代理管理 日志更新 Python CLI Parses plan files to extract task dependencies Delegates tasks to parallel subagents in waves Ensures correct task completion order using orchestration mode Updates plan documents with logs after each task completion Utilizes a loop to manage tasks until all are completed parallel-task is a skill that enables AI agents to act as orchestrators for subagents, managing task dependencies and updating plan documents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('m1heng/clawdbot-feishu/feishu-doc', 'community', 'm1heng', 'clawdbot-feishu', 'm1heng/clawdbot-feishu', 'feishu-doc', 0, 0, 51, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:52.765Z', 'a6e047a0530e40d9dc06db21d71ae4391267d932840753df7ebd0dd452e7944c', '{"id":"m1heng/clawdbot-feishu/feishu-doc","name":"feishu-doc","description":{"en":"The feishu-doc skill enables developers to manage documents and comments via a single tool. It supports actions like reading documents and extracting tokens from URLs.","zh":"Feishu 文档工具提供了文档读取、评论管理和 token 提取等功能，帮助开发者高效地处理文档","ja":"Feishu ドキュメントツールは、文書読み取り、コメント管理、トークン抽出など、開発者が文書を効率良く処理するための機能を提供します","ko":"Feishu 문서 도구는 문서 읽기, 댓글 관리, 토큰 추출 등 다양한 기능을 제공하여 개발자가 문서를 효율적으로 처리할 수 있도록 합니다","es":"Feishu-doc es una herramienta para gestionar documentos y comentarios con acciones personalizadas como leer documentos y extraer tokens","fr":"Feishu-doc est un outil pour gérer des documents et des commentaires avec des actions personnalisées comme lire des documents et extraire des tokens","de":"Feishu-doc ist ein Tool zur Verwaltung von Dokumenten und Kommentaren mit maßgeschneiderten Aktionen wie dem Lesen von Dokumenten und der Extraktion von Tokens","pt":"A ferramenta Feishu-Doc é uma solução de gerenciamento de documentos que permite realizar operações de leitura e comentários de forma eficiente","ru":"Feishu-Doc - это решение для управления документами, которое позволяет выполнять операции чтения и комментирования документов эффективно","ar":"أداة Feishu-Doc هي حل لإدارة الوثائق يسمح بتنفيذ عمليات القراءة والتعليقات بفعالية"},"seo":{"title":{"en":"feishu-doc: Document Management Setup Guide | AI Agent Skill","zh":"Feishu 文档工具集成指南","ja":"Feishu ドキュメントツールのベストプラクティス","ko":"Feishu 문서 도구 설정 가이드","es":"Guía de configuración de feishu-doc para desarrolladores","fr":"Guide d''intégration de feishu-doc pour les développeurs","de":"Einrichtungsleitfaden für feishu-doc-Entwickler","pt":"Guia de Configuração do Feishu-Doc: Ferramenta de Documentos","ru":"Настройка Feishu-Doc: ИИ Агент для Управления Документами","ar":"دليل إعداد Feishu-Doc: أداة إدارة الوثائق الذكية"},"description":{"en":"Unlock efficient document operations with feishu-doc. Discover how to extract tokens, read documents, and manage comments. Get started now!","zh":"了解 Feishu 文档工具的功能和特性，包括文档读取、评论管理和 token 提取","ja":"Feishu ドキュメントツールの機能と特性を紹介します。文書読み取り、コメント管理、トークン抽出など","ko":"Feishu 문서 도구의 기능과 특징을 살펴보세요. 문서 읽기, 댓글 관리, 토큰 추출 등","es":"Descubre cómo utilizar feishu-doc para gestionar documentos y comentarios con nuestras acciones personalizadas","fr":"Découvrez comment utiliser feishu-doc pour gérer des documents et des commentaires avec nos actions personnalisées","de":"Erfahren Sie, wie Sie feishu-doc verwenden, um Dokumente und Kommentare mit unseren maßgeschneiderten Aktionen zu verwalten","pt":"Aprenda a configurar e utilizar a ferramenta Feishu-Doc para gerenciar documentos e comentários de forma eficiente","ru":"Узнайте, как настроить и использовать Feishu-Doc для эффективного управления документами и комментариями","ar":"تعرف على كيفية إعداد واستخدام أداة Feishu-Doc لإدارة الوثائق والتعليقات بفعالية"},"definition":{"en":"feishu-doc is a document management tool that allows for token extraction and document operations, including comment management, using a single tool with action parameters.","zh":"Feishu 文档工具是一种提供文档读取、评论管理和 token 提取等功能的 AI 工具","ja":"Feishu ドキュメントツールは、文書読み取り、コメント管理、トークン抽出などの機能を提供する AI エージェントです","ko":"Feishu 문서 도구는 문서 읽기, 댓글 관리, 토큰 추출 등의 기능을 제공하는 AI 도구입니다","es":"Feishu-doc es una herramienta de documento que permite la gestión de documentos y comentarios mediante acciones personalizadas","fr":"Feishu-doc est un outil de document qui permet la gestion de documents et de commentaires via des actions personnalisées","de":"Feishu-doc ist ein Dokumenten-Tool, das die Verwaltung von Dokumenten und Kommentaren über maßgeschneiderte Aktionen ermöglicht","pt":"O que é Feishu-Doc? É uma ferramenta de gerenciamento de documentos que fornece operações de leitura e comentários","ru":"Что такое Feishu-Doc? Это инструмент управления документами, который предоставляет операции чтения и комментирования","ar":"ما هي أداة Feishu-Doc? هي أداة لإدارة الوثائق توفر عمليات القراءة والتعليقات"},"features":{"en":["Extracts doc_token from Feishu document URLs","Supports read action to retrieve document title, plain text content, and block statistics","Manages comments using the feishu_doc tool","Returns structured content with hint field, if present","Uses JSON format for action parameters, such as { \"action\": \"read\", \"doc_token\": \"ABC123def\" }"],"zh":["文档读取功能","评论管理功能","token 提取功能","支持 JSON 格式的文档内容","提供文档标题、平文内容和块统计信息"],"ja":["文書読み取り機能","コメント管理機能","トークン抽出機能","JSON 形式の文書内容をサポート","文書タイトル、平文内容、ブロック統計情報を提供"],"ko":["문서 읽기 기능","댓글 관리 기능","토큰 추출 기능","JSON 형식의 문서 내용을 지원","문서 제목, 평문 내용, 블록 통계 정보를 제공"],"es":["Lectura de documentos con extracción de tokens","Gestión de comentarios con acciones personalizadas","Compatibilidad con documentos de Feishu","Acciones de lectura y extracción de contenido","Soporte para URLs de Feishu"],"fr":["Lecture de documents avec extraction de tokens","Gestion de commentaires avec des actions personnalisées","Compatibilité avec les documents Feishu","Actions de lecture et d''extraction de contenu","Prise en charge des URLs Feishu"],"de":["Dokumentenlesung mit Token-Extraktion","Kommentarverwaltung mit maßgeschneiderten Aktionen","Kompatibilität mit Feishu-Dokumenten","Lese- und Inhaltsextraktionsaktionen","Unterstützung für Feishu-URLs"],"pt":["Suporte à leitura de documentos","Gerenciamento de comentários","Extração de token de documento","Ações de leitura e comentários via JSON"],"ru":["Поддержка чтения документов","Управление комментариями","Извлечение токена документа","Действия чтения и комментирования через JSON"],"ar":["دعم قراءة الوثائق","إدارة التعليقات","استخراج رمز الوثيقة","أفعال القراءة والتعليقات عبر JSON"]},"keywords":{"en":["how to use feishu-doc","feishu-doc setup guide","feishu-doc alternative","feishu-doc vs document management tools","feishu-doc install","feishu-doc token extraction","feishu-doc comment management","feishu-doc JSON action parameters","feishu-doc document operations"],"zh":["Feishu 文档工具","AI 工具","文档读取","评论管理","token 提取","JSON 格式","文档内容","开发者工具"],"ja":["Feishu ドキュメントツール","AI エージェント","文書読み取り","コメント管理","トークン抽出","JSON 形式","文書内容","開発者ツール"],"ko":["Feishu 문서 도구","AI 도구","문서 읽기","댓글 관리","토큰 추출","JSON 형식","문서 내용","개발자 도구"],"es":["feishu-doc","herramienta de documento","gestión de documentos","gestión de comentarios","acciones personalizadas","extracción de tokens","desarrollo de software","integración de API","herramientas de productividad"],"fr":["feishu-doc","outil de document","gestion de documents","gestion de commentaires","actions personnalisées","extraction de tokens","développement de logiciels","intégration d''API","outils de productivité"],"de":["feishu-doc","Dokumenten-Tool","Dokumentenverwaltung","Kommentarverwaltung","maßgeschneiderte Aktionen","Token-Extraktion","Software-Entwicklung","API-Integration","Produktivitäts-Tools"],"pt":["Feishu-Doc","gerenciamento de documentos","ferramenta de documentos","leitura de documentos","comentários de documentos","extração de token","JSON"],"ru":["Feishu-Doc","управление документами","инструмент управления документами","чтение документов","комментирование документов","извлечение токена","JSON"],"ar":["Feishu-Doc","إدارة الوثائق","أداة إدارة الوثائق","قراءة الوثائق","تعليقات الوثائق","استخراج رمز","JSON"]}},"owner":"m1heng","repo":"clawdbot-feishu","repoPath":"m1heng/clawdbot-feishu","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.283Z","topics":[],"category":"community","skillMd":{"name":"feishu-doc","description":"|","bodyPreview":"# Feishu Document Tool\n\nSingle tool `feishu_doc` with action parameter for all document operations including comment management.\n\n## Token Extraction\n\nFrom URL `https://xxx.feishu.cn/docx/ABC123def` → `doc_token` = `ABC123def`\nFrom URL `https://xxx.feishu.cn/docs/doccn123c` → `doc_token` = `doccn123c`\n\n## Actions\n\n### Read Document\n\n```json\n{ \"action\": \"read\", \"doc_token\": \"ABC123def\" }\n```\n\nReturns: title, plain text content, block statistics. Check `hint` field - if present, structured content","body":"# Feishu Document Tool\n\nSingle tool `feishu_doc` with action parameter for all document operations including comment management.\n\n## Token Extraction\n\nFrom URL `https://xxx.feishu.cn/docx/ABC123def` → `doc_token` = `ABC123def`\nFrom URL `https://xxx.feishu.cn/docs/doccn123c` → `doc_token` = `doccn123c`\n\n## Actions\n\n### Read Document\n\n```json\n{ \"action\": \"read\", \"doc_token\": \"ABC123def\" }\n```\n\nReturns: title, plain text content, block statistics. Check `hint` field - if present, structured content (tables, images) exists that requires `list_blocks`.\n\n### Write Document (Replace All)\n\n```json\n{ \"action\": \"write\", \"doc_token\": \"ABC123def\", \"content\": \"# Title\\n\\nMarkdown content...\" }\n```\n\nReplaces entire document with markdown content. Supports: headings, lists, code blocks, quotes, links, images (`![](url)` auto-uploaded), bold/italic/strikethrough.\n\n**Limitation:** Markdown tables are NOT supported.\n\n### Create + Write (Atomic, Recommended)\n\n```json\n{\n  \"action\": \"create_and_write\",\n  \"title\": \"New Document\",\n  \"content\": \"# Title\\n\\nMarkdown content...\"\n}\n```\n\nWith folder:\n```json\n{\n  \"action\": \"create_and_write\",\n  \"title\": \"New Document\",\n  \"content\": \"# Title\\n\\nMarkdown content...\",\n  \"folder_token\": \"fldcnXXX\"\n}\n```\n\nCreates the document and writes content in one call. Prefer this over separate `create` + `write`.\n\n### Append Content\n\n```json\n{ \"action\": \"append\", \"doc_token\": \"ABC123def\", \"content\": \"Additional content\" }\n```\n\nAppends markdown to end of document.\n\n### Create Document\n\n```json\n{ \"action\": \"create\", \"title\": \"New Document\" }\n```\n\nWith folder:\n```json\n{ \"action\": \"create\", \"title\": \"New Document\", \"folder_token\": \"fldcnXXX\" }\n```\n\nCreates an empty document (title only).\n\n### List Blocks\n\n```json\n{ \"action\": \"list_blocks\", \"doc_token\": \"ABC123def\" }\n```\n\nReturns full block data including tables, images. Use this to read structured content.\n\n### Get Single Block\n\n```json\n{ \"action\": \"get_block\", \"doc_token\": \"ABC123def\", \"block_id\": \"doxcnXXX\" }\n```\n\n### Update Block Text\n\n```json\n{ \"action\": \"update_block\", \"doc_token\": \"ABC123def\", \"block_id\": \"doxcnXXX\", \"content\": \"New text\" }\n```\n\n### Delete Block\n\n```json\n{ \"action\": \"delete_block\", \"doc_token\": \"ABC123def\", \"block_id\": \"doxcnXXX\" }\n```\n\n### List Comments\n\n```json\n{ \"action\": \"list_comments\", \"doc_token\": \"ABC123def\", \"page_size\": 50 }\n```\n\nReturns all comments for the document. Use `page_token` for pagination. Comments include `is_whole` field to distinguish between whole-document comments (true) and block-level comments (false).\n\n### Get Single Comment\n\n```json\n{ \"action\": \"get_comment\", \"doc_token\": \"ABC123def\", \"comment_id\": \"comment_xxx\" }\n```\n\n### Create Comment\n\n```json\n{ \"action\": \"create_comment\", \"doc_token\": \"ABC123def\", \"content\": \"Comment text\" }\n```\n\n### List Comment Replies\n\n```json\n{ \"action\": \"list_comment_replies\", \"doc_token\": \"ABC123def\", \"comment_id\": \"comment_xxx\", \"page_size\": 50 }\n```\n\n`page_size` should be a positive integer. If omitted, tool defaults to `50`.\n\n### Comment Write Scope\n\nCurrent tool provides documented comment write action `create_comment` (global comment creation).\nFor replies, use `list_comment_replies` for retrieval; the reply creation endpoint is not exposed in current SDK surface.\n\n## Reading Workflow\n\n1. Start with `action: \"read\"` - get plain text + statistics\n2. Check `block_types` in response for Table, Image, Code, etc.\n3. If structured content exists, use `action: \"list_blocks\"` for full data\n\n## Configuration\n\n```yaml\nchannels:\n  feishu:\n    tools:\n      doc: true  # default: true\n```\n\n**Note:** `feishu_wiki` depends on this tool - wiki page content is read/written via `feishu_doc`.\n\n## Permissions\n\nRequired: `docx:document`, `docx:document:readonly`, `docx:document.block:convert`, `drive:drive`\n\nFor comment operations:\n- Read comments: `docx:document.comment:read`\n- Write comments: `docx:document.comment` (optional, for create_comment)\n"},"lastSynced":"2026-03-08T02:00:52.765Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Management Agents needing seamless Feishu document integration and token extraction capabilities.","zh":"非常适合需要无缝集成飞书文档和令牌提取功能的文档管理代理。","ja":"文書管理エージェントが飛書ドキュメントのシームレスな統合とトークン抽出機能を必要とする場合に最適です。","ko":"문서 관리 에이전트가 Feishu 문서의 무결점 통합과 토큰 추출 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Gestión de Documentos que necesitan una integración de documentos de Feishu sin problemas y capacidades de extracción de tokens.","fr":"Parfait pour les Agents de Gestion de Documents ayant besoin d''une intégration de documents Feishu transparente et de capacités d''extraction de jetons.","de":"Perfekt für Dokumentenmanagement-Agents, die eine nahtlose Feishu-Dokumentintegration und Token-Extraktionsfunktionen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Documentos que precisam de integração de documentos Feishu sem interrupções e capacidades de extração de tokens.","ru":"Идеально подходит для агентов по управлению документами, которым необходима бесшовная интеграция документов Feishu и возможности извлечения токенов.","ar":"مثالي لعميل إدارة المستندات الذي يحتاج إلى دمج مستندات Feishu دون انقطاع وقدرات استخراج الرموز."},"recommendation":{"en":"Empowers agents to manage documents and comments via a single tool, supporting actions like reading documents and extracting tokens from URLs using the feishu-doc protocol, enabling efficient document analysis and automation.","zh":"赋予代理管理文档和评论的能力，通过单一工具支持诸如使用 feishu-doc 协议从 URL 中读取文档和提取令牌等操作，实现高效的文档分析和自动化。","ja":"エージェントがドキュメントとコメントを単一のツールで管理できるようにし、feishu-doc プロトコルを使用して URL からドキュメントを読み取り、トークンを抽出するなどのアクションをサポートし、効率的なドキュメント分析と自動化を可能にします。","ko":"에이전트가 문서와 댓글을 단일 도구로 관리할 수 있도록 하며, feishu-doc 프로토콜을 사용하여 URL에서 문서를 읽고 토큰을 추출하는 등의 동작을 지원하여 효율적인 문서 분석과 자동화를 가능하게 합니다.","es":"Habilita a los agentes a gestionar documentos y comentarios a través de una sola herramienta, que admite acciones como la lectura de documentos y la extracción de tokens de URLs utilizando el protocolo feishu-doc, lo que permite un análisis y automatización de documentos eficientes.","fr":"Permet aux agents de gérer des documents et des commentaires via un seul outil, qui prend en charge des actions telles que la lecture de documents et l''extraction de jetons à partir d''URL à l''aide du protocole feishu-doc, permettant ainsi une analyse et une automatisation de documents efficaces.","de":"Ermächtigt Agenten, Dokumente und Kommentare über ein einzelnes Tool zu verwalten, das Aktionen wie das Lesen von Dokumenten und das Extrahieren von Token aus URLs mithilfe des feishu-doc-Protokolls unterstützt, wodurch eine effiziente Dokumentenanalyse und -automatisierung ermöglicht wird.","pt":"Habilita os agentes a gerenciar documentos e comentários por meio de uma única ferramenta, com suporte a ações como leitura de documentos e extração de tokens de URLs usando o protocolo feishu-doc, permitindo uma análise e automação de documentos eficientes.","ru":"Наделяет агентов возможностью управлять документами и комментариями с помощью единственного инструмента, поддерживающего действия, такие как чтение документов и извлечение токенов из URL-адресов с использованием протокола feishu-doc, что обеспечивает эффективный анализ и автоматизацию документов.","ar":"يمنح العميل القدرة على إدارة المستندات والتعليقات من خلال أداة واحدة، مع دعم الإجراءات مثل قراءة المستندات واستخراج الرموز من عناوين URL باستخدام بروتوكول feishu-doc، مما يتيح تحليلًا وتنفيذًا فعالين للمستندات."},"useCases":{"en":["Extracting document tokens from Feishu URLs","Reading and analyzing Feishu document content","Automating comment management on Feishu documents"],"zh":["从飞书 URL 中提取文档令牌","读取和分析飞书文档内容","自动化飞书文档上的评论管理"],"ja":["飛書 URL からドキュメント トークンを抽出する","飛書ドキュメントの内容を読み取り分析する","飛書ドキュメント上的コメント管理を自動化する"],"ko":["Feishu URL에서 문서 토큰 추출하기","Feishu 문서 내용 읽기 및 분석하기","Feishu 문서의 댓글 관리 자동화"],"es":["Extraer tokens de documento de URLs de Feishu","Lectura y análisis de contenido de documentos de Feishu","Automatización de la gestión de comentarios en documentos de Feishu"],"fr":["Extraction de jetons de document à partir d''URL Feishu","Lecture et analyse de contenu de documents Feishu","Automatisation de la gestion de commentaires sur les documents Feishu"],"de":["Extrahieren von Dokumententoken aus Feishu-URLs","Lesen und Analysieren von Feishu-Dokumentinhalten","Automatisierung der Kommentarverwaltung in Feishu-Dokumenten"],"pt":["Extrair tokens de documentos de URLs do Feishu","Ler e analisar o conteúdo do documento do Feishu","Automatizar a gestão de comentários em documentos do Feishu"],"ru":["Извлечение токенов документов из URL-адресов Feishu","Чтение и анализ содержания документа Feishu","Автоматизация управления комментариями к документам Feishu"],"ar":["استخراج الرموز من مستندات عناوين URL من Feishu","قراءة وتحليل محتوى مستند Feishu","توفير إدارة التعليقات على مستندات Feishu"]},"limitations":{"en":["Requires Feishu document URL or doc_token","Limited to Feishu document operations"],"zh":["需要飞书文档 URL 或 doc_token","仅限飞书文档操作"],"ja":["飛書ドキュメント URL または doc_token が必要","飛書ドキュメント操作のみに限定"],"ko":["Feishu 문서 URL 또는 doc_token이 필요","Feishu 문서 작동만 제한"],"es":["Requiere URL de documento de Feishu o doc_token","Limitado a operaciones de documentos de Feishu"],"fr":["Nécessite une URL de document Feishu ou un doc_token","Limité aux opérations de documents Feishu"],"de":["Benötigt Feishu-Dokument-URL oder doc_token","Begrenzt auf Feishu-Dokumentoperationen"],"pt":["Requer URL de documento do Feishu ou doc_token","Limitado a operações de documentos do Feishu"],"ru":["Требуется URL-документа Feishu или doc_token","Ограничен операциями с документами Feishu"],"ar":["يتطلب عنوان URL للمستند من Feishu أو doc_token","محدود بالعمليات على مستندات Feishu"]},"version":4},"contentHash":"a6e047a0530e40d9dc06db21d71ae4391267d932840753df7ebd0dd452e7944c","qualityScore":51}');
