INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vectorize-io/hindsight/hindsight-docs', 'hindsight-docs', 'vectorize-io', 'hindsight', 'community', 'hindsight-docs vectorize-io hindsight community Hindsight-docs provides complete technical documentation for Hindsight, a biomimetic memory system for AI agents, helping developers understand its architecture and core concepts. It benefits AI agent developers who need to configure and integrate Hindsight with various SDKs. Hindsight 文档提供了 AI 智能体内存学习系统的完整技术文档，包括架构、核心概念和API集成 Hindsight ドキュメントは、AI エージェントの学習メモリシステムの完全な技術ドキュメントを提供します。アーキテクチャ、コアコンセプト、API 統合など Hindsight 문서는 AI 에이전트의 학습 메모리 시스템에 대한 완전한 기술 문서를 제공합니다. 아키텍처, 핵심 개념, API 통합 등 Hindsight-docs es un sistema de memoria biomimético para Agentes de IA que permite configurar y utilizar operaciones de retención, recuerdo y reflexión Hindsight-docs est un système de mémoire biomimétique pour les Agents IA qui permet de configurer et d''utiliser des opérations de rétention, de rappel et de réflexion Hindsight-docs ist ein biomimetisches Gedächtnissystem für KI-Agents, das die Konfiguration und Verwendung von Aufbewahrungs-, Abruf- und Reflexionsoperationen ermöglicht O Hindsight-docs é um sistema de memória biomimética para agentes de IA que permite configurar memória e dispositions. Aprenda a utilizar o Hindsight-docs com Python, Node.js e Rust. Hindsight-docs - это биомиметическая память для ИИ агентов, которая позволяет настраивать память и диспозиции. Узнайте, как использовать Hindsight-docs с Python, Node.js и Rust. Hindsight-docs هو نظام ذاكرة بايوميمتيكي للوكلاء الذكاء الاصطناعي الذي يسمح بتكوين الذاكرة والإمكانات. تعرف على كيفية استخدام Hindsight-docs مع Python و Node.js و Rust. how to use hindsight-docs hindsight-docs setup guide hindsight-docs alternative hindsight-docs vs biomimetic memory systems hindsight-docs install hindsight-docs documentation hindsight-docs python sdk hindsight-docs nodejs integration what is hindsight-docs hindsight-docs kubernetes deployment AI 智能体内存学习系统 Hindsight 文档 AI 智能体开发 内存学习系统 Python SDK Node.js SDK Rust SDK Docker Kubernetes pip Configure memory banks and dispositions for optimal performance Set up the Hindsight API server using Docker, Kubernetes, or pip Integrate with Python, Node.js, and Rust SDKs for seamless development Understand retrieval strategies including semantic, BM25, graph, and temporal Learn about retain, recall, and reflect operations for effective memory management hindsight-docs is a technical documentation skill for Hindsight, a biomimetic memory system that enables AI agents to learn and recall information.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dandye/ai-runbooks/correlate-ioc', 'community', 'dandye', 'ai-runbooks', 'dandye/ai-runbooks', 'correlate-ioc', 0, 0, 51, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:56.612Z', 'a8effc146063954faeb0c41e42db25fa7c27e89f036165de3a50e1470eb16d77', '{"id":"dandye/ai-runbooks/correlate-ioc","name":"correlate-ioc","description":{"en":"The correlate-ioc skill checks for existing SIEM alerts and cases related to specific Indicators of Compromise, benefiting security analysts and incident responders. It correlates SIEM alerts with IOCs, such as IP addresses and domains.","zh":"correlate-ioc Skill 检查现有的 SIEM 警报和案例，相关指标为 IOC_LIST 和可选的 TIME_FRAME_HOURS 和 SOAR_CASE_FILTER","ja":"correlate-ioc Skill は、既存の SIEM アラートとケースを、IOC_LIST およびオプションの TIME_FRAME_HOURS と SOAR_CASE_FILTER で関連付ける","ko":"correlate-ioc 스킬은 기존 SIEM 경고와 사례를 IOC_LIST 및 선택적 TIME_FRAME_HOURS 및 SOAR_CASE_FILTER와 관련","es":"Correlate-ioc busca alertas de SIEM y casos relacionados con Indicadores de Compromiso. Configura la habilidad para su uso en agentes de inteligencia artificial.","fr":"Correlate-ioc recherche des alertes SIEM et des cas liés aux indicateurs de compromis. Configurez la compétence pour son utilisation dans les agents d''IA.","de":"Correlate-ioc sucht nach SIEM-Alarmen und Fällen in Bezug auf Kompromissindikatoren. Konfigurieren Sie die Fähigkeit für die Verwendung in KI-Agents.","pt":"O Correlate-IOC é uma ferramenta de análise de Indicadores de Comprometimento que ajuda a detectar ameaças em sua infraestrutura, com recursos de busca de alerts de SIEM e casos de SOAR","ru":"ИИ Агент Correlate-IOC - это инструмент анализа Индикаторов Компрометации, который помогает обнаружить угрозы в вашей инфраструктуре, с возможностями поиска оповещений SIEM и дел SOAR","ar":"أداة تجميع IOC هي أداة تحليل مؤشرات الاختراق التي تساعد في اكتشاف التهديدات في بني