INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dandye/ai-runbooks/correlate-ioc', 'correlate-ioc', 'dandye', 'ai-runbooks', 'community', 'correlate-ioc dandye ai-runbooks community The correlate-ioc skill checks for existing SIEM alerts and cases related to specific Indicators of Compromise, benefiting security analysts and incident responders. It correlates SIEM alerts with IOCs, such as IP addresses and domains. correlate-ioc Skill 检查现有的 SIEM 警报和案例，相关指标为 IOC_LIST 和可选的 TIME_FRAME_HOURS 和 SOAR_CASE_FILTER correlate-ioc Skill は、既存の SIEM アラートとケースを、IOC_LIST およびオプションの TIME_FRAME_HOURS と SOAR_CASE_FILTER で関連付ける correlate-ioc 스킬은 기존 SIEM 경고와 사례를 IOC_LIST 및 선택적 TIME_FRAME_HOURS 및 SOAR_CASE_FILTER와 관련 Correlate-ioc busca alertas de SIEM y casos relacionados con Indicadores de Compromiso. Configura la habilidad para su uso en agentes de inteligencia artificial. Correlate-ioc recherche des alertes SIEM et des cas liés aux indicateurs de compromis. Configurez la compétence pour son utilisation dans les agents d''IA. Correlate-ioc sucht nach SIEM-Alarmen und Fällen in Bezug auf Kompromissindikatoren. Konfigurieren Sie die Fähigkeit für die Verwendung in KI-Agents. O Correlate-IOC é uma ferramenta de análise de Indicadores de Comprometimento que ajuda a detectar ameaças em sua infraestrutura, com recursos de busca de alerts de SIEM e casos de SOAR ИИ Агент Correlate-IOC - это инструмент анализа Индикаторов Компрометации, который помогает обнаружить угрозы в вашей инфраструктуре, с возможностями поиска оповещений SIEM и дел SOAR أداة تجميع IOC هي أداة تحليل مؤشرات الاختراق التي تساعد في اكتشاف التهديدات في بنيتك التحتية، مع ميزات البحث عن تنبيهات SIEM وحالات SOAR how to use correlate-ioc correlate-ioc setup guide SIEM alert correlation Indicators of Compromise (IOCs) analysis correlate-ioc vs other security tools install correlate-ioc what is correlate-ioc correlate-ioc tutorial correlate-ioc best practices correlate-ioc SIEM 警报 案例关联 IOC_LIST TIME_FRAME_HOURS SOAR_CASE_FILTER Python 开发 CLI 命令 Searches for alerts containing any IOC in the list using SIEM alert data Supports optional lookback period for SIEM alerts via TIME_FRAME_HOURS parameter Allows additional filtering for SOAR cases using SOAR_CASE_FILTER parameter Correlates IOCs such as IP addresses (e.g., 198.51.100.10) and domains (e.g., evil-domain.com) correlate-ioc is a skill that correlates SIEM alerts with Indicators of Compromise (IOCs) to identify potential security threats');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jvidalv/100cims/api', 'community', 'jvidalv', '100cims', 'jvidalv/100cims', 'api', 0, 0, 51, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:05.038Z', 'f319902131b628a0730dc935ed7c13dfd26368eea6db96797b3c3df6df534878', '{"id":"jvidalv/100cims/api","name":"api","description":{"en":"The api skill provides a hybrid backend using Next.js and Elysia for React Native mobile apps, enabling developers to track mountain summits and join hiking challenges.","zh":"使用 Next.js 和 Elysia 构建混合后端 API，实现 React Native 应用的数据交互","ja":"Next.js と Elysia を使用してハイブリッドバックエンド API を構築し、React Native アプリのデータ交換を実現します","ko":"Next.js와 Elysia를 사용하여 하이브리드 백엔드 API를 구축하고 React Native 앱의 데이터 교환을 구현합니다","es":"La API de 100cims es una plataforma de backend híbrida que combina Next.js y Elysia para desarrollar aplicaciones móviles robustas","fr":"L''API 100cims est une plateforme de backend hybride qui combine Next.js et Elysia pour développer des applications mobiles robustes","de":"Die 100cims-API ist eine hybride Backend-Plattform, die Next.js und Elysia kombiniert, um robuste Mobile Apps zu entwickeln","pt":"A API é um componente fundamental para o seu aplicativo React Native, permitindo a integração com o backend","ru":"API является фундаментальным компонентом для вашего приложения React Native, обеспечивающим интеграцию с бэкендом для ИИ Агентов","ar":"واجهة برمجة التطبيقات API هي مكون أساسي لبرنامجك React Native، مما يسمح بالتكامل مع الخادم الخلفي"},"seo":{"title":{"en":"api: Next.js and Elysia Hybrid Backend Setup Guide | AI A...","zh":"API 开发指南：Next.js + Elysia 混合后端","ja":"API Setup Guide：Next.js + Elysia ハイブリッドバックエンド","ko":"API 개발 가이드: Next.js + Elysia 하이브리드 백엔드","es":"Guía de configuración de API para desarrolladores de apli...","fr":"Guide de mise en place de l''API pour les développeurs d''a...","de":"API-Setup-Leitfaden für Mobile App-Entwickler","pt":"Guia de Configuração de API para Desenvolvedores","ru":"Настройка API: Руководство для ИИ Агентов","ar":"دليل إعداد واجهة برمجة التطبيقات API"},"description":{"en":"Unlock the full potential of the 100cims API with our expert guide, featuring Elysia app composition, Next.js catch-all, and Drizzle schema - start building ...","zh":"了解如何使用 Next.js 和 Elysia 构建混合后端 API，实现高性能和可扩展性","ja":"Next.js と Elysia を使用してハイブリッドバックエンド API を構築する方法について学びます","ko":"Next.js와 Elysia를 사용하여 하이브리드 백엔드 API를 구축하고 높은 성능 및 확장성을 달성하는 방법에 대해 알아보세요","es":"Aprende a configurar y utilizar la API de 100cims con Next.js y Elysia para desarrollar aplicaciones móviles","fr":"Découvrez comment configurer et utiliser l''API 100cims avec Next.js et Elysia pour développer des applications mobiles","de":"Erfahren Sie, wie Sie die 100cims-API mit Next.js und Elysia für die Entwicklung von Mobile Apps konfigurieren und verwenden","pt":"Aprenda a configurar a API para o seu aplicativo React Native, incluindo roteamento com Elysia e Next.js","ru":"Узнайте, как настроить API для своего приложения React Native, включая маршрутизацию с Elysia и Next.js для ИИ Агентов","ar":"تعلم كيفية إعداد واجهة برمجة التطبيقات API لبرنامجك React Native، بما في ذلك التوجيه مع Elysia و Next.js"},"definition":{"en":"api is a Next.js and Elysia hybrid backend for building scalable and efficient server-side applications","zh":"API 是一种软件接口，允许不同应用程序之间的数据交互","ja":"API は、異なるアプリケーション間のデータ交換を可能にするソフトウェアインターフェースです","ko":"API는 다른 애플리케이션 간의 데이터 교환을 가능하게 하는 소프트웨어 인터페이스입니다","es":"La API es un conjunto de reglas y protocolos que permiten la comunicación entre aplicaciones y servicios","fr":"L''API est un ensemble de règles et de protocoles qui permettent la communication entre les applications et les services","de":"Die API ist ein Satz von Regeln und Protokollen, die die Kommunikation zwischen Anwendungen und Diensten ermöglichen","pt":"A API é uma interface de programação que permite a comunicação entre o aplicativo e o servidor","ru":"API - это интерфейс программирования, обеспечивающий связь между приложением и сервером для ИИ Агентов","ar":"واجهة برمجة التطبيقات API هي واجهة برمجة تتيح الاتصال بين التطبيق والخادم"},"features":{"en":["Elysia app composition via src/api/routes/index.ts","Next.js catch-all routing with src/app/api/[[...slugs]]/route.ts","Drizzle schema management using src/db/schema.ts","Database client integration with src/db/index.ts","JWT middleware implementation in src/api/routes/@shared/jwt.ts","S3 integration using src/api/routes/@shared/s3.ts"],"zh":["Next.js 和 Elysia 混合后端","Elysia 应用程序组成和错误处理","Next.js catch-all 路由","Drizzle 模式管理","JWT 中间件","S3 集成"],"ja":["Next.js と Elysia ハイブリッドバックエンド","Elysia アプリケーション構成とエラー処理","Next.js catch-all ルーティング","Drizzle スキーマ管理","JWT ミドルウェア","S3 統合"],"ko":["Next.js와 Elysia 하이브리드 백엔드","Elysia 애플리케이션 구성 및 오류 처리","Next.js catch-all 라우팅","Drizzle 스키마 관리","JWT 미들웨어","S3 통합"],"es":["Arquitectura de backend híbrida con Next.js y Elysia","Manejo de rutas con Elysia y Next.js","Autenticación con JWT","Integración con S3","Esquema de base de datos con Drizzle"],"fr":["Architecture de backend hybride avec Next.js et Elysia","Gestion des routes avec Elysia et Next.js","Authentification avec JWT","Intégration avec S3","Schéma de base de données avec Drizzle"],"de":["Hybride Backend-Architektur mit Next.js und Elysia","Routenverwaltung mit Elysia und Next.js","Authentifizierung mit JWT","Integration mit S3","Datenbankschema mit Drizzle"],"pt":["Roteamento com Elysia","Integração com Next.js","Suporte a JWT","Integração com S3","Utilização de Drizzle para schema do banco de dados","Composição de aplicativos com Elysia"],"ru":["Маршрутизация с Elysia","Интеграция с Next.js","Поддержка JWT","Интеграция с S3","Использование Drizzle для схемы базы данных","Составление приложений с Elysia для ИИ Агентов"],"ar":["التوجيه مع Elysia","التكامل مع Next.js","دعم JWT","التكامل مع S3","استخدام Drizzle لschema قاعدة البيانات","تركيب التطبيقات مع Elysia"]},"keywords":{"en":["how to use api with Next.js","api vs Express.js","100cims api setup guide","Elysia framework tutorial","what is api in React Native","api alternative for mobile apps","api install with Drizzle schema","Next.js and Elysia hybrid backend","api setup for hiking challenges","api documentation for developers"],"zh":["API 开发","Next.js","Elysia","混合后端","React Native","数据交互","API 设计","后端开发"],"ja":["API 開発","Next.js","Elysia","ハイブリッドバックエンド","React Native","データ交換","API デザイン","バックエンド開発"],"ko":["API 개발","Next.js","Elysia","하이브리드 백엔드","React Native","데이터 교환","API 디자인","백엔드 개발"],"es":["desarrollo de aplicaciones móviles","API de 100cims","Next.js","Elysia","autenticación con JWT","integración con S3","esquema de base de datos con Drizzle","desarrollo de backend","arquitectura de backend híbrida"],"fr":["développement d''applications mobiles","API 100cims","Next.js","Elysia","authentification avec JWT","intégration avec S3","schéma de base de données avec Drizzle","développement de backend","architecture de backend hybride"],"de":["Entwicklung von Mobile Apps","100cims-API","Next.js","Elysia","Authentifizierung mit JWT","Integration mit S3","Datenbankschema mit Drizzle","Backend-Entwicklung","hybride Backend-Architektur"],"pt":["api react native","roteamento elysia","integração next.js","jwt middleware","s3 integração","drizzle schema","desenvolvimento api","guias de configuração api"],"ru":["api react native","маршрутизация elysia","интеграция next.js","jwt middleware","s3 интеграция","drizzle схема","разработка api","руководства по настройке api для ИИ Агентов"],"ar":["واجهة برمجة التطبيقات react native","التوجيه مع elysia","التكامل مع next.js","دعم jwt","التكامل مع s3","استخدام drizzle لschema","تطوير واجهة برمجة التطبيقات api","دليل إعداد واجهة برمجة التطبيقات api"]}},"owner":"jvidalv","repo":"100cims","repoPath":"jvidalv/100cims","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"api","description":"Use when working on the backend API (packages/api). Covers Elysia routes, Drizzle ORM, TypeBox schemas, JWT authentication, S3 uploads, Google Sheets logging, and the Next.js hybrid setup.","bodyPreview":"# API Development Guide\n\nYou are working on the **100cims API** (`packages/api`), a Next.js + Elysia hybrid backend.\n\n## Key Files\n\n| File | Purpose |\n| ---- | ------- |\n| `src/api/routes/index.ts` | Elysia app composition, error handling |\n| `src/app/api/[[...slugs]]/route.ts` | Next.js catch-all for Elysia |\n| `src/db/schema.ts` | Drizzle schema (source of truth) |\n| `src/db/index.ts` | Database client |\n| `src/api/routes/@shared/jwt.ts` | JWT middleware |\n| `src/api/routes/@shared/s3.ts` | S3","body":"# API Development Guide\n\nYou are working on the **100cims API** (`packages/api`), a Next.js + Elysia hybrid backend.\n\n## Key Files\n\n| File | Purpose |\n| ---- | ------- |\n| `src/api/routes/index.ts` | Elysia app composition, error handling |\n| `src/app/api/[[...slugs]]/route.ts` | Next.js catch-all for Elysia |\n| `src/db/schema.ts` | Drizzle schema (source of truth) |\n| `src/db/index.ts` | Database client |\n| `src/api/routes/@shared/jwt.ts` | JWT middleware |\n| `src/api/routes/@shared/s3.ts` | S3 upload utilities |\n| `src/api/lib/sheets.ts` | Google Sheets logging |\n| `drizzle.config.ts` | Database connection config |\n\n## Architecture\n\n### Hybrid Stack\n\n- **Next.js 15** (App Router) for web pages and runtime\n- **Elysia 1.4** for API routes (mounted at `/api/*`)\n- **Drizzle ORM** with PostgreSQL\n- **TypeBox** for schema validation\n\n### Why This Hybrid?\n\nElysia provides excellent TypeScript inference, OpenAPI generation, and performance while Next.js handles the server runtime and potential web pages.\n\n### Directory Structure\n\n- `/src/api/`: All Elysia API code\n  - `/routes/`: Route handlers (public, protected, @shared)\n  - `/schemas/`: TypeBox validation schemas\n  - `/lib/`: Utilities (sheets, dates, images, slug)\n- `/src/db/`: Database schema and client\n- `/src/app/`: Next.js pages and API catch-all route\n\n### Shared Utilities\n\n| File | Purpose |\n| ---- | ------- |\n| `src/api/lib/slug.ts` | `generateSlug()` - URL-friendly slug generation |\n| `src/api/lib/images.ts` | `isBase64SizeValid()` - Image size validation |\n| `src/api/lib/sheets.ts` | Google Sheets logging utilities |\n| `src/api/lib/dates.ts` | Date formatting utilities |\n\n## Key Patterns\n\n### Route Organization\n\n```\n/api/routes/\n├── @shared/          # Middleware, JWT, S3, types\n├── public/           # No auth required\n│   ├── mountains.route.ts\n│   ├── challenge.route.ts\n│   └── hiscores.route.ts\n├── protected/        # JWT required\n│   ├── summit.route.ts\n│   ├── user.route.ts\n│   ├── plan.route.ts\n│   ├── mountains/    # Folder-based organization\n│   │   ├── index.ts\n│   │   ├── my-list.route.ts\n│   │   └── update.route.ts\n│   └── community-challenge/\n│       ├── index.ts\n│       ├── create.route.ts\n│       ├── update.route.ts\n│       └── delete.route.ts\n└── index.ts          # Compose all routes\n```\n\n**Folder-based routes**: Group related endpoints in folders with an `index.ts` that composes them with a prefix. Each endpoint gets its own file.\n\n### Creating Routes\n\n```typescript\nimport { Elysia } from ''elysia'';\nimport { db } from ''@/db'';\nimport { userSchema } from ''@/api/schemas'';\n\nexport const userRoute = new Elysia({ prefix: ''/user'', tags: [''users''] })\n  .get(''/:id'', async ({ params }) => {\n    const user = await db.query.user.findFirst({\n      where: (u, { eq }) => eq(u.id, params.id)\n    });\n    return user;\n  }, {\n    detail: { summary: ''Get user by ID'' },\n    params: userSchema.params,\n    response: userSchema.response\n  });\n```\n\n### Protected Routes\n\n```typescript\nimport { jwt } from ''@/api/routes/@shared/jwt'';\nimport { store } from ''@/api/routes/@shared/store'';\n\nexport const summitRoute = new Elysia({ prefix: ''/summit'', tags: [''summits''] })\n  .use(jwt)\n  .use(store)\n  .derive(async ({ bearer, store }) => {\n    const payload = await bearer(bearer);\n    store.userId = payload.userId;\n  })\n  .post(''/'', async ({ body, store }) => {\n    // store.userId available from JWT\n    const summit = await db.insert(summitTable).values({\n      userId: store.userId,\n      mountainId: body.mountainId\n    });\n    return summit;\n  });\n```\n\n### Database Queries\n\n```typescript\nimport { db } from ''@/db'';\nimport { user, summit, mountain } from ''@/db/schema'';\nimport { eq, desc } from ''drizzle-orm'';\n\n// Simple query\nconst users = await db.select().from(user).where(eq(user.id, userId));\n\n// Join query\nconst summits = await db\n  .select({\n    id: summit.id,\n    mountainName: mountain.name,\n    date: summit.createdAt\n  })\n  .from(summit)\n  .leftJoin(mountain, eq(summit.mountainId, mountain.id))\n  .where(eq(summit.userId, userId))\n  .orderBy(desc(summit.createdAt));\n```\n\n### Schema Validation\n\n```typescript\nimport { t } from ''elysia'';\n\nexport const summitSchema = {\n  body: t.Object({\n    mountainId: t.String(),\n    date: t.Optional(t.String()),\n    image: t.Optional(t.String())\n  }),\n  response: {\n    200: t.Object({\n      id: t.String(),\n      mountainId: t.String(),\n      userId: t.String()\n    })\n  }\n};\n```\n\n### Pagination Pattern\n\nFor paginated endpoints, use this pattern for backwards compatibility:\n\n```typescript\n// Schema\nexport const PaginatedItemsSchema = t.Object({\n  items: t.Array(ItemSchema),\n  pagination: t.Object({\n    page: t.Number(),\n    pageSize: t.Number(),\n    totalItems: t.Number(),\n    totalPages: t.Number(),\n    hasMore: t.Boolean(),\n  }),\n});\n\n// Route handler - backwards compatible\nconst isPaginated = query.page !== undefined || query.limit !== undefined;\n\nif (isPaginated) {\n  // Return paginated results with count query\n  return { items: results, pagination: { page, pageSize, totalItems, totalPages, hasMore } };\n}\n\n// No pagination params = return ALL results (backwards compatible)\nreturn { items: results, pagination: { page: 1, pageSize: results.length, totalItems: results.length, totalPages: 1, hasMore: false } };\n```\n\n**Key**: Old clients without pagination params get all results. New clients can paginate.\n\n## Common Tasks\n\n### Add New Endpoint\n\n1. Create schema in `/api/schemas/`\n2. Create route file in `/routes/public/` or `/protected/`\n3. Import and use in `/routes/index.ts`\n4. Mobile app: Run `yarn generate-api-types`\n\n### Database Migration\n\n1. Update `/src/db/schema.ts`\n2. Run `yarn drizzle-kit push` (pushes to DB)\n3. Verify schema changes in database\n\n### Image Upload to S3\n\n```typescript\nimport { putImageOnS3 } from ''@/api/routes/@shared/s3'';\n\nconst key = `${process.env.APP_NAME}/user/avatar/${userId}.jpeg`;\nawait putImageOnS3(key, buffer);\n```\n\n### Log to Google Sheets\n\n```typescript\nimport { addRowToSheets, ERRORS_SPREADSHEET } from ''@/api/lib/sheets'';\n\nawait addRowToSheets(ERRORS_SPREADSHEET, [\n  ''error_type'',\n  ''status_code'',\n  ''url'',\n  ''message''\n]);\n```\n\n## Environment Variables\n\n- `DATABASE_URL`: PostgreSQL connection string\n- `AUTH_SECRET`: JWT signing secret\n- `AWS_*`: S3 credentials (region, bucket, access keys)\n- `SHEETS_*`: Google service account credentials\n- `APP_NAME`: Application name (used in S3 paths)\n\nSee `.env.example` for complete list.\n\n## Swagger Documentation\n\nAvailable at `/api/swagger` during development. Auto-generated from:\n- Route tags\n- TypeBox schemas\n- OpenAPI metadata in route definitions\n\n## Database Schema\n\nSee `/src/db/schema.ts` for full schema. Key tables:\n- `user`: OAuth accounts\n- `mountain`: Peak data (name, lat/lng, elevation, difficulty)\n- `summit`: User summit logs\n- `plan`: Group hiking plans\n- `plan_attendee`: Plan participants\n- `plan_chat`: Chat messages\n- `challenge`: Curated challenges\n- `hiscores`: Leaderboard\n\n## Error Handling\n\nGlobal error handler in `/routes/index.ts`:\n- Logs all errors to Google Sheets\n- Returns appropriate HTTP status codes\n- Distinguishes ValidationError, ParseError, generic errors\n\n## Deployment\n\nVercel (configured in root `vercel.json`):\n- Builds from `packages/api`\n- Environment variables set in Vercel dashboard\n- Automatic deployments on main branch\n"},"lastSynced":"2026-03-08T02:01:05.038Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents requiring hybrid backend development using Next.js and Elysia for React Native mobile apps.","zh":"适合需要使用 Next.js 和 Elysia 进行混合后端开发的全栈代理，用于 React Native 移动应用。","ja":"Next.js と Elysia を使用したハイブリッドバックエンド開発を必要とするフルスタックエージェントに適しています。React Native モバイルアプリ用です。","ko":"Next.js와 Elysia를 사용하여 하이브리드 백엔드 개발을 필요로 하는 풀스택 에이전트에 적합합니다. React Native 모바일 앱용입니다.","es":"Ideal para Agentes de Full Stack que requieren desarrollo de backend híbrido utilizando Next.js y Elysia para aplicaciones móviles de React Native.","fr":"Idéal pour les agents Full Stack nécessitant un développement de backend hybride utilisant Next.js et Elysia pour les applications mobiles React Native.","de":"Ideal für Full-Stack-Agents, die eine hybride Backend-Entwicklung mit Next.js und Elysia für React-Native-Mobile-Apps erfordern.","pt":"Ideal para Agentes Full Stack que exigem desenvolvimento híbrido de backend usando Next.js e Elysia para aplicativos móveis React Native.","ru":"Идеально для полнофункциональных агентов, требующих гибридного бэкенд-разработки с использованием Next.js и Elysia для мобильных приложений React Native.","ar":"مثالي لعميل متكامل يتطلب تطوير خلفي هجين باستخدام Next.js و Elysia لتطبيقات الجوال React Native."},"recommendation":{"en":"Empowers agents to build scalable APIs with Elysia app composition, error handling, and JWT middleware, leveraging Drizzle schema and S3 integration for robust data management.","zh":"赋予代理构建可扩展的 API 的能力，使用 Elysia 应用组合、错误处理和 JWT 中间件，利用 Drizzle 模式和 S3 集成进行强大的数据管理。","ja":"Elysia アプリのコンポジション、エラーハンドリング、JWT ミドルウェアを使用して、拡張可能な API を構築するエージェントを可能にします。Drizzle スキーマと S3 統合を使用した堅牢なデータ管理も可能です。","ko":"Elysia 애플리케이션 구성, 오류 처리 및 JWT 미들웨어를 사용하여 확장 가능한 API를 구축할 수 있는 에이전트를 가능하게 합니다. Drizzle 스키마 및 S3 통합을 사용한 강력한 데이터 관리도 가능합니다.","es":"Habilita a los agentes a crear APIs escalables con la composición de aplicaciones de Elysia, el manejo de errores y el middleware de JWT, aprovechando el esquema de Drizzle y la integración de S3 para un manejo de datos robusto.","fr":"Permet aux agents de créer des API évolutives avec la composition d''applications Elysia, la gestion des erreurs et le middleware JWT, en exploitant le schéma Drizzle et l''intégration S3 pour une gestion de données robuste.","de":"Ermächtigt Agents, skalierbare APIs mit der App-Zusammensetzung von Elysia, Fehlerbehandlung und JWT-Middleware zu erstellen, indem es das Drizzle-Schema und die S3-Integration für eine robuste Datenverwaltung nutzt.","pt":"Habilita os agentes a construir APIs escaláveis com composição de aplicativos Elysia, tratamento de erros e middleware JWT, aproveitando o esquema Drizzle e a integração do S3 para gerenciamento de dados robusto.","ru":"Наделяет агентов возможностью создавать масштабируемые API с помощью композиции приложений Elysia, обработки ошибок и middleware JWT, используя схему Drizzle и интеграцию с S3 для надежного управления данными.","ar":"يمكن للعميل بناء واجهات برمجة تطبيقات قابلة للتوسيع مع تكوين تطبيقات Elysia ومعالجة الأخطاء وبرمجيات JWT الوسيطة، مستفيدا من مخطط Drizzle وتكامل S3 لإدارة البيانات القوية."},"useCases":{"en":["Developing hybrid backends for React Native apps","Implementing JWT authentication for secure API routes","Integrating S3 storage for media handling"],"zh":["为 React Native 应用开发混合后端","实现 JWT 身份验证以保护 API 路由","集成 S3 存储以处理媒体"],"ja":["React Native アプリのハイブリッドバックエンド開発","JWT 認証を実装して API ルートを保護する","S3 ストレージを統合してメディアを処理する"],"ko":["React Native 애플리케이션을 위한 하이브리드 백엔드 개발","JWT 인증을 구현하여 API 루트를 보호","S3 스토리지를 통합하여 미디어를 처리"],"es":["Desarrollar backends híbridos para aplicaciones de React Native","Implementar autenticación JWT para rutas de API seguras","Integrar almacenamiento S3 para el manejo de medios"],"fr":["Développer des backends hybrides pour les applications React Native","Mettre en œuvre l''authentification JWT pour des routes API sécurisées","Intégrer le stockage S3 pour la gestion des médias"],"de":["Hybride Backends für React-Native-Apps entwickeln","JWT-Authentifizierung für sichere API-Routen implementieren","S3-Speicher für Medienhandhabung integrieren"],"pt":["Desenvolver backends híbridos para aplicativos React Native","Implementar autenticação JWT para rotas de API seguras","Integrar armazenamento S3 para manipulação de mídia"],"ru":["Разработка гибридных бэкендов для приложений React Native","Реализация аутентификации JWT для безопасных маршрутов API","Интеграция хранилища S3 для обработки медиа"],"ar":["تطوير الخلفيات الهجينة لتطبيقات الجوال React Native","تنفيذ مصادقة JWT لطرق واجهة برمجة التطبيقات الآمنة","دمج مخزن S3 لمعالجة الوسائط"]},"limitations":{"en":["Requires Next.js and Elysia setup","Dependent on Drizzle schema for database management","Limited to React Native mobile app development"],"zh":["需要 Next.js 和 Elysia 设置","依赖于 Drizzle 模式进行数据库管理","仅限 React Native 移动应用开发"],"ja":["Next.js と Elysia の設定が必要","Drizzle スキーマに依存してデータベース管理を行う","React Native モバイルアプリ開発のみ"],"ko":["Next.js와 Elysia 설정이 필요","Drizzle 스키마에 의존하여 데이터베이스 관리","React Native 모바일 애플리케이션 개발만"],"es":["Requiere configuración de Next.js y Elysia","Depende del esquema de Drizzle para la gestión de la base de datos","Limitado al desarrollo de aplicaciones móviles de React Native"],"fr":["Nécessite une configuration de Next.js et Elysia","Dépend du schéma Drizzle pour la gestion de la base de données","Limité au développement d''applications mobiles React Native"],"de":["Benötigt Next.js- und Elysia-Setup","Hängt vom Drizzle-Schema für die Datenbankverwaltung ab","Begrenzt auf die Entwicklung von React-Native-Mobile-Apps"],"pt":["Exig