INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jvidalv/100cims/api', 'api', 'jvidalv', '100cims', 'community', 'api jvidalv 100cims community The api skill provides a hybrid backend using Next.js and Elysia for React Native mobile apps, enabling developers to track mountain summits and join hiking challenges. 使用 Next.js 和 Elysia 构建混合后端 API，实现 React Native 应用的数据交互 Next.js と Elysia を使用してハイブリッドバックエンド API を構築し、React Native アプリのデータ交換を実現します Next.js와 Elysia를 사용하여 하이브리드 백엔드 API를 구축하고 React Native 앱의 데이터 교환을 구현합니다 La API de 100cims es una plataforma de backend híbrida que combina Next.js y Elysia para desarrollar aplicaciones móviles robustas L''API 100cims est une plateforme de backend hybride qui combine Next.js et Elysia pour développer des applications mobiles robustes Die 100cims-API ist eine hybride Backend-Plattform, die Next.js und Elysia kombiniert, um robuste Mobile Apps zu entwickeln A API é um componente fundamental para o seu aplicativo React Native, permitindo a integração com o backend API является фундаментальным компонентом для вашего приложения React Native, обеспечивающим интеграцию с бэкендом для ИИ Агентов واجهة برمجة التطبيقات API هي مكون أساسي لبرنامجك React Native، مما يسمح بالتكامل مع الخادم الخلفي how to use api with Next.js api vs Express.js 100cims api setup guide Elysia framework tutorial what is api in React Native api alternative for mobile apps api install with Drizzle schema Next.js and Elysia hybrid backend api setup for hiking challenges api documentation for developers API 开发 Next.js Elysia 混合后端 React Native 数据交互 API 设计 后端开发 Elysia app composition via src/api/routes/index.ts Next.js catch-all routing with src/app/api/[[...slugs]]/route.ts Drizzle schema management using src/db/schema.ts Database client integration with src/db/index.ts JWT middleware implementation in src/api/routes/@shared/jwt.ts S3 integration using src/api/routes/@shared/s3.ts api is a Next.js and Elysia hybrid backend for building scalable and efficient server-side applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sfc-gh-dflippo/snowflake-dbt-demo/doc-scraper', 'community', 'sfc-gh-dflippo', 'snowflake-dbt-demo', 'sfc-gh-dflippo/snowflake-dbt-demo', 'doc-scraper', 0, 0, 51, '2026-03-08T01:57:15.293Z', '2026-03-08T02:01:05.051Z', '3aa2c28ffc741680917fd33516db88e0c2acc23e1aeb05d4ca05b19f0e48efb6', '{"id":"sfc-gh-dflippo/snowflake-dbt-demo/doc-scraper","name":"doc-scraper","description":{"en":"The doc-scraper skill simplifies Snowflake documentation management by scraping docs.snowflake.com sections to Markdown with SQLite caching. It benefits developers working with Snowflake Data Cloud and dbt.","zh":"doc-scraper 是一个爬取 Snowflake 文档的工具，使用 SQLite 缓存以提高效率","ja":"doc-scraper は Snowflake ドキュメントをスクレイピングするツールで、SQLite キャッシュを使用して効率を高めています","ko":"doc-scraper는 Snowflake 문서를 크롤링하는 도구로 SQLite 캐시를 사용하여 효율을 높입니다","es":"doc-scraper es una herramienta para scraping de documentación de Snowflake con SQLite caching y compatibilidad con Python","fr":"doc-scraper est un outil de scraping de documentation Snowflake avec mise en cache SQLite et prise en charge de Python","de":"doc-scraper ist ein Tool für das Scraping von Snowflake-Dokumentation mit SQLite-Caching und Python-Unterstützung","pt":"O doc-scraper é uma ferramenta de extração de documentação do Snowflake que utiliza caching com SQLite e expiração de 7 dias.","ru":"ИИ Агент doc-scraper - это инструмент для сбора документации Snowflake, который использует кэширование SQLite и истечением срока действия 7 дней.","ar":"أداة doc-scraper هي أداة سحب وثائق سنوفليك المتقدمة التي تستخدم ذاكرة التخزين المؤقت SQLite وتنتهي صلاحيتها بعد 7 أيام."},"seo":{"title":{"en":"doc-scraper: Snowflake Documentation Setup Guide | AI Age...","zh":"doc-scraper 设置指南：Snowflake 文档爬取工具","ja":"doc-scraper Setup Guide: Snowflake ドキュメントスクレイピングツール","ko":"doc-scraper 설정 가이드: Snowflake 문서 크롤링 도구","es":"Guía de configuración de doc-scraper para Snowflake","fr":"Guide d''installation de doc-scraper pour Snowflake","de":"Einrichtungsanleitung für doc-scraper mit Snowflake","pt":"Guia de Configuração do doc-scraper: Ferramenta de Extraç...","ru":"ИИ Агент doc-scraper: Руководство по Настройке и Использо...","ar":"دليل إعداد أداة doc-scraper: أداة سحب وثائق متقدمة"},"description":{"en":"Unlock efficient Snowflake documentation scraping with doc-scraper. Learn how to set up and utilize this powerful AI agent skill for streamlined documentatio...","zh":"使用 doc-scraper 从 Snowflake 文档中提取数据，并将其缓存到 SQLite 中，有效期为 7 天","ja":"doc-scraper を使用して Snowflake ドキュメントからデータを抽出して SQLite にキャッシュします。有効期限は 7 日です","ko":"doc-scraper를 사용하여 Snowflake 문서에서 데이터를 추출하고 SQLite에 캐시합니다. 유효 기간은 7일입니다","es":"Aprende a configurar doc-scraper para scraping de documentación de Snowflake con SQLite y Python","fr":"Découvrez comment configurer doc-scraper pour le scraping de documentation Snowflake avec SQLite et Python","de":"Erfahren Sie, wie Sie doc-scraper für das Scraping von Snowflake-Dokumentation mit SQLite und Python einrichten","pt":"Aprenda a configurar e usar o doc-scraper, uma ferramenta de extração de documentação do Snowflake, com recursos como caching com SQLite e expiração de 7 dias.","ru":"Узнайте, как настроить и использовать ИИ Агент doc-scraper, инструмент для сбора документации Snowflake с функциями кэширования SQLite и истечением срока дей...","ar":"تعرف على كيفية إعداد واستخدام أداة doc-scraper، أداة سحب وثائق سنوفليك المتقدمة مع ميزات مثل ذاكرة التخزين المؤقت SQLite وانتهاء صلاحية 7 أيام."},"definition":{"en":"doc-scraper is a Python-based tool that scrapes Snowflake documentation into Markdown format, utilizing SQLite caching for efficient data storage and retrieval.","zh":"doc-scraper 是一个用于爬取和缓存 Snowflake 文档的 AI 工具","ja":"doc-scraper は Snowflake ドキュメントをスクレイピングしてキャッシュする AI エージェントです","ko":"doc-scraper는 Snowflake 문서를 크롤링하고 캐시하는 AI 에이전트입니다","es":"doc-scraper es una herramienta de AI que scrapea secciones de documentación de Snowflake a Markdown","fr":"doc-scraper est un outil d''IA qui scrape les sections de documentation Snowflake en Markdown","de":"doc-scraper ist ein AI-Tool, das Abschnitte der Snowflake-Dokumentation in Markdown scrape","pt":"O doc-scraper é uma ferramenta de extração de documentação que converte seções do site docs.snowflake.com em Markdown.","ru":"ИИ Агент doc-scraper - это инструмент для сбора документации, который конвертирует разделы сайта docs.snowflake.com в Markdown.","ar":"أداة doc-scraper هي أداة سحب وثائق تقوم بتحويل أقسام من موقع docs.snowflake.com إلى Markdown."},"features":{"en":["Scrapes docs.snowflake.com sections to Markdown format","Utilizes SQLite caching with a 7-day expiration policy","Supports customizable output directories via the --output-dir command option","Allows for adjustable spider depth using the --spider-depth command option","Auto-installs required dependencies, including uv and doc-scraper, on first-time setup","Enables subsequent runs with simplified command-line interfaces"],"zh":["支持 SQLite 缓存","7 天缓存过期","命令行界面","支持多级目录爬取","可配置输出目录","支持 Snowflake 文档爬取"],"ja":["SQLite キャッシュをサポート","7 日間のキャッシュ有効期限","コマンドラインインターフェース","複数レベルのディレクトリスクレイピングをサポート","出力ディレクトリを構成可能","Snowflake ドキュメントスクレイピングをサポート"],"ko":["SQLite 캐시 지원","7일 캐시 만료","명령줄 인터페이스","다단계 디렉토리 크롤링 지원","출력 디렉토리 구성 가능","Snowflake 문서 크롤링 지원"],"es":["Scraping de documentación de Snowflake a Markdown","Caching con SQLite con expiración de 7 días","Compatibilidad con Python para ejecución de scripts","Opción de configuración de salida de archivos","Soporte para profundidad de rastreo configurable"],"fr":["Scraping de documentation Snowflake en Markdown","Mise en cache avec SQLite avec expiration de 7 jours","Prise en charge de Python pour l''exécution de scripts","Option de configuration de sortie de fichiers","Support pour la profondeur de traçage configurable"],"de":["Scraping von Snowflake-Dokumentation in Markdown","Caching mit SQLite mit Ablauf von 7 Tagen","Unterstützung von Python für die Ausführung von Skripten","Option zur Konfiguration der Ausgabedateien","Unterstützung für konfigurierbare Spurtiefe"],"pt":["Extração de documentação do Snowflake","Caching com SQLite","Expiração de 7 dias","Suporte a múltiplos comandos","Opção de especificar diretório de saída","Opção de especificar profundidade de spider"],"ru":["Сбор документации Snowflake","Кэширование с SQLite","Истечение срока действия 7 дней","Поддержка нескольких команд","Возможность указать каталог вывода","Возможность указать глубину паука"],"ar":["سحب وثائق سنوفليك","ذاكرة التخزين المؤقت مع SQLite","انتهاء صلاحية 7 أيام","دعم أوامر متعددة","خيار تحديد دليل الإخراج","خيار تحديد عمق سحب"]},"keywords":{"en":["how to use doc-scraper","doc-scraper setup guide","Snowflake documentation scraper","doc-scraper vs dbt","doc-scraper install","what is doc-scraper","doc-scraper alternative","doc-scraper and Snowflake Data Cloud","doc-scraper Python script","doc-scraper SQLite caching"],"zh":["doc-scraper","Snowflake 文档爬取","SQLite 缓存","AI 工具","命令行界面","数据抽取","文档爬取","Snowflake 数据云","dbt"],"ja":["doc-scraper","Snowflake ドキュメントスクレイピング","SQLite キャッシュ","AI エージェント","コマンドラインインターフェース","データ抽出","ドキュメントスクレイピング","Snowflake データクラウド","dbt"],"ko":["doc-scraper","Snowflake 문서 크롤링","SQLite 캐시","AI 에이전트","명령줄 인터페이스","데이터 추출","문서 크롤링","Snowflake 데이터 클라우드","dbt"],"es":["doc-scraper","Snowflake","scraping de documentación","Markdown","SQLite","Python","herramientas de AI","desarrollo de software","integración de datos"],"fr":["doc-scraper","Snowflake","scraping de documentation","Markdown","SQLite","Python","outils d''IA","développement de logiciels","intégration de données"],"de":["doc-scraper","Snowflake","Scraping von Dokumentation","Markdown","SQLite","Python","AI-Tools","Software-Entwicklung","Datenintegration"],"pt":["doc-scraper","ferramenta de extração de documentação","Snowflake","SQLite","caching","expiração de 7 dias","comandos CLI","desenvolvimento de software"],"ru":["ИИ Агент doc-scraper","инструмент для сбора документации","Snowflake","SQLite","кэширование","истечение срока действия 7 дней","команды CLI","разработка программного обеспечения"],"ar":["أداة doc-scraper","أداة سحب وثائق","سنوفليك","SQLite","ذاكرة التخزين المؤقت","انتهاء صلاحية 7 أيام","أوامر CLI","تطوير البرمجيات"]}},"owner":"sfc-gh-dflippo","repo":"snowflake-dbt-demo","repoPath":"sfc-gh-dflippo/snowflake-dbt-demo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.293Z","topics":[],"category":"community","skillMd":{"name":"doc-scraper","description":"","bodyPreview":"# Snowflake Documentation Scraper\n\nScrapes docs.snowflake.com sections to Markdown with SQLite caching (7-day expiration).\n\n## Usage\n\n**First time setup** (auto-installs uv and doc-scraper):\n\n```bash\npython3 .claude/skills/doc-scraper/scripts/doc_scraper.py\n```\n\n**Subsequent runs:**\n\n```bash\ndoc-scraper --output-dir=./snowflake-docs\ndoc-scraper --output-dir=./snowflake-docs --base-path=\"/en/sql-reference/\"\ndoc-scraper --output-dir=./snowflake-docs --spider-depth=2\n```\n\n## Command Options\n\n| Opti","body":"# Snowflake Documentation Scraper\n\nScrapes docs.snowflake.com sections to Markdown with SQLite caching (7-day expiration).\n\n## Usage\n\n**First time setup** (auto-installs uv and doc-scraper):\n\n```bash\npython3 .claude/skills/doc-scraper/scripts/doc_scraper.py\n```\n\n**Subsequent runs:**\n\n```bash\ndoc-scraper --output-dir=./snowflake-docs\ndoc-scraper --output-dir=./snowflake-docs --base-path=\"/en/sql-reference/\"\ndoc-scraper --output-dir=./snowflake-docs --spider-depth=2\n```\n\n## Command Options\n\n| Option           | Default           | Description                           |\n| ---------------- | ----------------- | ------------------------------------- |\n| `--output-dir`   | **Required**      | Output directory for scraped docs     |\n| `--base-path`    | `/en/migrations/` | URL section to scrape                 |\n| `--spider-depth` | `1`               | Link depth: 0=seeds, 1=+links, 2=+2nd |\n| `--limit`        | None              | Cap URLs (for testing)                |\n| `--dry-run`      | -                 | Preview without writing               |\n\n## Output\n\n```sql\noutput-dir/\n├── SKILL.md              # Auto-generated index\n├── scraper_config.yaml   # Editable config (auto-created)\n├── .cache/               # SQLite cache (auto-managed)\n└── en/migrations/*.md    # Scraped pages with frontmatter\n```\n\n## Configuration\n\nAuto-created at `{output-dir}/scraper_config.yaml`:\n\n```yaml\nrate_limiting:\n  max_concurrent_threads: 4\nspider:\n  max_pages: 1000\n  allowed_paths: [\"/en/\"]\nscraped_pages:\n  expiration_days: 7\n```\n\n## Troubleshooting\n\n| Issue            | Solution                              |\n| ---------------- | ------------------------------------- |\n| Too many pages   | Lower `--spider-depth` or edit config |\n| Missing pages    | Increase `--spider-depth`             |\n| Cache corruption | Delete `{output-dir}/.cache/` (rare)  |\n"},"lastSynced":"2026-03-08T02:01:05.051Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing streamlined Snowflake documentation management and Markdown conversion.","zh":"非常适合需要简化Snowflake文档管理和Markdown转换的数据分析代理。","ja":"Snowflakeのドキュメント管理とMarkdown変換をストリームライン化する必要があるデータ分析エージェントに最適です。","ko":"Snowflake 문서 관리 및 Markdown 변환을 스트림라인화해야 하는 데이터 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de datos que necesitan una gestión de documentación de Snowflake optimizada y conversión a Markdown.","fr":"Parfait pour les agents d''analyse de données nécessitant une gestion de documentation Snowflake rationalisée et une conversion en Markdown.","de":"Perfekt für Data-Analytics-Agents, die eine optimierte Snowflake-Dokumentenverwaltung und Markdown-Konvertierung benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de gestão de documentação do Snowflake simplificada e conversão para Markdown.","ru":"Идеально для Агентов Анализа Данных, которым необходим упрощенный менеджмент документации Snowflake и преобразование в Markdown.","ar":"مثالي لعمليات تحليل البيانات التي تحتاج إلى إدارة توثيق Snowflake مبسطة وتحويل إلى Markdown."},"recommendation":{"en":"Empowers agents to scrape and cache Snowflake documentation from docs.snowflake.com to Markdown using SQLite, facilitating efficient data cloud management and dbt development with protocols like SQL and data formats like Markdown.","zh":"使代理能够从docs.snowflake.com中抓取和缓存Snowflake文档到Markdown，使用SQLite，促进高效的数据云管理和使用SQL和Markdown等协议的dbt开发。","ja":"エージェントがdocs.snowflake.comからのSnowflakeドキュメントをMarkdownにスクレイピングしてSQLiteでキャッシュすることを可能にし、SQLやMarkdownなどのプロトコルを使用した効率的なデータクラウド管理とdbt開発を促進します。","ko":"에이전트가 docs.snowflake.com의 Snowflake 문서를 Markdown로 스크레이핑하고 SQLite에서 캐싱할 수 있도록 해주어 SQL과 Markdown 등의 프로토콜을 사용한 효율적인 데이터 클라우드 관리 및 dbt 개발을 촉진합니다.","es":"Habilita a los agentes para extraer y almacenar en caché la documentación de Snowflake de docs.snowflake.com a Markdown utilizando SQLite, lo que facilita una gestión eficiente de la nube de datos y el desarrollo con dbt con protocolos como SQL y formatos de datos como Markdown.","fr":"Permet aux agents d''extraire et de mettre en cache la documentation Snowflake de docs.snowflake.com vers Markdown en utilisant SQLite, ce qui facilite une gestion efficace du cloud de données et le développement avec dbt avec des protocoles comme SQL et des formats de données comme Markdown.","de":"Ermächtigt die Agenten, die Snowflake-Dokumentation von docs.snowflake.com nach Markdown mithilfe von SQLite zu scrapen und zu cachen, was eine effiziente Daten-Cloud-Verwaltung und dbt-Entwicklung mit Protokollen wie SQL und Datenformaten wie Markdown ermöglicht.","pt":"Habilita os agentes a coletar e armazenar em cache a documentação do Snowflake de docs.snowflake.com para Markdown usando SQLite, facilitando o gerenciamento eficiente de dados na nuvem e o desenvolvimento com dbt e protocolos como SQL e formatos de dados como Markdown.","ru":"Наделяет агентов возможностью собирать и кэшировать документацию Snowflake с docs.snowflake.com в Markdown, используя SQLite, что облегчает эффективное управление данными в облаке и разработку с dbt и протоколами, такими как SQL, и форматами данных, такими как Markdown.","ar":"تمكّن الوكلاء من جمع وتخزين وثائق Snowflake من docs.snowflake.com إلى Markdown باستخدام SQLite، مما يسهل إدارة السحابة البيانات بكفاءة وتطوير dbt مع بروتوكولات مثل SQL وتنسيقات البيانات مثل Markdown."},"useCases":{"en":["Scraping Snowflake documentation for offline access","Caching SQL reference guides for faster lookup","Converting documentation to Markdown for easier integration with dbt projects"],"zh":["为离线访问抓取Snowflake文档","缓存SQL参考指南以实现更快的查找","将文档转换为Markdown，以便更容易地与dbt项目集成"],"ja":["オフラインアクセスのためにSnowflakeドキュメントをスクレイピングする","SQLリファレンスガイドをキャッシュして高速な検索を実現する","ドキュメントをMarkdownに変換してdbtプロジェクトとの統合を容易にする"],"ko":["오프라인 액세스를 위해 Snowflake 문서를 스크레이핑합니다.","SQL 참조 가이드를 캐싱하여 빠른 조회를实现합니다.","문서를 Markdown로 변환하여 dbt 프로젝트와의 통합을 쉽게합니다."],"es":["Extracción de documentación de Snowflake para acceso sin conexión","Almacenamiento en caché de guías de referencia de SQL para una búsqueda más rápida","Conversión de documentación a Markdown para una integración más sencilla con proyectos dbt"],"fr":["Extraction de la documentation Snowflake pour un accès hors ligne","Mise en cache des guides de référence SQL pour une recherche plus rapide","Conversion de la documentation en Markdown pour une intégration plus facile avec les projets dbt"],"de":["Scraping der Snowflake-Dokumentation für den Offline-Zugriff","Cachen der SQL-Referenzleitfäden für eine schnellere Suche","Umwandlung der Dokumentation in Markdown für eine einfachere Integration mit dbt-Projekten"],"pt":["Coletar documentação do Snowflake para acesso offline","Armazenar em cache guias de referência SQL para busca mais rápida","Converter documentação para Markdown para integração mais fácil com projetos dbt"],"ru":["Сбор документации Snowflake для автономного доступа","Кэширование справочных руководств SQL для быстрого поиска","Преобразование документации в Markdown для более легкой интеграции с проектами dbt"],"ar":["جمع توثيق Snowflake للوصول离 الخط","تخزين دليل مرجع SQL في الذاكرة Cache للبحث السريع","تحويل التوثيق إلى Markdown لتكامل أسهل مع مشاريع dbt"]},"limitations":{"en":["Requires Python 3 and uv library installation","7-day caching expiration limit","Limited to scraping docs.snowflake.com sections"],"zh":["需要Python 3和uv库安装","7天缓存过期限制","仅限抓取docs.snowflake.com的部分内容"],"ja":["Python 3とuvライブラリのインストールが必要","7日のキャッシュ有効期限の制限","docs.snowflake.comのセクションのスクレイピングのみに限定"],"ko":["Python 3 및 uv 라이브러리 설치가 필요합니다.","7일 캐시 만료 제한","docs.snowflake.com 섹션의 스크레이핑만 가능"],"es":["Requiere la instalación de Python 3 y la biblioteca uv","Límite de caducidad de la caché de 7 días","Limitado a la extracción de secciones de docs.snowflake.com"],"fr":["Nécessite l''installation de Python 3 et de la bibliothèque uv","Limite d''expiration de la mise en cache de 7 jours","Limité à l''extraction des sections de docs.snowflake.com"],"de":["Erfordert die Installation von Python 3 und der uv-Bibliothek","Grenze der Cachegültigkeit von 7 Tagen","Begrenzt auf das Scraping von Abschnitten von docs.snowflake.com"],"pt":["Requer Python 3 e instalação da biblioteca uv","Limite de expiração de cache de 7 dias","Limitado à coleta de seções de docs.snowflake.com"],"ru":["Требуется Python 3 и установка библиотеки uv","Ограничение срока действия кэша в 7 дней","Ограничен сбором разделов с docs.snowflake.com"],"ar":["يتطلب Python 3 وتثبيت مكتبة uv","حد زمني لانتهاء صلاحية ذاكرة التخزين المؤقت لمدة 7 أيام","محدود بجمع أقسام من docs.snowflake.com"]},"version":4},"contentHash":"3aa2c28ffc741680917fd33516db88e0c2acc23e1aeb05d4ca05b19f0e48efb6","qualityScore":51}');
