INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frogr/austnomaton/poster', 'poster', 'frogr', 'austnomaton', 'community', 'poster frogr austnomaton community The Poster skill allows developers to publish content to social platforms like Moltbook and X/Twitter. It supports cross-platform publishing, threads, and scheduling. Poster 技术允许开发者使用 AI 驱动的方式发布内容到社交媒体平台，包括 Moltbook 和 X/Twitter Poster 技術は、開発者が AI エージェントを使用してソーシャルメディアプラットフォームにコンテンツを投稿できるようにします Poster 기술은 개발자가 AI 에이전트를 사용하여 소셜미디어 플랫폼에 콘텐츠를 게시할 수 있도록 합니다 La habilidad de Poster permite publicar contenido en varias plataformas sociales con comandos CLI personalizados La compétence Poster permet de publier du contenu sur plusieurs plateformes sociales avec des commandes CLI personnalisées Die Fähigkeit von Poster ermöglicht die Veröffentlichung von Inhalten auf mehreren sozialen Plattformen mit benutzerdefinierten CLI-Befehlen O Poster é uma ferramenta de IA que permite publicar conteúdo em plataformas sociais de forma eficiente. Com suporte a Moltbook e X/Twitter ИИ Агент Poster - это инструмент, который позволяет публиковать контент на социальных платформах, таких как Moltbook и X/Twitter المنشور هو أداة ذكاء اصطناعي تمكنك من نشر المحتوى على منصات اجتماعية مثل Moltbook و X/Twitter how to use poster poster setup guide cross-platform publishing tools poster alternative poster vs Hootsuite poster install what is poster poster skill for AI agents social media publishing automation AI 社交媒体发布 Poster 技术 跨平台内容管理 Moltbook 发布 X/Twitter 发布 AI 驱动的社交媒体工具 Publishes content to Moltbook, X/Twitter, and other platforms Supports creating threads with the --thread option Allows scheduling posts for later with the --schedule option Enables saving drafts without posting using the --draft option Invokes posts and threads using the /poster command Poster is a skill that enables publishing content to social platforms using commands like /poster and options like --thread and --schedule.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TaylorHuston/local-life-manager/plan', 'community', 'TaylorHuston', 'local-life-manager', 'TaylorHuston/local-life-manager', 'plan', 0, 0, 51, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:09.332Z', '70c1bcc8a06d5a35101f6229d4de4910b3e31f414053ff8e6169c518470b5309', '{"id":"TaylorHuston/local-life-manager/plan","name":"plan","description":{"en":"The plan skill creates a customizable life management framework for Claude Code, generating PLAN.md files with phase-based breakdowns for tasks, spikes, and bugs. It benefits developers and teams seeking to streamline their workflows.","zh":"plan技能提供了一个可自定义的生活管理框架，用于创建任务、spikes和bugs的phase-based分解","ja":"planスキルは、タスク、スパイク、バグを段階的に分解するためのカスタマイズ可能なライフマネジメントフレームワークを提供します","ko":"plan 기능은 태스크, 스파이크, 버그를 चरण별로 분解하여 개인 생산성을 향상시키는 데 도움이 됩니다","es":"El framework ''plan'' es una herramienta personalizable para la gestión de la vida y la productividad, que utiliza CLI para crear planes de tareas y seguimiento.","fr":"Le framework ''plan'' est un outil personnalisable pour la gestion de la vie et de la productivité, qui utilise CLI pour créer des plans de tâches et de suivi.","de":"Das ''plan''-Framework ist ein anpassbares Werkzeug für das Lebens- und Produktivitätsmanagement, das CLI verwendet, um Aufgabenpläne und Nachverfolgung zu erstellen.","pt":"O plano é um framework personalizável para gerenciamento de vida, criado para Claude Code, que inclui skills, agentes e fluxos de trabalho para produtividade pessoal","ru":"План - это настраиваемая структура для управления жизнью, созданная для Claude Code, которая включает навыки, агенты и рабочие процессы для личной продуктивности","ar":"الخطة هي إطار قابل للتعديل لإدارة الحياة، تم إنشاؤه ل Claude Code، ويضم مهارات ووكلاء وتدفقات عمل لزيادة الإنتاجية الشخصية"},"seo":{"title":{"en":"plan: Customizable Life Management Framework for AI Agent...","zh":"AI计划工具设置指南 - Claude Code 任务管理","ja":"AIエージェントのplanスキル設定方法 - タスク管理のベストプラクティス","ko":"AI 에이전트 plan 기능 설정 가이드 - 개인 생산성 향상을 위한 워크플로우","es":"Guía de configuración de ''plan'' para productividad person...","fr":"Guide de configuration de ''plan'' pour la productivité per...","de":"Einrichtungsleitfaden für ''plan'' zur persönlichen Produkt...","pt":"Guia de Configuração do Plano: Ferramentas de Agente de I...","ru":"Настройка Плана: Инструменты ИИ Агентов для Личной Продук...","ar":"دليل إعداد الخطة: أدوات وكلاء الذكاء الاصطناعي للانتاجية"},"description":{"en":"Discover how to create phase-based breakdowns for tasks with /plan. Learn to automate workflows and get peer reviews with Gemini CLI. Get started now!","zh":"了解如何使用plan技能创建自定义的生活管理框架，包括phase-based任务分解、CLI命令和项目管理","ja":"AIエージェントのplanスキルを使用して、タスク管理と生産性を向上させる方法を学びます","ko":"plan 기능을 사용하여 개인 생산성과 태스크 관리를 향상시키는 방법을 알아보세요 - 워크플로우 자동화와 CLI 명령어","es":"Aprende a utilizar ''plan'' para gestionar tareas y mejorar tu productividad personal con herramientas de AI y CLI","fr":"Découvrez comment utiliser ''plan'' pour gérer vos tâches et améliorer votre productivité personnelle avec des outils d''IA et CLI","de":"Erfahren Sie, wie Sie ''plan'' nutzen können, um Aufgaben zu verwalten und Ihre persönliche Produktivität mit KI-Tools und CLI zu verbessern","pt":"Aprenda a configurar o plano para melhorar a produtividade com ferramentas de agente de IA e técnicas de gerenciamento de tarefas","ru":"Узнайте, как настроить план для повышения личной продуктивности с помощью инструментов ИИ агентов и техник управления задачами","ar":"تعرف على كيفية إعداد الخطة لتحسين الإنتاجية باستخدام أدوات وكلاء الذكاء الاصطناعي وتقنيات إدارة المهام"},"definition":{"en":"plan is a customizable life management framework for creating phase-based breakdowns of tasks, spikes, and bugs, utilizing commands like /plan and integrating with Gemini CLI.","zh":"plan技能是一种用于创建自定义生活管理框架的AI工具，用于任务和项目管理","ja":"planスキルは、タスクとプロジェクト管理のためのカスタマイズ可能なライフマネジメントフレームワークを作成するAIエージェントの機能です","ko":"plan 기능은 태스크와 프로젝트 관리를 위한 개인화된 라이프 관리 프레임워크를 생성하는 AI 에이전트의 기능입니다","es":"¿Qué es ''plan''? Un framework de gestión de la vida personalizable para la productividad y el seguimiento de tareas con herramientas de AI","fr":"Qu''est-ce que ''plan''? Un framework de gestion de la vie personnalisable pour la productivité et le suivi des tâches avec des outils d''IA","de":"Was ist ''plan''? Ein anpassbares Framework für das Lebens- und Produktivitätsmanagement mit KI-Tools für die Aufgabenverwaltung und -nachverfolgung","pt":"O que é um plano? Um framework de gerenciamento de vida personalizável para Claude Code","ru":"Что такое план? Настраиваемая структура управления жизнью для Claude Code","ar":"ما هي الخطة؟ إطار لإدارة الحياة قابل للتعديل ل Claude Code"},"features":{"en":["Creates PLAN.md files with phase-based breakdowns for tasks, spikes, and bugs","Supports auto-detection of projects and explicit project specification via --project flag","Generates exploration plans for spikes using /plan SPIKE-003 command","Integrates with Gemini CLI for peer review and second-opinion features via --second-opinion flag","Allows for issue type detection and customized plan structures"],"zh":["创建任务、spikes和bugs的phase-based分解","支持CLI命令行创建计划","自动检测项目和issue类型","支持Gemini CLI进行同行审查","创建自定义的生活管理框架"],"ja":["タスク、スパイク、バグの段階的な分解を作成する","CLIコマンドラインを使用して計画を作成する","プロジェクトとissueタイプを自動で検出する","Gemini CLIを使用して同行審査を行う","カスタマイズ可能なライフマネジメントフレームワークを作成する"],"ko":["태스크, 스파이크, 버그를 चरण별로 분해하는 기능","CLI 명령어를 사용하여 계획을 생성하는 기능","프로젝트와 이슈 유형을 자동으로 감지하는 기능","Gemini CLI를 사용하여 동료 리뷰를 받는 기능","개인화된 라이프 관리 프레임워크를 생성하는 기능"],"es":["Creación de planes de tareas con CLI","Detección automática de tipo de problema","Soporte para proyectos y seguimiento de tareas","Integración con Gemini CLI para revisiones por pares","Personalización de planes de tareas y seguimiento"],"fr":["Création de plans de tâches avec CLI","Détection automatique du type de problème","Prise en charge des projets et du suivi des tâches","Intégration avec Gemini CLI pour les révisions par les pairs","Personnalisation des plans de tâches et de suivi"],"de":["Erstellung von Aufgabenplänen mit CLI","Automatische Erkennung von Problemtypen","Unterstützung für Projekte und Aufgabenverwaltung","Integration mit Gemini CLI für Peer-Reviews","Anpassung von Aufgabenplänen und Nachverfolgung"],"pt":["Criação de PLAN.md com quebra de fase para tarefas, spikes e bugs","Detecção de tipo de problema para criar planos personalizados","Uso de linha de comando (CLI) para criar e gerenciar planos","Integração com Gemini CLI para revisão por pares","Suporte a projetos e tarefas personalizados"],"ru":["Создание PLAN.md с фазовой разбивкой для задач, спайков и ошибок","Обнаружение типа проблемы для создания индивидуальных планов","Использование командной строки (CLI) для создания и управления планами","Интеграция с Gemini CLI для рецензирования","Поддержка пользовательских проектов и задач"],"ar":["إنشاء PLAN.md مع كسر المرحلة ل المهام والرؤوس والbugs","اكتشاف نوع المشكلة لإنشاء خطط مخصصة","استخدام سطر الأوامر (CLI) لإنشاء وإدارة الخطط","التكامل مع Gemini CLI لمراجعة الأقران","دعم المشاريع والمهام المخصصة"]},"keywords":{"en":["how to use plan","plan setup guide","plan alternative","plan vs trello","plan install","what is plan","plan workflow automation","plan gemini cli integration","plan customizable life management","plan phase-based breakdown"],"zh":["AI计划工具","任务管理","CLI命令行","项目管理","生產力工具","AIエージェント","计划技能","生活管理框架"],"ja":["AIエージェント","planスキル","タスク管理","CLIコマンドライン","プロジェクト管理","生産性ツール","ライフマネジメントフレームワーク","同行審査"],"ko":["AI 에이전트","plan 기능","태스크 관리","CLI 명령어","프로젝트 관리","생산성 도구","라이프 관리 프레임워크","동료 리뷰"],"es":["herramientas de AI para productividad","gestión de tareas con CLI","framework de gestión de la vida","planificación de tareas personalizable","seguimiento de tareas con Gemini CLI","productividad personal con herramientas de AI","configuración de ''plan'' para productividad"],"fr":["outils d''IA pour la productivité","gestion de tâches avec CLI","framework de gestion de la vie","planification de tâches personnalisable","suivi des tâches avec Gemini CLI","productivité personnelle avec des outils d''IA","configuration de ''plan'' pour la productivité"],"de":["KI-Tools für die Produktivität","Aufgabenverwaltung mit CLI","Framework für das Lebens- und Produktivitätsmanagement","personalisierte Aufgabenplanung","Nachverfolgung von Aufgaben mit Gemini CLI","persönliche Produktivität mit KI-Tools","Einrichtung von ''plan'' für die Produktivität"],"pt":["plano de produtividade","ferramentas de agente de IA","gerenciamento de tarefas","Claude Code","Gemini CLI","CLI","produtividade pessoal","gestão de vida"],"ru":["план продуктивности","инструменты ИИ агентов","управление задачами","Claude Code","Gemini CLI","CLI","личная продуктивность","управление жизнью"],"ar":["خطة الإنتاجية","أدوات وكلاء الذكاء الاصطناعي","إدارة المهام","Claude Code","Gemini CLI","CLI","الإنتاجية الشخصية","إدارة الحياة"]}},"owner":"TaylorHuston","repo":"local-life-manager","repoPath":"TaylorHuston/local-life-manager","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"plan","description":"Create PLAN.md file with phase-based breakdown for issues. Use after creating an issue with /issue to break down work into phases.","bodyPreview":"# /plan\n\nCreate PLAN.md with phase-based breakdown for tasks, spikes, and bugs.\n\n## Usage\n\n```bash\n/plan 001                    # Create plan for issue 001 (auto-detect project)\n/plan 001 --project coordinatr  # Explicit project\n/plan SPIKE-003              # Plan for a spike (creates exploration plans)\n/plan 003 --second-opinion   # Get peer review from Gemini CLI before finalizing\n```\n\n## Issue Type Detection\n\n| Issue Type | Plan Structure | File Created |\n|------------|---------------|-------","body":"# /plan\n\nCreate PLAN.md with phase-based breakdown for tasks, spikes, and bugs.\n\n## Usage\n\n```bash\n/plan 001                    # Create plan for issue 001 (auto-detect project)\n/plan 001 --project coordinatr  # Explicit project\n/plan SPIKE-003              # Plan for a spike (creates exploration plans)\n/plan 003 --second-opinion   # Get peer review from Gemini CLI before finalizing\n```\n\n## Issue Type Detection\n\n| Issue Type | Plan Structure | File Created |\n|------------|---------------|--------------|\n| Task (TASK.md) | Sequential phases with checkpoints | PLAN.md |\n| Bug (BUG.md) | Investigation → Fix phases | PLAN.md |\n| Spike (SPIKE.md) | Exploration phases per approach | PLAN-1.md, PLAN-2.md, ... |\n\n## Execution Flow\n\n### For Task/Bug\n\n1. **Load Context**:\n   ```bash\n   Read: ideas/[project]/issues/###-*/TASK.md (or BUG.md)\n   Read: spaces/[project]/docs/specs/*.md (if implements: field exists)\n   Glob: spaces/[project]/docs/adrs/ADR-*.md\n   Glob: resources/research/*.md\n   ```\n\n   If the issue has an `implements:` field, load that specific spec section:\n   ```bash\n   Read: spaces/[project]/docs/specs/required-features.md  # Extract relevant section\n   ```\n\n2. **Cross-Project Pattern Search**:\n   ```bash\n   # Search other projects for similar implementations\n   Grep: spaces/*/src/ for relevant patterns\n   ```\n\n   Include relevant references in plan:\n   ```markdown\n   ## Related Implementations\n\n   Found similar patterns in other projects:\n   - `spaces/yourbench/src/auth/clerk.ts` - Clerk auth setup\n   - `spaces/coordinatr/src/lib/session.ts` - Session handling\n   ```\n\n3. **Library Documentation** (automatic for integrations):\n\n   **MANDATORY when task involves:**\n   - Installing/configuring external libraries or SDKs\n   - Framework integrations (auth providers, databases, APIs)\n   - Third-party services (Clerk, Stripe, AWS services, etc.)\n\n   **Process:**\n   ```bash\n   # 1. Resolve library ID\n   mcp__context7__resolve-library-id: {libraryName}\n\n   # 2. Fetch current documentation\n   mcp__context7__query-docs: {context7CompatibleLibraryID}\n\n   # 3. Search for recent patterns/best practices\n   WebSearch: \"{library} {framework} integration 2026\"\n   ```\n\n   **Document findings:**\n   ```markdown\n   ## Library Documentation Validation\n\n   **{Library Name}** (validated YYYY-MM-DD):\n   - Current version: X.Y.Z\n   - Key integration patterns: [summary]\n   - Recommended approach: [based on current docs]\n   ```\n\n4. **Generate Plan**:\n   - Break work into logical phases\n   - Each phase has clear deliverables\n   - Include checkpoints between phases\n   - Add \"Done When\" criteria\n\n5. **Write PLAN.md**:\n   - Present phases, estimated effort, dependencies\n   - Include \"Library Documentation Validation\" section (if applicable)\n   - Include \"Second Opinion Analysis\" section (if requested)\n\n6. **Commit Suggestion**:\n   - Ask: \"Commit PLAN.md to ideas repo? (yes/no)\"\n\n### For Spike (Exploration)\n\n1. **Load Context**: Read SPIKE.md (questions, success criteria, time box)\n\n2. **Gather Approaches**:\n   - Ask: \"How many approaches to explore?\" → N\n   - For each: \"Describe approach N?\"\n\n3. **Generate**: Create PLAN-N.md for each approach\n\n4. **Commit Suggestion**: Ask to commit all plan files\n\n## Task Plan Example\n\n```markdown\n# Implementation Plan: 001 Research Auth Patterns\n\n## Overview\nResearch authentication patterns for Coordinatr''s multi-tenant architecture.\n\n## Phase 1: Survey Existing Solutions\n\n### 1.1 - Research Auth Libraries\n- [ ] Review Better Auth documentation\n- [ ] Compare with Auth.js and Lucia\n- [ ] Document trade-offs\n\n### 1.2 - Multi-Tenant Patterns\n- [ ] Research team-based auth patterns\n- [ ] Review how Slack, Linear handle it\n- [ ] [CHECKPOINT] Summary document complete\n\n## Phase 2: Architecture Proposal\n\n### 2.1 - Draft Architecture\n- [ ] Create architecture diagram\n- [ ] Document token strategy\n- [ ] Define permission model\n\n### 2.2 - Review\n- [ ] Self-critique against requirements\n- [ ] [CHECKPOINT] Architecture doc complete\n\n## Done When\n- [ ] Auth library recommendation documented\n- [ ] Architecture proposal in ideas/coordinatr/docs/\n- [ ] Trade-offs and risks identified\n```\n\n## Second Opinion Feature\n\n**What**: Optional peer review from Gemini CLI before finalizing plans.\n\n**Usage**: Pass `--second-opinion` flag to trigger Gemini review with Context7 validation.\n\n**Process**:\n1. Send plan to Gemini CLI for review\n2. Validate each recommendation against Context7 docs\n3. Claude makes final decision on each:\n   - ✅ **ACCEPT**: Recommendation validated AND improves plan\n   - ⚠️ **MODIFY**: Good idea but needs adjustment\n   - ❌ **REJECT**: Invalid or not applicable\n4. Document all decisions in \"Second Opinion Analysis\" section\n\n**Requirements**:\n- Gemini CLI installed and functional\n- `--second-opinion` flag explicitly passed\n\n**Graceful degradation**: If Gemini unavailable, proceeds with Claude-only plan.\n\n## Workflow\n\n```\n/spec → /issue → /plan {ID} → (work phases) → /complete {ID}\n                    ↓\n          Load spec section from implements: field\n```\n\n**Creates:**\n- Task/Bug: `ideas/{project}/issues/###-*/PLAN.md`\n- Spike: `ideas/{project}/issues/###-*/PLAN-1.md`, `PLAN-2.md`, etc.\n"},"lastSynced":"2026-03-08T02:01:09.332Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing customizable life management frameworks and phase-based project planning.","zh":"非常适合需要可定制的生命周期管理框架和基于阶段的项目规划的开发代理。","ja":"開発エージェントがカスタマイズ可能なライフサイクル管理フレームワークとフェーズベースのプロジェクト計画が必要な場合に最適です。","ko":"개발 에이전트가 맞춤형 라이프 사이클 관리 프레임워크와 단계별 프로젝트 계획이 필요한 경우에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan marcos de gestión de vida personalizables y planificación de proyectos basada en fases.","fr":"Parfait pour les agents de développement nécessitant des cadres de gestion de vie personnalisables et une planification de projet basée sur les phases.","de":"Perfekt für Entwicklungsmittel, die anpassbare Lebensverwaltungsframeworks und phasenbasierte Projektplanung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de estruturas de gerenciamento de vida personalizáveis e planejamento de projetos baseado em fases.","ru":"Идеально подходит для агентов разработки, которым требуются настраиваемые фреймворки управления жизнью и фазно-ориентированное планирование проектов.","ar":"مثالية للوكلاء التطوير الذين يحتاجون إلى إطارات إدارة حياة قابلة للتحويل وخطط مشروع dựa على المراحل."},"recommendation":{"en":"Empowers agents to generate phase-based breakdowns for tasks, spikes, and bugs, creating PLAN.md files with customizable structures, utilizing command-line interfaces like Gemini CLI for peer review and project management.","zh":"赋予代理生成基于阶段的任务、Spikes和Bug的细分，创建具有可定制结构的PLAN.md文件，利用Gemini CLI等命令行接口进行同行评审和项目管理。","ja":"エージェントがタスク、スパイク、バグのフェーズベースのブレークダウンを生成し、カスタマイズ可能な構造を持つPLAN.mdファイルを作成することを可能にし、Gemini CLIなどのコマンドラインインターフェイスを使用してピアレビューとプロジェクト管理を実行します。","ko":"에이전트가 태스크, 스파이크, 버그의 단계별 분해를 생성하고, 맞춤형 구조를 가진 PLAN.md 파일을 생성하며, Gemini CLI와 같은 명령줄 인터페이스를 사용하여 동료 리뷰 및 프로젝트 관리를 수행할 수 있습니다.","es":"Habilita a los agentes a generar desgloses basados en fases para tareas, picos y errores, creando archivos PLAN.md con estructuras personalizables, utilizando interfaces de línea de comandos como Gemini CLI para revisión por pares y gestión de proyectos.","fr":"Permet aux agents de générer des décompositions basées sur les phases pour les tâches, les pics et les bogues, créant des fichiers PLAN.md avec des structures personnalisables, en utilisant des interfaces de ligne de commande comme Gemini CLI pour la révision par les pairs et la gestion de projet.","de":"Ermächtigt Agenten, phasenbasierte Aufschlüsselungen für Aufgaben, Spitzen und Fehler zu erstellen, indem sie PLAN.md-Dateien mit anpassbaren Strukturen erstellen, die Kommandozeilen-Schnittstellen wie Gemini CLI für Peer-Review und Projektmanagement nutzen.","pt":"Habilita os agentes a gerar quebras baseadas em fases para tarefas, spikes e bugs, criando arquivos PLAN.md com estruturas personalizáveis, utilizando interfaces de linha de comando como Gemini CLI para revisão por pares e gerenciamento de projetos.","ru":"Наделяет агентов возможностью генерировать фазно-ориентированные разбиения задач, спайков и багов, создавая файлы PLAN.md с настраиваемыми структурами, используя командные интерфейсы, такие как Gemini CLI, для рецензирования и управления проектами.","ar":"تمكّن الوكلاء من إنشاء تحليلات مرحلية لمهام وspikes وbugs، مع إمكانية إنشاء ملفات PLAN.md ذات هياكل قابلة للتعديل، باستخدام واجهات سطر الأوامر مثل Gemini CLI لمراجعة الأقران وإدارة المشاريع."},"useCases":{"en":["Automating project planning with phase-based breakdowns","Generating exploration plans for spikes","Streamlining workflows with customizable PLAN.md files"],"zh":["使用基于阶段的细分自动化项目规划","为Spikes生成探索计划","使用可定制的PLAN.md文件简化工作流"],"ja":["フェーズベースのブレークダウンを使用したプロジェクト計画の自動化","スパイクのための探索計画の生成","カスタマイズ可能なPLAN.mdファイルを使用したワークフローの合理化"],"ko":["단계별 분해를 사용한 프로젝트 계획 자동화","스파이크에 대한 탐색 계획 생성","맞춤형 PLAN.md 파일을 사용한 워크플로우 최적화"],"es":["Automatización de la planificación de proyectos con desgloses basados en fases","Generación de planes de exploración para picos","Optimización de flujos de trabajo con archivos PLAN.md personalizables"],"fr":["Automatisation de la planification de projet avec des décompositions basées sur les phases","Génération de plans d''exploration pour les pics","Optimisation des flux de travail avec des fichiers PLAN.md personnalisables"],"de":["Automatisierung der Projektplanung mit phasenbasierten Aufschlüsselungen","Erstellung von Erforschungsplänen für Spitzen","Optimierung von Workflows mit anpassbaren PLAN.md-Dateien"],"pt":["Automatizar o planejamento de projetos com quebras baseadas em fases","Gerar planos de exploração para spikes","Otimizar fluxos de trabalho com arquivos PLAN.md personalizáveis"],"ru":["Автоматизировать планирование проектов с фазно-ориентированными разбиениями","Генерировать планы исследования для спайков","Оптимизировать рабочие процессы с настраиваемыми файлами PLAN.md"],"ar":["توفير تخطيط المشاريع بالمراحل","إنشاء خطط استكشافية لspikes","تسهيل سير العمل بملفات PLAN.md قابلة للتعديل"]},"limitations":{"en":["Requires command-line interface access","Limited to generating PLAN.md files","Dependent on issue type detection for plan structure"],"zh":["需要命令行接口访问","仅限生成PLAN.md文件","依赖于问题类型检测来确定计划结构"],"ja":["コマンドラインインターフェイスへのアクセスが必要","PLAN.mdファイルの生成のみ","計画構造の決定には問題タイプの検出に依存する"],"ko":["명령줄 인터페이스 액세스가 필요","PLAN.md 파일 생성만","계획 구조 결정에는 문제 유형 감지에 의존"],"es":["Requiere acceso a la interfaz de línea de comandos","Limitado a la generación de archivos PLAN.md","Dependiente de la detección del tipo de problema para la estructura del plan"],"fr":["Nécessite un accès à l''interface de ligne de commande","Limité à la génération de fichiers PLAN.md","Dépend de la détection du type de problème pour la structure du plan"],"de":["Benötigt Zugriff auf die Kommandozeilen-Schnittstelle","Begrenzt auf die Erstellung von PLAN.md-Dateien","Abhängig von der Erkennung des Problemtyps für die Planstruktur"],"pt":["Requer acesso à interface de linha de comando","Limitado à geração de arquivos PLAN.md","Dependente da detecção do tipo de problema para a estrutura do plano"],"ru":["Требует доступа к командной строке","Ограничен генерацией файлов PLAN.md","Зависит от обнаружения типа проблемы для структуры плана"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","محدود بإنشاء ملفات PLAN.md","يعتمد على تحديد نوع المشكلة لهيكل الخطة"]},"version":4},"contentHash":"70c1bcc8a06d5a35101f6229d4de4910b3e31f414053ff8e6169c518470b5309","qualityScore":51}');
