INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TaylorHuston/local-life-manager/plan', 'plan', 'TaylorHuston', 'local-life-manager', 'community', 'plan TaylorHuston local-life-manager community The plan skill creates a customizable life management framework for Claude Code, generating PLAN.md files with phase-based breakdowns for tasks, spikes, and bugs. It benefits developers and teams seeking to streamline their workflows. plan技能提供了一个可自定义的生活管理框架，用于创建任务、spikes和bugs的phase-based分解 planスキルは、タスク、スパイク、バグを段階的に分解するためのカスタマイズ可能なライフマネジメントフレームワークを提供します plan 기능은 태스크, 스파이크, 버그를 चरण별로 분解하여 개인 생산성을 향상시키는 데 도움이 됩니다 El framework ''plan'' es una herramienta personalizable para la gestión de la vida y la productividad, que utiliza CLI para crear planes de tareas y seguimiento. Le framework ''plan'' est un outil personnalisable pour la gestion de la vie et de la productivité, qui utilise CLI pour créer des plans de tâches et de suivi. Das ''plan''-Framework ist ein anpassbares Werkzeug für das Lebens- und Produktivitätsmanagement, das CLI verwendet, um Aufgabenpläne und Nachverfolgung zu erstellen. O plano é um framework personalizável para gerenciamento de vida, criado para Claude Code, que inclui skills, agentes e fluxos de trabalho para produtividade pessoal План - это настраиваемая структура для управления жизнью, созданная для Claude Code, которая включает навыки, агенты и рабочие процессы для личной продуктивности الخطة هي إطار قابل للتعديل لإدارة الحياة، تم إنشاؤه ل Claude Code، ويضم مهارات ووكلاء وتدفقات عمل لزيادة الإنتاجية الشخصية how to use plan plan setup guide plan alternative plan vs trello plan install what is plan plan workflow automation plan gemini cli integration plan customizable life management plan phase-based breakdown AI计划工具 任务管理 CLI命令行 项目管理 生產力工具 AIエージェント 计划技能 生活管理框架 Creates PLAN.md files with phase-based breakdowns for tasks, spikes, and bugs Supports auto-detection of projects and explicit project specification via --project flag Generates exploration plans for spikes using /plan SPIKE-003 command Integrates with Gemini CLI for peer review and second-opinion features via --second-opinion flag Allows for issue type detection and customized plan structures plan is a customizable life management framework for creating phase-based breakdowns of tasks, spikes, and bugs, utilizing commands like /plan and integrating with Gemini CLI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sunholo-data/ailang/Benchmark Manager', 'community', 'sunholo-data', 'ailang', 'sunholo-data/ailang', 'Benchmark Manager', 0, 0, 51, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:14.315Z', 'f0c071b8dbfa409da13dc23d204b8c5e52c04db633b3f9023af6f937fe6a7674', '{"id":"sunholo-data/ailang/Benchmark Manager","name":"Benchmark Manager","description":{"en":"The Benchmark Manager skill helps developers manage AILANG evaluation benchmarks with correct prompt integration and debugging workflows. It provides best practices learned from real benchmark failures.","zh":"Benchmark Manager帮助您管理AILANG评估基准，包括调试工作流和提示集成","ja":"Benchmark ManagerはAILANG評価ベンチマークの管理を支援し、デバッグワークフローとプロンプト統合を提供する","ko":"Benchmark Manager는 AILANG 평가 벤치마크를 관리하고 디버깅 워크플로우와 프롬프트 통합을 지원한다","es":"Benchmark Manager es una herramienta para administrar evaluaciones de AI con integración de prompts correcta y depuración de flujos de trabajo","fr":"Benchmark Manager est un outil pour gérer les évaluations d''IA avec une intégration de prompts correcte et un débogage de flux de travail","de":"Benchmark Manager ist ein Tool zum Verwalten von AI-Bewertungen mit korrekter Prompt-Integration und Debug-Workflows","pt":"O Benchmark Manager é uma ferramenta para gerenciar avaliações de linguagem, permitindo a integração de prompt, fluxos de depuração e melhores práticas","ru":"Benchmark Manager - это инструмент для управления оценками языка, позволяющий интегрировать промпт, отладочные потоки и лучшие практики","ar":"مدير المقارنة هو أداة لإدارة تقييمات اللغة، مما يسمح بدمج الاستطلاع وfluxes التصحيح وأفضل الممارسات"},"seo":{"title":{"en":"Benchmark Manager: Setup Guide for AI Agents | AI Agent S...","zh":"AI工具Benchmark Manager配置指南","ja":"AIエージェントBenchmark Managerのベストプラクティス","ko":"AI Benchmark Manager 설정 가이드","es":"Guía de configuración de Benchmark Manager para AI Agents","fr":"Guide de mise en route de Benchmark Manager pour les outi...","de":"Einrichtungsleitfaden für Benchmark Manager bei KI-Tools","pt":"Guia de Configuração do Benchmark Manager para Ferramenta...","ru":"Руководство по настройке Benchmark Manager для ИИ Агентов","ar":"دليل إعداد مدير المقارنة لآلات اللغة الإصطناعية"},"description":{"en":"Discover how to manage AILANG evaluation benchmarks with ease. Learn to debug workflows and integrate prompts correctly with the Benchmark Manager skill.","zh":"了解如何使用Benchmark Manager管理AILANG评估基准，包括正确的提示集成和调试工作流","ja":"AILANG評価ベンチマークを管理するためのBenchmark Managerの使い方とベストプラクティス","ko":"AILANG 평가 벤치마크를 관리하는 Benchmark Manager의 기능과 사용법","es":"Aprende a administrar evaluaciones de AI con Benchmark Manager y mejora tus flujos de depuración con las mejores prácticas","fr":"Découvrez comment gérer les évaluations d''IA avec Benchmark Manager et améliorez vos flux de débogage avec les meilleures pratiques","de":"Erfahren Sie, wie Sie AI-Bewertungen mit Benchmark Manager verwalten und Ihre Debug-Workflows mit Best Practices verbessern","pt":"Aprenda a gerenciar avaliações de linguagem com o Benchmark Manager, incluindo integração de prompt, fluxos de depuração e melhores práticas","ru":"Узнайте, как управлять оценками языка с помощью Benchmark Manager, включая интеграцию промпта, отладочные потоки и лучшие практики","ar":"تعلم كيفية إدارة تقييمات اللغة مع مدير المقارنة، بما في ذلك دمج الاستطلاع، وfluxes التصحيح وأفضل الممارسات"},"definition":{"en":"Benchmark Manager is a skill that manages AILANG evaluation benchmarks with features like prompt integration, debugging, and best practices for AI model evaluation.","zh":"Benchmark Manager是一种AI工具，用于管理AILANG评估基准","ja":"Benchmark Managerは、AILANG評価ベンチマークを管理するAIエージェントの一種","ko":"Benchmark Manager는 AILANG 평가 벤치마크를 관리하는 AI 에이전트의 일종","es":"Benchmark Manager es una herramienta de gestión de evaluaciones de AI que permite la integración de prompts y depuración de flujos de trabajo","fr":"Benchmark Manager est un outil de gestion d''évaluations d''IA qui permet l''intégration de prompts et le débogage de flux de travail","de":"Benchmark Manager ist ein Tool zur Verwaltung von AI-Bewertungen, das die Integration von Prompts und die Fehlersuche in Workflows ermöglicht","pt":"O que é Benchmark Manager? É uma ferramenta para gerenciar avaliações de linguagem","ru":"Что такое Benchmark Manager? Это инструмент для управления оценками языка","ar":"ما هو مدير المقارنة؟ هو أداة لإدارة تقييمات اللغة"},"features":{"en":["Manages AILANG evaluation benchmarks with correct prompt integration","Provides debugging workflows using scripts like show_full_prompt.sh","Supports testing benchmarks with specific models like claude-haiku-4-5","Checks benchmark YAML for common issues","Integrates with ailang eval-suite for model evaluation","Offers best practices learned from real benchmark failures"],"zh":["支持AILANG评估基准管理","提供调试工作流和提示集成","支持CLI命令行工具","可以测试特定模型的benchmark","可以检查benchmark YAML文件的常见问题"],"ja":["AILANG評価ベンチマークの管理をサポート","デバッグワークフローとプロンプト統合を提供","CLIコマンドラインツールをサポート","特定のモデルでのベンチマークのテストを可能に","ベンチマークYAMLファイルの一般的な問題をチェック"],"ko":["AILANG 평가 벤치마크 관리 지원","디버깅 워크플로우와 프롬프트 통합 제공","CLI 명령줄 도구 지원","특정 모델의 벤치마크 테스트 가능","벤치마크 YAML 파일의 일반적인 문제 점검"],"es":["Integración de prompts correcta para modelos de lenguaje","Depuración de flujos de trabajo con scripts personalizados","Evaluación de benchmarks con modelos específicos como Claude Haiku","Comprobación de archivos YAML para problemas comunes","Uso de CLI para evaluar y depurar benchmarks"],"fr":["Intégration de prompts correcte pour les modèles de langage","Débogage de flux de travail avec des scripts personnalisés","Évaluation de benchmarks avec des modèles spécifiques comme Claude Haiku","Vérification de fichiers YAML pour les problèmes courants","Utilisation de la CLI pour évaluer et déboguer les benchmarks"],"de":["Korrekture Integration von Prompts für Sprachmodelle","Fehlersuche in Workflows mit benutzerdefinierten Skripten","Bewertung von Benchmarks mit spezifischen Modellen wie Claude Haiku","Überprüfung von YAML-Dateien auf häufige Probleme","Verwendung von CLI zur Bewertung und Fehlersuche von Benchmarks"],"pt":["Integração de prompt para modelos de linguagem","Fluxos de depuração para identificar problemas","Melhores práticas para avaliações de linguagem","Suporte ao CLI para avaliações de linguagem","Integração com o modelo Claude-Haiku-4-5"],"ru":["Интеграция промпта для языковых моделей","Отладочные потоки для выявления проблем","Лучшие практики для оценок языка","Поддержка CLI для оценок языка","Интеграция с моделью Claude-Haiku-4-5"],"ar":["دمج الاستطلاع لنمذجة اللغة","fluxes التصحيح لتحديد المشاكل","أفضل الممارسات لتقييمات اللغة","دعم CLI لتقييمات اللغة","دمج مع نموذج Claude-Haiku-4-5"]},"keywords":{"en":["how to use Benchmark Manager","Benchmark Manager setup guide","AILANG evaluation benchmarks","debugging workflows for AI models","Benchmark Manager alternative","Benchmark Manager vs other AI skills","install Benchmark Manager","what is Benchmark Manager","Benchmark Manager for AI agents","managing AI model evaluation benchmarks"],"zh":["AI工具","Benchmark Manager","AILANG评估基准","调试工作流","提示集成","CLI命令行工具","AI开发"],"ja":["AIエージェント","Benchmark Manager","AILANG評価ベンチマーク","デバッグワークフロー","プロンプト統合","CLIコマンドラインツール","AI開発"],"ko":["AI 에이전트","Benchmark Manager","AILANG 평가 벤치마크","디버깅 워크플로우","프롬프트 통합","CLI 명령줄 도구","AI 개발"],"es":["Benchmark Manager","AI Agents","evaluación de AI","integración de prompts","depuración de flujos de trabajo","CLI para AI","modelos de lenguaje","evaluación de benchmarks"],"fr":["Benchmark Manager","outils d''IA","évaluation d''IA","intégration de prompts","débogage de flux de travail","CLI pour IA","modèles de langage","évaluation de benchmarks"],"de":["Benchmark Manager","KI-Tools","AI-Bewertung","Prompt-Integration","Fehlersuche in Workflows","CLI für KI","Sprachmodelle","Bewertung von Benchmarks"],"pt":["Benchmark Manager","Ferramentas de IA","Avaliações de linguagem","Integração de prompt","Fluxos de depuração","Melhores práticas","CLI","Modelo Claude-Haiku-4-5","Desenvolvimento de linguagem natural"],"ru":["Benchmark Manager","ИИ Агенты","Оценки языка","Интеграция промпта","Отладочные потоки","Лучшие практики","CLI","Модель Claude-Haiku-4-5","Разработка языковых моделей"],"ar":["مدير المقارنة","آلات اللغة الإصطناعية","تقييمات اللغة","دمج الاستطلاع","fluxes التصحيح","أفضل الممارسات","CLI","نموذج Claude-Haiku-4-5","تطوير لغة طبيعية"]}},"owner":"sunholo-data","repo":"ailang","repoPath":"sunholo-data/ailang","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"Benchmark Manager","description":"Create and manage AILANG eval benchmarks. Use when user asks to create benchmarks, fix benchmark issues, debug failing benchmarks, or analyze benchmark results.","bodyPreview":"# Benchmark Manager\n\nManage AILANG evaluation benchmarks with correct prompt integration, debugging workflows, and best practices learned from real benchmark failures.\n\n## Quick Start\n\n**Debugging a failing benchmark:**\n```bash\n# 1. Show the full prompt that models see\n.claude/skills/benchmark-manager/scripts/show_full_prompt.sh json_parse\n\n# 2. Test a benchmark with a specific model\nailang eval-suite --models claude-haiku-4-5 --benchmarks json_parse\n\n# 3. Check benchmark YAML for common issues","body":"# Benchmark Manager\n\nManage AILANG evaluation benchmarks with correct prompt integration, debugging workflows, and best practices learned from real benchmark failures.\n\n## Quick Start\n\n**Debugging a failing benchmark:**\n```bash\n# 1. Show the full prompt that models see\n.claude/skills/benchmark-manager/scripts/show_full_prompt.sh json_parse\n\n# 2. Test a benchmark with a specific model\nailang eval-suite --models claude-haiku-4-5 --benchmarks json_parse\n\n# 3. Check benchmark YAML for common issues\n.claude/skills/benchmark-manager/scripts/check_benchmark.sh benchmarks/json_parse.yml\n```\n\n## When to Use This Skill\n\nInvoke this skill when:\n- User asks to create a new benchmark\n- User asks to debug/fix a failing benchmark\n- User wants to understand why models generate wrong code\n- User asks about benchmark YAML format\n- Benchmarks show 0% pass rate despite language support\n\n## CRITICAL: prompt vs task_prompt\n\n**This is the most important concept for benchmark management.**\n\n### The Problem (v0.4.8 Discovery)\n\nBenchmarks have TWO different prompt fields with VERY different behavior:\n\n| Field | Behavior | Use When |\n|-------|----------|----------|\n| `prompt:` | **REPLACES** the teaching prompt entirely | Testing raw model capability (rare) |\n| `task_prompt:` | **APPENDS** to teaching prompt | Normal benchmarks (99% of cases) |\n\n### Why This Matters\n\n```yaml\n# BAD - Model never sees AILANG syntax!\nprompt: |\n  Write a program that prints \"Hello\"\n\n# GOOD - Model sees teaching prompt + task\ntask_prompt: |\n  Write a program that prints \"Hello\"\n```\n\nWith `prompt:`, models generate Python/pseudo-code because they never learn AILANG syntax.\n\n### How Prompts Combine\n\nFrom `internal/eval_harness/spec.go` (lines 91-93):\n```go\nfullPrompt := basePrompt  // Teaching prompt from prompts/v0.4.x.md\nif s.TaskPrompt != \"\" {\n    fullPrompt = fullPrompt + \"\\n\\n## Task\\n\\n\" + s.TaskPrompt\n}\n```\n\nThe teaching prompt teaches AILANG syntax; `task_prompt` adds the specific task.\n\n## Available Scripts\n\n### `scripts/show_full_prompt.sh`\n\nShows the complete prompt that models receive for a benchmark.\n\n**Usage:**\n```bash\n.claude/skills/benchmark-manager/scripts/show_full_prompt.sh <benchmark_id>\n\n# Example:\n.claude/skills/benchmark-manager/scripts/show_full_prompt.sh json_parse\n```\n\n### `scripts/check_benchmark.sh`\n\nValidates a benchmark YAML file for common issues.\n\n**Usage:**\n```bash\n.claude/skills/benchmark-manager/scripts/check_benchmark.sh benchmarks/<name>.yml\n```\n\n**Checks for:**\n- Using `prompt:` instead of `task_prompt:` (warning)\n- Missing required fields\n- Invalid capability names\n- Syntax errors in YAML\n\n### `scripts/test_benchmark.sh`\n\nRuns a quick single-model test of a benchmark.\n\n**Usage:**\n```bash\n.claude/skills/benchmark-manager/scripts/test_benchmark.sh <benchmark_id> [model]\n\n# Examples:\n.claude/skills/benchmark-manager/scripts/test_benchmark.sh json_parse\n.claude/skills/benchmark-manager/scripts/test_benchmark.sh json_parse claude-haiku-4-5\n```\n\n## Benchmark YAML Format\n\n### Required Fields\n\n```yaml\nid: my_benchmark              # Unique identifier (snake_case)\ndescription: \"Short description of what this tests\"\nlanguages: [\"python\", \"ailang\"]\nentrypoint: \"main\"            # Function to call\ncaps: [\"IO\"]                  # Required capabilities\ndifficulty: \"easy|medium|hard\"\nexpected_gain: \"low|medium|high\"\ntask_prompt: |                # ALWAYS use task_prompt, not prompt!\n  Write a program in <LANG> that:\n  1. Does something\n  2. Prints the result\n\n  Output only the code, no explanations.\nexpected_stdout: |            # Exact expected output\n  expected output here\n```\n\n### Capability Names\n\nValid capabilities: `IO`, `FS`, `Clock`, `Net`\n\n```yaml\n# File I/O\ncaps: [\"IO\"]\n\n# HTTP requests\ncaps: [\"Net\", \"IO\"]\n\n# File system operations\ncaps: [\"FS\", \"IO\"]\n```\n\n## Creating New Benchmarks\n\n### Step 1: Determine Requirements\n\n- What language feature/capability is being tested?\n- Can models solve this with just the teaching prompt?\n- What''s the expected output?\n\n### Step 2: Write the Benchmark\n\n```yaml\nid: my_new_benchmark\ndescription: \"Test feature X capability\"\nlanguages: [\"python\", \"ailang\"]\nentrypoint: \"main\"\ncaps: [\"IO\"]\ndifficulty: \"medium\"\nexpected_gain: \"medium\"\ntask_prompt: |\n  Write a program in <LANG> that:\n  1. Clear description of task\n  2. Another step\n  3. Print the result\n\n  Output only the code, no explanations.\nexpected_stdout: |\n  exact expected output\n```\n\n### Step 3: Validate and Test\n\n```bash\n# Check for issues\n.claude/skills/benchmark-manager/scripts/check_benchmark.sh benchmarks/my_new_benchmark.yml\n\n# Test with cheap model first\nailang eval-suite --models claude-haiku-4-5 --benchmarks my_new_benchmark\n```\n\n## Debugging Failing Benchmarks\n\n### Symptom: 0% Pass Rate Despite Language Support\n\n**Check 1: Is it using `task_prompt:`?**\n```bash\ngrep -E \"^prompt:\" benchmarks/failing_benchmark.yml\n# If this returns a match, change to task_prompt:\n```\n\n**Check 2: What prompt do models see?**\n```bash\n.claude/skills/benchmark-manager/scripts/show_full_prompt.sh failing_benchmark\n```\n\n**Check 3: Is the teaching prompt up to date?**\n```bash\n# After editing prompts/v0.x.x.md, you MUST rebuild:\nmake quick-install\n```\n\n### Symptom: Models Copy Template Instead of Solving Task\n\nThe teaching prompt includes a template structure. If models copy it verbatim:\n\n1. Make sure task is clearly different from examples in teaching prompt\n2. Check that `task_prompt` explicitly describes what to do\n3. Consider if the task description is ambiguous\n\n### Symptom: compile_error on Valid Syntax\n\nCommon AILANG-specific issues models get wrong:\n\n| Wrong | Correct | Notes |\n|-------|---------|-------|\n| `print(42)` | `print(show(42))` | print expects string |\n| `a % b` | `mod_Int(a, b)` | No % operator |\n| `def main()` | `export func main()` | Wrong keyword |\n| `for x in xs` | `match xs { ... }` | No for loops |\n\nIf models consistently make these mistakes, the teaching prompt needs improvement (use prompt-manager skill).\n\n## Common Mistakes\n\n### 1. Using `prompt:` Instead of `task_prompt:`\n\n```yaml\n# WRONG - Models never see AILANG syntax\nprompt: |\n  Write code that...\n\n# CORRECT - Teaching prompt + task\ntask_prompt: |\n  Write code that...\n```\n\n### 2. Forgetting to Rebuild After Prompt Changes\n\n```bash\n# After editing prompts/v0.x.x.md:\nmake quick-install  # REQUIRED!\n```\n\n### 3. Putting Hints in Benchmarks\n\n```yaml\n# WRONG - Hints in benchmark\ntask_prompt: |\n  Write code that prints 42.\n  Hint: Use print(show(42)) in AILANG.\n\n# CORRECT - No hints; if models fail, fix the teaching prompt\ntask_prompt: |\n  Write code that prints 42.\n```\n\nIf models need AILANG-specific hints, the teaching prompt is incomplete. Use the prompt-manager skill to fix it.\n\n### 4. Testing Too Many Models at Once\n\n```bash\n# WRONG - Expensive and slow for debugging\nailang eval-suite --full --benchmarks my_test\n\n# CORRECT - Use one cheap model first\nailang eval-suite --models claude-haiku-4-5 --benchmarks my_test\n```\n\n## Resources\n\n### Reference Guide\nSee [`resources/reference.md`](resources/reference.md) for:\n- Complete list of valid benchmark fields\n- Capability reference\n- Example benchmarks\n\n### Related Skills\n- **prompt-manager**: When benchmark failures indicate teaching prompt issues\n- **eval-analyzer**: For analyzing results across many benchmarks\n- **use-ailang**: For writing correct AILANG code\n- **devtools-prompt**: For toolchain docs (debugging, tracing, eval workflows) — `ailang devtools-prompt`\n\n## Notes\n\n- Benchmarks live in `benchmarks/` directory\n- Eval results go to `eval_results/` directory\n- Teaching prompts are embedded in binary - rebuild after changes (`ailang prompt` for syntax, `ailang devtools-prompt` for toolchain)\n- Use `<LANG>` placeholder in task_prompt - it''s replaced with \"AILANG\" or \"Python\"\n"},"lastSynced":"2026-03-08T02:01:14.315Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced AILANG evaluation benchmark management with correct prompt integration and debugging workflows.","zh":"适合需要高级AILANG评估基准管理的AI代理，具有正确的提示集成和调试工作流程。","ja":"高度なAILANG評価ベンチマーク管理が必要なAIエージェントに適しています。正しいプロンプト統合とデバッグワークフローを備えています。","ko":"고급 AILANG 평가 벤치마크 관리가 필요한 AI 에이전트에게 적합합니다. 올바른 프롬프트 통합 및 디버깅 워크플로를 제공합니다.","es":"Perfecto para Agentes de IA que necesitan una gestión avanzada de la evaluación de benchmarks de AILANG con una integración correcta de prompts y flujos de trabajo de depuración.","fr":"Parfait pour les agents IA nécessitant une gestion avancée de l''évaluation des benchmarks AILANG avec une intégration correcte de prompts et des workflows de débogage.","de":"Perfekt für KI-Agents, die eine erweiterte Verwaltung von AILANG-Benchmark-Evaluierungen mit korrekter Prompt-Integration und Debugging-Workflows benötigen.","pt":"Perfeito para Agentes de IA que necessitam de gestão avançada de benchmark de avaliação AILANG com integração correta de prompts e fluxos de trabalho de depuração.","ru":"Идеально для ИИ-агентов, которым требуется продвинутая оценка и управление эталонами AILANG с правильной интеграцией подсказок и отладочных рабочих процессов.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى إدارة تقييم متقدمة لAILANG مع دمج صحيح للتحفيز وعمليات تصحيح الأخطاء."},"recommendation":{"en":"Empowers agents to manage AILANG evaluation benchmarks with best practices learned from real benchmark failures, utilizing scripts like show_full_prompt.sh and ailang eval-suite for efficient debugging and testing with specific models like claude-haiku-4-5.","zh":"赋予代理管理AILANG评估基准的能力，使用脚本如show_full_prompt.sh和ailang eval-suite，学习真实基准失败的最佳实践，实现高效的调试和测试，支持特定的模型如claude-haiku-4-5。","ja":"エージェントにAILANG評価ベンチマークを管理する能力を与え、スクリプトsuch as show_full_prompt.shとailang eval-suiteを使用し、実際のベンチマークの失敗から学んだベストプラクティスを利用して、効率的なデバッグとテストを実現します。特定のモデルsuch as claude-haiku-4-5にも対応しています。","ko":"에이전트에게 AILANG 평가 벤치마크를 관리할 수 있는 능력을 부여하며, show_full_prompt.sh 및 ailang eval-suite와 같은 스크립트를 사용하여 실제 벤치마크 실패에서 학습한最佳實踐을 활용하여 효율적인 디버깅 및 테스트를 구현합니다. 특정 모델such as claude-haiku-4-5에도対応합니다.","es":"Habilita a los agentes a gestionar los benchmarks de evaluación de AILANG con las mejores prácticas aprendidas de fallos reales de benchmarks, utilizando scripts como show_full_prompt.sh y ailang eval-suite para un depuración y prueba eficientes con modelos específicos como claude-haiku-4-5.","fr":"Permet aux agents de gérer les benchmarks d''évaluation AILANG avec les meilleures pratiques apprises de véritables défaillances de benchmarks, en utilisant des scripts tels que show_full_prompt.sh et ailang eval-suite pour un débogage et des tests efficaces avec des modèles spécifiques comme claude-haiku-4-5.","de":"Ermächtigt Agents, AILANG-Evaluierungsbenchmarks mit bewährten Verfahren zu verwalten, die aus realen Benchmark-Fehlern gelernt wurden, unter Verwendung von Skripten wie show_full_prompt.sh und ailang eval-suite für effizientes Debugging und Testen mit spezifischen Modellen wie claude-haiku-4-5.","pt":"Habilita os agentes a gerenciar os benchmarks de avaliação AILANG com as melhores práticas aprendidas com falhas reais de benchmarks, utilizando scripts como show_full_prompt.sh e ailang eval-suite para depuração e teste eficientes com modelos específicos como claude-haiku-4-5.","ru":"Наделяет агентов возможностью управлять эталонами оценки AILANG с использованием передовых методов, полученных из реальных неудач эталонов, используя скрипты, такие как show_full_prompt.sh и ailang eval-suite для эффективной отладки и тестирования с конкретными моделями, такими как claude-haiku-4-5.","ar":"يُمكّن الوكيل من إدارة معايير تقييم AILANG باستخدام أفضل الممارسات المكتسبة من فشل المعايير الفعلية، باستخدام نصوص مثل show_full_prompt.sh و ailang eval-suite للتصحيح الفعال والاختبار مع نماذج محددة مثل claude-haiku-4-5."},"useCases":{"en":["Debugging failing benchmarks with full prompt visibility","Testing benchmarks with specific AI models like claude-haiku-4-5","Analyzing benchmark YAML for common issues to improve evaluation suite efficiency"],"zh":["完整提示可见性调试失败的基准","使用特定的AI模型such as claude-haiku-4-5进行基准测试","分析基准YAML以改善评估套件的效率"],"ja":["フルプロンプトの可視性で失敗したベンチマークをデバッグする","特定のAIモデルsuch as claude-haiku-4-5を使用してベンチマークをテストする","ベンチマークのYAMLを分析して評価スイートの効率を向上させる"],"ko":["전체 프롬프트 가시성으로 실패한 벤치마크 디버깅","특정 AI 모델such as claude-haiku-4-5를 사용하여 벤치마크 테스트","벤치마크 YAML 분석하여 평가 스위트 효율 개선"],"es":["Depuración de benchmarks con fallos con visibilidad completa de los prompts","Pruebas de benchmarks con modelos de IA específicos como claude-haiku-4-5","Análisis de benchmark YAML para problemas comunes para mejorar la eficiencia de la suite de evaluación"],"fr":["Débogage des benchmarks en échec avec visibilité complète des prompts","Tests de benchmarks avec des modèles d''IA spécifiques comme claude-haiku-4-5","Analyse de benchmark YAML pour les problèmes courants afin d''améliorer l''efficacité de la suite d''évaluation"],"de":["Fehlerhafte Benchmarks mit voller Prompt-Sichtbarkeit debuggen","Benchmarks mit spezifischen KI-Modellen wie claude-haiku-4-5 testen","Benchmark-YAML analysieren, um häufige Probleme zu finden und die Effizienz der Evaluierungssuite zu verbessern"],"pt":["Depuração de benchmarks com falha com visibilidade completa do prompt","Testar benchmarks com modelos de IA específicos como claude-haiku-4-5","Analisar benchmark YAML para problemas comuns para melhorar a eficiência da suíte de avaliação"],"ru":["Отладка неудачных эталонов с полной видимостью подсказки","Тестирование эталонов с конкретными моделями ИИ, такими как claude-haiku-4-5","Анализ эталона YAML для общих проблем для повышения эффективности оценочной серии"],"ar":["تصحيح اختبار المعايير الفاشلة مع الرؤية الكاملة للتحفيز","اختبار المعايير مع نماذج ذكاء اصطناعي محددة مثل claude-haiku-4-5","تحليل معيار YAML للقضايا الشائعة لتحسين كفاءة حزمة التقييم"]},"limitations":{"en":["Requires AILANG evaluation benchmarks setup","Dependent on specific model availability like claude-haiku-4-5 for testing"],"zh":["需要AILANG评估基准设置","依赖于特定的模型可用性such as claude-haiku-4-5进行测试"],"ja":["AILANG評価ベンチマークの設定が必要","特定のモデルsuch as claude-haiku-4-5の可用性に依存してテストする"],"ko":["AILANG 평가 벤치마크 설정 필요","특정 모델such as claude-haiku-4-5의 가용성에 의존하여 테스트"],"es":["Requiere la configuración de benchmarks de evaluación de AILANG","Dependiente de la disponibilidad de modelos específicos como claude-haiku-4-5 para pruebas"],"fr":["Nécessite la configuration des benchmarks d''évaluation AILANG","Dépend de la disponibilité de modèles spécifiques comme claude-haiku-4-5 pour les tests"],"de":["Benötigt die Einrichtung von AILANG-Evaluierungsbenchmarks","Abhängig von der Verfügbarkeit spezifischer Modelle wie claude-haiku-4-5 für Tests"],"pt":["Requer configuração de benchmarks de avaliação AILANG","Dependente da disponibilidade de modelos específicos como claude-haiku-4-5 para teste"],"ru":["Требует настройки эталонов оценки AILANG","Зависит от доступности конкретных моделей, таких как claude-haiku-4-5, для тестирования"],"ar":["يتطلب إعداد معايير تقييم AILANG","يعتمد على توافر نماذج محددة مثل claude-haiku-4-5 للاختبار"]},"version":4},"contentHash":"f0c071b8dbfa409da13dc23d204b8c5e52c04db633b3f9023af6f937fe6a7674","qualityScore":51}');
