INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sunholo-data/ailang/Benchmark Manager', 'Benchmark Manager', 'sunholo-data', 'ailang', 'community', 'Benchmark Manager sunholo-data ailang community The Benchmark Manager skill helps developers manage AILANG evaluation benchmarks with correct prompt integration and debugging workflows. It provides best practices learned from real benchmark failures. Benchmark Manager帮助您管理AILANG评估基准，包括调试工作流和提示集成 Benchmark ManagerはAILANG評価ベンチマークの管理を支援し、デバッグワークフローとプロンプト統合を提供する Benchmark Manager는 AILANG 평가 벤치마크를 관리하고 디버깅 워크플로우와 프롬프트 통합을 지원한다 Benchmark Manager es una herramienta para administrar evaluaciones de AI con integración de prompts correcta y depuración de flujos de trabajo Benchmark Manager est un outil pour gérer les évaluations d''IA avec une intégration de prompts correcte et un débogage de flux de travail Benchmark Manager ist ein Tool zum Verwalten von AI-Bewertungen mit korrekter Prompt-Integration und Debug-Workflows O Benchmark Manager é uma ferramenta para gerenciar avaliações de linguagem, permitindo a integração de prompt, fluxos de depuração e melhores práticas Benchmark Manager - это инструмент для управления оценками языка, позволяющий интегрировать промпт, отладочные потоки и лучшие практики مدير المقارنة هو أداة لإدارة تقييمات اللغة، مما يسمح بدمج الاستطلاع وfluxes التصحيح وأفضل الممارسات how to use Benchmark Manager Benchmark Manager setup guide AILANG evaluation benchmarks debugging workflows for AI models Benchmark Manager alternative Benchmark Manager vs other AI skills install Benchmark Manager what is Benchmark Manager Benchmark Manager for AI agents managing AI model evaluation benchmarks AI工具 Benchmark Manager AILANG评估基准 调试工作流 提示集成 CLI命令行工具 AI开发 Manages AILANG evaluation benchmarks with correct prompt integration Provides debugging workflows using scripts like show_full_prompt.sh Supports testing benchmarks with specific models like claude-haiku-4-5 Checks benchmark YAML for common issues Integrates with ailang eval-suite for model evaluation Offers best practices learned from real benchmark failures Benchmark Manager is a skill that manages AILANG evaluation benchmarks with features like prompt integration, debugging, and best practices for AI model evaluation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('9aia/pachira/nuxt-seo', 'community', '9aia', 'pachira', '9aia/pachira', 'nuxt-seo', 0, 0, 51, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:21.442Z', '254b902fbdd467b08ff7c2556f02dec2afc99fcd47583e02d1f31f9c30e8fbb3', '{"id":"9aia/pachira/nuxt-seo","name":"nuxt-seo","description":{"en":"nuxt-seo is a module for managing SEO configurations, generating robots.txt and sitemap.xml files, and creating dynamic OG images. It benefits developers working with Nuxt.js applications.","zh":"Nuxt SEO 是一个用于管理网站 SEO 配置的模块，支持动态 OG 图像生成、JSON-LD 结构化数据和面包屑导航","ja":"Nuxt SEO は、Web サイトの SEO 構成を管理するためのモジュールです。動的な OG 画像生成、JSON-LD 構造化データ、パンくずリストナビゲーションなどをサポートします","ko":"Nuxt SEO는 웹사이트의 SEO 구성 관리를 위한 모듈로서 동적 OG 이미지 생성, JSON-LD 구조화 데이터 및 빵屑导航 등을 지원합니다","es":"Nuxt SEO es un módulo para gestionar la configuración de SEO en aplicaciones Nuxt.js, incluyendo la generación de robots.txt y sitemap.xml","fr":"Nuxt SEO est un module pour gérer la configuration du SEO dans les applications Nuxt.js, notamment la génération de robots.txt et sitemap.xml","de":"Nuxt SEO ist ein Modul zur Verwaltung der SEO-Konfiguration in Nuxt.js-Anwendungen, einschließlich der Generierung von robots.txt und sitemap.xml","pt":"O Nuxt SEO é uma ferramenta para gerenciar configurações de SEO em aplicações Nuxt.js, incluindo geração de sitemap.xml e robots.txt.","ru":"Nuxt SEO — это инструмент для управления настройками SEO в приложениях Nuxt.js, включая генерацию sitemap.xml и robots.txt для ИИ Агентов.","ar":"Nuxt SEO هو أداة لإدارة إعدادات SEO في تطبيقات Nuxt.js، بما في ذلك إنشاء sitemap.xml و robots.txt لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"nuxt-seo: Setup Guide for AI Agents | AI Agent Skill","zh":"Nuxt SEO 设置指南 - 简化搜索引擎优化配置","ja":"Nuxt SEO SetUp Guide - 検索エンジン最適化を簡素化","ko":"Nuxt SEO 설정 가이드 - 검색 엔진 최적화 구성 간소화","es":"Guía de configuración de Nuxt SEO para desarrolladores","fr":"Guide de configuration de Nuxt SEO pour les développeurs","de":"Nuxt SEO-Konfigurationsleitfaden für Entwickler","pt":"Guia de Configuração do Nuxt SEO para Desenvolvedores","ru":"Настройка Nuxt SEO: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد Nuxt SEO لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to install and configure nuxt-seo for optimal SEO configuration, robots.txt generation, and JSON-LD structured data. Get started now!","zh":"使用 Nuxt SEO 模块轻松配置网站的 SEO 设置，包括站点 URL、名称、索引性和 robots.txt 生成","ja":"Nuxt SEO モジュールを使用して、Web サイトの SEO 設定を簡単に構成します。サイト URL、名前、インデックス可能性、robots.txt の生成など","ko":"Nuxt SEO 모듈을 사용하여 웹사이트의 SEO 설정을 쉽게 구성합니다. 사이트 URL, 이름, 색인 가능성 및 robots.txt 생성 등","es":"Aprende a configurar Nuxt SEO para mejorar el posicionamiento de tu sitio web en los motores de búsqueda","fr":"Découvrez comment configurer Nuxt SEO pour améliorer le référencement de votre site web","de":"Erfahren Sie, wie Sie Nuxt SEO konfigurieren, um die Sichtbarkeit Ihrer Website in Suchmaschinen zu verbessern","pt":"Aprenda a configurar o Nuxt SEO para melhorar a visibilidade do seu site com recursos como robots.txt e sitemap.xml","ru":"Узнайте, как настроить Nuxt SEO для улучшения видимости вашего сайта с помощью функций như robots.txt и sitemap.xml для ИИ Агентов","ar":"تعرف على كيفية إعداد Nuxt SEO لتحسين ظهور موقعك على الويب باستخدام ميزات مثل robots.txt و sitemap.xml لأدوات الذكاء الاصطناعي"},"definition":{"en":"nuxt-seo is a Nuxt.js module for managing SEO configurations, including site URL, name, indexability, and JSON-LD structured data.","zh":"Nuxt SEO 是一个用于简化网站搜索引擎优化配置的模块","ja":"Nuxt SEO は、Web サイトの検索エンジン最適化構成を簡素化するためのモジュールです","ko":"Nuxt SEO는 웹사이트의 검색 엔진 최적화 구성 간소화를 위한 모듈입니다","es":"Nuxt SEO es un módulo de Nuxt.js para la configuración de SEO","fr":"Nuxt SEO est un module Nuxt.js pour la configuration du SEO","de":"Nuxt SEO ist ein Nuxt.js-Modul für die SEO-Konfiguration","pt":"O Nuxt SEO é um módulo para Nuxt.js que facilita a configuração de SEO.","ru":"Nuxt SEO — это модуль для Nuxt.js, который упрощает настройку SEO для ИИ Агентов.","ar":"Nuxt SEO هو مكون لإضافته إلى Nuxt.js لتحسين إعدادات SEO لأدوات الذكاء الاصطناعي."},"features":{"en":["Generates robots.txt and sitemap.xml files","Creates dynamic OG images","Supports JSON-LD structured data (schema.org)","Handles breadcrumbs and canonical URLs","Configures site URL, name, and indexability","Uses @nuxtjs/seo module via npx nuxi command"],"zh":["SEO 配置支持（站点 URL、名称、索引性）","动态 OG 图像生成","JSON-LD 结构化数据（schema.org）","面包屑导航和规范 URL","robots.txt 和 sitemap.xml 生成"],"ja":["SEO 構成のサポート（サイト URL、名前、インデックス可能性）","動的な OG 画像生成","JSON-LD 構造化データ（schema.org）","パンくずリストナビゲーションと正規 URL","robots.txt と sitemap.xml の生成"],"ko":["SEO 구성 지원（사이트 URL, 이름, 색인 가능성）","동적 OG 이미지 생성","JSON-LD 구조화 데이터（schema.org）","빵屑导航과 표준 URL","robots.txt 및 sitemap.xml 생성"],"es":["Generación de robots.txt y sitemap.xml","Configuración de la URL del sitio y el nombre del sitio","Generación de imágenes OG dinámicas","Datos estructurados de JSON-LD (schema.org)","Generación de breadcrumbs y URLs canónicas"],"fr":["Génération de robots.txt et sitemap.xml","Configuration de l''URL du site et du nom du site","Génération d''images OG dynamiques","Données structurées de JSON-LD (schema.org)","Génération de breadcrumbs et d''URL canónicas"],"de":["Generierung von robots.txt und sitemap.xml","Konfiguration der Site-URL und des Site-Namens","Generierung von dynamischen OG-Bildern","Strukturierte Daten von JSON-LD (schema.org)","Generierung von Breadcrumbs und kanonischen URLs"],"pt":["Geração de sitemap.xml","Criação de robots.txt","Geração de imagem OG dinâmica","Estrutura de dados JSON-LD (schema.org)","Geração de breadcrumbs e URLs canônicas"],"ru":["Генерация sitemap.xml","Создание robots.txt","Генерация динамических изображений OG","Структурированные данные JSON-LD (schema.org) для ИИ Агентов","Генерация breadcrumbs и канонических URL"],"ar":["إنشاء sitemap.xml","إنشاء robots.txt","إنشاء صورة OG動态","بيانات JSON-LD المهيكلة (schema.org) لأدوات الذكاء الاصطناعي","إنشاء breadcrumbs و URLsCanon"]},"keywords":{"en":["how to use nuxt-seo","nuxt-seo setup guide","nuxt-seo alternative","nuxt-seo vs prismicio","nuxt-seo install","what is nuxt-seo","nuxt-seo configuration","nuxt-seo json-ld","nuxt-seo robots.txt","nuxt-seo sitemap.xml"],"zh":["Nuxt SEO","搜索引擎优化","网站配置","SEO 模块","动态 OG 图像","JSON-LD 结构化数据","AIエージェント工具"],"ja":["Nuxt SEO","検索エンジン最適化","Web サイト構成","SEO モジュール","動的な OG 画像","JSON-LD 構造化データ","AIエージェント"],"ko":["Nuxt SEO","검색 엔진 최적화","웹사이트 구성","SEO 모듈","동적 OG 이미지","JSON-LD 구조화 데이터","AI 에이전트 도구"],"es":["Nuxt SEO","configuración de SEO","generación de robots.txt","generación de sitemap.xml","imagenes OG dinámicas","datos estructurados de JSON-LD","breadcrumbs y URLs canónicas"],"fr":["Nuxt SEO","configuration du SEO","génération de robots.txt","génération de sitemap.xml","images OG dynamiques","données structurées de JSON-LD","fil d''ariane et URL canónicas"],"de":["Nuxt SEO","SEO-Konfiguration","Generierung von robots.txt","Generierung von sitemap.xml","dynamische OG-Bilder","strukturierte Daten von JSON-LD","Breadcrumbs und kanonische URLs"],"pt":["Nuxt SEO","configuração SEO","geração de sitemap","robots.txt","otimização de site","desenvolvimento web","Nuxt.js","ferramentas de SEO"],"ru":["Nuxt SEO","настройка SEO","генерация sitemap","robots.txt","оптимизация сайта","веб-разработка","Nuxt.js","инструменты SEO для ИИ Агентов"],"ar":["Nuxt SEO","إعدادات SEO","إنشاء sitemap","robots.txt","تحسين موقع","تطوير الويب","Nuxt.js","أدوات SEO لأدوات الذكاء الاصطناعي"]}},"owner":"9aia","repo":"pachira","repoPath":"9aia/pachira","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"nuxt-seo","description":"Nuxt SEO meta-module with robots, sitemap, og-image, schema-org. Use when configuring SEO, generating sitemaps, creating OG images, or adding structured data.","bodyPreview":"# Nuxt SEO\n\n```bash\nnpx nuxi module add @nuxtjs/seo\n```\n\n## When to Use\n\nWorking with:\n\n- SEO configuration (site URL, name, indexability)\n- Robots.txt and sitemap.xml generation\n- Dynamic OG image generation\n- JSON-LD structured data (schema.org)\n- Breadcrumbs and canonical URLs\n\n## Loading Files\n\n**Consider loading these reference files based on your task:**\n\n- [ ] [references/site-config.md](references/site-config.md) - if configuring site URL, name, or SEO foundation\n- [ ] [references/crawla","body":"# Nuxt SEO\n\n```bash\nnpx nuxi module add @nuxtjs/seo\n```\n\n## When to Use\n\nWorking with:\n\n- SEO configuration (site URL, name, indexability)\n- Robots.txt and sitemap.xml generation\n- Dynamic OG image generation\n- JSON-LD structured data (schema.org)\n- Breadcrumbs and canonical URLs\n\n## Loading Files\n\n**Consider loading these reference files based on your task:**\n\n- [ ] [references/site-config.md](references/site-config.md) - if configuring site URL, name, or SEO foundation\n- [ ] [references/crawlability.md](references/crawlability.md) - if setting up robots.txt or sitemap.xml\n- [ ] [references/og-image.md](references/og-image.md) - if generating dynamic OG images\n- [ ] [references/schema-org.md](references/schema-org.md) - if adding JSON-LD structured data\n- [ ] [references/utilities.md](references/utilities.md) - if working with breadcrumbs, canonical URLs, or link checking\n\n**DO NOT load all files at once.** Load only what''s relevant to your current task.\n\n## Site Config\n\nFoundation for all SEO modules. Configure `site` in `nuxt.config.ts`, access via `useSiteConfig()`. See [references/site-config.md](references/site-config.md) for full options.\n\n## Module Overview\n\n| Module            | Purpose         | Key API                       |\n| ----------------- | --------------- | ----------------------------- |\n| nuxt-site-config  | Shared config   | `useSiteConfig()`             |\n| @nuxtjs/robots    | robots.txt      | `useRobotsRule()`             |\n| @nuxtjs/sitemap   | sitemap.xml     | `defineSitemapEventHandler()` |\n| nuxt-og-image     | OG images       | `defineOgImage()`             |\n| nuxt-schema-org   | JSON-LD         | `useSchemaOrg()`              |\n| nuxt-seo-utils    | Meta utilities  | `useBreadcrumbItems()`        |\n| nuxt-link-checker | Link validation | Build-time checks             |\n\n## Nuxt Content v3\n\nUse `asSeoCollection()` for automatic sitemap, og-image, and schema-org from frontmatter:\n\n```ts\n// content.config.ts\nimport { defineCollection, defineContentConfig } from ''@nuxt/content''\nimport { asSeoCollection } from ''@nuxtjs/seo/content''\n\nexport default defineContentConfig({\n  collections: {\n    posts: defineCollection(asSeoCollection({ type: ''page'', source: ''posts/**'' }))\n  }\n})\n```\n\n**Important:** Load `@nuxtjs/seo` before `@nuxt/content` in modules array:\n\n```ts\nexport default defineNuxtConfig({\n  modules: [''@nuxtjs/seo'', ''@nuxt/content'']\n})\n```\n\nFrontmatter fields: `ogImage`, `sitemap`, `robots`, `schemaOrg`.\n\n## Related Skills\n\n- [nuxt-content](../nuxt-content/SKILL.md) - For MDC rendering with SEO frontmatter\n\n## Links\n\n- [Documentation](https://nuxtseo.com)\n- [GitHub](https://github.com/harlan-zw/nuxt-seo)\n\n## Token Efficiency\n\nMain skill: ~250 tokens. Each sub-file: ~400-600 tokens. Only load files relevant to current task.\n"},"lastSynced":"2026-03-08T02:01:21.442Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced SEO configuration and dynamic OG image generation for Nuxt.js applications.","zh":"非常适合需要高级SEO配置和动态OG图片生成的Nuxt.js应用的前端代理","ja":"Nuxt.jsアプリケーションで高度なSEO設定と動的OG画像生成が必要なフロントエンドエージェントに最適","ko":"고급 SEO 설정과 동적 OG 이미지 생성이 필요한 Nuxt.js 애플리케이션을 위한 프론트엔드 에이전트에 적합","es":"Perfecto para Agentes Frontend que necesitan una configuración avanzada de SEO y generación dinámica de imágenes OG para aplicaciones Nuxt.js.","fr":"Parfait pour les agents Frontend ayant besoin d''une configuration SEO avancée et d''une génération d''images OG dynamiques pour les applications Nuxt.js.","de":"Perfekt für Frontend-Agents, die eine erweiterte SEO-Konfiguration und eine dynamische OG-Bildgenerierung für Nuxt.js-Anwendungen benötigen.","pt":"Perfeito para Agentes Frontend que precisam de configuração avançada de SEO e geração dinâmica de imagens OG para aplicações Nuxt.js.","ru":"Идеально подходит для агентов Frontend, которым необходима расширенная настройка SEO и динамическая генерация изображений OG для приложений Nuxt.js.","ar":"مثالي لعميل واجهة المستخدم التي تحتاج إلى إعداد متقدم لتحسين محركات البحث وتوليد صورة OG ديناميكي لبرامج Nuxt.js."},"recommendation":{"en":"Empowers agents to manage SEO configurations, generate robots.txt and sitemap.xml files, and create dynamic OG images using Nuxt.js, while also supporting JSON-LD structured data and schema.org protocols.","zh":"赋予代理管理SEO配置、生成robots.txt和sitemap.xml文件、使用Nuxt.js创建动态OG图片的能力，同时支持JSON-LD结构化数据和schema.org协议","ja":"エージェントに、SEO設定を管理し、robots.txtとsitemap.xmlファイルを生成し、Nuxt.jsを使用して動的OG画像を作成する機能を提供し、同時にJSON-LD構造化データとschema.orgプロトコルをサポート","ko":"에이전트가 SEO 설정을 관리하고, robots.txt와 sitemap.xml 파일을 생성하며, Nuxt.js를 사용하여 동적 OG 이미지를 생성하는 기능을 제공하며,同时 JSON-LD 구조화 데이터와 schema.org 프로토콜을 지원","es":"Permite a los agentes gestionar configuraciones de SEO, generar archivos robots.txt y sitemap.xml, y crear imágenes OG dinámicas utilizando Nuxt.js, además de admitir datos estructurados JSON-LD y protocolos schema.org.","fr":"Permet aux agents de gérer les configurations SEO, de générer des fichiers robots.txt et sitemap.xml, et de créer des images OG dynamiques à l''aide de Nuxt.js, tout en prenant en charge les données structurées JSON-LD et les protocoles schema.org.","de":"Ermöglicht es Agents, SEO-Konfigurationen zu verwalten, robots.txt- und sitemap.xml-Dateien zu generieren und dynamische OG-Bilder mit Nuxt.js zu erstellen, während auch JSON-LD-Strukturdaten und schema.org-Protokolle unterstützt werden.","pt":"Habilita os agentes a gerenciar configurações de SEO, gerar arquivos robots.txt e sitemap.xml, e criar imagens OG dinâmicas usando Nuxt.js, enquanto também suporta dados estruturados JSON-LD e protocolos schema.org.","ru":"Наделяет агентов возможностью управлять настройками SEO, генерировать файлы robots.txt и sitemap.xml, а также создавать динамические изображения OG с помощью Nuxt.js, при этом поддерживая структурированные данные JSON-LD и протоколы schema.org.","ar":"يمكن للعميل إدارة إعدادات تحسين محركات البحث وتوليد ملفات robots.txt و sitemap.xml وإنشاء صور OG ديناميكي باستخدام Nuxt.js، مع دعم البيانات المنظمة JSON-LD وبروتوكولات schema.org."},"useCases":{"en":["Automating SEO configuration for Nuxt.js sites","Generating dynamic OG images for social media sharing","Creating and managing robots.txt and sitemap.xml files","Implementing JSON-LD structured data for improved search engine indexing"],"zh":["自动化Nuxt.js站点的SEO配置","为社交媒体分享生成动态OG图片","创建和管理robots.txt和sitemap.xml文件","实现JSON-LD结构化数据以提高搜索引擎索引"],"ja":["Nuxt.jsサイトのSEO設定を自動化","ソーシャルメディアでの共有用に動的OG画像を生成","robots.txtとsitemap.xmlファイルを作成して管理","検索エンジンのインデックスを改善するためにJSON-LD構造化データを実装"],"ko":["Nuxt.js 사이트의 SEO 설정 자동화","소셜 미디어 공유를 위한 동적 OG 이미지 생성","robots.txt와 sitemap.xml 파일 생성 및 관리","검색 엔진 인덱싱 향상을 위한 JSON-LD 구조화 데이터 구현"],"es":["Automatización de la configuración de SEO para sitios Nuxt.js","Generación de imágenes OG dinámicas para compartir en redes sociales","Creación y gestión de archivos robots.txt y sitemap.xml","Implementación de datos estructurados JSON-LD para mejorar el indexado de motores de búsqueda"],"fr":["Automation de la configuration SEO pour les sites Nuxt.js","Génération d''images OG dynamiques pour le partage sur les réseaux sociaux","Création et gestion de fichiers robots.txt et sitemap.xml","Mise en œuvre de données structurées JSON-LD pour améliorer l''indexation des moteurs de recherche"],"de":["Automatisierung der SEO-Konfiguration für Nuxt.js-Websites","Generierung dynamischer OG-Bilder für das Teilen in sozialen Medien","Erstellung und Verwaltung von robots.txt- und sitemap.xml-Dateien","Implementierung von JSON-LD-Strukturdaten für eine verbesserte Suchmaschinen-Indexierung"],"pt":["Automatizar a configuração de SEO para sites Nuxt.js","Gerar imagens OG dinâmicas para compartilhamento em redes sociais","Criar e gerenciar arquivos robots.txt e sitemap.xml","Implementar dados estruturados JSON-LD para melhorar o indexamento de mecanismos de busca"],"ru":["Автоматизировать настройку SEO для сайтов Nuxt.js","Генерировать динамические изображения OG для обмена в социальных сетях","Создавать и управлять файлами robots.txt и sitemap.xml","Реализовывать структурированные данные JSON-LD для улучшения индексирования поисковыми системами"],"ar":["توفير إعدادات تحسين محركات البحث آلياً لمواقع Nuxt.js","توليد صور OG ديناميكي للمشاركة على وسائل التواصل الاجتماعي","إنشاء وإدارة ملفات robots.txt و sitemap.xml","تنفيذ بيانات JSON-LD المنظمة لتحسين فهرسة محركات البحث"]},"limitations":{"en":["Requires Nuxt.js application setup","Limited to Nuxt.js ecosystem","Needs @nuxtjs/seo module installation via npx nuxi module add @nuxtjs/seo"],"zh":["需要Nuxt.js应用设置","仅限Nuxt.js生态系统","需要通过npx nuxi module add @nuxtjs/seo安装@nuxtjs/seo模块"],"ja":["Nuxt.jsアプリケーションの設定が必要","Nuxt.jsエコシステムのみ","@nuxtjs/seoモジュールをnpx nuxi module add @nuxtjs/seo経由でインストールする必要がある"],"ko":["Nuxt.js 애플리케이션 설정 필요","Nuxt.js 생태계만 해당","@nuxtjs/seo 모듈을 npx nuxi module add @nuxtjs/seo를 통해 설치해야 함"],"es":["Requiere configuración de la aplicación Nuxt.js","Limitado al ecosistema Nuxt.js","Necesita la instalación del módulo @nuxtjs/seo mediante npx nuxi module add @nuxtjs/seo"],"fr":["Nécessite une configuration de l''application Nuxt.js","Limité à l''écosystème Nuxt.js","Nécessite l''installation du module @nuxtjs/seo via npx nuxi module add @nuxtjs/seo"],"de":["Benötigt die Einrichtung einer Nuxt.js-Anwendung","Begrenzt auf das Nuxt.js-Ökosystem","Benötigt die Installation des @nuxtjs/seo-Moduls über npx nuxi module add @nuxtjs/seo"],"pt":["Requer configuração de aplicativo Nuxt.js","Limitado ao ecossistema Nuxt.js","Necessita instalação do módulo @nuxtjs/seo via npx nuxi module add @nuxtjs/seo"],"ru":["Требует настройки приложения Nuxt.js","Ограничен экосистемой Nuxt.js","Требует установки модуля @nuxtjs/seo через npx nuxi module add @nuxtjs/seo"],"ar":["يتطلب إعداد تطبيق Nuxt.js","محدود بنظام Nuxt.js","يحتاج إلى تثبيت وحدة @nuxtjs/seo عبر npx nuxi module add @nuxtjs/seo"]},"version":4},"contentHash":"254b902fbdd467b08ff7c2556f02dec2afc99fcd47583e02d1f31f9c30e8fbb3","qualityScore":51}');
