INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('9aia/pachira/nuxt-seo', 'nuxt-seo', '9aia', 'pachira', 'community', 'nuxt-seo 9aia pachira community nuxt-seo is a module for managing SEO configurations, generating robots.txt and sitemap.xml files, and creating dynamic OG images. It benefits developers working with Nuxt.js applications. Nuxt SEO 是一个用于管理网站 SEO 配置的模块，支持动态 OG 图像生成、JSON-LD 结构化数据和面包屑导航 Nuxt SEO は、Web サイトの SEO 構成を管理するためのモジュールです。動的な OG 画像生成、JSON-LD 構造化データ、パンくずリストナビゲーションなどをサポートします Nuxt SEO는 웹사이트의 SEO 구성 관리를 위한 모듈로서 동적 OG 이미지 생성, JSON-LD 구조화 데이터 및 빵屑导航 등을 지원합니다 Nuxt SEO es un módulo para gestionar la configuración de SEO en aplicaciones Nuxt.js, incluyendo la generación de robots.txt y sitemap.xml Nuxt SEO est un module pour gérer la configuration du SEO dans les applications Nuxt.js, notamment la génération de robots.txt et sitemap.xml Nuxt SEO ist ein Modul zur Verwaltung der SEO-Konfiguration in Nuxt.js-Anwendungen, einschließlich der Generierung von robots.txt und sitemap.xml O Nuxt SEO é uma ferramenta para gerenciar configurações de SEO em aplicações Nuxt.js, incluindo geração de sitemap.xml e robots.txt. Nuxt SEO — это инструмент для управления настройками SEO в приложениях Nuxt.js, включая генерацию sitemap.xml и robots.txt для ИИ Агентов. Nuxt SEO هو أداة لإدارة إعدادات SEO في تطبيقات Nuxt.js، بما في ذلك إنشاء sitemap.xml و robots.txt لأدوات الذكاء الاصطناعي. how to use nuxt-seo nuxt-seo setup guide nuxt-seo alternative nuxt-seo vs prismicio nuxt-seo install what is nuxt-seo nuxt-seo configuration nuxt-seo json-ld nuxt-seo robots.txt nuxt-seo sitemap.xml Nuxt SEO 搜索引擎优化 网站配置 SEO 模块 动态 OG 图像 JSON-LD 结构化数据 AIエージェント工具 Generates robots.txt and sitemap.xml files Creates dynamic OG images Supports JSON-LD structured data (schema.org) Handles breadcrumbs and canonical URLs Configures site URL, name, and indexability Uses @nuxtjs/seo module via npx nuxi command nuxt-seo is a Nuxt.js module for managing SEO configurations, including site URL, name, indexability, and JSON-LD structured data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('paunchygent/skriptoteket/selenium-testing', 'community', 'paunchygent', 'skriptoteket', 'paunchygent/skriptoteket', 'selenium-testing', 0, 0, 51, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:24.429Z', '5b61ffa0b4dcac088717fb2506cf5092c5a09bbc5c0cc80ffd27fee3ec87cfd7', '{"id":"paunchygent/skriptoteket/selenium-testing","name":"selenium-testing","description":{"en":"Selenium-testing is a Teacher-first Script Hub for running curated, upload-based tools, ideal for developers who need browser automation and visual testing capabilities.","zh":"Selenium 测试工具提供了浏览器自动化和视觉测试的解决方案，使用 Python 和 WebDriver 实现","ja":"Selenium テストツールは、ブラウザ自動化と視覚テストのための解決策を提供し、Python と WebDriver を使用します","ko":"Selenium 테스트 도구는 브라우저 자동화와 시각적 테스트를 위한 솔루션을 제공하며 Python과 WebDriver를 사용합니다","es":"Selenium Testing es una herramienta para automatizar tareas en el navegador utilizando Python y WebDriver. Permite ejecutar scripts de automatización y pruebas visuales","fr":"Selenium Testing est un outil pour automatiser des tâches dans le navigateur en utilisant Python et WebDriver. Il permet d''exécuter des scripts d''automatisation et des tests visuels","de":"Selenium Testing ist ein Tool zur Automatisierung von Aufgaben im Browser mit Python und WebDriver. Es ermöglicht die Ausführung von Automatisierungsskripten und visuellen Tests","pt":"O Selenium Testing é uma ferramenta de automação de navegador que permite a execução de testes visuais e funcionais de forma eficiente","ru":"Selenium Testing - это инструмент для автоматизации браузера, который позволяет выполнять визуальные и функциональные тесты эффективно","ar":"اختبار السيّلميوم هو أداة للتحكم الآلي في المتصفحات التي تمكن من تشغيل الاختبارات البصرية والوظيفية بفعالية"},"seo":{"title":{"en":"Selenium-Testing: Automated Browser Testing Setup Guide |...","zh":"Selenium 测试工具集成指南","ja":"Selenium テストのベストプラクティス","ko":"Selenium 테스트 환경 설정 가이드","es":"Guía de configuración de Selenium Testing para automatiza...","fr":"Guide de configuration de Selenium Testing pour l''automat...","de":"Konfigurationsleitfaden für Selenium Testing zur Browser-...","pt":"Guia de Configuração do Selenium Testing para Automação d...","ru":"Настройка ИИ Агентов: Руководство по Selenium Testing для...","ar":"دليل إعداد اختبار السيّلميوم للتحكم الآلي في المتصفحات"},"description":{"en":"Unlock efficient browser automation with selenium-testing. Learn how to run curated tools and scripts with our expert guide. Get started today!","zh":"利用 Selenium 进行浏览器自动化和视觉测试，了解如何使用 WebDriver 和截图功能","ja":"Selenium を使用してブラウザ自動化と視覚テストを実行する方法について学びます","ko":"Selenium을 사용하여 브라우저 자동화와 시각적 테스트를 수행하는 방법에 대해 알아보세요","es":"Aprende a configurar y ejecutar herramientas de Selenium Testing para automatizar tareas en el navegador con Python y WebDriver","fr":"Découvrez comment configurer et exécuter des outils de Selenium Testing pour automatiser des tâches dans le navigateur avec Python et WebDriver","de":"Erfahren Sie, wie Sie Selenium-Testing-Tools konfigurieren und ausführen, um Aufgaben im Browser mit Python und WebDriver zu automatisieren","pt":"Aprenda a configurar o Selenium Testing para automação de navegador e aumente a eficiência dos seus testes com ferramentas de upload curadas","ru":"Узнайте, как настроить Selenium Testing для автоматизации браузера и повысьте эффективность ваших тестов с помощью проверенных инструментов загрузки","ar":"تعلم كيفية إعداد اختبار السيّلميوم للتحكم الآلي في المتصفحات وزيادة كفاءة اختباراتك مع أدوات التحميل المعتمدة"},"definition":{"en":"Selenium-testing is a skill that enables automated browser testing using selenium, webdriver, and screenshot technologies.","zh":"Selenium 测试是指使用 Selenium 工具进行浏览器自动化和视觉测试的过程","ja":"Selenium テストとは、Selenium ツールを使用してブラウザ自動化と視覚テストを実行するプロセスです","ko":"Selenium 테스트는 Selenium 도구를 사용하여 브라우저 자동화와 시각적 테스트를 수행하는 과정입니다","es":"Selenium Testing es una técnica de automatización de navegador que utiliza Python y WebDriver para ejecutar scripts y pruebas","fr":"Selenium Testing est une technique d''automatisation de navigateur qui utilise Python et WebDriver pour exécuter des scripts et des tests","de":"Selenium Testing ist eine Technik zur Automatisierung von Browsern, die Python und WebDriver verwendet, um Skripte und Tests auszuführen","pt":"O que é Selenium Testing? É uma ferramenta de automação de navegador que utiliza o WebDriver para executar testes","ru":"Что такое Selenium Testing? Это инструмент для автоматизации браузера, который использует WebDriver для выполнения тестов","ar":"ما هو اختبار السيّلميوم؟ هو أداة للتحكم الآلي في المتصفحات التي تستخدم WebDriver لتشغيل الاختبارات"},"features":{"en":["Runs curated tools and scripts using pdm run python -m scripts.<module>","Supports browser automation using selenium and webdriver","Enables visual testing with screenshot capabilities","Follows Skriptoteket-specific login/env conventions as outlined in .agents/rules/075-browser-automation.md","Utilizes Python modules such as os, pathlib, and selenium.webdriver"],"zh":["浏览器自动化","视觉测试","WebDriver 支持","截图功能","Python 脚本集成","CLI 命令行运行"],"ja":["ブラウザ自動化","視覚テスト","WebDriver サポート","スクリーンショット機能","Python スクリプト統合","CLI コマンドライン実行"],"ko":["브라우저 자동화","시각적 테스트","WebDriver 지원","스크린샷 기능","Python 스크립트 통합","CLI 명령줄 실행"],"es":["Automatización de navegador con Python y WebDriver","Ejecución de scripts de automatización y pruebas visuales","Utilización de Selenium para pruebas de interfaz de usuario","Integración con herramientas de desarrollo como PDM","Soporte para diferentes navegadores y sistemas operativos"],"fr":["Automatisation de navigateur avec Python et WebDriver","Exécution de scripts d''automatisation et de tests visuels","Utilisation de Selenium pour les tests d''interface utilisateur","Intégration avec des outils de développement tels que PDM","Prise en charge de différents navigateurs et systèmes d''exploitation"],"de":["Automatisierung von Browsern mit Python und WebDriver","Ausführung von Automatisierungsskripten und visuellen Tests","Verwendung von Selenium für Benutzeroberflächentests","Integration mit Entwicklungstools wie PDM","Unterstützung für verschiedene Browser und Betriebssysteme"],"pt":["Automação de navegador com Selenium WebDriver","Testes visuais e funcionais com ferramentas de upload curadas","Suporte a screenshot e gravação de vídeo","Integração com o Python e o CLI","Compatibilidade com diferentes navegadores e plataformas"],"ru":["Автоматизация браузера с помощью Selenium WebDriver","Визуальные и функциональные тесты с помощью проверенных инструментов загрузки","Поддержка скриншотов и видеозаписи","Интеграция с Python и CLI","Совместимость с разными браузерами и платформами"],"ar":["التحكم الآلي في المتصفحات مع سيّلميوم WebDriver","اختبارات بصرية ووظيفية مع أدوات التحميل المعتمدة","دعم لقطات الشاشة وتسجيل الفيديو","التكامل مع بايثون وCLI","التوافق مع متصفحات و플اتفورمات مختلفة"]},"keywords":{"en":["how to use selenium-testing","selenium-testing setup guide","selenium-testing alternative","selenium-testing vs webdriver","selenium-testing install","what is selenium-testing","selenium-testing tutorial","automated browser testing with selenium-testing"],"zh":["Selenium 测试","浏览器自动化","视觉测试","WebDriver","Python 脚本","CLI 命令行","AIエージェント工具","自动化测试"],"ja":["Selenium テスト","ブラウザ自動化","視覚テスト","WebDriver","Python スクリプト","CLI コマンドライン","AIエージェントツール","自動テスト"],"ko":["Selenium 테스트","브라우저 자동화","시각적 테스트","WebDriver","Python 스크립트","CLI 명령줄","AI 에이전트 도구","자동화 테스트"],"es":["Selenium Testing","automatización de navegador","Python","WebDriver","pruebas visuales","desarrollo de software","herramientas de testing","automatización de interfaz de usuario","PDM"],"fr":["Selenium Testing","automatisation de navigateur","Python","WebDriver","tests visuels","développement de logiciels","outils de testing","automatisation d''interface utilisateur","PDM"],"de":["Selenium Testing","Automatisierung von Browsern","Python","WebDriver","visuelle Tests","Software-Entwicklung","Testing-Tools","Automatisierung von Benutzeroberflächen","PDM"],"pt":["selenium testing","automação de navegador","testes visuais","ferramentas de upload","python","cli","webdriver","screenshot","vídeo"],"ru":["selenium testing","автоматизация браузера","визуальные тесты","инструменты загрузки","python","cli","webdriver","скриншот","видео"],"ar":["اختبار السيّلميوم","التحكم الآلي في المتصفحات","اختبارات بصرية","أدوات التحميل","بايثون","CLI","WebDriver","لقطات الشاشة","فيديو"]}},"owner":"paunchygent","repo":"skriptoteket","repoPath":"paunchygent/skriptoteket","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.299Z","topics":[],"category":"community","skillMd":{"name":"selenium-testing","description":"Browser automation with Selenium WebDriver for Python. (project)","bodyPreview":"# Selenium Testing\n\n## When to Use\n\n- Browser automation, visual testing\n- Mentions: \"selenium\", \"webdriver\", \"screenshot\"\n\n## Canonical Repo Rules\n\nFor Skriptoteket-specific login/env conventions, follow:\n\n- `.agents/rules/075-browser-automation.md`\n\n## Run\n\n```bash\npdm run python -m scripts.<module>\n```\n\n## Quick Pattern\n\n```python\nimport os\nfrom pathlib import Path\n\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nfrom selenium.webdriver.support.ui import WebDriverWa","body":"# Selenium Testing\n\n## When to Use\n\n- Browser automation, visual testing\n- Mentions: \"selenium\", \"webdriver\", \"screenshot\"\n\n## Canonical Repo Rules\n\nFor Skriptoteket-specific login/env conventions, follow:\n\n- `.agents/rules/075-browser-automation.md`\n\n## Run\n\n```bash\npdm run python -m scripts.<module>\n```\n\n## Quick Pattern\n\n```python\nimport os\nfrom pathlib import Path\n\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nfrom selenium.webdriver.support.ui import WebDriverWait\nfrom selenium.webdriver.support import expected_conditions as EC\n\n\ndef _read_dotenv(path: Path) -> dict[str, str]:\n    if not path.exists():\n        return {}\n\n    values: dict[str, str] = {}\n    for line in path.read_text(encoding=\"utf-8\").splitlines():\n        stripped = line.strip()\n        if not stripped or stripped.startswith(\"#\") or \"=\" not in stripped:\n            continue\n        key, value = stripped.split(\"=\", 1)\n        values[key.strip()] = value.strip()\n    return values\n\n\ndotenv = _read_dotenv(Path(os.environ.get(\"DOTENV_PATH\", \".env\")))\n\n\ndef _get_config_value(*, key: str, default: str | None = None) -> str | None:\n    return os.environ.get(key) or dotenv.get(key) or default\n\n\nbase_url = _get_config_value(key=\"BASE_URL\", default=\"http://127.0.0.1:8000\") or \"http://127.0.0.1:8000\"\nemail = _get_config_value(key=\"PLAYWRIGHT_EMAIL\") or _get_config_value(key=\"BOOTSTRAP_SUPERUSER_EMAIL\")\npassword = _get_config_value(key=\"PLAYWRIGHT_PASSWORD\") or _get_config_value(\n    key=\"BOOTSTRAP_SUPERUSER_PASSWORD\"\n)\n\nif not email or not password:\n    raise SystemExit(\n        \"Missing credentials. Either set PLAYWRIGHT_EMAIL/PLAYWRIGHT_PASSWORD (recommended for prod) \"\n        \"or BOOTSTRAP_SUPERUSER_EMAIL/BOOTSTRAP_SUPERUSER_PASSWORD (dev). \"\n        \"Provide them in DOTENV_PATH (default: .env) or export them in your shell.\"\n    )\n\noptions = webdriver.ChromeOptions()\noptions.add_argument(\"--headless=new\")\ndriver = webdriver.Chrome(options=options)\ndriver.set_window_size(1440, 900)\n\n# Login\ndriver.get(f\"{base_url}/login\")\ndriver.find_element(By.NAME, \"email\").send_keys(email)\ndriver.find_element(By.NAME, \"password\").send_keys(password)\ndriver.find_element(By.CSS_SELECTOR, \"button[type=''submit'']\").click()\nWebDriverWait(driver, 10).until(EC.presence_of_element_located((By.XPATH, \"//*[contains(., ''Inloggad som'')]\")))\n\n# Screenshot\nPath(\".artifacts\").mkdir(parents=True, exist_ok=True)\ndriver.get(f\"{base_url}/admin/tools\")\ndriver.save_screenshot(\".artifacts/selenium-admin-tools.png\")\ndriver.quit()\n```\n\n## HTMX Caveat\n\nUse explicit `WebDriverWait` with `EC.url_contains()` instead of implicit waits.\n\n## Context7\n\nUse `mcp__context7__get-library-docs` with `/seleniumhq/selenium` for API details.\n"},"lastSynced":"2026-03-08T02:01:24.429Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing advanced browser automation and visual testing capabilities.","zh":"适合需要高级浏览器自动化和视觉测试能力的自动化代理。","ja":"高度なブラウザ自動化と視覚テスト機能を必要とする自動化エージェントに適しています。","ko":"고급 브라우저 자동화 및 시각적 테스트 기능이 필요한 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización que necesitan capacidades de automatización avanzada del navegador y pruebas visuales.","fr":"Parfait pour les Agents d''Automatisation ayant besoin de capacités d''automatisation de navigateur avancées et de tests visuels.","de":"Perfekt für Automatisierungsagenten, die erweiterte Browser-Automatisierung und visuelle Testfunktionen benötigen.","pt":"Perfeito para Agentes de Automação que necessitam de capacidades avançadas de automação de navegador e testes visuais.","ru":"Идеально подходит для агентов автоматизации, которым необходимы продвинутые возможности автоматизации браузера и визуального тестирования.","ar":"مثالي للوكلاء الآليين الذين يحتاجون إلى قدرات متقدمة في автоматизации المتصفح واختبارات بصرية."},"recommendation":{"en":"Empowers agents to automate browser interactions using selenium and webdriver, enabling visual testing and screenshot capabilities via Python scripts.","zh":"使代理能够使用selenium和webdriver自动化浏览器交互，通过Python脚本实现视觉测试和截图功能。","ja":"エージェントがseleniumとwebdriverを使用してブラウザの相互作用を自動化し、Pythonスクリプトを介して視覚テストとスクリーンショット機能を可能にします。","ko":"에이전트가 selenium과 webdriver를 사용하여 브라우저 상호 작용을 자동화하고, Python 스크립트를 통해 시각적 테스트 및 스크린샷 기능을 가능하게 합니다.","es":"Habilita a los agentes a automatizar las interacciones del navegador utilizando selenium y webdriver, permitiendo capacidades de prueba visual y captura de pantalla a través de scripts de Python.","fr":"Permet aux agents d''automatiser les interactions de navigateur à l''aide de selenium et webdriver, permettant ainsi des capacités de test visuel et de capture d''écran via des scripts Python.","de":"Ermöglicht es Agenten, Browser-Interaktionen mit selenium und webdriver zu automatisieren, wodurch visuelle Test- und Screenshot-Funktionen über Python-Skripte ermöglicht werden.","pt":"Habilita os agentes a automatizar interações de navegador usando selenium e webdriver, permitindo capacidades de teste visual e capturas de tela via scripts Python.","ru":"Наделяет агентов возможностью автоматизировать взаимодействия браузера с помощью selenium и webdriver, обеспечивая возможности визуального тестирования и захвата экрана через скрипты Python.","ar":"يمنح الوكلاء القدرة على 자동 hóa التفاعلات المتصفح باستخدام selenium و webdriver، وتمكين قدرات الاختبار البصري وتقطيع الشاشة من خلال scripts Python."},"useCases":{"en":["Automating browser interactions for testing","Generating screenshots for visual validation","Debugging web applications using selenium"],"zh":["自动化浏览器交互进行测试","生成截图用于视觉验证","使用selenium调试Web应用程序"],"ja":["テストのためのブラウザの相互作用を自動化する","視覚的な検証のためのスクリーンショットを生成する","seleniumを使用してWebアプリケーションをデバッグする"],"ko":["테스트를 위한 브라우저 상호 작용 자동화","시각적 확인을 위한 스크린샷 생성","selenium을 사용한 웹 애플리케이션 디버깅"],"es":["Automatizar interacciones de navegador para pruebas","Generar capturas de pantalla para validación visual","Depurar aplicaciones web utilizando selenium"],"fr":["Automatiser les interactions de navigateur pour les tests","Générer des captures d''écran pour la validation visuelle","Déboguer les applications web à l''aide de selenium"],"de":["Automatisieren von Browser-Interaktionen für Tests","Erzeugen von Screenshots für visuelle Überprüfung","Debuggen von Webanwendungen mit selenium"],"pt":["Automatizar interações de navegador para testes","Gerar capturas de tela para validação visual","Depurar aplicações web usando selenium"],"ru":["Автоматизация взаимодействий браузера для тестирования","Генерация скриншотов для визуальной проверки","Отладка веб-приложений с помощью selenium"],"ar":["أتمتة التفاعلات المتصفح للاختبار","генерация لقطة الشاشة للتحقق البصري","تصحيح الأخطاء في التطبيقات الويب باستخدام selenium"]},"limitations":{"en":["Requires Python environment","Dependent on selenium and webdriver libraries"],"zh":["需要Python环境","依赖于selenium和webdriver库"],"ja":["Python環境が必要","seleniumとwebdriverライブラリに依存する"],"ko":["Python 환경이 필요","selenium과 webdriver 라이브러리에 의존"],"es":["Requiere entorno de Python","Dependiente de las bibliotecas selenium y webdriver"],"fr":["Nécessite un environnement Python","Dépendant des bibliothèques selenium et webdriver"],"de":["Benötigt Python-Umgebung","Abhängig von den Bibliotheken selenium und webdriver"],"pt":["Requer ambiente Python","Dependente das bibliotecas selenium e webdriver"],"ru":["Требуется среда Python","Зависит от библиотек selenium и webdriver"],"ar":["يتطلب بيئة Python","يعتمد على مكتبات selenium و webdriver"]},"version":4},"contentHash":"5b61ffa0b4dcac088717fb2506cf5092c5a09bbc5c0cc80ffd27fee3ec87cfd7","qualityScore":51}');
