INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('paunchygent/skriptoteket/selenium-testing', 'selenium-testing', 'paunchygent', 'skriptoteket', 'community', 'selenium-testing paunchygent skriptoteket community Selenium-testing is a Teacher-first Script Hub for running curated, upload-based tools, ideal for developers who need browser automation and visual testing capabilities. Selenium 测试工具提供了浏览器自动化和视觉测试的解决方案，使用 Python 和 WebDriver 实现 Selenium テストツールは、ブラウザ自動化と視覚テストのための解決策を提供し、Python と WebDriver を使用します Selenium 테스트 도구는 브라우저 자동화와 시각적 테스트를 위한 솔루션을 제공하며 Python과 WebDriver를 사용합니다 Selenium Testing es una herramienta para automatizar tareas en el navegador utilizando Python y WebDriver. Permite ejecutar scripts de automatización y pruebas visuales Selenium Testing est un outil pour automatiser des tâches dans le navigateur en utilisant Python et WebDriver. Il permet d''exécuter des scripts d''automatisation et des tests visuels Selenium Testing ist ein Tool zur Automatisierung von Aufgaben im Browser mit Python und WebDriver. Es ermöglicht die Ausführung von Automatisierungsskripten und visuellen Tests O Selenium Testing é uma ferramenta de automação de navegador que permite a execução de testes visuais e funcionais de forma eficiente Selenium Testing - это инструмент для автоматизации браузера, который позволяет выполнять визуальные и функциональные тесты эффективно اختبار السيّلميوم هو أداة للتحكم الآلي في المتصفحات التي تمكن من تشغيل الاختبارات البصرية والوظيفية بفعالية how to use selenium-testing selenium-testing setup guide selenium-testing alternative selenium-testing vs webdriver selenium-testing install what is selenium-testing selenium-testing tutorial automated browser testing with selenium-testing Selenium 测试 浏览器自动化 视觉测试 WebDriver Python 脚本 CLI 命令行 AIエージェント工具 自动化测试 Runs curated tools and scripts using pdm run python -m scripts.<module> Supports browser automation using selenium and webdriver Enables visual testing with screenshot capabilities Follows Skriptoteket-specific login/env conventions as outlined in .agents/rules/075-browser-automation.md Utilizes Python modules such as os, pathlib, and selenium.webdriver Selenium-testing is a skill that enables automated browser testing using selenium, webdriver, and screenshot technologies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('iQeda/MyRust-NeetCode/lc-show', 'community', 'iQeda', 'MyRust-NeetCode', 'iQeda/MyRust-NeetCode', 'lc-show', 0, 0, 51, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:27.484Z', '7d84fb06ec0c4a0cd9aa04a57ed5b2d2e6471db5b679463352544575dde04945', '{"id":"iQeda/MyRust-NeetCode/lc-show","name":"lc-show","description":{"en":"The lc-show skill generates Rust code templates for LeetCode problems and displays problem details. It benefits developers solving LeetCode challenges.","zh":"lc-show 是一个用于显示 LeetCode 问题详情和生成 Rust 代码模板的工具，帮助开发者提高开发效率","ja":"lc-show は、LeetCode 問題の詳細を表示し、Rust コードテンプレートを生成するツールです","ko":"lc-show는 LeetCode 문제 상세 정보를 표시하고 Rust 코드 템플릿을 생성하여 개발자에게 도움을 주는 도구입니다","es":"lc-show es una herramienta que muestra detalles de problemas y genera plantillas de código Rust en el directorio problems/. Utiliza la CLI de LeetCode para mostrar la descripción del problema y generar el código.","fr":"lc-show est un outil qui affiche les détails des problèmes et génère des modèles de code Rust dans le répertoire problems/. Il utilise la CLI de LeetCode pour afficher la description du problème et générer le code.","de":"lc-show ist ein Tool, das Problemdetails anzeigt und Rust-Code-Vorlagen im problems/-Verzeichnis generiert. Es verwendet die LeetCode-CLI, um die Problembeschreibung anzuzeigen und den Code zu generieren.","pt":"O lc-show é uma ferramenta de AI que exibe detalhes de problemas e gera templates de código Rust para desenvolvedores.","ru":"ИИ Агент lc-show - это инструмент, который показывает детали задач и генерирует шаблоны кода Rust для разработчиков.","ar":"أداة الوسائط الذكية lc-show هي أداة تعرض تفاصيل المشكلات وتوليد قوالب كود الرست للمطورين."},"seo":{"title":{"en":"lc-show: LeetCode Problem Setup Guide | AI Agent Skill","zh":"lc-show 设置指南：显示 LeetCode 问题详情和 Rust 模板","ja":"lc-show セットアップガイド：LeetCode 問題の詳細と Rust テンプレートの表示","ko":"lc-show 설정 가이드: LeetCode 문제 상세 정보 및 Rust 템플릿 표시","es":"Guía de configuración de lc-show para desarrolladores","fr":"Guide d''installation de lc-show pour les développeurs","de":"Einrichtungsleitfaden für lc-show-Entwickler","pt":"Guia de Configuração do lc-show: Ferramenta de AI para De...","ru":"Настройка ИИ Агента lc-show: Руководство для Разработчиков","ar":"دليل إعداد lc-show: أداة الوسائط الذكية للمطورين"},"description":{"en":"Discover how to use lc-show to streamline LeetCode problem solving. Get started with our setup guide and master Rust template generation today!","zh":"使用 lc-show 显示 LeetCode 问题详情并生成 Rust 代码模板，提高开发效率","ja":"lc-show を使用して LeetCode 問題の詳細を表示し、Rust コードテンプレートを生成する","ko":"lc-show를 사용하여 LeetCode 문제 상세 정보를 표시하고 Rust 코드 템플릿을 생성하여 개발 효율성을 향상시키세요","es":"Aprende a utilizar lc-show para mostrar detalles de problemas y generar plantillas de código Rust en el directorio problems/","fr":"Découvrez comment utiliser lc-show pour afficher les détails des problèmes et générer des modèles de code Rust dans le répertoire problems/","de":"Erfahren Sie, wie Sie lc-show verwenden, um Problemdetails anzuzeigen und Rust-Code-Vorlagen im problems/-Verzeichnis zu generieren","pt":"Aprenda a configurar o lc-show, uma ferramenta de AI para desenvolvedores, e melhore sua produtividade com recursos de código Rust","ru":"Узнайте, как настроить ИИ Агент lc-show, инструмент для разработчиков, и повысьте свою производительность с помощью возможностей кода Rust","ar":"تعرف على إعداد أداة الوسائط الذكية lc-show للمطورين وطور إنتاجيتك باستخدام ميزات 코드 Rust"},"definition":{"en":"lc-show is a skill that displays LeetCode problem details and generates Rust templates in the problems/ directory.","zh":"lc-show 是一个命令行工具，用于显示 LeetCode 问题详情和生成 Rust 代码模板","ja":"lc-show は、LeetCode 問題の詳細を表示し、Rust コードテンプレートを生成する CLI ツールです","ko":"lc-show는 LeetCode 문제 상세 정보를 표시하고 Rust 코드 템플릿을 생성하는 CLI 도구입니다","es":"lc-show es una herramienta de desarrollo que muestra detalles de problemas de LeetCode y genera plantillas de código Rust","fr":"lc-show est un outil de développement qui affiche les détails des problèmes de LeetCode et génère des modèles de code Rust","de":"lc-show ist ein Entwicklungstool, das Problemdetails von LeetCode anzeigt und Rust-Code-Vorlagen generiert","pt":"O lc-show é uma ferramenta de AI que fornece detalhes de problemas e gera código Rust","ru":"ИИ Агент lc-show - это инструмент, который предоставляет детали задач и генерирует код Rust","ar":"أداة الوسائط الذكية lc-show هي أداة توفر تفاصيل المشكلات وتوليد كود الرست"},"features":{"en":["Displays LeetCode problem descriptions using the `leetcode show` command","Generates Rust code templates with the `-g -l rust` option","Moves generated files to the `problems/` directory","Supports problem details display with `2>/dev/null` error handling","Creates files in the format `<problem_id>.<problem-name>.rs`"],"zh":["显示 LeetCode 问题详情","生成 Rust 代码模板","支持命令行操作","自动移动生成的文件到 problems 目录"],"ja":["LeetCode 問題の詳細を表示する","Rust コードテンプレートを生成する","CLI 操作をサポートする","生成されたファイルを problems ディレクトリに自動的に移動する"],"ko":["LeetCode 문제 상세 정보 표시","Rust 코드 템플릿 생성","CLI 명령어 지원","생성된 파일을 problems 디렉토리에 자동으로 이동"],"es":["Muestra detalles de problemas de LeetCode","Genera plantillas de código Rust en el directorio problems/","Utiliza la CLI de LeetCode para mostrar la descripción del problema","Genera código Rust con la opción -g y -l rust","Mueve el archivo generado al directorio problems/","Soporte para la línea de comandos"],"fr":["Affiche les détails des problèmes de LeetCode","Génère des modèles de code Rust dans le répertoire problems/","Utilise la CLI de LeetCode pour afficher la description du problème","Génère du code Rust avec les options -g et -l rust","Déplace le fichier généré dans le répertoire problems/","Prise en charge de la ligne de commande"],"de":["Zeigt Problemdetails von LeetCode an","Generiert Rust-Code-Vorlagen im problems/-Verzeichnis","Verwendet die LeetCode-CLI, um die Problembeschreibu