INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('iQeda/MyRust-NeetCode/lc-show', 'lc-show', 'iQeda', 'MyRust-NeetCode', 'community', 'lc-show iQeda MyRust-NeetCode community The lc-show skill generates Rust code templates for LeetCode problems and displays problem details. It benefits developers solving LeetCode challenges. lc-show 是一个用于显示 LeetCode 问题详情和生成 Rust 代码模板的工具，帮助开发者提高开发效率 lc-show は、LeetCode 問題の詳細を表示し、Rust コードテンプレートを生成するツールです lc-show는 LeetCode 문제 상세 정보를 표시하고 Rust 코드 템플릿을 생성하여 개발자에게 도움을 주는 도구입니다 lc-show es una herramienta que muestra detalles de problemas y genera plantillas de código Rust en el directorio problems/. Utiliza la CLI de LeetCode para mostrar la descripción del problema y generar el código. lc-show est un outil qui affiche les détails des problèmes et génère des modèles de code Rust dans le répertoire problems/. Il utilise la CLI de LeetCode pour afficher la description du problème et générer le code. lc-show ist ein Tool, das Problemdetails anzeigt und Rust-Code-Vorlagen im problems/-Verzeichnis generiert. Es verwendet die LeetCode-CLI, um die Problembeschreibung anzuzeigen und den Code zu generieren. O lc-show é uma ferramenta de AI que exibe detalhes de problemas e gera templates de código Rust para desenvolvedores. ИИ Агент lc-show - это инструмент, который показывает детали задач и генерирует шаблоны кода Rust для разработчиков. أداة الوسائط الذكية lc-show هي أداة تعرض تفاصيل المشكلات وتوليد قوالب كود الرست للمطورين. how to use lc-show lc-show setup guide lc-show alternative lc-show vs LeetCode CLI lc-show install what is lc-show Rust template generation LeetCode problem solving lc-show tutorial lc-show LeetCode Rust 命令行工具 代码模板生成 AI エージェント 开发工具 Displays LeetCode problem descriptions using the `leetcode show` command Generates Rust code templates with the `-g -l rust` option Moves generated files to the `problems/` directory Supports problem details display with `2>/dev/null` error handling Creates files in the format `<problem_id>.<problem-name>.rs` lc-show is a skill that displays LeetCode problem details and generates Rust templates in the problems/ directory.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anadav/computer-structure-lecture-slides/extract-page', 'community', 'anadav', 'computer-structure-lecture-slides', 'anadav/computer-structure-lecture-slides', 'extract-page', 0, 0, 51, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:34.594Z', 'd267ee80ca0d83520245dfef75450e92068dc0db99d2ed59252403650c6883ec', '{"id":"anadav/computer-structure-lecture-slides/extract-page","name":"extract-page","description":{"en":"The extract-page skill extracts a single page from a PDF as a PNG image, benefiting developers who need to manipulate PDF content. It utilizes the tools/extract_page.py script for page extraction.","zh":"Extract Page工具使用Python脚本从PDF中提取单页，输出为PNG图像。支持自定义输出路径和页码索引","ja":"Extract PageツールはPythonスクリプトを使用してPDFから1ページを抽出します。PNG画像として出力し、カスタム出力パスとページ番号インデックスをサポートします","ko":"Extract Page 도구는 Python 스크립트를 사용하여 PDF에서 단일 페이지를 추출하고 PNG 이미지로 출력합니다. 사용자 지정 출력 경로 및 페이지 번호 인덱스를 지원합니다","es":"La herramienta de extracción de página de PDF es una herramienta de línea de comandos que utiliza Python para extraer páginas de un archivo PDF y convertirlas en imágenes PNG.","fr":"L''outil d''extraction de page PDF est un outil en ligne de commande qui utilise Python pour extraire des pages d''un fichier PDF et les convertir en images PNG.","de":"Das PDF-Seiten-Extraktions-Tool ist ein Kommandozeilen-Tool, das Python verwendet, um Seiten aus einer PDF-Datei zu extrahieren und in PNG-Bilder umzuwandeln.","pt":"A ferramenta extract-page é uma ferramenta de linha de comando que extrai páginas PDF como imagens PNG. Ela usa Python e oferece opções personalizadas para saída.","ru":"ИИ Агент extract-page - это инструмент командной строки, который извлекает страницы PDF в виде изображений PNG. Он использует Python и предлагает настраиваемые опции для вывода.","ar":"أداة Extract-Page هي أداة سطر أوامر تستخرج صفحات PDF كصور PNG. تستخدم Python وتوفر خيارات مخصصة للخرج."},"seo":{"title":{"en":"extract-page: PDF Page Extraction Setup Guide | AI Agent ...","zh":"Extract Page_SETUP GUIDE - AI工具","ja":"Extract Page_BEST PRACTICES - AIエージェント","ko":"Extract Page_SETUP GUIDE - AI 도구","es":"Herramienta de Extracción de Página de PDF: Guía de Confi...","fr":"Outil d''Extraction de Page PDF: Meilleures Pratiques","de":"PDF-Seiten-Extraktions-Tool: Einrichtungsanleitung","pt":"Guia de Configuração do Extract-Page: Ferramenta de Extra...","ru":"Настройка ИИ Агента Extract-Page: Инструмент для Извлечен...","ar":"دليل إعداد Extract-Page: أداة استخراج صفحات PDF"},"description":{"en":"Discover how to extract single pages from PDFs as PNG images using extract-page. Get started with our easy-to-use tool and optimize your workflow today!","zh":"使用Extract Page工具从PDF中提取单页，输出为PNG图像，了解如何使用Python脚本实现AI工具","ja":"Extract Pageツールを使用してPDFから1ページを抽出します。PNG画像として出力し、Pythonスクリプトを使用したAIエージェントの使い方を学びましょう","ko":"Extract Page 도구를 사용하여 PDF에서 단일 페이지를 추출하고 PNG 이미지로 출력합니다. Python 스크립트를 사용하여 AI 도구를 사용하는 방법을 알아보세요","es":"Aprende a utilizar la herramienta de extracción de página de PDF para convertir páginas en imágenes PNG con Python y CLI","fr":"Découvrez comment utiliser l''outil d''extraction de page PDF pour convertir des pages en images PNG avec Python et CLI","de":"Erfahren Sie, wie Sie das PDF-Seiten-Extraktions-Tool verwenden, um Seiten in PNG-Bilder mit Python und CLI umzuwandeln","pt":"Aprenda a usar a ferramenta extract-page para extrair páginas PDF como imagens PNG. Veja exemplos e dicas de uso.","ru":"Узнайте, как использовать ИИ Агент extract-page для извлечения страниц PDF в виде изображений PNG. Примеры и советы по использованию.","ar":"تعرف على كيفية استخدام أداة Extract-Page لاستخراج صفحات PDF كصور PNG. شاهد الأمثلة والنصائح لاستخدام الأداة."},"definition":{"en":"extract-page is a tool that allows users to extract a single page from a PDF document and save it as a PNG image using the command line interface.","zh":"Extract Page是AI工具，使用Python脚本从PDF中提取单页","ja":"Extract PageはAIエージェントで、Pythonスクリプトを使用してPDFから1ページを抽出します","ko":"Extract Page는 AI 도구로 Python 스크립트를 사용하여 PDF에서 단일 페이지를 추출합니다","es":"La herramienta de extracción de página de PDF es una herramienta de software que utiliza AI Agent para extraer páginas de un archivo PDF","fr":"L''outil d''extraction de page PDF est un outil logiciel qui utilise un agent IA pour extraire des pages d''un fichier PDF","de":"Das PDF-Seiten-Extraktions-Tool ist ein Software-Tool, das einen AI-Agenten verwendet, um Seiten aus einer PDF-Datei zu extrahieren","pt":"O extract-page é uma ferramenta que extrai páginas PDF como imagens PNG usando Python.","ru":"Extract-page - это инструмент, который извлекает страницы PDF в виде изображений PNG с помощью Python.","ar":"Extract-Page هي أداة تستخرج صفحات PDF كصور PNG باستخدام Python."},"features":{"en":["Extracts single pages from PDF files using tools/extract_page.py","Supports custom output paths for extracted pages","Generates PNG images from extracted pages","Utilizes 1-indexed page numbers for accurate extraction","Allows for basic usage with python tools/extract_page.py $ARGUMENTS[0] $ARGUMENTS[1] command"],"zh":["使用Python脚本从PDF中提取单页","支持自定义输出路径","输出为PNG图像","支持页码索引（1-index）","使用CLI命令行工具"],"ja":["Pythonスクリプトを使用してPDFから1ページを抽出","カスタム出力パスをサポート","PNG画像として出力","ページ番号インデックス（1-index）をサポート","CLIコマンドラインツールを使用"],"ko":["Python 스크립트를 사용하여 PDF에서 단일 페이지를 추출","사용자 지정 출력 경로를 지원","PNG 이미지로 출력","페이지 번호 인덱스（1-index）를 지원","CLI 명령줄 도구를 사용"],"es":["Utiliza Python para extraer páginas de un archivo PDF","Convierte páginas en imágenes PNG","Admite ruta de salida personalizada con la opción -o","Puede extraer páginas individuales o múltiples","Utiliza la línea de comandos para una integración fácil con otros herramientas"],"fr":["Utilise Python pour extraire des pages d''un fichier PDF","Converte des pages en images PNG","Prend en charge le chemin de sortie personnalisé avec l''option -o","Peut extraire des pages individuelles ou multiples","Utilise la ligne de commande pour une intégration facile avec d''autres outils"],"de":["Verwendet Python, um Seiten aus einer PDF-Datei zu extrahieren","Wandelt Seiten in PNG-Bilder um","Unterstützt benutzerdefinierten Ausgabepfad mit der Option -o","Kann einzelne oder mehrere Seiten extrahieren","Verwendet die Kommandozeile für eine einfache Integration mit anderen Tools"],"pt":["Extração de páginas PDF como imagens PNG","Uso de Python para processamento","Opções personalizadas para saída de arquivos","Suporte a página indexada em 1","Uso via linha de comando com ferramenta extract_page.py"],"ru":["Извлечение страниц PDF в виде изображений PNG","Использование Python для обработки","Настройка опций для вывода файлов","Поддержка страницы с индексом 1","Использование через командную строку с инструментом extract_page.py"],"ar":["استخراج صفحات PDF كصور PNG","استخدام Python للمعالجة","خيارات مخصصة للخرج الملفات","دعم صفحه المُفهرسة في 1","استخدام عبر سطر الأوامر مع أداة extract_page.py"]},"keywords":{"en":["how to use extract-page","extract-page alternative","extract-page setup guide","pdf page extraction tool","extract-page vs pdftk","extract-page install","what is extract-page","extract-page python script","pdf to png converter"],"zh":["Extract Page","AI工具","PDF提取","Python脚本","PNG图像","CLI命令行工具","页码索引","自定义输出路径"],"ja":["Extract Page","AIエージェント","PDF抽出","Pythonスクリプト","PNG画像","CLIコマンドラインツール","ページ番号インデックス","カスタム出力パス"],"ko":["Extract Page","AI 도구","PDF 추출","Python 스크립트","PNG 이미지","CLI 명령줄 도구","페이지 번호 인덱스","사용자 지정 출력 경로"],"es":["herramienta de extracción de página de PDF","AI Agent para PDF","Python para PDF","CLI para PDF","extracción de página de PDF","conversión de PDF a PNG","ruta de salida personalizada"],"fr":["outil d''extraction de page PDF","agent IA pour PDF","Python pour PDF","CLI pour PDF","extraction de page PDF","conversion de PDF en PNG","chemin de sortie personnalisé"],"de":["PDF-Seiten-Extraktions-Tool","AI-Agent für PDF","Python für PDF","CLI für PDF","Seitenextraktion aus PDF","Umwandlung von PDF in PNG","benutzerdefinierter Ausgabepfad"],"pt":["extract-page","ferramenta de extração de páginas PDF","Python","linha de comando","imagens PNG","processamento de PDF","ferramentas de desenvolvimento"],"ru":["extract-page","ИИ Агент","инструмент для извлечения страниц PDF","Python","командная строка","изображения PNG","обработка PDF","инструменты разработки"],"ar":["extract-page","أداة استخراج صفحات PDF","Python","سطر الأوامر","صور PNG","معالجة PDF","أدوات التطوير"]}},"owner":"anadav","repo":"computer-structure-lecture-slides","repoPath":"anadav/computer-structure-lecture-slides","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.301Z","topics":[],"category":"community","skillMd":{"name":"extract-page","description":"Extract a single page from a PDF as a PNG image for quick preview.","bodyPreview":"# Extract PDF Page Tool\n\nUse `tools/extract_page.py` to extract a single page from a PDF as a PNG image.\n\n## Usage\n\n**Basic usage:**\n```bash\npython tools/extract_page.py $ARGUMENTS[0] $ARGUMENTS[1]\n```\n\n**With custom output path:**\n```bash\npython tools/extract_page.py <file>.pdf <page> -o output.png\n```\n\n## Examples\n\n```bash\n# Extract page 5 from build/lecture.pdf\npython tools/extract_page.py build/lecture.pdf 5\n\n# Output will be: build/lecture.page5.png\n```\n\n## Notes\n\n- Page numbers are 1-index","body":"# Extract PDF Page Tool\n\nUse `tools/extract_page.py` to extract a single page from a PDF as a PNG image.\n\n## Usage\n\n**Basic usage:**\n```bash\npython tools/extract_page.py $ARGUMENTS[0] $ARGUMENTS[1]\n```\n\n**With custom output path:**\n```bash\npython tools/extract_page.py <file>.pdf <page> -o output.png\n```\n\n## Examples\n\n```bash\n# Extract page 5 from build/lecture.pdf\npython tools/extract_page.py build/lecture.pdf 5\n\n# Output will be: build/lecture.page5.png\n```\n\n## Notes\n\n- Page numbers are 1-indexed\n- Default output: `<file>.page<N>.png`\n- Uses pdftoppm (poppler), sips (macOS), or ImageMagick convert\n"},"lastSynced":"2026-03-08T02:01:34.594Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Processing Agents needing precise PDF page extraction and image conversion capabilities.","zh":"非常适合需要精确PDF页面提取和图像转换功能的文档处理Agent。","ja":"正確なPDFページ抽出と画像変換機能を必要とするドキュメント処理エージェントに最適です。","ko":"정확한 PDF 페이지 추출 및 이미지 변환 기능이 필요한 문서 처리 에이전트에 완벽합니다.","es":"Ideal para agentes de procesamiento de documentos que necesitan capacidades precisas de extracción de páginas PDF y conversión de imágenes.","fr":"Parfait pour les agents de traitement de documents nécessitant des capacités précises d''extraction de pages PDF et de conversion d''images.","de":"Perfekt für Dokumentenverarbeitungs-Agents, die präzise PDF-Seitenextraktion und Bildkonvertierungsfähigkeiten benötigen.","pt":"Ideal para Agentes de Processamento de Documentos que necessitam de capacidades precisas de extração de páginas PDF e conversão de imagens.","ru":"Идеально подходит для Агентов обработки документов, которым требуются точные возможности извлечения страниц PDF и преобразования изображений.","ar":"مثالي لوكلاء معالجة المستندات الذين يحتاجون إلى إمكانيات دقيقة لاستخراج صفحات PDF وتحويل الصور."},"recommendation":{"en":"Enables direct extraction of specific PDF pages as PNG images using 1-indexed page numbering. Provides developers with visual document manipulation capabilities through command-line execution of Python scripts.","zh":"支持使用1起始页码将特定PDF页面直接提取为PNG图像。通过命令行执行Python脚本，为开发人员提供可视化文档操作能力。","ja":"1から始まるページ番号を使用して特定のPDFページをPNG画像として直接抽出できます。Pythonスクリプトのコマンドライン実行を通じて開発者に視覚的なドキュメント操作機能を提供します。","ko":"1부터 시작하는 페이지 번호를 사용하여 특정 PDF 페이지를 PNG 이미지로 직접 추출할 수 있습니다. Python 스크립트의 명령줄 실행을 통해 개발자에게 시각적 문서 조작 기능을 제공합니다.","es":"Permite la extracción directa de páginas PDF específicas como imágenes PNG utilizando una numeración de páginas basada en 1. Proporciona a los desarrolladores capacidades de manipulación visual de documentos mediante la ejecución por línea de comandos de scripts Python.","fr":"Permet l''extraction directe de pages PDF spécifiques en tant qu''images PNG en utilisant une numérotation de pages basée sur 1. Fournit aux développeurs des capacités de manipulation visuelle de documents via l''exécution en ligne de commande de scripts Python.","de":"Ermöglicht die direkte Extraktion spezifischer PDF-Seiten als PNG-Bilder unter Verwendung einer 1-basierten Seitennummerierung. Bietet Entwicklern visuelle Dokumentenbearbeitungsfähigkeiten durch Kommandozeilenausführung von Python-Scripts.","pt":"Permite a extração direta de páginas PDF específicas como imagens PNG usando numeração de páginas baseada em 1. Fornece aos desenvolvedores capacidades de manipulação visual de documentos através da execução de linha de comando de scripts Python.","ru":"Позволяет напрямую извлекать определенные страницы PDF в виде изображений PNG с использованием нумерации страниц, начинающейся с 1. Предоставляет разработчикам возможности визуального управления документами через выполнение скриптов Python из командной строки.","ar":"يتيح الاستخراج المباشر لصفحات PDF محددة كصور PNG باستخدام ترقيم الصفحات القائم على 1. يوفر للمطورين إمكانيات معالجة المستندات المرئية من خلال التنفيذ عبر سطر الأوامر لنصوص Python."},"useCases":{"en":["Extracting specific pages for visual analysis","Converting PDF documentation to image formats","Preparing document pages for OCR processing","Creating visual previews of PDF content"],"zh":["提取特定页面用于视觉分析","将PDF文档转换为图像格式","为OCR处理准备文档页面","创建PDF内容的视觉预览"],"ja":["視覚的分析のための特定ページの抽出","PDFドキュメントの画像形式への変換","OCR処理のためのドキュメントページの準備","PDFコンテンツの視覚的なプレビューの作成"],"ko":["시각적 분석을 위한 특정 페이지 추출","PDF 문서를 이미지 형식으로 변환","OCR 처리를 위한 문서 페이지 준비","PDF 콘텐츠의 시각적 미리보기 생성"],"es":["Extracción de páginas específicas para análisis visual","Conversión de documentación PDF a formatos de imagen","Preparación de páginas de documentos para procesamiento OCR","Creación de vistas previas visuales del contenido PDF"],"fr":["Extraction de pages spécifiques pour analyse visuelle","Conversion de la documentation PDF en formats d''image","Préparation de pages de documents pour traitement OCR","Création d''aperçus visuels du contenu PDF"],"de":["Extraktion spezifischer Seiten zur visuellen Analyse","Konvertierung von PDF-Dokumentation in Bildformate","Vorbereitung von Dokumentenseiten für die OCR-Verarbeitung","Erstellung visueller Vorschauen von PDF-Inhalten"],"pt":["Extrair páginas específicas para análise visual","Converter documentação PDF para formatos de imagem","Preparar páginas de documento para processamento OCR","Criar pré-visualizações visuais do conteúdo PDF"],"ru":["Извлечение определенных страниц для визуального анализа","Преобразование документации PDF в форматы изображений","Подготовка страниц документов для обработки OCR","Создание визуальных превью содержимого PDF"],"ar":["استخراج صفحات محددة للتحليل المرئي","تحويل توثيق PDF إلى تنسيقات الصور","تحضير صفحات المستندات لمعالجة OCR","إنشاء معاينات بصرية لمحتوى PDF"]},"limitations":{"en":["Requires Python environment","Page numbers are 1-indexed only","Outputs PNG format exclusively","Single page extraction per operation"],"zh":["需要Python环境","仅支持1起始页码","仅输出PNG格式","每次操作仅提取单个页面"],"ja":["Python環境が必要","ページ番号は1からのみ対応","PNG形式での出力のみ","操作ごとに単一ページの抽出のみ"],"ko":["Python 환경 필요","페이지 번호는 1부터 시작만 지원","PNG 형식으로만 출력","작업당 단일 페이지만 추출"],"es":["Requiere un entorno Python","Los números de página son exclusivamente basados en 1","Genera exclusivamente formato PNG","Extracción de una sola página por operación"],"fr":["Nécessite un environnement Python","Les numéros de page sont exclusivement basés sur 1","Produit exclusivement le format PNG","Extraction d''une seule page par opération"],"de":["Erfordert eine Python-Umgebung","Seitennummern sind ausschließlich 1-basiert","Gibt ausschließlich PNG-Format aus","Einzelseitenextraktion pro Operation"],"pt":["Requer um ambiente Python","Os números de página são apenas baseados em 1","Gera exclusivamente formato PNG","Extração de página única por operação"],"ru":["Требуется среда Python","Номера страниц только начинаются с 1","Вывод исключительно в формате PNG","Извлечение одной страницы за операцию"],"ar":["يتطلب بيئة Python","أرقام الصفحات تعتمد على 1 فقط","يخرج حصريًا بتنسيق PNG","استخراج صفحة واحدة لكل عملية"]},"version":4},"contentHash":"d267ee80ca0d83520245dfef75450e92068dc0db99d2ed59252403650c6883ec","qualityScore":51}');
