INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anadav/computer-structure-lecture-slides/extract-page', 'extract-page', 'anadav', 'computer-structure-lecture-slides', 'community', 'extract-page anadav computer-structure-lecture-slides community The extract-page skill extracts a single page from a PDF as a PNG image, benefiting developers who need to manipulate PDF content. It utilizes the tools/extract_page.py script for page extraction. Extract Page工具使用Python脚本从PDF中提取单页，输出为PNG图像。支持自定义输出路径和页码索引 Extract PageツールはPythonスクリプトを使用してPDFから1ページを抽出します。PNG画像として出力し、カスタム出力パスとページ番号インデックスをサポートします Extract Page 도구는 Python 스크립트를 사용하여 PDF에서 단일 페이지를 추출하고 PNG 이미지로 출력합니다. 사용자 지정 출력 경로 및 페이지 번호 인덱스를 지원합니다 La herramienta de extracción de página de PDF es una herramienta de línea de comandos que utiliza Python para extraer páginas de un archivo PDF y convertirlas en imágenes PNG. L''outil d''extraction de page PDF est un outil en ligne de commande qui utilise Python pour extraire des pages d''un fichier PDF et les convertir en images PNG. Das PDF-Seiten-Extraktions-Tool ist ein Kommandozeilen-Tool, das Python verwendet, um Seiten aus einer PDF-Datei zu extrahieren und in PNG-Bilder umzuwandeln. A ferramenta extract-page é uma ferramenta de linha de comando que extrai páginas PDF como imagens PNG. Ela usa Python e oferece opções personalizadas para saída. ИИ Агент extract-page - это инструмент командной строки, который извлекает страницы PDF в виде изображений PNG. Он использует Python и предлагает настраиваемые опции для вывода. أداة Extract-Page هي أداة سطر أوامر تستخرج صفحات PDF كصور PNG. تستخدم Python وتوفر خيارات مخصصة للخرج. how to use extract-page extract-page alternative extract-page setup guide pdf page extraction tool extract-page vs pdftk extract-page install what is extract-page extract-page python script pdf to png converter Extract Page AI工具 PDF提取 Python脚本 PNG图像 CLI命令行工具 页码索引 自定义输出路径 Extracts single pages from PDF files using tools/extract_page.py Supports custom output paths for extracted pages Generates PNG images from extracted pages Utilizes 1-indexed page numbers for accurate extraction Allows for basic usage with python tools/extract_page.py $ARGUMENTS[0] $ARGUMENTS[1] command extract-page is a tool that allows users to extract a single page from a PDF document and save it as a PNG image using the command line interface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DW225/ree-board/signal-state-management', 'community', 'DW225', 'ree-board', 'DW225/ree-board', 'signal-state-management', 0, 0, 51, '2026-03-08T01:57:15.304Z', '2026-03-08T02:01:58.407Z', '983fb9eacda7d8731f760c7fed42bfec26c210acfaf34d33250010d739ef8830', '{"id":"DW225/ree-board/signal-state-management","name":"signal-state-management","description":{"en":"Signal-state-management is a skill for managing client-side application state and creating reactive UI updates. It benefits developers working with Turso, Next.js, and Supabase Auth.","zh":"信号状态管理是一种用于管理客户端应用程序状态的技术，支持reactive UI更新和computed值","ja":"シグナルステート管理は、クライアントサイドアプリケーションの状態を管理するためのテクノロジーで、reactive UI更新とcomputed値をサポートする","ko":"신호 상태 관리는 클라이언트 측 애플리케이션 상태를 관리하기 위한 기술로 reactive UI 업데이트 및 계산된 값을 지원합니다","es":"Signal State Management es una técnica para gestionar el estado de las aplicaciones reactivas, permitiendo actualizaciones de interfaz de usuario eficientes y computadas","fr":"La gestion d''état de signal est une technique pour gérer l''état des applications réactives, permettant des mises à jour d''interface utilisateur efficaces et calculées","de":"Signal State Management ist eine Technik zur Verwaltung des Zustands reaktiver Anwendungen, ermöglicht effiziente Benutzeroberflächen-Aktualisierungen und berechnete Werte","pt":"O gerenciamento de estado de sinal é uma técnica para gerenciar o estado do cliente com Turso, Next.js e Supabase Auth","ru":"Управление состоянием сигнала - это техника для управления состоянием клиента с помощью Turso, Next.js и Supabase Auth","ar":"إدارة حالة الإشارة هي تقنية لإدارة حالة العميل مع Turso و Next.js و Supabase Auth"},"seo":{"title":{"en":"Signal-State-Management: Reactive UI Updates for AI Agent...","zh":"信号状态管理Setup Guide","ja":"シグナルステート管理ベストプラクティス","ko":"신호 상태 관리 설정 가이드","es":"Guía de configuración de Signal State Management para apl...","fr":"Guide de mise en œuvre de la gestion d''état de signal pou...","de":"Einrichtungsleitfaden für Signal State Management in reak...","pt":"Guia de Configuração de Gerenciamento de Estado de Sinal","ru":"Настройка ИИ Агентов: Управление Состоянием Сигнала","ar":"إعداد أداة الإدارة الحكومية لإشارات الحالة"},"description":{"en":"Unlock efficient state management with signal-state-management. Learn how to integrate signals with React components and optimize re-renders. Get started now!","zh":"了解信号状态管理的技术细节，优化客户端应用程序状态管理","ja":"シグナルステート管理のテクニカルな詳細を学び、クライアントサイドアプリケーションの状態管理を最適化する","ko":"신호 상태 관리의 기술적인 세부 사항을 배우고 클라이언트 측 애플리케이션 상태 관리를 최적화하세요","es":"Aprende a implementar Signal State Management en tus aplicaciones con Turso, Next.js y Supabase Auth para una gestión de estado eficiente","fr":"Découvrez comment mettre en œuvre la gestion d''état de signal dans vos applications avec Turso, Next.js et Supabase Auth pour une gestion d''état efficace","de":"Erfahren Sie, wie Sie Signal State Management in Ihren Anwendungen mit Turso, Next.js und Supabase Auth für eine effiziente Zustandsverwaltung implementieren","pt":"Aprenda a gerenciar o estado do cliente com Turso, Next.js e Supabase Auth para criar atualizações de UI reativas","ru":"Узнайте, как управлять состоянием клиента с помощью Turso, Next.js и Supabase Auth для создания реактивных обновлений UI","ar":"تعرف على كيفية إدارة حالة العميل مع Turso و Next.js و Supabase Auth لإنشاء تحديثات واجهة المستخدم تفاعلية"},"definition":{"en":"signal-state-management is a technique for managing mutable state and computed values in client-side applications using signals.","zh":"信号状态管理是一种用于管理客户端应用程序状态的技术","ja":"シグナルステート管理は、クライアントサイドアプリケーションの状態を管理するためのテクノロジー","ko":"신호 상태 관리는 클라이언트 측 애플리케이션 상태를 관리하기 위한 기술","es":"Signal State Management es una técnica de gestión de estado que utiliza señales para actualizar la interfaz de usuario de manera eficiente","fr":"La gestion d''état de signal est une technique de gestion d''état qui utilise des signaux pour mettre à jour l''interface utilisateur de manière efficace","de":"Signal State Management ist eine Zustandsverwaltungstechnik, die Signale verwendet, um die Benutzeroberfläche effizient zu aktualisieren","pt":"Gerenciamento de estado de sinal é uma técnica para gerenciar o estado do cliente","ru":"Управление состоянием сигнала - это техника для управления состоянием клиента","ar":"إدارة حالة الإشارة هي تقنية لإدارة حالة العميل"},"features":{"en":["Manages client-side application state using simple signals","Creates reactive UI updates with computed signals","Batches state updates for performance optimization","Organizes state by domain using boards, posts, and members","Integrates signals with React components for efficient rendering","Optimizes re-renders using Turso and Supabase Auth"],"zh":["支持reactive UI更新","实现computed值","批量状态更新以提高性能","按照域组织状态（板块、帖子、成员）","将信号集成到React组件中","优化重新渲染"],"ja":["reactive UI更新をサポート","computed値を実装","状態更新をバッチ処理してパフォーマンスを向上","状態をドメイン別に整理（ボード、ポスト、メンバー）","シグナルをReactコンポーネントに統合","再描画を最適化"],"ko":["reactive UI 업데이트 지원","계산된 값 구현","상태 업데이트를 일괄 처리하여 성능 향상","상태를 도메인별로 정리（보드, 포스트, 멤버）","신호를 React 컴포넌트에 통합","重新 렌더링 최적화"],"es":["Gestión de estado de cliente con Turso","Actualizaciones de interfaz de usuario reactivas con Next.js","Autenticación con Supabase Auth","Valores computados para una gestión de estado eficiente","Actualizaciones de estado por lotes para mejorar el rendimiento","Organización de estado por dominio para una mejor escalabilidad"],"fr":["Gestion d''état de client avec Turso","Mises à jour d''interface utilisateur réactives avec Next.js","Authentification avec Supabase Auth","Valeurs calculées pour une gestion d''état efficace","Mises à jour d''état par lots pour améliorer les performances","Organisation de l''état par domaine pour une meilleure évolutivité"],"de":["Client-Seitige Zustandsverwaltung mit Turso","Reaktive Benutzeroberflächen-Aktualisierungen mit Next.js","Authentifizierung mit Supabase Auth","Berechnete Werte für eine effiziente Zustandsverwaltung","Zustands-Aktualisierungen in Batches für verbesserte Leistung","Zustands-Organisation nach Domänen für eine bessere Skalierbarkeit"],"pt":["Gerenciamento de estado do cliente com Turso","Criação de atualizações de UI reativas com Next.js","Integração com Supabase Auth","Gerenciamento de estado por domínio","Otimização de re-renders"],"ru":["Управление состоянием клиента с помощью Turso","Создание реактивных обновлений UI с помощью Next.js","Интеграция с Supabase Auth","Управление состоянием по домену","Оптимизация переотрисовки"],"ar":["إدارة حالة العميل مع Turso","إنشاء تحديثات واجهة المستخدم تفاعلية مع Next.js","التكامل مع Supabase Auth","إدارة حالة العميل حسب المجال","تحسين إعادة التصيير"]},"keywords":{"en":["how to use signal-state-management","what is signal-state-management","signal-state-management vs react state","signal-state-management install","signal-state-management setup guide","reactive ui updates with signal-state-management","turso and supabase auth integration","signal-state-management alternative","signal-state-management and next.js"],"zh":["信号状态管理","客户端应用程序状态管理","reactive UI更新","computed值","状态更新","AIエージェント","信号状态管理Setup Guide"],"ja":["シグナルステート管理","クライアントサイドアプリケーションの状態管理","reactive UI更新","computed値","状態更新","AIエージェント","シグナルステート管理ベストプラクティス"],"ko":["신호 상태 관리","클라이언트 측 애플리케이션 상태 관리","reactive UI 업데이트","계산된 값","상태 업데이트","AI 도구","신호 상태 관리 설정 가이드"],"es":["Signal State Management","gestión de estado de cliente","Turso","Next.js","Supabase Auth","valores computados","actualizaciones de estado por lotes","organización de estado por dominio","aplicaciones reactivas","Herramientas de AI para desarrolladores"],"fr":["Gestion d''état de signal","gestion d''état de client","Turso","Next.js","Supabase Auth","valeurs calculées","mises à jour d''état par lots","organisation de l''état par domaine","applications réactives","Outils d''IA pour les développeurs"],"de":["Signal State Management","Client-Seitige Zustandsverwaltung","Turso","Next.js","Supabase Auth","berechnete Werte","Zustands-Aktualisierungen in Batches","Zustands-Organisation nach Domänen","reaktive Anwendungen","KI-Tools für Entwickler"],"pt":["gerenciamento de estado de sinal","turso","next.js","supabase auth","estado do cliente","atualizações de ui reativas","integração com supabase auth"],"ru":["управление состоянием сигнала","turso","next.js","supabase auth","состояние клиента","реактивные обновления ui","интеграция с supabase auth"],"ar":["إدارة حالة الإشارة","turso","next.js","supabase auth","حالة العميل","تحديثات واجهة المستخدم تفاعلية","التكامل مع supabase auth"]}},"owner":"DW225","repo":"ree-board","repoPath":"DW225/ree-board","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.304Z","topics":[],"category":"community","skillMd":{"name":"signal-state-management","description":"Preact Signals for reactive state management, signal vs computed signal usage, batch updates for performance, action creator patterns, signal integration with React components, state management by domain (boards posts members), reactive patterns, and signal best practices for ree-board project","bodyPreview":"# Signal State Management\n\n## When to Use This Skill\n\nActivate this skill when working on:\n\n- Managing client-side application state\n- Creating reactive UI updates\n- Implementing computed values\n- Batching state updates for performance\n- Organizing state by domain (boards, posts, members)\n- Integrating signals with React components\n- Optimizing re-renders\n\n## Core Patterns\n\n### Signal vs Computed Signal\n\n**Simple Signal:** Holds mutable state\n\n```typescript\nimport { signal } from \"@preact/signal","body":"# Signal State Management\n\n## When to Use This Skill\n\nActivate this skill when working on:\n\n- Managing client-side application state\n- Creating reactive UI updates\n- Implementing computed values\n- Batching state updates for performance\n- Organizing state by domain (boards, posts, members)\n- Integrating signals with React components\n- Optimizing re-renders\n\n## Core Patterns\n\n### Signal vs Computed Signal\n\n**Simple Signal:** Holds mutable state\n\n```typescript\nimport { signal } from \"@preact/signals-react\";\n\n// ✅ Simple signal for primitive values\nexport const currentBoardId = signal<string | null>(null);\n\n// ✅ Simple signal for complex state\nexport const postsSignal = signal<Post[]>([]);\n```\n\n**Computed Signal:** Derives value from other signals\n\n```typescript\nimport { signal, computed } from \"@preact/signals-react\";\n\nexport const postsSignal = signal<Post[]>([]);\nexport const filterSignal = signal<PostFilter>(\"all\");\n\n// ✅ Computed signal automatically updates\nexport const filteredPosts = computed(() => {\n  const posts = postsSignal.value;\n  const filter = filterSignal.value;\n\n  if (filter === \"all\") return posts;\n  return posts.filter((p) => p.type === filter);\n});\n```\n\n### State Organization by Domain\n\n**Separate Files for Each Domain:**\n\n```typescript\n// lib/signal/postSignals.ts\nimport { signal, computed } from \"@preact/signals-react\";\n\n// State\nexport const postsSignal = signal<Post[]>([]);\nexport const selectedPostId = signal<string | null>(null);\n\n// Computed values\nexport const selectedPost = computed(() => {\n  const id = selectedPostId.value;\n  if (!id) return null;\n  return postsSignal.value.find((p) => p.id === id);\n});\n\nexport const postsByType = computed(() => {\n  const posts = postsSignal.value;\n  return {\n    wentWell: posts.filter((p) => p.type === \"went_well\"),\n    toImprove: posts.filter((p) => p.type === \"to_improve\"),\n    actionItems: posts.filter((p) => p.type === \"action_items\"),\n  };\n});\n\n// Actions\nexport const addPost = (post: Post) => {\n  postsSignal.value = [...postsSignal.value, post];\n};\n\nexport const updatePost = (id: string, updates: Partial<Post>) => {\n  postsSignal.value = postsSignal.value.map((p) =>\n    p.id === id ? { ...p, ...updates } : p\n  );\n};\n\nexport const deletePost = (id: string) => {\n  postsSignal.value = postsSignal.value.filter((p) => p.id !== id);\n};\n```\n\n### Action Creator Pattern\n\n**Encapsulate State Updates:**\n\n```typescript\n// lib/signal/boardSignals.ts\nimport { signal } from \"@preact/signals-react\";\n\nexport const boardsSignal = signal<Board[]>([]);\nexport const loadingSignal = signal<boolean>(false);\nexport const errorSignal = signal<string | null>(null);\n\n// ✅ Action creators for complex operations\nexport const loadBoards = async () => {\n  loadingSignal.value = true;\n  errorSignal.value = null;\n\n  try {\n    const boards = await fetchBoards();\n    boardsSignal.value = boards;\n  } catch (error) {\n    errorSignal.value = \"Failed to load boards\";\n    console.error(error);\n  } finally {\n    loadingSignal.value = false;\n  }\n};\n\nexport const createBoard = async (name: string) => {\n  try {\n    const newBoard = await createBoardAction(name);\n    // Optimistic update\n    boardsSignal.value = [...boardsSignal.value, newBoard];\n    return newBoard;\n  } catch (error) {\n    errorSignal.value = \"Failed to create board\";\n    throw error;\n  }\n};\n```\n\n### Batch Updates for Performance\n\n**Update Multiple Signals Together:**\n\n```typescript\nimport { batch } from \"@preact/signals-react\";\n\n// ❌ Bad: Triggers 3 re-renders\nconst updateBoard = (id: string, data: BoardUpdate) => {\n  boardsSignal.value = updateBoardList(id, data);\n  selectedBoardId.value = id;\n  lastUpdatedSignal.value = Date.now();\n};\n\n// ✅ Good: Triggers 1 re-render\nconst updateBoard = (id: string, data: BoardUpdate) => {\n  batch(() => {\n    boardsSignal.value = updateBoardList(id, data);\n    selectedBoardId.value = id;\n    lastUpdatedSignal.value = Date.now();\n  });\n};\n```\n\n### Integration with React Components\n\n**Reading Signals:**\n\n```typescript\n\"use client\";\n\nimport { postsSignal, filteredPosts } from \"@/lib/signal/postSignals\";\n\nexport function PostList() {\n  // ✅ Component re-renders when signal changes\n  const posts = filteredPosts.value;\n\n  return (\n    <div>\n      {posts.map((post) => (\n        <PostCard key={post.id} post={post} />\n      ))}\n    </div>\n  );\n}\n```\n\n**Updating Signals:**\n\n```typescript\n\"use client\";\n\nimport { updatePost } from \"@/lib/signal/postSignals\";\n\nexport function EditPostForm({ postId }: { postId: string }) {\n  const handleSubmit = (content: string) => {\n    // ✅ Update signal\n    updatePost(postId, { content });\n\n    // Persist to database\n    updatePostAction(postId, content);\n  };\n\n  return <form onSubmit={handleSubmit}>...</form>;\n}\n```\n\n### Combining Signals with Server Actions\n\n**Pattern:** Update signal first (optimistic), then persist\n\n```typescript\n\"use client\";\n\nimport { addPost, deletePost } from \"@/lib/signal/postSignals\";\nimport { createPost as createPostAction } from \"@/lib/actions/post/createPost\";\n\nexport function CreatePostButton({ boardId }: { boardId: string }) {\n  const handleCreate = async () => {\n    // Create temporary post for optimistic UI\n    const tempPost: Post = {\n      id: `temp-${Date.now()}`,\n      boardId,\n      content: \"\",\n      type: \"went_well\",\n      createdAt: new Date(),\n    };\n\n    // ✅ Optimistic update\n    addPost(tempPost);\n\n    try {\n      // Persist to database\n      const savedPost = await createPostAction(boardId, \"\", \"went_well\");\n\n      // Replace temp with real post\n      deletePost(tempPost.id);\n      addPost(savedPost);\n    } catch (error) {\n      // Rollback on error\n      deletePost(tempPost.id);\n      showError(\"Failed to create post\");\n    }\n  };\n\n  return <button onClick={handleCreate}>Create Post</button>;\n}\n```\n\n### Signal Performance Patterns\n\n**Avoid Unnecessary Signal Subscriptions:**\n\n```typescript\n// ❌ Bad: Creates new computed signal on every render\nfunction PostCount() {\n  const count = computed(() => postsSignal.value.length);\n  return <div>{count.value}</div>;\n}\n\n// ✅ Good: Computed signal defined once outside component\nconst postCount = computed(() => postsSignal.value.length);\n\nfunction PostCount() {\n  return <div>{postCount.value}</div>;\n}\n```\n\n**Use Signal Peeking for Non-Reactive Reads:**\n\n```typescript\nimport { postsSignal } from \"@/lib/signal/postSignals\";\n\nfunction logCurrentPosts() {\n  // ✅ Read without subscribing (doesn''t trigger re-render)\n  console.log(\"Current posts:\", postsSignal.peek());\n}\n```\n\n## Anti-Patterns\n\n### ❌ Mutating Signal Values Directly\n\n**Bad:**\n\n```typescript\n// ❌ Never mutate signal values directly\npostsSignal.value.push(newPost);\n```\n\n**Good:**\n\n```typescript\n// ✅ Create new array\npostsSignal.value = [...postsSignal.value, newPost];\n```\n\n### ❌ Creating Signals Inside Components\n\n**Bad:**\n\n```typescript\nfunction MyComponent() {\n  // ❌ Creates new signal on every render\n  const localSignal = signal(0);\n  return <div>{localSignal.value}</div>;\n}\n```\n\n**Good:**\n\n```typescript\n// ✅ Define signals outside components\nconst counterSignal = signal(0);\n\nfunction MyComponent() {\n  return <div>{counterSignal.value}</div>;\n}\n```\n\n### ❌ Not Using Batch for Multiple Updates\n\n**Bad:**\n\n```typescript\n// ❌ Triggers 3 re-renders\nconst resetFilters = () => {\n  filterSignal.value = \"all\";\n  sortSignal.value = \"date\";\n  searchSignal.value = \"\";\n};\n```\n\n**Good:**\n\n```typescript\n// ✅ Triggers 1 re-render\nimport { batch } from \"@preact/signals-react\";\n\nconst resetFilters = () => {\n  batch(() => {\n    filterSignal.value = \"all\";\n    sortSignal.value = \"date\";\n    searchSignal.value = \"\";\n  });\n};\n```\n\n### ❌ Forgetting .value Accessor\n\n**Bad:**\n\n```typescript\n// ❌ Comparing signal object, not value\nif (currentBoardId === \"board-123\") {\n  // This will never be true\n}\n```\n\n**Good:**\n\n```typescript\n// ✅ Access signal value\nif (currentBoardId.value === \"board-123\") {\n  // Correct comparison\n}\n```\n\n## Integration with Other Skills\n\n- **[nextjs-app-router](../nextjs-app-router/SKILL.md):** Signals used in client components\n- **[ably-realtime](../ably-realtime/SKILL.md):** Update signals from real-time messages\n- **[drizzle-patterns](../drizzle-patterns/SKILL.md):** Sync signals with database state\n- **[testing-patterns](../testing-patterns/SKILL.md):** Reset signals in test setup\n\n## Project-Specific Context\n\n### Key Files\n\n- `lib/signal/boardSignals.ts` - Board listing and management\n- `lib/signal/postSignals.ts` - Post state within boards\n- `lib/signal/memberSignals.ts` - Board member management\n- `components/board/PostProvider.tsx` - Signal updates from real-time\n\n### Domain-Specific Signals\n\n**Board Management:**\n\n```typescript\n// lib/signal/boardSignals.ts\nexport const boardsSignal = signal<Board[]>([]);\nexport const currentBoardId = signal<string | null>(null);\nexport const currentBoard = computed(() =>\n  boardsSignal.value.find((b) => b.id === currentBoardId.value)\n);\n```\n\n**Post Management:**\n\n```typescript\n// lib/signal/postSignals.ts\nexport const postsSignal = signal<Post[]>([]);\nexport const postFilter = signal<PostType | \"all\">(\"all\");\nexport const filteredPosts = computed(() => {\n  const filter = postFilter.value;\n  if (filter === \"all\") return postsSignal.value;\n  return postsSignal.value.filter((p) => p.type === filter);\n});\n```\n\n**Member Management:**\n\n```typescript\n// lib/signal/memberSignals.ts\nexport const membersSignal = signal<Member[]>([]);\nexport const currentUserRole = computed(() => {\n  const members = membersSignal.value;\n  const userId = currentUserId.value;\n  return members.find((m) => m.userId === userId)?.role || \"guest\";\n});\n```\n\n### Real-Time Integration\n\n**Update Signals from Ably Messages:**\n\n```typescript\n// components/board/PostProvider.tsx\nuseChannel(`board:${boardId}`, (message) => {\n  switch (message.name) {\n    case \"post:create\":\n      addPost(message.data);\n      break;\n\n    case \"post:update\":\n      updatePost(message.data.id, message.data);\n      break;\n\n    case \"post:delete\":\n      deletePost(message.data.id);\n      break;\n  }\n});\n```\n\n### Testing Signals\n\n**Reset Signals in beforeEach:**\n\n```typescript\nimport { postsSignal, filterSignal } from \"@/lib/signal/postSignals\";\n\nbeforeEach(() => {\n  postsSignal.value = [];\n  filterSignal.value = \"all\";\n});\n\ntest(\"filters posts by type\", () => {\n  postsSignal.value = [\n    { id: \"1\", type: \"went_well\", content: \"Test\" },\n    { id: \"2\", type: \"to_improve\", content: \"Test\" },\n  ];\n\n  filterSignal.value = \"went_well\";\n  expect(filteredPosts.value).toHaveLength(1);\n});\n```\n\n---\n\n**Last Updated:** 2026-01-10\n"},"lastSynced":"2026-03-08T02:01:58.407Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring advanced state management and reactive UI updates in Turso, Next.js, and Supabase Auth applications.","zh":"适用于需要高级状态管理和响应式 UI 更新的 Turso、Next.js 和 Supabase Auth 前端代理。","ja":"Turso、Next.js、Supabase Auth アプリケーションで高度な状態管理とリアクティブ UI 更新を必要とするフロントエンド エージェントに最適です。","ko":"Turso, Next.js, Supabase Auth 애플리케이션에서 고급 상태 관리 및 반응형 UI 업데이트 기능이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Ideal para Agentes Frontend que requieren gestión de estado avanzada y actualizaciones de interfaz de usuario reactivas en aplicaciones Turso, Next.js y Supabase Auth.","fr":"Idéal pour les agents Frontend nécessitant une gestion d''état avancée et des mises à jour d''interface utilisateur réactives dans les applications Turso, Next.js et Supabase Auth.","de":"Ideal für Frontend-Agents, die eine erweiterte Zustandsverwaltung und reaktive Benutzeroberflächen-Aktualisierungen in Turso-, Next.js- und Supabase-Auth-Anwendungen benötigen.","pt":"Ideal para Agentes Frontend que exigem gerenciamento de estado avançado e atualizações de UI reativas em aplicações Turso, Next.js e Supabase Auth.","ru":"Идеально подходит для агентов Frontend, требующих продвинутого управления состоянием и реактивных обновлений UI в приложениях Turso, Next.js и Supabase Auth.","ar":"مثالي للوكلاء الأماميين الذين يتطلبون إدارة حالة متقدمة وتحديثات واجهة المستخدم التفاعلية في تطبيقات Turso و Next.js و Supabase Auth."},"recommendation":{"en":"Empowers agents to manage client-side application state, create reactive UI updates, and optimize re-renders using signals and computed values with libraries like @preact/signal, leveraging protocols such as reactive state updates and batching for performance.","zh":"赋予代理管理客户端应用程序状态、创建响应式 UI 更新和使用信号和计算值优化重新渲染的能力，利用类似 @preact/signal 的库，并依赖诸如响应式状态更新和批处理等协议以提高性能。","ja":"エージェントがクライアントサイドアプリケーションの状態を管理し、リアクティブ UI 更新を作成し、シグナルと計算値を使用して再描画を最適化する機能を提供し、@preact/signal などのライブラリを活用し、パフォーマンスの向上のためにリアクティブ状態更新やバッチングなどのプロトコルを利用します。","ko":"에이전트가 클라이언트 측 애플리케이션 상태를 관리하고 반응형 UI 업데이트를 생성하며 신호 및 계산된 값을 사용하여 다시 렌더링을 최적화할 수 있는 기능을 제공하며 @preact/signal과 같은 라이브러리를 사용하며 성능을 개선하기 위해 반응형 상태 업데이트와 배치 처리 등의 프로토콜을 활용합니다.","es":"Permite a los agentes gestionar el estado de la aplicación del lado del cliente, crear actualizaciones de interfaz de usuario reactivas y optimizar las nuevas representaciones utilizando señales y valores calculados con bibliotecas como @preact/signal, aprovechando protocolos como actualizaciones de estado reactivas y lotes para el rendimiento.","fr":"Permet aux agents de gérer l''état de l''application côté client, de créer des mises à jour d''interface utilisateur réactives et d''optimiser les re-rendus en utilisant des signaux et des valeurs calculées avec des bibliothèques comme @preact/signal, en exploitant des protocoles tels que les mises à jour d''état réactives et le batch pour les performances.","de":"Ermöglicht es Agenten, den Zustand der Client-Anwendung zu verwalten, reaktive Benutzeroberflächen-Aktualisierungen zu erstellen und Neuzeichnungen mit Hilfe von Signalen und berechneten Werten mit Bibliotheken wie @preact/signal zu optimieren, wobei Protokolle wie reaktive Zustandsaktualisierungen und Batchverarbeitung für die Leistung genutzt werden.","pt":"Habilita os agentes a gerenciar o estado do aplicativo no lado do cliente, criar atualizações de UI reativas e otimizar re-renderizações usando sinais e valores computados com bibliotecas como @preact/signal, aproveitando protocolos como atualizações de estado reativas e batch para desempenho.","ru":"Позволяет агентам управлять состоянием приложения на стороне клиента, создавать реактивные обновления UI и оптимизировать повторную отрисовку с помощью сигналов и вычисляемых значений с использованием библиотек seperti @preact/signal, используя протоколы like реактивные обновления состояния и пакетирование для производительности.","ar":"تمكين الوكلاء من إدارة حالة التطبيق على جانب العميل، وخلق تحديثات واجهة المستخدم التفاعلية وتحسين إعادة التصيير باستخدام الإشارات والقيم المحسوبة مع المكتبات مثل @preact/signal، واستخدام بروتوكولات مثل تحديثات الحالة التفاعلية والتحزيم للأداء."},"useCases":{"en":["Implementing computed values for dynamic UI updates","Batching state updates for improved application performance","Organizing state by domain for enhanced data management"],"zh":["为动态 UI 更新实现计算值","批量状态更新以提高应用程序性能","按领域组织状态以增强数据管理"],"ja":["動的 UI 更新のための計算値の実装","バッチ状態更新によるアプリケーションのパフォーマンスの向上","ドメイン別の状態の組織化によるデータ管理の強化"],"ko":["동적 UI 업데이트를 위한 계산된 값의 구현","배치 상태 업데이트를 통한 애플리케이션 성능 개선","도메인별 상태의 조직화를 통한 데이터 관리 강화"],"es":["Implementar valores calculados para actualizaciones de interfaz de usuario dinámicas","Lotes de actualizaciones de estado para una mejor experiencia de la aplicación","Organizar el estado por dominio para una mejor gestión de datos"],"fr":["Mettre en œuvre des valeurs calculées pour des mises à jour d''interface utilisateur dynamiques","Lot de mises à jour d''état pour améliorer les performances de l''application","Organiser l''état par domaine pour une meilleure gestion des données"],"de":["Implementieren von berechneten Werten für dynamische Benutzeroberflächen-Aktualisierungen","Batchen von Zustandsaktualisierungen für eine verbesserte Anwendungsleistung","Organisieren des Zustands nach Domäne für eine verbesserte Datenverwaltung"],"pt":["Implementar valores computados para atualizações de UI dinâmicas","Fazer batch de atualizações de estado para melhoria do desempenho do aplicativo","Organizar estado por domínio para gerenciamento de dados aprimorado"],"ru":["Реализовать вычисляемые значения для динамических обновлений UI","Пакетировать обновления состояния для улучшения производительности приложения","Организовать состояние по домену для улучшения управления данными"],"ar":["تنفيذ قيم محسوبة لتحديثات واجهة المستخدم الديناميكية","تحزيم تحديثات الحالة لتحسين أداء التطبيق","تنظيم الحالة حسب النطاق لتحسين إدارة البيانات"]},"limitations":{"en":["Requires knowledge of client-side state management","Specific to Turso, Next.js, and Supabase Auth applications","Dependent on @preact/signal library"],"zh":["需要客户端状态管理的知识","特定于 Turso、Next.js 和 Supabase Auth 应用程序","依赖 @preact/signal 库"],"ja":["クライアントサイド状態管理の知識が必要","Turso、Next.js、Supabase Auth アプリケーションに特有","@preact/signal ライブラリに依存"],"ko":["클라이언트 측 상태 관리에 대한 지식이 필요합니다.","Turso, Next.js, Supabase Auth 애플리케이션에 특정","@preact/signal 라이브러리에 의존"],"es":["Requiere conocimiento de la gestión de estado del lado del cliente","Específico para aplicaciones Turso, Next.js y Supabase Auth","Dependiente de la biblioteca @preact/signal"],"fr":["Nécessite des connaissances en matière de gestion d''état côté client","Spécifique aux applications Turso, Next.js et Supabase Auth","Dépendant de la bibliothèque @preact/signal"],"de":["Benötigt Kenntnisse über die Client-seitige Zustandsverwaltung","Spezifisch für Turso-, Next.js- und Supabase-Auth-Anwendungen","Abhängig von der Bibliothek @preact/signal"],"pt":["Exige conhecimento de gerenciamento de estado no lado do cliente","Específico para aplicações Turso, Next.js e Supabase Auth","Dependente da biblioteca @preact/signal"],"ru":["Требует знаний управления состоянием на стороне клиента","Специфичен для приложений Turso, Next.js и Supabase Auth","Зависит от библиотеки @preact/signal"],"ar":["يتطلب معرفة بإدارة حالة جانب العميل","محدد لتطبيقات Turso و Next.js و Supabase Auth","يعتمد على مكتبة @preact/signal"]},"version":4},"contentHash":"983fb9eacda7d8731f760c7fed42bfec26c210acfaf34d33250010d739ef8830","qualityScore":51}');
