INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DW225/ree-board/signal-state-management', 'signal-state-management', 'DW225', 'ree-board', 'community', 'signal-state-management DW225 ree-board community Signal-state-management is a skill for managing client-side application state and creating reactive UI updates. It benefits developers working with Turso, Next.js, and Supabase Auth. 信号状态管理是一种用于管理客户端应用程序状态的技术，支持reactive UI更新和computed值 シグナルステート管理は、クライアントサイドアプリケーションの状態を管理するためのテクノロジーで、reactive UI更新とcomputed値をサポートする 신호 상태 관리는 클라이언트 측 애플리케이션 상태를 관리하기 위한 기술로 reactive UI 업데이트 및 계산된 값을 지원합니다 Signal State Management es una técnica para gestionar el estado de las aplicaciones reactivas, permitiendo actualizaciones de interfaz de usuario eficientes y computadas La gestion d''état de signal est une technique pour gérer l''état des applications réactives, permettant des mises à jour d''interface utilisateur efficaces et calculées Signal State Management ist eine Technik zur Verwaltung des Zustands reaktiver Anwendungen, ermöglicht effiziente Benutzeroberflächen-Aktualisierungen und berechnete Werte O gerenciamento de estado de sinal é uma técnica para gerenciar o estado do cliente com Turso, Next.js e Supabase Auth Управление состоянием сигнала - это техника для управления состоянием клиента с помощью Turso, Next.js и Supabase Auth إدارة حالة الإشارة هي تقنية لإدارة حالة العميل مع Turso و Next.js و Supabase Auth how to use signal-state-management what is signal-state-management signal-state-management vs react state signal-state-management install signal-state-management setup guide reactive ui updates with signal-state-management turso and supabase auth integration signal-state-management alternative signal-state-management and next.js 信号状态管理 客户端应用程序状态管理 reactive UI更新 computed值 状态更新 AIエージェント 信号状态管理Setup Guide Manages client-side application state using simple signals Creates reactive UI updates with computed signals Batches state updates for performance optimization Organizes state by domain using boards, posts, and members Integrates signals with React components for efficient rendering Optimizes re-renders using Turso and Supabase Auth signal-state-management is a technique for managing mutable state and computed values in client-side applications using signals.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Maple-and-Spruce/maple-and-spruce/local-development', 'community', 'Maple-and-Spruce', 'maple-and-spruce', 'Maple-and-Spruce/maple-and-spruce', 'local-development', 0, 0, 51, '2026-03-08T01:57:15.302Z', '2026-03-08T02:02:17.294Z', '2a32b942d95e1813d6ad7fe66a5aae42f3ee986e70c41a3f4833d8576ae467ec', '{"id":"Maple-and-Spruce/maple-and-spruce/local-development","name":"local-development","description":{"en":"The local-development skill enables users to run functions and web apps locally for testing purposes. It supports commands like `npx nx run functions:serve` for building and serving functions.","zh":"本地开发环境允许用户在本地运行函数和 Web 应用，调试模拟器问题，运行 Storybook。使用 Claude AI Agent 搭建本地开发环境","ja":"ローカル開発環境では、ユーザーが関数と Web アプリをローカルで実行し、エミュレータの問題をデバッグし、Storybook を実行できます。Claude AIエージェントを使用してローカル開発環境をセットアップします","ko":"로컬 개발 환경을 통해 사용자는 로컬에서 함수 및 웹 애플리케이션을 실행하고 에뮬레이터 문제를 디버깅하며 Storybook을 실행할 수 있습니다. Claude AI 에이전트를 사용하여 로컬 개발 환경을 설정합니다","es":"El desarrollo local con AI Agent permite probar y depurar aplicaciones web y funciones de manera efectiva utilizando comandos como `npx nx run functions:serve`","fr":"Le développement local avec Outil IA permet de tester et de déboguer les applications web et les fonctions de manière efficace en utilisant des commandes comme `npx nx run functions:serve`","de":"Die lokale Entwicklung mit KI-Tool ermöglicht es, Webanwendungen und Funktionen effektiv zu testen und zu debuggen, indem Sie Befehle wie `npx nx run functions:serve` verwenden","pt":"O desenvolvimento local permite testar e depurar aplicações web e funções de forma eficiente","ru":"Местное развитие позволяет тестировать и отлаживать веб-приложения и функции эффективно","ar":"التطوير المحلي يسمح باختبار وتحديد الأخطاء في التطبيقات الويب والوظائف بفعالية"},"seo":{"title":{"en":"Local-Development: Setup Guide for AI Agents | AI Agent S...","zh":"本地开发环境搭建指南 - Claude AI Agent","ja":"ローカル開発環境のセットアップガイド - Claude AIエージェント","ko":"로컬 개발 환경 설정 가이드 - Claude AI 에이전트","es":"Guía de configuración de desarrollo local con AI Agent","fr":"Guide de mise en place du développement local avec Outil IA","de":"Einrichtungsleitfaden für lokale Entwicklung mit KI-Tool","pt":"Guia de Configuração de Desenvolvimento Local com Ferrame...","ru":"Настройка Местного Развития с ИИ Агентами","ar":"إعداد التطوير المحلي مع أدوات الإي الأجنت"},"description":{"en":"Discover how to run functions and web apps locally with the local-development skill. Learn how to troubleshoot emulator issues and get started with Storybook...","zh":"了解如何使用 Claude AI Agent 搭建本地开发环境，运行函数和 Web 应用，调试模拟器问题，运行 Storybook","ja":"Claude AIエージェントを使用してローカル開発環境をセットアップし、関数と Web アプリを実行し、エミュレータの問題をデバッグし、Storybook を実行する方法を学びます","ko":"Claude AI 에이전트를 사용하여 로컬 개발 환경을 설정하고 함수 및 웹 애플리케이션을 실행하며 에뮬레이터 문제를 디버깅하며 Storybook을 실행하는 방법에 대해 알아보세요","es":"Aprende a configurar el desarrollo local con AI Agent para probar y depurar tus aplicaciones web y funciones de manera efectiva","fr":"Découvrez comment configurer le développement local avec Outil IA pour tester et déboguer vos applications web et fonctions de manière efficace","de":"Erfahren Sie, wie Sie die lokale Entwicklung mit KI-Tool einrichten, um Ihre Webanwendungen und Funktionen effektiv zu testen und zu debuggen","pt":"Aprenda a configurar o desenvolvimento local com ferramentas de IA para testar e depurar aplicações web e funções","ru":"Узнайте, как настроить местное развитие с ИИ агентами для тестирования и отладки веб-приложений и функций","ar":"تعرف على كيفية إعداد التطوير المحلي مع أدوات الإي الأجنت لاختبار وتحديد الأخطاء في التطبيقات الويب والوظائف"},"definition":{"en":"Local-development is a skill that allows users to run and test web apps and functions locally, facilitating troubleshooting and development.","zh":"本地开发环境是指在本地机器上运行和测试应用程序的环境","ja":"ローカル開発環境とは、ローカルマシン上でアプリケーションを実行してテストする環境のこと","ko":"로컬 개발 환경이란 로컬 머신에서 애플리케이션을 실행하고 테스트하는 환경을 말합니다","es":"Desarrollo local es una habilidad de AI Agent que permite a los desarrolladores probar y depurar aplicaciones web y funciones de manera local","fr":"Le développement local est une compétence de l''Outil IA qui permet aux développeurs de tester et de déboguer les applications web et les fonctions de manière locale","de":"Lokale Entwicklung ist eine Fähigkeit von KI-Tool, die es Entwicklern ermöglicht, Webanwendungen und Funktionen lokal zu testen und zu debuggen","pt":"Desenvolvimento local é um processo de testar e depurar aplicações web e funções em um ambiente local","ru":"Местное развитие - это процесс тестирования и отладки веб-приложений и функций в локальной среде","ar":"التطوير المحلي هو عملية اختبار وتحديد الأخطاء في التطبيقات الويب والوظائف في بيئة محلية"},"features":{"en":["Runs functions locally using `npx nx run functions:serve` command","Builds functions and copies `.env.dev` to `dist/apps/functions/.env`","Starts watch mode for real-time updates","Supports Storybook for UI component development","Enables local testing and troubleshooting of web apps","Facilitates development with Nx and Node.js"],"zh":["使用 npx nx run functions:serve 命令运行函数","支持本地运行 Web 应用","调试模拟器问题","运行 Storybook","自动构建函数和复制 .env.dev 文件"],"ja":["npx nx run functions:serve コマンドを使用して関数を実行","ローカルで Web アプリを実行する機能","エミュレータの問題をデバッグ","Storybook を実行","関数の自動ビルドと .env.dev ファイルのコピー"],"ko":["npx nx run functions:serve 명령을 사용하여 함수를 실행","로컬에서 웹 애플리케이션을 실행하는 기능","에뮬레이터 문제를 디버깅","Storybook을 실행","함수의 자동 빌드 및 .env.dev 파일의 복사"],"es":["Ejecución de funciones locales con `npx nx run functions:serve`","Compilación de funciones y copia de `.env.dev` a `dist/apps/functions/.env`","Iniciar el modo de vigilancia para detectar cambios","Depuración de aplicaciones web y funciones de manera local","Integración con Storybook para probar componentes de manera aislada"],"fr":["Exécution de fonctions locales avec `npx nx run functions:serve`","Compilation de fonctions et copie de `.env.dev` à `dist/apps/functions/.env`","Démarrage du mode de surveillance pour détecter les modifications","Débogage d''applications web et de fonctions de manière locale","Intégration avec Storybook pour tester des composants de manière isolée"],"de":["Ausführung von Funktionen lokal mit `npx nx run functions:serve`","Kompilierung von Funktionen und Kopie von `.env.dev` nach `dist/apps/functions/.env`","Starten des Überwachungsmodus zum Erkennen von Änderungen","Debuggen von Webanwendungen und Funktionen lokal","Integration mit Storybook zum Testen von Komponenten isoliert"],"pt":["Execução de funções locais com `npx nx run functions:serve`","Compilação de funções e cópia de `.env.dev` para `dist/apps/functions/.env`","Início do modo de observação com `npx nx run functions:serve`","Teste e depuração de aplicações web e funções em um ambiente local","Utilização de tecnologias como Nx e Storybook"],"ru":["Запуск функций локально с `npx nx run functions:serve`","Компиляция функций и копирование `.env.dev` в `dist/apps/functions/.env`","Запуск режима наблюдения с `npx nx run functions:serve`","Тестирование и отладка веб-приложений и функций в локальной среде","Использование технологий seperti Nx и Storybook"],"ar":["تشغيل الوظائف المحلية مع `npx nx run functions:serve`","مجمع الوظائف ونسخ `.env.dev` إلى `dist/apps/functions/.env`","بدء وضع المراقبة مع `npx nx run functions:serve`","اختبار وتحديد الأخطاء في التطبيقات الويب والوظائف في بيئة محلية","استخدام تقنيات مثل Nx و Storybook"]},"keywords":{"en":["how to use local-development","local-development setup guide","local-development vs docker","what is local-development","local-development install","local-development alternative","local-development troubleshooting","local-development and Storybook","local-development with Nx"],"zh":["本地开发环境","Claude AI Agent","函数运行","Web 应用开发","模拟器调试","Storybook","npx nx run functions:serve","本地开发工具"],"ja":["ローカル開発環境","Claude AIエージェント","関数実行","Web アプリ開発","エミュレータのデバッグ","Storybook","npx nx run functions:serve","ローカル開発ツール"],"ko":["로컬 개발 환경","Claude AI 에이전트","함수 실행","웹 애플리케이션 개발","에뮬레이터 디버깅","Storybook","npx nx run functions:serve","로컬 개발 도구"],"es":["desarrollo local","AI Agent","pruebas locales","depuración de aplicaciones web","Storybook","nx","functions:serve","desarrollo de aplicaciones web","herramientas de desarrollo"],"fr":["développement local","Outil IA","tests locaux","débogage d''applications web","Storybook","nx","functions:serve","développement d''applications web","outils de développement"],"de":["lokale Entwicklung","KI-Tool","lokale Tests","Debuggen von Webanwendungen","Storybook","nx","functions:serve","Webanwendungs-Entwicklung","Entwicklungstools"],"pt":["desenvolvimento local","ferramentas de IA","testar aplicações web","depurar funções","Nx","Storybook","CLI","desenvolvimento de software"],"ru":["местное развитие","ИИ агенты","тестирование веб-приложений","отладка функций","Nx","Storybook","CLI","разработка программного обеспечения"],"ar":["التطوير المحلي","أدوات الإي الأجنت","اختبار التطبيقات الويب","تحديد الأخطاء في الوظائف","Nx","Storybook","CLI","تطوير البرمجيات"]}},"owner":"Maple-and-Spruce","repo":"maple-and-spruce","repoPath":"Maple-and-Spruce/maple-and-spruce","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"local-development","description":"Running functions and web app locally, troubleshooting emulator issues, Storybook. Use when running or debugging locally.","bodyPreview":"# Local Development\n\n## When to Use\n\nUse this skill when running the web app or functions locally, troubleshooting emulator issues, or running Storybook.\n\n## Important\n\nThe user runs functions and web app locally for testing. Claude writes code and creates PRs -- Claude does NOT deploy or run dev servers.\n\n## Running Functions Locally (user runs this)\n\n```bash\npnpm exec nx run functions:serve\n```\n\nThis command:\n1. Builds the functions\n2. Copies `.env.dev` to `dist/apps/functions/.env`\n3. Starts","body":"# Local Development\n\n## When to Use\n\nUse this skill when running the web app or functions locally, troubleshooting emulator issues, or running Storybook.\n\n## Important\n\nThe user runs functions and web app locally for testing. Claude writes code and creates PRs -- Claude does NOT deploy or run dev servers.\n\n## Running Functions Locally (user runs this)\n\n```bash\npnpm exec nx run functions:serve\n```\n\nThis command:\n1. Builds the functions\n2. Copies `.env.dev` to `dist/apps/functions/.env`\n3. Starts watch mode for rebuilds (background)\n4. Runs `firebase serve --only functions --project=dev` on port 5001\n\n## Running Web App Locally (user runs this)\n\n```bash\npnpm exec nx run maple-spruce:serve\n```\n\nRuns on http://localhost:3000\n\n## Running Storybook\n\n```bash\npnpm exec nx run maple-spruce:storybook\n# Opens http://localhost:6006\n```\n\nBuilding Storybook:\n```bash\npnpm exec nx run maple-spruce:build-storybook\n# Output: dist/storybook/maple-spruce\n```\n\n## Running Tests\n\n```bash\npnpm test\n```\n\n## Deployment\n\nUser decides when to deploy to dev. Production deploys automatically via CI/CD on merge to main.\n\n## Troubleshooting Local Functions\n\n### Emulator prompts for environment variables\n\nThe Firebase emulator is not finding the `.env` file. This happens when:\n- The build clears `dist/apps/functions/` before the `.env` is copied\n- A stale watch process is interfering\n\n**Fix:**\n```bash\n# Kill any stale processes\npkill -f \"firebase serve\"\npkill -f \"nx run functions\"\n\n# Clean and restart\nrm -rf dist/apps/functions\npnpm exec nx run functions:serve\n```\n\n**Why this happens:**\n- Firebase reads `.env` from `dist/apps/functions/`\n- The `nx run functions:build` clears this directory\n- The serve command copies `.env.dev` after build, before starting the emulator\n- If ordering is wrong or stale processes exist, the emulator starts without the `.env`\n\n**Key indicator it''s working:**\n```\ni  functions: Loaded environment variables from .env.\n```\n"},"lastSynced":"2026-03-08T02:02:17.294Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents requiring rapid local testing and development of web apps and functions.","zh":"非常适合需要快速本地测试和开发 Web 应用及功能的 Full Stack Agent。","ja":"Web アプリケーションと機能の迅速なローカルテストと開発を必要とする Full Stack Agent に最適です。","ko":"웹 앱 및 기능의 신속한 로컬 테스트와 개발이 필요한 Full Stack Agent에 이상적입니다.","es":"Ideal para agentes Full Stack que requieren pruebas locales rápidas y desarrollo de aplicaciones web y funciones.","fr":"Idéal pour les agents Full Stack nécessitant des tests locaux rapides et le développement d''applications web et de fonctions.","de":"Ideal für Full Stack Agents, die schnelles lokales Testen und die Entwicklung von Web-Apps und Funktionen erfordern.","pt":"Ideal para Agentes Full Stack que requerem testes locais rápidos e desenvolvimento de aplicações web e funções.","ru":"Идеально подходит для Full Stack агентов, которым требуется быстрое локальное тестирование и разработка веб-приложений и функций.","ar":"مثالي لوكلاء Full Stack الذين يتطلبون اختبارًا محليًا سريعًا وتطويرًا لتطبيقات الويب والوظائف."},"recommendation":{"en":"Empowers agents to run functions and web apps locally for testing purposes, utilizing commands like `npx nx run functions:serve` for building and serving functions, and supporting environments like `.env.dev` for development configurations.","zh":"赋能 Agent 在本地运行功能和 Web 应用以进行测试，利用诸如 `npx nx run functions:serve` 之类的命令来构建和服务功能，并支持诸如 `.env.dev` 之类的开发配置环境。","ja":"`npx nx run functions:serve` のようなコマンドを利用して機能のビルドと提供を行い、開発構成のために `.env.dev` のような環境をサポートすることで、テスト目的でエージェントがローカルに関数と Web アプリケーションを実行できるようにします。","ko":"`npx nx run functions:serve`와 같은 명령어를 사용하여 기능을 빌드하고 제공하며, 개발 구성을 위한 `.env.dev`와 같은 환경을 지원하여, 테스트 목적으로 에이전트가 로컬에서 기능과 웹 앱을 실행할 수 있도록 합니다.","es":"Permite a los agentes ejecutar funciones y aplicaciones web localmente con fines de prueba, utilizando comandos como `npx nx run functions:serve` para construir y servir funciones, y admitiendo entornos como `.env.dev` para configuraciones de desarrollo.","fr":"Permet aux agents d''exécuter des fonctions et des applications web localement à des fins de test, en utilisant des commandes comme `npx nx run functions:serve` pour construire et servir des fonctions, et en prenant en charge des environnements tels que `.env.dev` pour les configurations de développement.","de":"Ermöglicht es Agents, Funktionen und Web-Apps lokal für Testzwecke auszuführen, unter Verwendung von Befehlen wie `npx nx run functions:serve` zum Bauen und Servieren von Funktionen, und unterstützt Umgebungen wie `.env.dev` für Entwicklungskonfigurationen.","pt":"Capacita os agentes a executar funções e aplicações web localmente para fins de teste, utilizando comandos como `npx nx run functions:serve` para construir e servir funções, e suportando ambientes como `.env.dev` para configurações de desenvolvimento.","ru":"Позволяет агентам запускать функции и веб-приложения локально в целях тестирования, используя такие команды, как `npx nx run functions:serve` для сборки и запуска функций, а также поддерживая среды, такие как `.env.dev` для конфигураций разработки.","ar":"يمكّن الوكلاء من تشغيل الوظائف وتطبيقات الويب محليًا لأغراض الاختبار، باستخدام أوامر مثل `npx nx run functions:serve` لبناء وخدمة الوظائف، ودعم بيئات مثل `.env.dev` لتكوينات التطوير."},"useCases":{"en":["Debugging emulator issues","Running Storybook for UI component testing","Testing web apps locally before deployment"],"zh":["调试模拟器问题","运行 Storybook 以进行 UI 组件测试","部署前在本地测试 Web 应用"],"ja":["エミュレーターの問題のデバッグ","UI コンポーネントテストのための Storybook の実行","デプロイ前のローカルでの Web アプリケーションのテスト"],"ko":["에뮬레이터 문제 디버깅","UI 컴포넌트 테스트를 위한 Storybook 실행","배포 전 로컬에서 웹 앱 테스트"],"es":["Depuración de problemas del emulador","Ejecución de Storybook para pruebas de componentes de UI","Prueba de aplicaciones web localmente antes de la implementación"],"fr":["Débogage des problèmes de l''émulateur","Exécution de Storybook pour les tests de composants d''interface utilisateur","Test d''applications web localement avant le déploiement"],"de":["Debugging von Emulatorproblemen","Ausführen von Storybook für UI-Komponententests","Lokales Testen von Web-Apps vor dem Deployment"],"pt":["Depuração de problemas do emulador","Execução do Storybook para teste de componentes de UI","Teste de aplicações web localmente antes da implantação"],"ru":["Отладка проблем эмулятора","Запуск Storybook для тестирования компонентов пользовательского интерфейса","Локальное тестирование веб-приложений перед развертыванием"],"ar":["تصحيح مشاكل المحاكي","تشغيل Storybook لاختبار مكونات واجهة المستخدم","اختبار تطبيقات الويب محليًا قبل النشر"]},"limitations":{"en":["Requires local development environment setup","Does not deploy or run dev servers","Limited to local testing and development purposes"],"zh":["需要设置本地开发环境","不部署或运行开发服务器","仅限于本地测试和开发目的"],"ja":["ローカル開発環境のセットアップが必要","開発サーバーをデプロイまたは実行しない","ローカルテストと開発目的に限定される"],"ko":["로컬 개발 환경 설정이 필요함","개발 서버를 배포하거나 실행하지 않음","로컬 테스트 및 개발 목적으로만 제한됨"],"es":["Requiere la configuración de un entorno de desarrollo local","No implementa ni ejecuta servidores de desarrollo","Limitado a propósitos de pruebas y desarrollo local"],"fr":["Nécessite la configuration d''un environnement de développement local","Ne déploie pas ni n''exécute de serveurs de développement","Limité aux tests locaux et aux fins de développement"],"de":["Erfordert die Einrichtung einer lokalen Entwicklungsumgebung","Führt keine Deployments durch und betreibt keine Dev-Server","Beschränkt sich auf lokale Tests und Entwicklungszwecke"],"pt":["Requer configuração do ambiente de desenvolvimento local","Não implanta ou executa servidores de desenvolvimento","Limitado a propósitos de teste e desenvolvimento local"],"ru":["Требует настройки локальной среды разработки","Не развертывает и не запускает dev-серверы","Ограничено целями локального тестирования и разработки"],"ar":["يتطلب إعداد بيئة التطوير المحلية","لا يقوم بنشر أو تشغيل خوادم التطوير","يقتصر على أغراض الاختبار والتطوير المحلي"]},"version":4},"contentHash":"2a32b942d95e1813d6ad7fe66a5aae42f3ee986e70c41a3f4833d8576ae467ec","qualityScore":51}');
