INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Maple-and-Spruce/maple-and-spruce/local-development', 'local-development', 'Maple-and-Spruce', 'maple-and-spruce', 'community', 'local-development Maple-and-Spruce maple-and-spruce community The local-development skill enables users to run functions and web apps locally for testing purposes. It supports commands like `npx nx run functions:serve` for building and serving functions. 本地开发环境允许用户在本地运行函数和 Web 应用，调试模拟器问题，运行 Storybook。使用 Claude AI Agent 搭建本地开发环境 ローカル開発環境では、ユーザーが関数と Web アプリをローカルで実行し、エミュレータの問題をデバッグし、Storybook を実行できます。Claude AIエージェントを使用してローカル開発環境をセットアップします 로컬 개발 환경을 통해 사용자는 로컬에서 함수 및 웹 애플리케이션을 실행하고 에뮬레이터 문제를 디버깅하며 Storybook을 실행할 수 있습니다. Claude AI 에이전트를 사용하여 로컬 개발 환경을 설정합니다 El desarrollo local con AI Agent permite probar y depurar aplicaciones web y funciones de manera efectiva utilizando comandos como `npx nx run functions:serve` Le développement local avec Outil IA permet de tester et de déboguer les applications web et les fonctions de manière efficace en utilisant des commandes comme `npx nx run functions:serve` Die lokale Entwicklung mit KI-Tool ermöglicht es, Webanwendungen und Funktionen effektiv zu testen und zu debuggen, indem Sie Befehle wie `npx nx run functions:serve` verwenden O desenvolvimento local permite testar e depurar aplicações web e funções de forma eficiente Местное развитие позволяет тестировать и отлаживать веб-приложения и функции эффективно التطوير المحلي يسمح باختبار وتحديد الأخطاء في التطبيقات الويب والوظائف بفعالية how to use local-development local-development setup guide local-development vs docker what is local-development local-development install local-development alternative local-development troubleshooting local-development and Storybook local-development with Nx 本地开发环境 Claude AI Agent 函数运行 Web 应用开发 模拟器调试 Storybook npx nx run functions:serve 本地开发工具 Runs functions locally using `npx nx run functions:serve` command Builds functions and copies `.env.dev` to `dist/apps/functions/.env` Starts watch mode for real-time updates Supports Storybook for UI component development Enables local testing and troubleshooting of web apps Facilitates development with Nx and Node.js Local-development is a skill that allows users to run and test web apps and functions locally, facilitating troubleshooting and development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aclinia/torchlight-of-building/adding-mod-parsers', 'community', 'aclinia', 'torchlight-of-building', 'aclinia/torchlight-of-building', 'adding-mod-parsers', 0, 0, 51, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:28.577Z', '7d8ca938f11cca696e75476cc4ae4ae4798fe8194aeb68944fde8c9c3edad642', '{"id":"aclinia/torchlight-of-building/adding-mod-parsers","name":"adding-mod-parsers","description":{"en":"The adding-mod-parsers skill converts raw mod strings into typed Mod objects for calculation engines. It benefits developers working with mod string patterns and variants.","zh":"添加Mod解析器以支持新的模态字符串模式和扩展现有模态类型，使用模板基于的系统进行模式匹配","ja":"AIエージェントのModパーサーを追加して、新しいモッド文字列パターンをサポートし、既存のモッドタイプを拡張するためのテンプレートベースのシステムを使用します","ko":"AI 에이전트의 Mod 파서를 추가하여 새로운 모드 문자열 패턴을 지원하고 기존 모드 유형을 확장하는 템플릿 기반 시스템을 사용합니다","es":"adding-mod-parsers es una habilidad que permite agregar soporte para nuevos patrones de cadenas de modificación y tipos de modificación en el motor de cálculo.","fr":"adding-mod-parsers est une compétence qui permet d''ajouter une prise en charge de nouveaux modèles de chaînes de modification et de types de modification dans le moteur de calcul.","de":"adding-mod-parsers ist eine Fähigkeit, die es ermöglicht, Unterstützung für neue Muster von Modifikationszeichenfolgen und Modifikationstypen im Berechnungsmotor hinzuzufügen.","pt":"O analisador de mod converte strings de mod crus em objetos Mod tipados","ru":"Парсер мод преобразует сырые строки мода в типизированные объекты Mod","ar":"محلل Mod يتحول السلاسل الخام إلى كائنات Mod المُصنفة"},"seo":{"title":{"en":"Adding-Mod-Parsers: Template-Based Mod String Parsing Set...","zh":"AIエージェント添加Mod解析器_setup指南","ja":"AIエージェントのModパーサー追加_best_practices","ko":"AI 에이전트 Mod 파서 추가 설정 가이드","es":"Guía de configuración de adding-mod-parsers para Agentes ...","fr":"Guide d''installation d''adding-mod-parsers pour Outils d''IA","de":"Einrichtungsleitfaden für adding-mod-parsers in KI-Tools","pt":"Guia de Configuração de Analisadores de Mod","ru":"Настройка Парсеров Мод: ИИ Агенты","ar":"إضافة محلل Mod: دليل التطوير"},"description":{"en":"Discover how to implement adding-mod-parsers for efficient mod string conversion. Learn to set up template-based parsing and unlock new mod types for your ca...","zh":"了解如何添加Mod解析器以支持新的模态字符串模式和扩展现有模态类型","ja":"AIエージェントのModパーサー追加方法を学び、新しいモッド文字列パターンをサポートし、既存のモッドタイプを拡張する","ko":"AI 에이전트의 Mod 파서 추가 방법을 알아보고 새로운 모드 문자열 패턴을 지원하고 기존 모드 유형을 확장하는 방법을 배우세요","es":"Aprende a agregar parsers de modificación para mejorar el motor de cálculo de tus Agentes de IA con adding-mod-parsers","fr":"Découvrez comment ajouter des analyseurs de modification pour améliorer le moteur de calcul de vos Outils d''IA avec adding-mod-parsers","de":"Erfahren Sie, wie Sie Parser für Modifikationen hinzufügen, um den Berechnungsmotor Ihrer KI-Tools mit adding-mod-parsers zu verbessern","pt":"Aprenda a adicionar analisadores de mod ao seu projeto com este guia passo a passo","ru":"ИИ Агенты: узнайте, как настроить парсеры мод для расширения возможностей вашего проекта","ar":"اكتشف كيفية إضافة محلل Mod إلى مشروعك باستخدام دليل التطوير الشامل"},"definition":{"en":"Adding-mod-parsers is a template-based system for converting raw mod strings into typed Mod objects used by calculation engines.","zh":"Mod解析器是一种将原始模态字符串转换为类型化Mod对象的技术，用于计算引擎","ja":"Modパーサーは、生のモッド文字列を計算エンジンで使用される型付きModオブジェクトに変換する技術です","ko":"Mod 파서는 원시 모드 문자열을 계산 엔진에서 사용하는 유형화된 모드 객체로 변환하는 기술입니다","es":"adding-mod-parsers es una habilidad que convierte cadenas de modificación raw en objetos de modificación tipados para el motor de cálculo","fr":"adding-mod-parsers est une compétence qui convertit des chaînes de modification brutes en objets de modification typés pour le moteur de calcul","de":"adding-mod-parsers ist eine Fähigkeit, die rohe Modifikationszeichenfolgen in typisierte Modifikationsobjekte für den Berechnungsmotor umwandelt","pt":"O que é um analisador de mod? Um sistema baseado em modelos para correspondência de padrões","ru":"Что такое парсер мод? Шаблонная система для сопоставления с образцом","ar":"ما هو محلل Mod؟ نظام قائم على القوالب لمطابقة الأنماط"},"features":{"en":["Uses a template-based system for pattern matching","Supports adding new mod string patterns","Extends existing mod types to handle new variants","Adds new mod types to the calculation engine","Utilizes Mod type definitions from src/tli/mod.ts","Enables parser template customization"],"zh":["支持新的模态字符串模式","扩展现有模态类型以处理新的变体","添加新的模态类型到计算引擎","使用模板基于的系统进行模式匹配","Mod类型定义存储在src/tli/mod.ts文件中"],"ja":["新しいモッド文字列パターンのサポート","既存のモッドタイプを拡張して新しいバリアントを処理する","計算エンジンに新しいモッドタイプを追加する","テンプレートベースのシステムを使用したパターンマッチング","Modタイプ定義はsrc/tli/mod.tsファイルに保存されます"],"ko":["새로운 모드 문자열 패턴 지원","기존 모드 유형을 확장하여 새로운 변형을 처리","계산 엔진에 새로운 모드 유형을 추가","템플릿 기반 시스템을 사용한 패턴 매칭","모드 유형 정의는 src/tli/mod.ts 파일에 저장됩니다"],"es":["Soporte para patrones de cadenas de modificación personalizadas","Extensión de tipos de modificación existentes para manejar nuevas variantes","Adición de nuevos tipos de modificación al motor de cálculo","Uso de un sistema de plantillas para la coincidencia de patrones","Definición de tipos de modificación en src/tli/mod.ts"],"fr":["Prise en charge de modèles de chaînes de modification personnalisés","Extension de types de modification existants pour gérer de nouvelles variantes","Ajout de nouveaux types de modification au moteur de calcul","Utilisation d''un système de modèles pour la correspondance de modèles","Définition de types de modification dans src/tli/mod.ts"],"de":["Unterstützung für benutzerdefinierte Muster von Modifikationszeichenfolgen","Erweiterung bestehender Modifikationstypen zur Verarbeitung neuer Varianten","Hinzufügen neuer Modifikationstypen zum Berechnungsmotor","Verwendung eines Template-Systems für die Musterabgleich","Definition von Modifikationstypen in src/tli/mod.ts"],"pt":["Conversão de strings de mod crus em objetos Mod tipados","Sistema baseado em modelos para correspondência de padrões","Suporte para adicionar novos padrões de string de mod","Extensão de tipos de mod existentes para lidar com novas variantes","Adição de novos tipos de mod ao mecanismo de cálculo"],"ru":["Преобразование сырых строк мода в типизированные объекты Mod","Шаблонная система для сопоставления с образцом","Поддержка добавления новых шаблонов строк мода","Расширение существующих типов мод для обработки новых вариантов","Добавление новых типов мод в расчетный механизм"],"ar":["تحويل السلاسل الخام إلى كائنات Mod المُصنفة","نظام قائم على القوالب لمطابقة الأنماط","دعم لإضافة أنماط جديدة من السلاسل الخام","توسيع أنواع Mod الحالية لمعالجة المتغيرات الجديدة","إضافة أنواع Mod جديدة إلى محرك الحساب"]},"keywords":{"en":["how to use adding-mod-parsers","what is adding-mod-parsers","adding-mod-parsers alternative","adding-mod-parsers vs mod string parsing","adding-mod-parsers install","adding-mod-parsers setup guide","template-based mod string parsing","mod string conversion for calculation engines"],"zh":["AIエージェント","Mod解析器","模态字符串模式","计算引擎","模板基于的系统","添加Mod解析器","扩展模态类型","添加新的模态类型"],"ja":["AIエージェント","Modパーサー","モッド文字列パターン","計算エンジン","テンプレートベースのシステム","Modパーサー追加","モッドタイプの拡張","新しいモッドタイプの追加"],"ko":["AI 에이전트","Mod 파서","모드 문자열 패턴","계산 엔진","템플릿 기반 시스템","Mod 파서 추가","모드 유형 확장","새로운 모드 유형 추가"],"es":["adding-mod-parsers","Agentes de IA","motor de cálculo","patrones de cadenas de modificación","tipos de modificación","plantillas de coincidencia de patrones","src/tli/mod.ts","desarrollo de Agentes de IA"],"fr":["adding-mod-parsers","Outils d''IA","moteur de calcul","modèles de chaînes de modification","types de modification","système de modèles de correspondance","src/tli/mod.ts","développement d''Outils d''IA"],"de":["adding-mod-parsers","KI-Tools","Berechnungsmotor","Muster von Modifikationszeichenfolgen","Modifikationstypen","Template-System für Musterabgleich","src/tli/mod.ts","Entwicklung von KI-Tools"],"pt":["analisador de mod","adicionar analisador de mod","guias de configuração","desenvolvimento de projetos","IИ Агенты","ferramentas de desenvolvimento","tecnologias de desenvolvimento"],"ru":["парсер мод","настройка парсера мод","ИИ Агенты","расширение возможностей проекта","разработка проектов","технологии разработки","инструменты разработки"],"ar":["محلل Mod","إضافة محلل Mod","دليل التطوير","تطوير المشاريع","أدوات تطوير","تقنيات تطوير","محرك الحساب"]}},"owner":"aclinia","repo":"torchlight-of-building","repoPath":"aclinia/torchlight-of-building","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.310Z","topics":[],"category":"community","skillMd":{"name":"adding-mod-parsers","description":"Use when adding new mod parsers to convert game mod strings to typed Mod objects - guides the template-based parsing pattern (project)","bodyPreview":"# Adding Mod Parsers\n\n## Overview\n\nThe mod parser converts raw mod strings (e.g., `\"+10% all stats\"`) into typed `Mod` objects used by the calculation engine. It uses a **template-based** system for pattern matching.\n\n## When to Use\n\n- Adding support for new mod string patterns\n- Extending existing mod types to handle new variants\n- Adding new mod types to the engine\n\n## Project File Locations\n\n| Purpose | File Path |\n|---------|-----------|\n| Mod type definitions | `src/tli/mod.ts` |\n| Parser t","body":"# Adding Mod Parsers\n\n## Overview\n\nThe mod parser converts raw mod strings (e.g., `\"+10% all stats\"`) into typed `Mod` objects used by the calculation engine. It uses a **template-based** system for pattern matching.\n\n## When to Use\n\n- Adding support for new mod string patterns\n- Extending existing mod types to handle new variants\n- Adding new mod types to the engine\n\n## Project File Locations\n\n| Purpose | File Path |\n|---------|-----------|\n| Mod type definitions | `src/tli/mod.ts` |\n| Parser templates | `src/tli/mod-parser/templates.ts` |\n| Enum registrations | `src/tli/mod-parser/enums.ts` |\n| Calculation handlers | `src/tli/calcs/offense.ts` |\n| Tests | `src/tli/mod-parser.test.ts` |\n\n## Implementation Checklist\n\n### 1. Check if Mod Type Exists\n\nLook in `src/tli/mod.ts` under `ModDefinitions`. If the mod type doesn''t exist, add it:\n\n```typescript\ninterface ModDefinitions {\n  // ... existing types ...\n  NewModType: { value: number; someField: string };\n}\n```\n\n### 2. Add Template in `templates.ts`\n\nTemplates use a DSL for pattern matching. **Do not add comments to templates.ts** - the template string itself is self-documenting.\n\n```typescript\nt(\"{value:dec%} all stats\").output((c) => ({\n  type: \"StatPct\",\n  value: c.value,\n  statModType: \"all\",\n})),\nt(\"{value:dec%} {statModType:StatWord}\")\n  .enum(\"StatWord\", StatWordMapping)\n  .output((c) => ({ type: \"StatPct\", value: c.value, statModType: c.statModType })),\nt(\"{value:dec%} [additional] [{modType:DmgModType}] damage\").output((c) => ({\n  type: \"DmgPct\",\n  value: c.value,\n  dmgModType: c.modType ?? \"global\",\n  addn: c.additional !== undefined,\n})),\nt(\"{value:dec%} attack and cast speed\").outputMany([\n  spec((c) => ({ type: \"AspdPct\", value: c.value, addn: false })),\n  spec((c) => ({ type: \"CspdPct\", value: c.value, addn: false })),\n]),\n```\n\n**Template capture types:**\n\n| Type | Matches | Example Input → Output |\n|------|---------|------------------------|\n| `{name:int}` | Unsigned integer | `\"5\"` → `5` |\n| `{name:dec}` | Unsigned decimal | `\"21.5\"` → `21.5` |\n| `{name:int%}` | Unsigned integer percent | `\"30%\"` → `30` |\n| `{name:dec%}` | Unsigned decimal percent | `\"96%\"` → `96` |\n| `{name:+int}` | **Signed** integer (requires `+` or `-`) | `\"+5\"` → `5`, `\"-3\"` → `-3` |\n| `{name:+dec}` | **Signed** decimal (requires `+` or `-`) | `\"+21.5\"` → `21.5` |\n| `{name:+int%}` | **Signed** integer percent | `\"+30%\"` → `30`, `\"-15%\"` → `-15` |\n| `{name:+dec%}` | **Signed** decimal percent | `\"+96%\"` → `96` |\n| `{name:?int}` | **Optional-sign** integer (matches with or without `+`/`-`) | `\"5\"` → `5`, `\"+5\"` → `5`, `\"-3\"` → `-3` |\n| `{name:?dec}` | **Optional-sign** decimal | `\"21.5\"` → `21.5`, `\"+21.5\"` → `21.5` |\n| `{name:?int%}` | **Optional-sign** integer percent | `\"30%\"` → `30`, `\"+30%\"` → `30` |\n| `{name:?dec%}` | **Optional-sign** decimal percent | `\"96%\"` → `96`, `\"+96%\"` → `96` |\n| `{name:EnumType}` | Enum lookup | `{dmgType:DmgChunkType}` |\n\n**Signed vs Unsigned vs Optional-sign Types:**\n- Use **unsigned** (`dec%`, `int`) when input NEVER has `+` or `-` (e.g., `\"8% additional damage applied to Life\"`)\n- Use **signed** (`+dec%`, `+int`) when input ALWAYS has `+` or `-` (e.g., `\"+25% additional damage\"`)\n- Use **optional-sign** (`?dec%`, `?int`) when input MAY OR MAY NOT have a sign — this avoids needing two separate templates for signed/unsigned variants\n- Signed types will NOT match unsigned inputs, and unsigned will NOT match signed inputs\n- Prefer `?dec%` over two separate `dec%`/`+dec%` templates when the same mod can appear with or without a sign\n\n**Optional syntax:**\n- `[additional]` - Optional literal, sets `c.additional?: true`\n- `[{modType:DmgModType}]` - Optional capture, sets `c.modType?: DmgModType`\n- `{(effect|damage)}` - Alternation (regex-style)\n\n### 3. Add Enum Mapping (if needed)\n\nIf you need custom word → value mapping, add to `enums.ts`:\n\n```typescript\nexport const StatWordMapping: Record<string, string> = {\n  strength: \"str\",\n  dexterity: \"dex\",\n  intelligence: \"int\",\n};\n\nregisterEnum(\"StatWord\", [\"strength\", \"dexterity\", \"intelligence\"]);\n```\n\n### 4. Add Handler in `offense.ts` (if new mod type)\n\nIf you added a new mod type, add handling in `calculateOffense()` or relevant helper:\n\n```typescript\ncase \"NewModType\": {\n  break;\n}\n```\n\nFor existing mod types with new variants (like adding `statModType: \"all\"`), update existing handlers to also filter for the new variant:\n\n```typescript\nconst flat = sumByValue(\n  statMods.filter((m) => m.statModType === statType || m.statModType === \"all\"),\n);\n```\n\n### 5. Add Tests\n\nAdd test cases in `src/tli/mod_parser.test.ts`:\n\n```typescript\ntest(\"parse percentage all stats\", () => {\n  const result = parseMod(\"+10% all stats\");\n  expect(result).toEqual([\n    {\n      type: \"StatPct\",\n      statModType: \"all\",\n      value: 10,\n    },\n  ]);\n});\n```\n\n### 6. Verify\n\n```bash\npnpm test src/tli/mod_parser.test.ts\npnpm typecheck\npnpm check\n```\n\n## Template Ordering\n\n**IMPORTANT:** More specific patterns must come before generic ones in `allParsers` array.\n\n```typescript\n// Good: specific before generic\nt(\"{value:dec%} all stats\").output(...),           // Specific\nt(\"{value:dec%} {statModType:StatWord}\").output(...), // Generic\n\n// Bad: generic would match first and fail on \"all stats\"\n```\n\n## Examples\n\n### Simple Value Parser (Signed)\n\n**Input:** `\"+10% all stats\"` (starts with `+`)\n\n```typescript\nt(\"{value:+dec%} all stats\").output((c) => ({\n  type: \"StatPct\",\n  value: c.value,\n  statModType: \"all\",\n})),\n```\n\n### Simple Value Parser (Unsigned)\n\n**Input:** `\"8% additional damage applied to Life\"` (no sign)\n\n```typescript\nt(\"{value:dec%} additional damage applied to life\").output((c) => ({\n  type: \"DmgPct\",\n  value: c.value,\n  dmgModType: \"global\",\n  addn: true,\n})),\n```\n\n### Parser with Condition (Signed)\n\n**Input:** `\"+40% damage if you have Blocked recently\"`\n\n```typescript\nt(\"{value:+dec%} damage if you have blocked recently\").output((c) => ({\n  type: \"DmgPct\",\n  value: c.value,\n  dmgModType: \"global\",\n  addn: false,\n  cond: \"has_blocked_recently\",\n})),\n```\n\n### Parser with Per-Stackable (Signed in \"deals\" position)\n\n**Input:** `\"Deals +1% additional damage to an enemy for every 2 points of Frostbite Rating the enemy has\"`\n\nNote: The `+` appears AFTER \"deals\", so use `{value:+dec%}`:\n\n```typescript\nt(\"deals {value:+dec%} additional damage to an enemy for every {amt:int} points of frostbite rating the enemy has\")\n  .output((c) => ({\n    type: \"DmgPct\",\n    value: c.value,\n    dmgModType: \"global\",\n    addn: true,\n    per: { stackable: \"frostbite_rating\", amt: c.amt },\n  })),\n```\n\n### Multi-Output Parser (Signed)\n\n**Input:** `\"+6% attack and cast speed\"`\n\n```typescript\nt(\"{value:+dec%} [additional] attack and cast speed\").outputMany([\n  spec((c) => ({ type: \"AspdPct\", value: c.value, addn: c.additional !== undefined })),\n  spec((c) => ({ type: \"CspdPct\", value: c.value, addn: c.additional !== undefined })),\n]),\n```\n\n### Flat Stat Parser (Signed)\n\n**Input:** `\"+166 Max Mana\"`\n\n```typescript\nt(\"{value:+dec} max mana\").output((c) => ({ type: \"MaxMana\", value: c.value })),\n```\n\n### Optional-Sign Parser\n\n**Input:** `\"12.5% Sealed Mana Compensation for Spirit Magus Skills\"` OR `\"+12.5% Sealed Mana Compensation for Spirit Magus Skills\"`\n\nUse `?dec%` when the same mod string can appear with or without a `+`/`-` sign, avoiding the need for two separate templates:\n\n```typescript\nt(\"{value:?dec%} sealed mana compensation for spirit magus skills\").output(\n  (c) => ({ type: \"SealedManaCompPct\", value: c.value, addn: false, skillType: \"spirit_magus\" }),\n),\n```\n\n### No-Op Parser (Recognized but produces no mods)\n\n**Input:** `\"Energy Shield starts to Charge when Blocking\"`\n\nUse `outputNone()` when a mod string should be recognized (not flagged as unparsed) but has no effect on calculations:\n\n```typescript\nt(\"energy shield starts to charge when blocking\").outputNone(),\n```\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Using `dec%` for input with `+` prefix | Use `+dec%` for inputs like `\"+25% damage\"`, or `?dec%` if sign is optional |\n| Using `+dec%` for input without sign | Use `dec%` for inputs like `\"8% damage applied to life\"`, or `?dec%` if sign is optional |\n| Two templates for signed/unsigned variants of the same mod | Use `?dec%` to match both in a single template |\n| Template doesn''t match input case | Templates are matched case-insensitively; input is normalized to lowercase |\n| Missing `type` field in output mapper | Include `type: \"ModType\"` in the returned object — contextual typing from the `Mod` discriminated union handles narrowing |\n| Handler doesn''t account for new variant | Update `offense.ts` to handle new values (e.g., `statModType === \"all\"`) |\n| Generic template before specific | Move specific templates earlier in `allParsers` array |\n\n## Data Flow\n\n```\nRaw string: \"+10% all stats\"\n    ↓ normalize (lowercase, trim)\n\"10% all stats\"\n    ↓ template matching (allParsers)\n{ type: \"StatPct\", value: 10, statModType: \"all\" }\n    ↓ calculateStats() in offense.ts\nApplied to str, dex, int calculations\n```\n"},"lastSynced":"2026-03-08T02:02:28.577Z","agentAnalysis":{"suitability":{"en":"Essential for Calculation Engine Agents processing game mod strings and stat systems.","zh":"对于处理游戏模组字符串和状态系统的计算引擎代理至关重要。","ja":"ゲームモッド文字列とステートシステムを処理する計算エンジンエージェントに不可欠です。","ko":"게임 모드 문자열 및 상태 시스템을 처리하는 계산 엔진 에이전트에 필수적입니다.","es":"Esencial para Agentes de Motor de Cálculo que procesan cadenas de modificación de juegos y sistemas de estadísticas.","fr":"Essentiel pour les Agents de Moteur de Calcul traitant les chaînes de modification de jeu et les systèmes de statistiques.","de":"Wesentlich für Calculation Engine Agents, die Spielmod-Strings und Statistiksysteme verarbeiten.","pt":"Essencial para Agentes de Motor de Cálculo que processam strings de mod de jogos e sistemas de estatísticas.","ru":"Необходимо для агентов расчетного двигателя, обрабатывающих строки мода игр и системы статистики.","ar":"ضروري لمحлати الهندسة الحسابية التي معالجة سلسلة تعديل اللعبة ونظام الإحصاءات."},"recommendation":{"en":"Enables robust parsing of raw mod strings into typed Mod objects using a template-based pattern matching system. Provides structured data conversion for calculation engines handling complex stat modifications and variant patterns.","zh":"启用使用模板基于的模式匹配系统对原始模组字符串进行强大的解析，使用类型化的Mod对象。为处理复杂的状态修改和变体模式的计算引擎提供结构化数据转换。","ja":"テンプレートベースのパターンマッチングシステムを使用して生のモッド文字列を型付けされたModオブジェクトにロバストに解析することを可能にします。複雑なステータス変更とバリアントパターンを処理する計算エンジンに構造化データ変換を提供します。","ko":"템플릿 기반의 패턴 매칭 시스템을 사용하여 원시 모드 문자열을 유형화된 Mod 객체로 강력하게 구문 분석합니다. 복잡한 상태 수정 및 변형 패턴을 처리하는 계산 엔진을 위한 구조화된 데이터 변환을 제공합니다.","es":"Permite un análisis robusto de cadenas de modificación raw en objetos Mod tipados utilizando un sistema de coincidencia de patrones basado en plantillas. Proporciona una conversión de datos estructurados para motores de cálculo que manejan modificaciones de estadísticas complejas y patrones de variantes.","fr":"Permet un traitement robuste des chaînes de modification brutes en objets Mod typés à l''aide d''un système de correspondance de modèles basé sur des modèles. Fournit une conversion de données structurées pour les moteurs de calcul qui gèrent des modifications de statistiques complexes et des modèles de variantes.","de":"Ermöglicht eine robuste Verarbeitung von Rohmod-Strings in typisierte Mod-Objekte unter Verwendung eines templatebasierten Mustervergleichssystems. Bietet eine strukturierte Datenkonvertierung für Berechnungsmotoren, die komplexe Statistikmodifikationen und Variantenmuster verarbeiten.","pt":"Permite a análise robusta de strings de mod brutas em objetos Mod tipados usando um sistema de correspondência de padrões baseado em modelos. Fornece conversão de dados estruturados para motores de cálculo que lidam com modificações de estatísticas complexas e padrões variados.","ru":"Позволяет выполнять прочную разборку сырых строк мода в типизированные объекты Mod с помощью системы сопоставления шаблонов на основе шаблонов. Предоставляет структурированное преобразование данных для расчетных двигателей, обрабатывающих сложные модификации статистики и вариативные шаблоны.","ar":"يسمح بتحليل قوي للتعديلات الخام من سلسلة إلى كائنات تعديل من نوع، باستخدام نظام مطابق للنمط على أساس القوالب. يوفر تحويل البيانات المهيكلة للمحركات الحسابية التي تتعامل مع تعديلات إحصائية معقدة وأنماط متغيرة."},"useCases":{"en":["Converting raw mod strings to typed objects","Extending existing mod types with new variants","Adding support for new mod string patterns","Integrating mod parsing into calculation pipelines"],"zh":["将生模字符串转换为类型化对象","使用新变体扩展现有的模类型","为新模字符串模式添加支持","将模解析集成到计算流水线中"],"ja":["生のモッド文字列を型付けされたオブジェクトに変換する","新しいバリアントを使用して既存のモッドタイプを拡張する","新しいモッド文字列パターンのサポートを追加する","モッド解析を計算パイプラインに統合する"],"ko":["원시 모드 문자열을 유형화된 객체로 변환하는 것","새로운 변형을 사용하여 기존의 모드 유형을 확장하는 것","새로운 모드 문자열 패턴에 대한 지원을 추가하는 것","모드 구문을 계산 파이프라인에 통합하는 것"],"es":["Conversión de cadenas de modificación raw en objetos tipados","Extensión de los tipos de modificación existentes con nuevas variantes","Adición de soporte para nuevos patrones de cadenas de modificación","Integración de la analítica de modificación en pipelines de cálculo"],"fr":["Conversion de chaînes de modification brutes en objets typés","Extension des types de modification existants avec de nouvelles variantes","Ajout de la prise en charge de nouveaux modèles de chaînes de modification","Intégration de l''analyse de modification dans les pipelines de calcul"],"de":["Konvertierung von Rohmod-Strings in typisierte Objekte","Erweiterung der vorhandenen Modtypen mit neuen Varianten","Hinzufügung der Unterstützung für neue Muster von Mod-Strings","Integrierung der Mod-Analyse in Berechnungspipelines"],"pt":["Conversão de strings de mod brutos em objetos tipados","Extensão de tipos de mod existentes com novas variantes","Adição de suporte para novos padrões de strings de mod","Integração da análise de mod em pipelines de cálculo"],"ru":["Преобразование сырых строк мода в типизированные объекты","Расширение существующих типов мода новыми вариантами","Добавление поддержки новых форматов строк мода","Интеграция разбора мода в расчетные конвейеры"],"ar":["تحويل تعديلات السلسلة الخام إلى كائنات من النوع","توسيع أنواع تعديل موجودة بمتغيرات جديدة","إضافة دعم لتنسيقات جديدة من سلسلة تعديل","دمج تحليل التعديل في خطوط أنابيب الحساب"]},"limitations":{"en":["Requires mod type definitions in src/tli/mod.ts","Template-based system may need pattern updates for new formats","Dependent on calculation engine integration"],"zh":["需要在src/tli/mod.ts中定义模类型","基于模板的系统可能需要为新格式更新模式","依赖于计算引擎集成"],"ja":["src/tli/mod.tsにモッドタイプの定義が必要","テンプレートベースのシステムでは新しい形式のためにパターンを更新する必要がある","計算エンジンの統合に依存する"],"ko":["src/tli/mod.ts에 모드 유형 정의가 필요함","템플릿 기반 시스템은 새로운 형식에 대한 패턴 업데이트가 필요할 수 있음","계산 엔진 통합에 의존함"],"es":["Requiere definiciones de tipo de modificación en src/tli/mod.ts","El sistema basado en plantillas puede necesitar actualizaciones de patrones para nuevos formatos","Dependiente de la integración del motor de cálculo"],"fr":["Nécessite des définitions de type de modification dans src/tli/mod.ts","Le système basé sur des modèles peut nécessiter des mises à jour de modèles pour les nouveaux formats","Dépend de l''intégration du moteur de calcul"],"de":["Benötigt Modtyp-Definitionen in src/tli/mod.ts","Das templatebasierte System kann möglicherweise Pattern-Updates für neue Formate benötigen","Abhängig von der Integration des Berechnungsmotors"],"pt":["Requer definições de tipo de mod em src/tli/mod.ts","Sistema baseado em modelos pode precisar de atualizações de padrões para novos formatos","Dependente da integração do motor de cálculo"],"ru":["Требует определений типа мода в src/tli/mod.ts","Система на основе шаблонов может потребовать обновления шаблонов для новых форматов","Зависит от интеграции расчетного двигателя"],"ar":["يتطلب تعريفات نوع تعديل في src/tli/mod.ts","نظام القالب قد يحتاج إلى تحديث الأنماط للتنسيقات الجديدة","يعتمد على دمج محرك الحساب"]},"version":4},"contentHash":"7d8ca938f11cca696e75476cc4ae4ae4798fe8194aeb68944fde8c9c3edad642","qualityScore":51}');
