INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aclinia/torchlight-of-building/adding-mod-parsers', 'adding-mod-parsers', 'aclinia', 'torchlight-of-building', 'community', 'adding-mod-parsers aclinia torchlight-of-building community The adding-mod-parsers skill converts raw mod strings into typed Mod objects for calculation engines. It benefits developers working with mod string patterns and variants. 添加Mod解析器以支持新的模态字符串模式和扩展现有模态类型，使用模板基于的系统进行模式匹配 AIエージェントのModパーサーを追加して、新しいモッド文字列パターンをサポートし、既存のモッドタイプを拡張するためのテンプレートベースのシステムを使用します AI 에이전트의 Mod 파서를 추가하여 새로운 모드 문자열 패턴을 지원하고 기존 모드 유형을 확장하는 템플릿 기반 시스템을 사용합니다 adding-mod-parsers es una habilidad que permite agregar soporte para nuevos patrones de cadenas de modificación y tipos de modificación en el motor de cálculo. adding-mod-parsers est une compétence qui permet d''ajouter une prise en charge de nouveaux modèles de chaînes de modification et de types de modification dans le moteur de calcul. adding-mod-parsers ist eine Fähigkeit, die es ermöglicht, Unterstützung für neue Muster von Modifikationszeichenfolgen und Modifikationstypen im Berechnungsmotor hinzuzufügen. O analisador de mod converte strings de mod crus em objetos Mod tipados Парсер мод преобразует сырые строки мода в типизированные объекты Mod محلل Mod يتحول السلاسل الخام إلى كائنات Mod المُصنفة how to use adding-mod-parsers what is adding-mod-parsers adding-mod-parsers alternative adding-mod-parsers vs mod string parsing adding-mod-parsers install adding-mod-parsers setup guide template-based mod string parsing mod string conversion for calculation engines AIエージェント Mod解析器 模态字符串模式 计算引擎 模板基于的系统 添加Mod解析器 扩展模态类型 添加新的模态类型 Uses a template-based system for pattern matching Supports adding new mod string patterns Extends existing mod types to handle new variants Adds new mod types to the calculation engine Utilizes Mod type definitions from src/tli/mod.ts Enables parser template customization Adding-mod-parsers is a template-based system for converting raw mod strings into typed Mod objects used by calculation engines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HomericIntelligence/ProjectOdyssey/agent-hierarchy-diagram', 'community', 'HomericIntelligence', 'ProjectOdyssey', 'HomericIntelligence/ProjectOdyssey', 'agent-hierarchy-diagram', 0, 0, 51, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:31.115Z', '40ead33fdaaf23863321346e9051385741925658f1282b970ca915ed3db20cf0', '{"id":"HomericIntelligence/ProjectOdyssey/agent-hierarchy-diagram","name":"agent-hierarchy-diagram","description":{"en":"The agent-hierarchy-diagram skill generates visual diagrams showing agent system structure and relationships, benefiting teams and new contributors. It provides a training framework written in Mojo.","zh":"agent-hierarchy-diagram是一个用于生成AIエージェント系统层次结构图的工具，帮助开发者理解系统结构和关系","ja":"AIエージェント階層図生成ツールは、エージェントシステムの構造と関係を可視化するためのツールです","ko":"AI 에이전트 계층 구조図 생성 도구는 에이전트 시스템의 구조와 관계를 시각화하는 데 사용됩니다","es":"El diagrama de jerarquía de agentes es una herramienta para generar diagramas visuales de estructura y relaciones de sistemas de agentes","fr":"Le diagramme de hiérarchie d''agents est un outil pour générer des diagrammes visuels de structure et de relations de systèmes d''agents","de":"Das Agenten-Hierarchie-Diagramm ist ein Tool zum Erstellen von visuellen Diagrammen von Struktur und Beziehungen von Agentsystemen","pt":"O diagrama de hierarquia de agentes gera diagramas visuais da estrutura e relacionamentos do sistema de agentes","ru":"Иерархическая диаграмма ИИ Агентов генерирует визуальные диаграммы структуры и отношений системы ИИ Агентов","ar":"مخطط هرمية الوكلاء يولد مخططات بصرية لهيكل نظام الوكلاء وعلاقاته"},"seo":{"title":{"en":"agent-hierarchy-diagram: Visualize AI Agent Structures | ...","zh":"AIエージェント层次结构图生成工具 - Setup Guide","ja":"AIエージェント階層図生成ツール - ベストプラクティス","ko":"AI 에이전트 계층 구조図 생성 도구 - 사용자 가이드","es":"Guía de configuración de diagramas de jerarquía de agente...","fr":"Guide de 