INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HomericIntelligence/ProjectOdyssey/agent-hierarchy-diagram', 'agent-hierarchy-diagram', 'HomericIntelligence', 'ProjectOdyssey', 'community', 'agent-hierarchy-diagram HomericIntelligence ProjectOdyssey community The agent-hierarchy-diagram skill generates visual diagrams showing agent system structure and relationships, benefiting teams and new contributors. It provides a training framework written in Mojo. agent-hierarchy-diagram是一个用于生成AIエージェント系统层次结构图的工具，帮助开发者理解系统结构和关系 AIエージェント階層図生成ツールは、エージェントシステムの構造と関係を可視化するためのツールです AI 에이전트 계층 구조図 생성 도구는 에이전트 시스템의 구조와 관계를 시각화하는 데 사용됩니다 El diagrama de jerarquía de agentes es una herramienta para generar diagramas visuales de estructura y relaciones de sistemas de agentes Le diagramme de hiérarchie d''agents est un outil pour générer des diagrammes visuels de structure et de relations de systèmes d''agents Das Agenten-Hierarchie-Diagramm ist ein Tool zum Erstellen von visuellen Diagrammen von Struktur und Beziehungen von Agentsystemen O diagrama de hierarquia de agentes gera diagramas visuais da estrutura e relacionamentos do sistema de agentes Иерархическая диаграмма ИИ Агентов генерирует визуальные диаграммы структуры и отношений системы ИИ Агентов مخطط هرمية الوكلاء يولد مخططات بصرية لهيكل نظام الوكلاء وعلاقاته how to use agent-hierarchy-diagram agent-hierarchy-diagram alternative agent-hierarchy-diagram setup guide what is agent-hierarchy-diagram agent-hierarchy-diagram vs other frameworks agent-hierarchy-diagram install Mojo training framework visualizing agent relationships generating ASCII tree diagrams AIエージェント 层次结构图 agent-hierarchy-diagram Mojo ASCII树形图 Mermaid图 Generates ASCII tree diagrams using ./scripts/generate_hierarchy_diagram.sh Creates Mermaid diagrams with ./scripts/generate_mermaid_diagram.sh Saves diagrams to documentation with ./scripts/generate_h Visualizes agent relationships for presentations Documents agent system for teams Supports onboarding new contributors agent-hierarchy-diagram is a training framework that generates visual diagrams of agent system structures and relationships using Mojo.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('schuttpj/baseline-app/webapp-testing', 'community', 'schuttpj', 'baseline-app', 'schuttpj/baseline-app', 'webapp-testing', 0, 0, 51, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:38.485Z', '31e301853c09c350e8a55e8e078a1f6e5873f3cdda6cd05a46ddd3d1f0ab6c61', '{"id":"schuttpj/baseline-app/webapp-testing","name":"webapp-testing","description":{"en":"The webapp-testing skill enables developers to comprehensively test and debug local web applications using Playwright automation, verifying UI behavior and interactions.","zh":"Web应用测试技能使用Playwright自动化测试和调试本地Web应用","ja":"WebアプリケーションテストスキルはPlaywrightを使用してローカルWebアプリケーションの自動化テストとデバッグを実現","ko":"웹애플리케이션 테스트 기능은 Playwright를 사용하여 로컬 웹애플리케이션의 자동화 테스트와 디버깅을 구현","es":"La prueba de aplicaciones web es crucial para garantizar la calidad y la funcionalidad de las aplicaciones. Con Playwright, puedes automatizar las pruebas de tu aplicación web.","fr":"Les tests d''applications web sont essentiels pour garantir la qualité et la fonctionnalité des applications. Avec Playwright, vous pouvez automatiser les tests de votre application web.","de":"Die Überprüfung von Webanwendungen ist entscheidend, um die Qualität und Funktionalität von Anwendungen zu gewährleisten. Mit Playwright können Sie die Tests Ihrer Webanwendung automatisieren.","pt":"O teste de aplicativos web permite testar funcionalidades de frontend em um navegador real e verificar comportamentos de UI e interações","ru":"Тестирование веб-приложений позволяет тестировать функциональность frontend в реальном браузере и проверять поведение UI и взаимодействия","ar":"اختبار التطبيقات الويب يسمح باختبار ميزات واجهة المستخدم في متصفح حقيقي وتحقق من سلوك واجهة المستخدم والتفاعلات"},"seo":{"title":{"en":"webapp-testing: Comprehensive Testing Setup Guide | AI Ag...","zh":"Web应用测试_setup指南","ja":"Webアプリケーションテストベストプラクティス","ko":"웹애플리케이션 테스트 설정 가이드","es":"Guía de configuración de pruebas de aplicaciones web con ...","fr":"Configurer les tests d''applications web avec Playwright -...","de":"Einrichten von Webanwendungstests mit Playwright - Leitfaden","pt":"Guia de Configuração do Teste de Aplicativos Web com Play...","ru":"Настройка тестирования веб-приложений с помощью ИИ Агенто...","ar":"دليل إعداد اختبار التطبيقات الويب باستخدام Playwright ووك..."},"description":{"en":"Discover how to test and debug local web applications with Playwright automation. Learn to verify UI behavior, capture screenshots, and inspect browser conso...","zh":"使用AIエージェント的Web应用测试技能，实现自动化测试和调试","ja":"AIエージェントのWebアプリケーションテストスキルを使用して自動化テストとデバッグを実現","ko":"AI Tools의 웹애플리케이션 테스트 기능을 사용하여 자동화 테스트와 디버깅을 구현","es":"Aprende a probar aplicaciones web de forma automatizada con Playwright. Descubre cómo depurar y verificar la funcionalidad de tu aplicación web.","fr":"Découvrez comment tester vos applications web de manière automatisée avec Playwright. Apprenez à déboguer et à vérifier la fonctionnalité de votre applicatio...","de":"Erfahren Sie, wie Sie Webanwendungen mit Playwright automatisiert testen. Entdecken Sie, wie Sie die Funktionalität Ihrer Webanwendung debuggen und überprüfen.","pt":"Aprenda a testar aplicativos web localmente com Playwright e descubra como automatizar testes de frontend e debugar problemas de UI","ru":"Узнайте, как тестировать веб-приложения локально с помощью Playwright и ИИ Агентов, и автоматизировать тесты frontend и отладку проблем UI","ar":"تعرف على كيفية اختبار التطبيقات الويب المحلية باستخدام Playwright ووكيل التطوير، وتعلم автоматизация اختبار واجهة المستخدم وتصحيح الأخطاء"},"definition":{"en":"webapp-testing is a skill that enables comprehensive testing and debugging of local web applications using Playwright automation.","zh":"Web应用测试是使用Playwright自动化测试和调试本地Web应用的技能","ja":"WebアプリケーションテストはPlaywrightを使用してローカルWebアプリケーションの自動化テストとデバッグのスキル","ko":"웹애플리케이션 테스트는 Playwright를 사용하여 로컬 웹애플리케이션의 자동화 테스트와 디버깅의 기능","es":"La prueba de aplicaciones web es el proceso de verificar la funcionalidad y el comportamiento de una aplicación web en un entorno de prueba","fr":"Le test d''applications web est le processus de vérification de la fonctionnalité et du comportement d''une application web dans un environnement de test","de":"Die Überprüfung von Webanwendungen ist der Prozess der Überprüfung der Funktionalität und des Verhaltens einer Webanwendung in einer Testumgebung","pt":"O teste de aplicativos web é uma habilidade que permite testar e depurar aplicativos web localmente usando automação Playwright","ru":"Тестирование веб-приложений - это навык, который позволяет тестировать и отлаживать веб-приложения локально с помощью автоматизации Playwright","ar":"اختبار التطبيقات الويب هو مهارة تسمح باختبار وتصحيح الأخطاء في التطبيقات الويب المحلية باستخدام автоматизация Playwright"},"features":{"en":["Test frontend functionality in a real browser","Verify UI behavior and interactions","Capture screenshots for documentation or debugging","Inspect browser console logs","Validate form submissions and user flows","Check responsive design across viewports"],"zh":["使用Playwright自动化测试","验证UI行为和交互","捕获屏幕截图","检查浏览器控制台日志","验证表单提交和用户流程","检查响应式设计"],"ja":["Playwrightを使用した自動化テスト","UIの動作とインタラクションの検証","スクリーンショットのキャプチャ","ブラウザコンソールログの検査","フォーム送信とユーザーフローの検証","レスポンシブデザインの検査"],"ko":["Playwright를 사용한 자동화 테스트","UI 동작과 상호작용의 검증","스크린샷 캡처","브라우저 콘솔 로그 검사","폼 제출과 사용자 흐름의 검증","반응형 디자인 검사"],"es":["Pruebas de funcionalidad de frontend en un navegador real","Verificación del comportamiento de la interfaz de usuario y las interacciones","Depuración de problemas de la aplicación web","Captura de pantallazos para documentación o depuración","Inspección de registros de la consola del navegador","Validación de envíos de formularios y flujos de usuario"],"fr":["Tests de fonctionnalité de frontend dans un navigateur réel","Vérification du comportement de l''interface utilisateur et des interactions","Débogage des problèmes d''application web","Capture d''écran pour documentation ou débogage","Inspection des journaux de la console du navigateur","Validation des soumissions de formulaires et des flux d''utilisateur"],"de":["Funktionsprüfung von Frontend in einem echten Browser","Überprüfung des Verhaltens der Benutzeroberfläche und der Interaktionen","Fehlerbehebung bei Webanwendungsproblemen","Bildschirmaufnahme für Dokumentation oder Fehlerbehebung","Überprüfung der Browser-Konsole-Protokolle","Validierung von Formulareingaben und Benutzerflüssen"],"pt":["Testar funcionalidades de frontend em um navegador real","Verificar comportamentos de UI e interações","Depurar problemas de aplicativos web","Capturar telas para documentação ou depuração","Inspecionar logs de console do navegador"],"ru":["Тестировать функциональность frontend в реальном браузере","Проверять поведение UI и взаимодействия","Отлаживать проблемы веб-приложений","Сделать скриншоты для документации или отладки","Осмотреть журналы консоли браузера"],"ar":["اختبار ميزات واجهة المستخدم في متصفح حقيقي","تحقق من سلوك واجهة المستخدم والتفاعلات","تصحيح الأخطاء في التطبيقات الويب","التقاط الشاشات لتوثيق أو تصحيح الأخطاء","فحص سجلات وحدة التحكم في المتصفح"]},"keywords":{"en":["how to use webapp-testing","webapp-testing setup guide","Playwright automation testing","web application testing tools","webapp-testing vs Selenium","webapp-testing install","debugging local web applications","webapp-testing alternative","webapp-testing tutorial"],"zh":["Web应用测试","Playwright自动化测试","UI测试","浏览器控制台日志","响应式设计","自动化测试工具","Web应用调试","AIエージェント","Web开发测试"],"ja":["Webアプリケーションテスト","Playwright自動化テスト","UIテスト","ブラウザコンソールログ","レスポンシブデザイン","自動化テストツール","Webアプリケーションデバッグ","AIエージェント","Web開発テスト"],"ko":["웹애플리케이션 테스트","Playwright 자동화 테스트","UI 테스트","브라우저 콘솔 로그","반응형 디자인","자동화 테스트 도구","웹애플리케이션 디버깅","AI Tools","웹 개발 테스트"],"es":["pruebas de aplicaciones web","automatización de pruebas","Playwright","depuración de aplicaciones web","verificación de funcionalidad","captura de pantallazos","inspección de registros de consola","validación de formularios","flujo de usuario"],"fr":["tests d''applications web","automatisation des tests","Playwright","débogage d''applications web","vérification de fonctionnalité","capture d''écran","inspection des journaux de console","validation des formulaires","flux d''utilisateur"],"de":["Webanwendungstests","Automatisierung von Tests","Playwright","Fehlerbehebung bei Webanwendungen","Überprüfung von Funktionalität","Bildschirmaufnahme","Überprüfung von Browser-Konsole-Protokollen","Validierung von Formulareingaben","Benutzerfluss"],"pt":["teste de aplicativos web","Playwright","automação de testes","depuração de aplicativos web","testes de frontend","UI testing","desenvolvimento de aplicativos web"],"ru":["тестирование веб-приложений","Playwright","автоматизация тестирования","отладка веб-приложений","тесты frontend","UI-тестирование","разработка веб-приложений"],"ar":["اختبار التطبيقات الويب","Playwright","أتمتة الاختبار","تصحيح الأخطاء في التطبيقات الويب","اختبار واجهة المستخدم","اختبار واجهة المستخدم","تطوير التطبيقات الويب"]}},"owner":"schuttpj","repo":"baseline-app","repoPath":"schuttpj/baseline-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"webapp-testing","description":"Toolkit for interacting with and testing local web applications using Playwright. Supports verifying frontend functionality, debugging UI behavior, capturing browser screenshots, and viewing browser logs.","bodyPreview":"# Web Application Testing\n\nThis skill enables comprehensive testing and debugging of local web applications using Playwright automation.\n\n## When to Use This Skill\n\nUse this skill when you need to:\n- Test frontend functionality in a real browser\n- Verify UI behavior and interactions\n- Debug web application issues\n- Capture screenshots for documentation or debugging\n- Inspect browser console logs\n- Validate form submissions and user flows\n- Check responsive design across viewports\n\n## Prerequisit","body":"# Web Application Testing\n\nThis skill enables comprehensive testing and debugging of local web applications using Playwright automation.\n\n## When to Use This Skill\n\nUse this skill when you need to:\n- Test frontend functionality in a real browser\n- Verify UI behavior and interactions\n- Debug web application issues\n- Capture screenshots for documentation or debugging\n- Inspect browser console logs\n- Validate form submissions and user flows\n- Check responsive design across viewports\n\n## Prerequisites\n\n- Node.js installed on the system\n- A locally running web application (or accessible URL)\n- Playwright will be installed automatically if not present\n\n## Core Capabilities\n\n### 1. Browser Automation\n- Navigate to URLs\n- Click buttons and links\n- Fill form fields\n- Select dropdowns\n- Handle dialogs and alerts\n\n### 2. Verification\n- Assert element presence\n- Verify text content\n- Check element visibility\n- Validate URLs\n- Test responsive behavior\n\n### 3. Debugging\n- Capture screenshots\n- View console logs\n- Inspect network requests\n- Debug failed tests\n\n## Usage Examples\n\n### Example 1: Basic Navigation Test\n```javascript\n// Navigate to a page and verify title\nawait page.goto(''http://localhost:3000'');\nconst title = await page.title();\nconsole.log(''Page title:'', title);\n```\n\n### Example 2: Form Interaction\n```javascript\n// Fill out and submit a form\nawait page.fill(''#username'', ''testuser'');\nawait page.fill(''#password'', ''password123'');\nawait page.click(''button[type=\"submit\"]'');\nawait page.waitForURL(''**/dashboard'');\n```\n\n### Example 3: Screenshot Capture\n```javascript\n// Capture a screenshot for debugging\nawait page.screenshot({ path: ''debug.png'', fullPage: true });\n```\n\n## Guidelines\n\n1. **Always verify the app is running** - Check that the local server is accessible before running tests\n2. **Use explicit waits** - Wait for elements or navigation to complete before interacting\n3. **Capture screenshots on failure** - Take screenshots to help debug issues\n4. **Clean up resources** - Always close the browser when done\n5. **Handle timeouts gracefully** - Set reasonable timeouts for slow operations\n6. **Test incrementally** - Start with simple interactions before complex flows\n7. **Use selectors wisely** - Prefer data-testid or role-based selectors over CSS classes\n\n## Common Patterns\n\n### Pattern: Wait for Element\n```javascript\nawait page.waitForSelector(''#element-id'', { state: ''visible'' });\n```\n\n### Pattern: Check if Element Exists\n```javascript\nconst exists = await page.locator(''#element-id'').count() > 0;\n```\n\n### Pattern: Get Console Logs\n```javascript\npage.on(''console'', msg => console.log(''Browser log:'', msg.text()));\n```\n\n### Pattern: Handle Errors\n```javascript\ntry {\n  await page.click(''#button'');\n} catch (error) {\n  await page.screenshot({ path: ''error.png'' });\n  throw error;\n}\n```\n\n## Limitations\n\n- Requires Node.js environment\n- Cannot test native mobile apps (use React Native Testing Library instead)\n- May have issues with complex authentication flows\n- Some modern frameworks may require specific configuration\n"},"lastSynced":"2026-03-08T02:02:38.485Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced web application testing and debugging capabilities with Playwright automation.","zh":"非常适合需要高级Web应用程序测试和调试功能的前端代理，特别是使用Playwright自动化。","ja":"Playwright自動化を使用して高度なWebアプリケーション테ストとデバッグ機能を必要とするフロントエンドエージェントに最適です。","ko":"Playwright 자동화를 사용하여 고급 웹 애플리케이션 테스트 및 디버깅 기능이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan capacidades avanzadas de prueba y depuración de aplicaciones web con automatización de Playwright.","fr":"Parfait pour les agents Frontend qui ont besoin de fonctionnalités avancées de test et de débogage d''applications Web avec l''automatisation de Playwright.","de":"Perfekt für Frontend-Agents, die erweiterte Funktionen zur Überprüfung und Fehlersuche von Webanwendungen mit Playwright-Automatisierung benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de teste e depuração de aplicações web com automação Playwright.","ru":"Идеально подходит для агентов Frontend, которым необходимы расширенные возможности тестирования и отладки веб-приложений с помощью автоматизации Playwright.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إمكانيات متقدمة لاختبار وتحليل التطبيقات الإلكترونية باستخدام أتمتة Playwright."},"recommendation":{"en":"Empowers agents to verify UI behavior and interactions, capture screenshots for documentation or debugging, and inspect browser console logs using Playwright automation, ensuring comprehensive testing and debugging of local web applications.","zh":"赋予代理验证UI行为和交互、捕获屏幕截图用于文档或调试，并使用Playwright自动化检查浏览器控制台日志，确保对本地Web应用程序进行全面测试和调试。","ja":"Playwright自動化を使用して、UIの動作と相互作用を検証し、ドキュメントまたはデバッグ用のスクリーンショットをキャプチャし、ブラウザのコンソールログを検査することで、エージェントに権限を与え、ローカルWebアプリケーションの包括的なテストとデバッグを保証します。","ko":"Playwright 자동화를 사용하여 UI 동작 및 상호 작용을 확인하고 문서 또는 디버깅을 위해 스크린샷을 캡처하며 브라우저 콘솔 로그를 검사하여 에이전트에게 권한을 부여함으로써 로컬 웹 애플리케이션에 대한 종합적인 테스트 및 디버깅을 보장합니다.","es":"Habilita a los agentes a verificar el comportamiento de la interfaz de usuario y las interacciones, capturar capturas de pantalla para documentación o depuración, e inspeccionar registros de la consola del navegador utilizando la automatización de Playwright, garantizando una prueba y depuración exhaustivas de aplicaciones web locales.","fr":"Permet aux agents de vérifier le comportement de l''interface utilisateur et les interactions, de capturer des captures d''écran pour la documentation ou le débogage, et d''inspecter les journaux de la console du navigateur en utilisant l''automatisation de Playwright, garantissant ainsi des tests et un débogage complets des applications Web locales.","de":"Ermöglicht es den Agenten, das Verhalten der Benutzeroberfläche und die Interaktionen zu überprüfen, Screenshots für Dokumentation oder Fehlersuche zu erfassen und die Browser-Konsole-Protokolle mithilfe der Playwright-Automatisierung zu überprüfen, wodurch eine umfassende Überprüfung und Fehlersuche lokaler Webanwendungen gewährleistet wird.","pt":"Permite que os agentes verifiquem o comportamento da interface do usuário e as interações, capturam imagens de tela para documentação ou depuração e inspecionam logs da console do navegador usando a automação Playwright, garantindo testes e depuração abrangentes de aplicações web locais.","ru":"Наделяет агентов возможностью проверять поведение пользовательского интерфейса и взаимодействия, захватывать скриншоты для документации или отладки и просматривать журналы консоли браузера с помощью автоматизации Playwright, обеспечивая всестороннее тестирование и отладку локальных веб-приложений.","ar":"تمكن الوكلاء من التحقق من سلوك واجهة المستخدم والتفاعلات، وتقديم لقطات الشاشة للوثائق أو التحليل،และการ فحص سجلات وحدة التحكم للمتصفح باستخدام أتمتة Playwright، مما يضمن اختبارًا وتحليلًا شاملاً للتطبيقات الإلكترونية المحلية."},"useCases":{"en":["Automating frontend functionality tests in real browsers","Debugging web application issues and verifying responsive design across viewports","Validating form submissions and user flows"],"zh":["在真实浏览器中自动化前端功能测试","调试Web应用程序问题并在视口中验证响应式设计","验证表单提交和用户流"],"ja":["実際のブラウザでフロントエンド機能テストを自動化する","Webアプリケーションの問題をデバッグし、ビューポート全体でレスポンシブデザインを検証する","フォームの提出とユーザーフローを検証する"],"ko":["실제 브라우저에서 프론트엔드 기능 테스트 자동화","웹 애플리케이션 문제 디버깅 및 뷰포트에서 반응형 디자인 확인","폼 제출 및 사용자 흐름 확인"],"es":["Automatizar pruebas de funcionalidad de frontend en navegadores reales","Depurar problemas de aplicaciones web y verificar el diseño receptivo en diferentes puntos de vista","Validar envíos de formularios y flujos de usuario"],"fr":["Automatiser les tests de fonctionnalité de frontend dans des navigateurs réels","Déboguer les problèmes d''applications Web et vérifier la conception réactive à différents points de vue","Valider les envois de formulaires et les flux d''utilisateurs"],"de":["Automatisierung von Frontend-Funktionalitätstests in echten Browsern","Fehlersuche bei Webanwendungsproblemen und Überprüfung des responsiven Designs in verschiedenen Ansichten","Überprüfung von Formulareingaben und Benutzerfluss"],"pt":["Automatizar testes de funcionalidades de frontend em navegadores reais","Depurar problemas de aplicações web e verificar design responsivo em diferentes viewports","Validar envios de formulários e fluxos de usuário"],"ru":["Автоматизировать тестирование функциональности frontend в реальных браузерах","Отлаживать проблемы веб-приложений и проверять адаптивный дизайн на разных viewport","Проверять отправку форм и потоки пользователей"],"ar":["أتمتة اختبار الوظائف الأمامية في المتصفحات الفعلية","تصحيح أخطاء التطبيقات الإلكترونية والتحقق من التصميم المرن عبر مختلف العرض","التحقق من إرسال النماذج وتدفقات المستخدمين"]},"limitations":{"en":["Requires Playwright automation setup","Limited to local web application testing"],"zh":["需要Playwright自动化设置","仅限本地Web应用程序测试"],"ja":["Playwright自動化のセットアップが必要","ローカルWebアプリケーションのテストのみ"],"ko":["Playwright 자동화 설정 필요","로컬 웹 애플리케이션 테스트만 가능"],"es":["Requiere configuración de automatización de Playwright","Limitado a pruebas de aplicaciones web locales"],"fr":["Nécessite une configuration d''automatisation de Playwright","Limité aux tests d''applications Web locales"],"de":["Erfordert Playwright-Automatisierungseinrichtung","Begrenzt auf lokale Webanwendungstests"],"pt":["Requer configuração de automação Playwright","Limitado a testes de aplicações web locais"],"ru":["Требует настройки автоматизации Playwright","Ограничен тестированием локальных веб-приложений"],"ar":["يتطلب إعداد أتمتة Playwright","محدود باختبار التطبيقات الإلكترونية المحلية"]},"version":4},"contentHash":"31e301853c09c350e8a55e8e078a1f6e5873f3cdda6cd05a46ddd3d1f0ab6c61","qualityScore":51}');
