INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shren207/awesome-anki/managing-embeddings', 'managing-embeddings', 'shren207', 'awesome-anki', 'community', 'managing-embeddings shren207 awesome-anki community Managing-embeddings is a web application that divides Anki cards into atomic units using Gemini embedding. It benefits AI agent developers by providing a specialized embedding management system. 本文介绍了如何使用Gemini Embedding API管理嵌入式模型，包括模型选择、维度设置和输入限制等技术细节 Gemini Embedding APIを使用してエンベディングを管理する方法について説明します Gemini 임베딩 API를 사용하여 임베딩을 관리하는 방법을 기술적으로 설명합니다 Managing-Embeddings es una aplicación que divide tarjetas Anki en unidades atómicas. Utiliza Gemini y GoogleGenAI para mejorar la similitud semántica Managing-Embeddings est une application qui divise les cartes Anki en unités atomiques. Elle utilise Gemini et GoogleGenAI pour améliorer la similarité sémantique Managing-Embeddings ist eine Anwendung, die Anki-Karten in atomare Einheiten unterteilt. Sie verwendet Gemini und GoogleGenAI, um die semantische Ähnlichkeit zu verbessern O gerenciamento de embeddings é uma técnica para dividir cartões Anki em unidades atômicas, utilizando o modelo Gemini com dimensão 768 e limite de entrada de 8K tokens. Управление вложениями - это техника разделения карточек Anki на атомарные единицы, использующая модель Gemini с размерностью 768 и ограничением входных данных 8К токенов. إدارة الإنشاءات هي تقنية لتقسيم بطاقات Anki إلى وحدات ذرية، باستخدام نموذج Gemini مع بعد 768 وحدود دخول 8K الرموز. how to use managing-embeddings what is managing-embeddings managing-embeddings alternative managing-embeddings vs OpenAI managing-embeddings install managing-embeddings setup guide Gemini embedding for AI agents Anki card management with embeddings semantic similarity tasks with managing-embeddings AI工具管理嵌入式模型 Gemini Embedding API 嵌入式模型管理 机器学习模型优化 自然语言处理 Gemini模型选择 维度设置 输入限制 Utilizes the Gemini embedding model (gemini-embedding-001) for semantic similarity tasks Operates with a 768-dimensional embedding space (default value) Accepts input limits of up to 8K tokens Supports taskType specification as SEMANTIC_SIMILARITY Directly calls the @google/genai library (GoogleGenAI) for embedding management Features a modular structure with client.ts and cosine.ts files for Gemini embedding API client and cosine similarity calculations Managing-embeddings is a technical skill for dividing Anki cards into atomic units using Gemini embedding, specifically designed for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('munlucky/moon-bot/implementation-runner', 'community', 'munlucky', 'moon-bot', 'munlucky/moon-bot', 'implementation-runner', 0, 0, 51, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:53.245Z', '1f8337300c150c9609a9f87d9b99e20f5b5aacd19e04593220507f9dd70846f7', '{"id":"munlucky/moon-bot/implementation-runner","name":"implementation-runner","description":{"en":"The implementation-runner skill automates implementation for AI agents, benefiting developers by streamlining the process. It checks requirements, defines change scope, and records changes.","zh":"Implementation Runner 是一种自动化代码变更和实现的工具，支持分析上下文和决策技能链","ja":"Implementation Runner は、分析コンテキストと決定スキルチェーンをサポートするコード実装と変更を自動化するツールです","ko":"Implementation Runner는 분석 컨텍스트와 결정 스킬 체인을 지원하는 자동화된 코드 변경과 구현 도구입니다","es":"Implementation-runner es una skill técnica para agentes de IA que ejecuta cambios de código. Analiza el contexto de la solicitud, define el alcance de la implementación y genera un resumen de los archivos modificados, marcando la finalización en analysisContext.","fr":"Implementation-runner est une compétence technique pour agents IA exécutant des modifications de code. Elle analyse le contexte de la requête, définit la portée des implémentations et génère un résumé des fichiers modifiés.","de":"Implementation-runner ist eine technische Fähigkeit für KI-Agenten, die Codeänderungen ausführt. Sie analysiert den Anfragekontext, definiert den Implementierungsumfang und erstellt eine Zusammenfassung der geänderten Dateien.","pt":"O Implementation Runner é uma ferramenta de automação que analisa o contexto e implementa mudanças nos arquivos de código","ru":"Implementation Runner - это инструмент автоматизации, который анализирует контекст и реализует изменения в файлах кода","ar":"Implementation Runner هو أداة تلقائية لتحليل السياق وتنفيذ التغييرات في الملفات البرمجية"},"seo":{"title":{"en":"implementation-runner: Automated Implementation Setup Gui...","zh":"Implementation Runner 安装指南：自动化代码变更","ja":"Implementation Runner のベストプラクティス：AIエージェントによるコード実装","ko":"Implementation Runner 설정 가이드: 자동화된 코드 변경","es":"implementation-runner: Guía de Implementación para Agente...","fr":"implementation-runner : Guide d''Implémentation pour Agent...","de":"implementation-runner: Implementierungsleitfaden für KI-A...","pt":"Guia de Configuração do Implementation Runner para Desenv...","ru":"Настройка ИИ Агентов: Implementation Runner для Разработч...","ar":"دليل تنفيذ Implementation Runner لأصحاب التطبيقات"},"description":{"en":"Discover how implementation-runner simplifies AI agent development. Learn to automate implementation and get started with our setup guide today!","zh":"了解 Implementation Runner 的功能和特点，自动化代码变更和实现","ja":"Implementation Runner の機能と特徴を紹介。AIエージェントを使用したコード実装を自動化する","ko":"Implementation Runner의 기능과 특징을 살펴보세요. 자동화된 코드 변경과 구현","es":"Skill de agente de IA que automatiza la implementación de código. Procesa mensajes de usuario, cadenas de habilidades y archivos abiertos para generar parche...","fr":"Compétence d''agent IA automatisant l''implémentation de code. Traite les messages utilisateur, les chaînes de compétences et les fichiers ouverts pour générer...","de":"KI-Agenten-Fähigkeit zur Automatisierung der Code-Implementierung. Verarbeitet Benutzernachrichten, Skill-Ketten und geöffnete Dateien zur Patch-Generierung.","pt":"Aprenda a configurar o Implementation Runner para automatizar tarefas de desenvolvimento com análise de contexto e implementação de mudanças","ru":"Узнайте, как настроить Implementation Runner для автоматизации задач разработки с помощью анализа контекста и реализации изменений","ar":"تعرف على كيفية تنفيذ Implementation Runner لتسريع عملية التطوير باستخدام تحليل السياق وتنفيذ التغييرات"},"definition":{"en":"implementation-runner is a skill that automates the implementation process for AI agents, using inputs like analysisContext and repo data to define and record changes","zh":"Implementation Runner 是一种自动化代码变更和实现的 AI 工具","ja":"Implementation Runner は、コード実装と変更を自動化する AI エージェントです","ko":"Implementation Runner는 자동화된 코드 변경과 구현을 위한 AI 도구입니다","es":"Implementation-runner es una skill de agente de IA que automatiza la implementación de cambios de código. Procesa entradas como analysisContext.request.userMessage y repo.openFiles, ejecuta un procedimiento definido y genera un parche con los archivos modificados.","fr":"Implementation-runner est une compétence d''agent IA automatisant l''implémentation des modifications de code. Elle traite les entrées comme analysisContext.request.userMessage et repo.openFiles, exécute une procédure et génère un correctif.","de":"Implementation-runner ist eine KI-Agenten-Fähigkeit zur Automatisierung von Codeänderungen. Sie verarbeitet Eingaben wie analysisContext.request.userMessage und repo.openFiles, führt eine Prozedur aus und generiert einen Patch.","pt":"O que é Implementation Runner? É uma ferramenta que automatiza a implementação de mudanças nos arquivos de código com base no contexto","ru":"Что такое Implementation Runner? Это инструмент, который автоматизирует реализацию изменений в файлах кода на основе контекста","ar":"ما هو Implementation Runner؟ هو أداة تلقائية لتنفيذ التغييرات في الملفات البرمجية بناءً على السياق"},"features":{"en":["Checks requirements and context using analysisContext.request.userMessage","Defines change scope and implements changes based on analysisContext.decisions.skillChain","Records changed files and key change summary in repo.changedFiles","Updates implementation completion in analysisContext","Utilizes repo.openFiles and analysisContext.artifacts.contextDocPath for context-aware implementation"],"zh":["支持分析上下文和决策技能链","自动化代码变更和实现","记录改变的文件和关键变化摘要","更新实现完成状态"],"ja":["分析コンテキストと決定スキルチェーンをサポート","コード実装と変更を自動化","変更されたファイルと重要な変更の概要を記録","実装完了状態を更新"],"ko":["분석 컨텍스트와 결정 스킬 체인을 지원","자동화된 코드 변경과 구현","변경된 파일과 주요 변경 요약을 기록","구현 완료 상태를 업데이트"],"es":["Procesa analysisContext.request.userMessage para la solicitud inicial","Analiza analysisContext.decisions.skillChain para la toma de decisiones","Utiliza analysisContext.repo.openFiles para el contexto del código","Ejecuta un procedimiento de 4 pasos para la implementación","Genera una salida en YAML con repo.changedFiles y signals.implementationComplete"],"fr":["Traite analysisContext.request.userMessage pour la demande initiale","Analyse analysisContext.decisions.skillChain pour la prise de décision","Utilise analysisContext.repo.openFiles pour le contexte du code","Exécute une procédure en 4 étapes pour l''implémentation","Produit une sortie YAML avec repo.changedFiles et signals.implementationComplete"],"de":["Verarbeitet analysisContext.request.userMessage für die Anfrage","Analysiert analysisContext.decisions.skillChain für Entscheidungen","Nutzt analysisContext.repo.openFiles für Code-Kontext","Führt ein 4-Schritte-Verfahren zur Implementierung aus","Generiert YAML-Ausgabe mit repo.changedFiles und signals.implementationComplete"],"pt":["Análise de contexto com `analysisContext.request.userMessage`","Definição do escopo de mudanças com `analysisContext.decisions.skillChain`","Gravação de arquivos alterados e resumo das mudanças","Atualização do status de implementação em `analysisContext`","Suporte a arquivos de código em `src/...`"],"ru":["Анализ контекста с помощью `analysisContext.request.userMessage`","Определение области изменений с помощью `analysisContext.decisions.skillChain`","Запись измененных файлов и краткое описание изменений","Обновление статуса реализации в `analysisContext`","Поддержка файлов кода в `src/...`"],"ar":["تحليل السياق باستخدام `analysisContext.request.userMessage`","تحديد نطاق التغييرات باستخدام `analysisContext.decisions.skillChain`","تسجيل الملفات المعدلة وملخص التغييرات","تحديث حالة التنفيذ في `analysisContext`","دعم الملفات البرمجية في `src/...`"]},"keywords":{"en":["how to use implementation-runner","implementation-runner setup guide","implementation-runner alternative","implementation-runner vs competitor skills","implementation-runner install","what is implementation-runner","automated implementation for AI agents","analysisContext implementation","repo data implementation"],"zh":["Implementation Runner","AI 工具","自动化代码变更","代码实现","分析上下文","决策技能链"],"ja":["Implementation Runner","AI エージェント","コード実装","コード変更","分析コンテキスト","決定スキルチェーン"],"ko":["Implementation Runner","AI 도구","자동화된 코드 변경","코드 구현","분석 컨텍스트","결정 스킬 체인"],"es":["agente de IA implementation-runner","automatización de implementación de código","analysisContext request userMessage","skillChain decisiones agente IA","repo openFiles contexto código","YAML changedFiles implementationComplete","procedimiento agente de desarrollo","parches de código automatizados"],"fr":["agent IA implementation-runner","automatisation implémentation code","analysisContext request userMessage","skillChain décisions agent IA","repo openFiles contexte code","YAML changedFiles implementationComplete","procédure agent développement","correctifs de code automatisés"],"de":["KI-Agent implementation-runner","Automatisierung Code-Implementierung","analysisContext request userMessage","skillChain Entscheidungen KI-Agent","repo openFiles Code-Kontext","YAML changedFiles implementationComplete","Prozedur Entwicklungsagent","automatisierte Code-Patches"],"pt":["Implementation Runner","automação de desenvolvimento","análise de contexto","implementação de mudanças","arquivos de código","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Implementation Runner","автоматизация разработки","анализ контекста","реализация изменений","файлы кода","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["Implementation Runner","أدوات التطوير","تحليل السياق","تنفيذ التغييرات","ملفات البرمجية","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"munlucky","repo":"moon-bot","repoPath":"munlucky/moon-bot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.317Z","topics":[],"category":"community","skillMd":{"name":"implementation-runner","description":"Performs implementation in the chain and records completion state and changed files in analysisContext. Use during implementation.","bodyPreview":"# Implementation Runner\n\n## Inputs\n- `analysisContext.request.userMessage`\n- `analysisContext.decisions.skillChain`\n- `analysisContext.repo.openFiles`\n- `analysisContext.artifacts.contextDocPath` (if present)\n\n## Procedure\n1. Check requirements and context.\n2. Define change scope and implement.\n3. Record changed files and key change summary.\n4. Update implementation completion in `analysisContext`.\n\n## Output (patch)\n```yaml\nsignals.implementationComplete: true\nrepo.changedFiles:\n  - src/...\nnot","body":"# Implementation Runner\n\n## Inputs\n- `analysisContext.request.userMessage`\n- `analysisContext.decisions.skillChain`\n- `analysisContext.repo.openFiles`\n- `analysisContext.artifacts.contextDocPath` (if present)\n\n## Procedure\n1. Check requirements and context.\n2. Define change scope and implement.\n3. Record changed files and key change summary.\n4. Update implementation completion in `analysisContext`.\n\n## Output (patch)\n```yaml\nsignals.implementationComplete: true\nrepo.changedFiles:\n  - src/...\nnotes:\n  - \"implementation: complete, changed_files=3\"\n```\n\n## Rules\n- Do not call other skills/subagents.\n- If failed or deferred, record the reason in `notes`.\n"},"lastSynced":"2026-03-08T02:02:53.245Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated implementation and change management capabilities.","zh":"适用于需要自动化实施和变更管理能力的开发代理。","ja":"自動化された実装と変更管理機能を必要とする開発エージェントに最適。","ko":"자동화된 구현 및 변경 관리 기능이 필요한 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren capacidades de implementación y gestión de cambios automatizadas.","fr":"Idéal pour les agents de développement nécessitant des capacités de mise en œuvre et de gestion des changements automatisées.","de":"Ideal für Entwicklungsmittel, die eine automatisierte Implementierung und Änderungsmanagementfunktionen erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem implementação automatizada e capacidades de gerenciamento de alterações.","ru":"Идеально для агентов разработки, требующих автоматизированной реализации и возможностей управления изменениями.","ar":"مثالي للوكلاء النموزجيين الذين يتطلبون التنفيذ الآلي وقدرات إدارة التغيير."},"recommendation":{"en":"Empowers agents to streamline implementation processes by checking requirements, defining change scope, and recording changes, utilizing context from user messages, skill chains, and repository files, while updating implementation completion in analysisContext.","zh":"使代理能够通过检查要求、定义变更范围和记录变更，利用来自用户消息、技能链和存储库文件的上下文，同时在analysisContext中更新实现完成情况，从而简化实现流程。","ja":"エージェントが要件を確認し、変更の範囲を定義し、変更を記録し、ユーザー メッセージ、スキル チェーン、リポジトリ ファイルからのコンテキストを使用しながら、analysisContext で実装の完了状況を更新して、実装プロセスを合理化できるようにします。","ko":"요구 사항을 확인하고 변경 범위를 정의하며 변경 사항을 기록하고 사용자 메시지, 스킬 체인 및 리포지토리 파일에서 컨텍스트를 활용하여 analysisContext에서 구현 완료 상태를 업데이트하여 구현 프로세스를 최적화할 수 있도록 에이전트를 강화합니다.","es":"Permite a los agentes simplificar los procesos de implementación comprobando los requisitos, definiendo el alcance de los cambios y grabando los cambios, utilizando el contexto de los mensajes de usuario, las cadenas de habilidades y los archivos del repositorio, al mismo tiempo que actualiza la finalización de la implementación en analysisContext.","fr":"Permet aux agents de simplifier les processus de mise en œuvre en vérifiant les exigences, en définissant la portée des changements et en enregistrant les changements, en utilisant le contexte des messages utilisateur, des chaînes de compétences et des fichiers de référentiel, tout en mettant à jour l''achèvement de la mise en œuvre dans analysisContext.","de":"Ermöglicht es den Mitteln, Implementierungsprozesse zu rationalisieren, indem sie Anforderungen überprüfen, den Änderungsumfang definieren und Änderungen aufzeichnen, unter Nutzung des Kontexts von Benachrichtigungen, Fähigkeitsketten und Repository-Dateien, während sie gleichzeitig die Implementierungsfertigstellung in analysisContext aktualisieren.","pt":"Habilita os agentes a simplificar os processos de implementação, verificando os requisitos, definindo o escopo das alterações e registrando as alterações, utilizando o contexto das mensagens do usuário, cadeias de habilidades e arquivos do repositório, ao mesmo tempo em que atualiza a conclusão da implementação em analysisContext.","ru":"Наделяет агентов возможностью упростить процессы реализации, проверяя требования, определяя объем изменений и регистрируя изменения, используя контекст сообщений пользователей, цепочек навыков и файлов репозитория, при этом обновляя завершение реализации в analysisContext.","ar":"يمنح الوكلاء القدرة على تبسيط عمليات التنفيذ من خلال التحقق من المتطلبات وتحديد نطاق التغييرات وتسجيل التغييرات، باستخدام السياق من رسائل المستخدم وسلاسل المهارات وملفات المستودع، مع تحديث إكمال التنفيذ في analysisContext."},"useCases":{"en":["Automating implementation for AI agent integrations","Defining and managing change scope for repository updates","Recording and tracking changes to repository files"],"zh":["自动化AI代理集成的实施","定义和管理存储库更新的变更范围","记录和跟踪存储库文件的变化"],"ja":["AI エージェント統合の実装を自動化する","リポジトリ更新の変更範囲を定義および管理する","リポジトリ ファイルの変更を記録および追跡する"],"ko":["AI 에이전트 통합을 위한 구현 자동화","리포지토리 업데이트 변경范围 정의 및 관리","리포지토리 파일 변경 사항 기록 및 추적"],"es":["Automatización de la implementación para integraciones de agentes de IA","Definir y gestionar el alcance de los cambios para actualizaciones de repositorio","Grabar y realizar un seguimiento de los cambios en los archivos del repositorio"],"fr":["Automatisation de la mise en œuvre pour les intégrations d''agents IA","Définition et gestion de la portée des changements pour les mises à jour de référentiel","Enregistrement et suivi des changements dans les fichiers de référentiel"],"de":["Automatisierung der Implementierung für KI-Agenten-Integrationen","Definition und Verwaltung des Änderungsumfangs für Repository-Aktualisierungen","Aufzeichnung und Nachverfolgung von Änderungen an Repository-Dateien"],"pt":["Automatizar a implementação para integrações de agentes de IA","Definir e gerenciar o escopo das alterações para atualizações do repositório","Registrar e rastrear alterações nos arquivos do repositório"],"ru":["Автоматизировать реализацию для интеграций агентов ИИ","Определить и управлять объемом изменений для обновлений репозитория","Регистрировать и отслеживать изменения в файлах репозитория"],"ar":["توفير التنفيذ الآلي لمضيفات الوكلاء الذكاء الاصطناعي","تحديد وإدارة نطاق التغييرات لتحديثات المستودع","تسجيل وتتبع التغييرات في ملفات المستودع"]},"limitations":{"en":["Requires access to analysisContext and repository files","Dependent on userMessage and skillChain inputs"],"zh":["需要访问analysisContext和存储库文件","依赖于userMessage和skillChain输入"],"ja":["analysisContextおよびリポジトリ ファイルへのアクセスが必要","userMessageおよびskillChainの入力に依存"],"ko":["analysisContext 및 리포지토리 파일 액세스가 필요함","userMessage 및 skillChain 입력에 의존"],"es":["Requiere acceso a analysisContext y archivos del repositorio","Dependiente de las entradas de userMessage y skillChain"],"fr":["Nécessite un accès à analysisContext et aux fichiers de référentiel","Dépend des entrées userMessage et skillChain"],"de":["Erfordert Zugriff auf analysisContext und Repository-Dateien","Abhängig von den Eingaben userMessage und skillChain"],"pt":["Requer acesso ao analysisContext e arquivos do repositório","Depende das entradas de userMessage e skillChain"],"ru":["Требует доступа к analysisContext и файлам репозитория","Зависит от ввода userMessage и skillChain"],"ar":["يتطلب الوصول إلى analysisContext وملفات المستودع","يعتمد على مدخلات userMessage وskillChain"]},"version":4},"contentHash":"1f8337300c150c9609a9f87d9b99e20f5b5aacd19e04593220507f9dd70846f7","qualityScore":51}');
